// режим: 0 = по винрейту группы, 1 = по длине боя, 2 = фиксирован, 3 = приспешники (с/без)
// scale=1: польза атома растёт с мощью бойцов, цена = коэф * (бюджет/800)
struct AtomDef {
    const char* name;
    double init, lo, hi;
    int mode, scale;
};
