// Сеть-Сборщик (net_builder.cc) подменяет статичные параметры: на каждом решении генератора она видит, что уже куплено, и выдаёт поправку.
// Генератор по-прежнему сам следит за бюджетом, поэтому все инварианты цены сохраняются при любых решениях сети.
struct BuildBrain {
    virtual bool bern(int id, double p0, double u) = 0;                              // u — равномерное число из общего потока
    virtual int cat(int base, int n, const double* p0, double u) = 0;                // p0[j] — исходные вероятности (сумма 1)
    virtual double warp(int id, double u) = 0;                                       // доля бюджета u в [0,1) → растянутая
    virtual ~BuildBrain() {}
};
thread_local BuildBrain* g_bb = nullptr;
struct BuildState {   // что видит сеть-Сборщик о строящемся боссе
    double budget = 0, spent = 0, passLeft = 0;
    int nAbil = 0, depth = 0;
};
thread_local BuildState g_bstate;
thread_local const float* g_th = nullptr;
thread_local std::vector<std::pair<int, float>>* g_trace = nullptr;
thread_local int g_buildDepth = 0;
// решение «да/нет»: p = σ(logit(p0) + θ)
inline bool bern(int id, double p0) {
    if (g_bb) return g_bb->bern(id, p0, rand01());
    if (!g_th) return rand01() < p0;
    double th = g_th[id], p = th == 0.0f ? p0 : 1.0 / (1.0 + std::exp(-(std::log(p0 / (1.0 - p0)) + th)));
    bool x = rand01() < p;
    if (g_trace) g_trace->push_back({id, (float)((x ? 1.0 : 0.0) - p)});
    return x;
}
// равновероятный выбор из n: веса e^θ
inline int catN(int base, int n) {
    if (g_bb) {
        double p[24];   // до 24 вариантов (состояния — 15)
        for (int j = 0; j < n; j++) p[j] = 1.0 / n;
        return g_bb->cat(base, n, p, rand01());
    }
    if (!g_th) return irand(n);
    bool zero = true;
    for (int j = 0; j < n; j++)
        if (g_th[base + j] != 0.0f) zero = false;
    double pj[24], tot = 0;
    for (int j = 0; j < n; j++) {
        pj[j] = std::exp((double)g_th[base + j]);
        tot += pj[j];
    }
    int c;
    if (zero)
        c = irand(n);
    else {
        double r = rand01() * tot;
        c = n - 1;
        for (int j = 0; j < n; j++) {
            r -= pj[j];
            if (r <= 0) {
                c = j;
                break;
            }
        }
    }
    if (g_trace)
        for (int j = 0; j < n; j++) g_trace->push_back({base + j, (float)((j == c ? 1.0 : 0.0) - pj[j] / tot)});
    return c;
}
// выбор по накопленным вероятностям cum0 (последняя = 1); θ умножает вес варианта на e^θ
inline int catP(int base, int n, const double* cum0) {
    double r = rand01();
    if (g_bb) {
        double p[16];
        for (int j = 0; j < n; j++) p[j] = cum0[j] - (j ? cum0[j - 1] : 0.0);
        return g_bb->cat(base, n, p, r);
    }
    if (!g_th) {
        for (int j = 0; j < n - 1; j++)
            if (r < cum0[j]) return j;
        return n - 1;
    }
    bool zero = true;
    for (int j = 0; j < n; j++)
        if (g_th[base + j] != 0.0f) zero = false;
    double pj[24], tot = 0;
    for (int j = 0; j < n; j++) {
        pj[j] = (cum0[j] - (j ? cum0[j - 1] : 0.0)) * std::exp((double)g_th[base + j]);
        tot += pj[j];
    }
    int c = n - 1;
    if (zero) {
        for (int j = 0; j < n - 1; j++)
            if (r < cum0[j]) {
                c = j;
                break;
            }
    } else {
        double q = r * tot;
        for (int j = 0; j < n; j++) {
            q -= pj[j];
            if (q <= 0) {
                c = j;
                break;
            }
        }
    }
    if (g_trace)
        for (int j = 0; j < n; j++) g_trace->push_back({base + j, (float)((j == c ? 1.0 : 0.0) - pj[j] / tot)});
    return c;
}
// Число во весь технический диапазон игрока (после теста 4 ноября: у Сборщика нет игровых потолков — только технические
// пределы, остальное ограничивает цена). Корзины по логарифмической шкале от lo до hi (до 24), внутри корзины —
// равномерно. Без Сборщика корзина k выпадает с весом 0.7^k (чаще малые числа), Сборщик сдвигает веса своими логитами.
int magN(int f, int lo, int hi, int step = 1) {
    if (hi <= lo) return lo;
    const int id = MAGID(f), V = (hi - lo) / step + 1, K = std::min(24, V);
    int edge[25];   // корзина k — номера значений [edge[k], edge[k+1])
    for (int k = 0; k < K; k++) edge[k] = (int)std::lround(std::pow((double)V, (double)k / K)) - 1;
    edge[K] = V;
    for (int k = 1; k < K; k++) edge[k] = std::min(std::max(edge[k], edge[k - 1] + 1), V - (K - k));
    double p0[24], tot0 = 0;
    for (int k = 0; k < K; k++) tot0 += (p0[k] = std::pow(0.7, k));
    for (int k = 0; k < K; k++) p0[k] /= tot0;
    const double r = rand01();
    int c = K - 1;
    if (g_bb)
        c = g_bb->cat(id, K, p0, r);
    else {
        double pj[24], tot = 0;
        for (int k = 0; k < K; k++) tot += (pj[k] = p0[k] * (g_th ? std::exp((double)g_th[id + k]) : 1.0));
        double q = r * tot;
        for (int k = 0; k < K; k++) {
            q -= pj[k];
            if (q <= 0) { c = k; break; }
        }
        if (g_th && g_trace)
            for (int k = 0; k < K; k++) g_trace->push_back({id + k, (float)((k == c ? 1.0 : 0.0) - pj[k] / tot)});
    }
    return lo + step * (edge[c] + irand(edge[c + 1] - edge[c]));
}
// доля бюджета u∈[0,1): растяжка u^e^θ (θ>0 — меньше, θ<0 — больше)
inline double warp(int id, double u) {
    if (g_bb) return g_bb->warp(id, u);
    if (!g_th) return u;
    double th = g_th[id];
    double v = th == 0.0f ? u : std::pow(u, std::exp(th));
    if (g_trace) g_trace->push_back({id, (float)(-1.0 - std::exp(-th) * std::log(std::max(v, 1e-12)))});
    return v;
}
const double DELIV_CUM[3] = {0.40, 0.85, 1.0};
const double USES_CUM[4] = {0.15, 0.25, 0.35, 1.0};
struct BuildScope {
    BuildState saved;
    BuildScope() : saved(g_bstate) {
        if (g_trace && g_buildDepth == 0) g_trace->clear();
        g_buildDepth++;
        g_bstate = BuildState();
        g_bstate.depth = g_buildDepth;
    }
    ~BuildScope() {
        g_buildDepth--;
        g_bstate = saved;   // вложенная сборка (шаблон миньона) не должна портить состояние внешней
    }
};

Wp buildWeapon(const Coef& C, double wBudget, bool forceMelee) {
    Wp p;
    int di = catN(BC_WDIE, DICE_N);
    p.s = DICE[di];
    p.finesse = bern(BP_WFINESSE, 0.5);
    p.range = (forceMelee || bern(BP_WMELEE, 0.45)) ? 5 : magN(MG_WRANGE, 10, MAX_FT_G, 5);
    // боеприпасное — всегда ЛОВ, фехтовальным бывает лишь метательное
    if (p.range > 5) {
        p.ammo = bern(BP_WAMMO, 0.7);
        if (p.ammo) p.finesse = false;
    }
    if (p.range <= 5 && bern(BP_WREACH, 0.16)) {
        p.reach = magN(MG_WREACH, 10, MAX_FT_G, 5);
    }
    {
        double r = rand01();
        p.type = r < 0.385 ? DT_PIERCING : (r < 0.731 ? DT_SLASHING : DT_BLUDGEONING);
    }
    int k = magN(MG_WATT, 1, MAX_COUNT_G), n = 0;
    // замер: число атак задано
    if (g_probe.tier == TR_ATT && !g_probe.attUsed) {
        k = (int)g_probe.n + 1;
        g_probe.attUsed = true;
    }
    // не хватает даже на один кубик выбранного размера — берём кубик меньше (иначе к20/к100 на малом бюджете оставляли
    // босса безоружным, а безоружный в v21 оружием не бьёт)
    for (const int k0 = k; di >= 0; di--) {
        p.s = DICE[di];
        k = k0;
        while (k >= 1) {
            double per1 = C[AT_WPNDICE] * (p.s + 1) / 2.0 * hitsF(C, k) * wpMult(C, p.range, p.reach, k);
            n = (int)std::floor((wBudget - (p.finesse ? 3 : 0)) / per1);
            if (n >= 1) break;
            k = k > 1 ? std::max(1, k / 2) : 0;
        }
        if (k >= 1 && n >= 1) break;
    }
    if (k >= 1 && n >= 1) {
        p.n = n;
        p.att = k;
        p.cost = wpPrice(p, C);
    } else
        p = Wp{};
    return p;
}
// фактическая дальность атаки оружием (досягаемость или дальность)
inline int atkDist(const Boss& b) {
    return b.wRange > 5 ? std::max(b.wRange, b.wLong) : b.reach;   // дальняя дистанция — с помехой (advState)
}
// дальность способности: приём «при попадании» и атака второй рукой бьют своим оружием (вторая рука — только вблизи)
inline int specReach(const Boss& b, const Spec& s) {
    if (s.offhand) return b.reach;
    if (s.onHit) return atkDist(b);
    return s.range;
}
inline bool hasOffhand(const Boss& b) {
    for (auto& s : b.abil)
        if (s.offhand) return true;
    return false;
}
// доспехи (v21, как в D&D): без доспеха и лёгкий — вся ЛОВ к КД, средний — не больше +2, тяжёлый — ЛОВ не идёт
enum Armor { AR_NONE, AR_LIGHT, AR_MEDIUM, AR_HEAVY, AR_N };
const char* ARN[AR_N] = {"без доспеха", "лёгкий доспех", "средний доспех", "тяжёлый доспех"};
inline int dexAC(const Boss& b) {
    const int m = modOf(b.stats[DEX]);
    return b.armor == AR_HEAVY ? 0 : (b.armor == AR_MEDIUM ? std::min(m, 2) : m);
}
// КД = 10 + купленные единицы + ЛОВ по доспеху + щит
inline int unarmoredBonus(const Boss& b) {   // защита без доспеха (пакет атомов 3): модификатор выбранной характеристики, если плюс
    return b.armor == AR_NONE && b.unarmoredStat >= 0 && b.unarmoredStat < STAT_N ? std::max(0, modOf(b.stats[b.unarmoredStat])) : 0;
}
inline int calcAC(const Boss& b) {   // без доспеха (пакет атомов 3) — и модификатор выбранной характеристики (если плюс)
    const int ua = b.armor == AR_NONE && b.unarmoredStat >= 0 && b.unarmoredStat < STAT_N ? std::max(0, modOf(b.stats[b.unarmoredStat])) : 0;
    return 10 + b.acV + dexAC(b) + (b.shield ? 2 : 0) + ua;
}
// контекст цены по готовому телу (см. PriceCtx); PcGuard ставит его на время расчёта и возвращает прежний
inline void setPriceCtx(const Boss& b) {
    g_pc.on = true;
    g_pc.acV = b.acV;
    g_pc.ac = calcAC(b);
    g_pc.att = b.wN > 0 ? std::max(1, b.wAtt) : 1;
    g_pc.strMod = modOf(b.stats[STR]);
    g_pc.dexMod = modOf(b.stats[DEX]);
    g_pc.conSave = modOf(b.stats[CON]) + (((b.saveProf >> CON) & 1u) ? b.prof : 0);
}
struct PcGuard {
    PriceCtx prev;
    explicit PcGuard(const Boss& b) : prev(g_pc) { setPriceCtx(b); }
    ~PcGuard() { g_pc = prev; }
};
// грань оружия в бою: универсальное двумя руками (без щита и второй руки) — бóльшая
inline int wDie(const Boss& b) { return (b.wVers > b.wS && !b.shield && !hasOffhand(b)) ? b.wVers : b.wS; }
// цена доспеха и щита: срезанная доспехом ЛОВ к КД возвращает очки (тяжёлый при отрицательной ЛОВ — добавляет КД и стоит),
// щит, помеха к Скрытности (возврат), без владения (возврат); двуручное (возврат) и универсальное оружие
long long armorPrice(const Boss& b, const Coef& C) {
    double p = -C[AT_ARMDEX] * (modOf(b.stats[DEX]) - dexAC(b));
    if (b.shield) p += C[AT_SHIELD];
    if (b.armStealth && b.armor) p -= C[AT_STEALTHDIS];
    if (b.noArmProf && (b.armor || b.shield)) p -= C[AT_NOARMPROF] * scl(AT_NOARMPROF) * b.prof / 2.0;
    // защита без доспеха (пакет атомов 3): такой же КД по лестнице КД, с долей C[AT_UNARMORED]
    if (const int ua = unarmoredBonus(b)) p += C[AT_UNARMORED] * (acCost(b.acV + ua) - acCost(b.acV));
    return p >= 0 ? (long long)std::ceil(p) : -(long long)std::ceil(-p);
}
const char* SZN[6] = {"крошечный", "маленький", "средний", "большой", "огромный", "громадный"};
// цена размера (v21): крупнее среднего — за ступень (захватить и толкнуть могут лишь на ступень меньше); мельче с тяжёлым
// оружием — помеха к его атакам, очки возвращаются
long long sizePrice(const Boss& b, const Coef& C) {
    double p = 0;
    if (b.size > 2) p = C[AT_SIZEUP] * scl(AT_SIZEUP) * (b.size - 2);
    if (b.size < 2 && b.wN > 0 && b.wHeavy) p = -C[AT_SIZEDN] * scl(AT_SIZEDN) * (2 - b.size);
    return p >= 0 ? (long long)std::ceil(p) : -(long long)std::ceil(-p);
}
long long weaponHandsPrice(const Boss& b, const Coef& C) {
    if (b.wN <= 0) return 0;
    double p = 0;
    if (b.wTwoH) p -= C[AT_TWOHAND];
    if (b.wVers > b.wS) p += C[AT_WPNDICE] * b.wN * (b.wVers - b.wS) / 2.0 * hitsF(C, b.wAtt) * wpMult(C, b.wRange, b.reach, b.wAtt) * C[AT_VERS];
    return p >= 0 ? (long long)std::ceil(p) : -(long long)std::ceil(-p);
}
inline void markArmor(const Boss& b, AMask& m) {
    if (b.size > 2) m |= ONE << AT_SIZEUP;
    if (b.size < 2 && b.wN > 0 && b.wHeavy) m |= ONE << AT_SIZEDN;
    if (b.armor == AR_MEDIUM || b.armor == AR_HEAVY) m |= ONE << AT_ARMDEX;
    if (b.shield) m |= ONE << AT_SHIELD;
    if (b.armStealth && b.armor) m |= ONE << AT_STEALTHDIS;
    if (b.noArmProf && (b.armor || b.shield)) m |= ONE << AT_NOARMPROF;
    if (b.wN > 0 && b.wTwoH) m |= ONE << AT_TWOHAND;
    if (b.wN > 0 && b.wVers > b.wS) m |= ONE << AT_VERS;
}
// v21: оружие бьёт вблизи, если оно ближнее или метательное (кинжал, дротик); боеприпасное (лук, арбалет) — только
// издали. Безоружный атаки оружием не делает и провоцированных атак не совершает.
inline bool meleeWeapon(const Boss& b) {
    return b.wN > 0 && (b.wRange <= 5 || !b.wAmmo);
}
// досягаемость ближнего удара: у ближнего оружия своя, у метательного и голых рук 5 фт
inline int meleeReach(const Boss& b) {
    return b.wN > 0 && b.wRange <= 5 ? b.reach : 5;
}
// дальность конкретной атаки оружием: метательным по цели вплотную бьют как ближним (без помехи за врага рядом)
inline int wpAtkRange(const Boss& b, int dist) {
    return (b.wRange > 5 && !b.wAmmo && dist <= 5) ? 5 : b.wRange;
}
// Парирование и контратака: оружием ближнего боя или голыми руками; с луком в руках нельзя
inline bool handsForMelee(const Boss& b) {
    return b.wN <= 0 || meleeWeapon(b);
}

// Характеристика спасброска от состояния — по смыслу эффекта (телесное — ТЕЛ, воля — МДР, разум — ИНТ, захват/сбивание
// — СИЛ)
int condSaveStat(int k) {
    switch (k) {
        case C_PRONE:
        case C_RESTR:
        case C_GRAPPLE:
            return STR;
        case C_POISON:
        case C_BLIND:
        case C_STUN:
        case C_PARAL:
            return CON;
        case C_DISTR:
            return INT;
        case C_LIT:
            return DEX;
        // испуган, замедлен, недееспособен, очарован
        default:
            return WIS;
    }
}
// Скидка на подавляемую пассивку (tgt: 1 регенерация, 2 аура, 4 защиты): чем чаще встречается подавляющий урон, тем
// больше скидка
double suppMul(const Boss& b, const Coef& C, int tgt) {
    if (!b.suppMask || !(b.suppTgt & tgt)) return 1.0;
    double q = 0;
    for (int t = 0; t < DT_N; t++)
        if ((b.suppMask >> t) & 1) q += g_share[t];
    return 1.0 - C[AT_SUPP] * std::min(1.0, 5.0 * q);
}
// цена правила «когда → что»: цена эффекта × доля времени условия; «атаки по мне с преимуществом» возвращает очки
long long rulePrice(const Rule& r, const Boss& b, const Coef& C) {
    auto P = [&](int a, double m = 1.0) { return C[a] * m * scl(a); };
    double e = 0;
    switch (r.what) {
        case E_ADVATK: e = P(AT_E_ADVATK); break;
        case E_DMG: e = C[AT_E_DMG] * r.n * (r.s + 1) / 2.0 / 3.5 * (r.once ? C[AT_E_ONCE] : hitsF(C, b.wAtt)); break;   // на каждый удар
        case E_AC: e = C[AT_E_AC] * r.n; break;
        case E_DISVSME: e = P(AT_E_DISVSME); break;
        case E_ADVVSME: e = -P(AT_E_ADVVSME); break;
        case E_RES: e = P(AT_E_RES, 5.0) * suppMul(b, C, 4); break;
        case E_RESNM: e = P(AT_E_RES, 5.0 * g_nmShare) * suppMul(b, C, 4); break;
        case E_ADVSAVE: e = P(AT_E_ADVSAVE); break;
        case E_SAVEB: e = P(AT_E_SAVEB) * r.n; break;
        case E_ATKDIE: e = P(AT_E_ATKDIE) * r.n * (r.s + 1) / 5.0; break;   // за к4-эквивалент
        case E_SAVEDIE: e = P(AT_E_SAVEDIE) * r.n * (r.s + 1) / 5.0; break;
        case E_DMGRED: e = P(AT_E_DMGRED) * r.n; break;
        case E_PIERCE: e = P(AT_E_PIERCE, 5.0 * g_share[std::clamp(r.n, 0, DT_N - 1)]); break;
        case E_NOCOVER: e = P(AT_E_NOCOVER); break;
        case E_POWER: e = P(AT_E_POWER) * r.n * hitsF(C, b.wAtt); break;   // размен на каждый удар
        case E_NOOA: e = P(AT_E_NOOA); break;
        case E_SKILLADV: e = P(AT_E_SKILLADV) * (skCombat(std::clamp(r.n, 0, SK_N - 1)) ? 1.0 : 0.1); break;   // небоевой навык — почти даром
        case E_DISATK: e = -P(AT_E_DISATK); break;          // недостаток: очки возвращаются
        case E_ACMINUS: e = -P(AT_E_ACMINUS) * r.n; break;
    }
    e *= C[AT_W_ALWAYS + r.when];
    if (r.allyR > 0) e *= 1 + C[AT_RULEAURA] * tierN(TR_AURARAD, r.allyR / 5.0);   // аура: и на союзников рядом
    return e >= 0 ? (long long)std::ceil(e) : -(long long)std::ceil(-e);
}
// атомы правила: условие и эффект (и «раз в ход»)
inline void markRule(const Rule& r, AMask& m) {
    static const int EA[E_N] = {AT_E_ADVATK, AT_E_DMG, AT_E_AC, AT_E_DISVSME, AT_E_ADVVSME, AT_E_RES, AT_E_RES, AT_E_ADVSAVE, AT_E_SAVEB, AT_E_ATKDIE, AT_E_SAVEDIE, AT_E_DMGRED, AT_E_PIERCE, AT_E_NOCOVER, AT_E_POWER, AT_E_NOOA,
                                AT_E_SKILLADV, AT_E_DISATK, AT_E_ACMINUS};
    if (r.allyR > 0) m |= ONE << AT_RULEAURA;
    m |= ONE << (AT_W_ALWAYS + r.when);
    m |= ONE << EA[r.what];
    if (r.what == E_DMG && r.once) m |= ONE << AT_E_ONCE;
}
std::string describeRule(const Rule& r) {
    std::string w = r.when == W_FOECOND ? std::string("у противника «") + CN[r.warg] + "»" : WN[r.when];
    std::string e = EN[r.what];
    if (r.what == E_DMG) e = "+" + std::to_string(r.n) + "к" + std::to_string(r.s) + " к урону оружия" + (r.once ? ", раз в ход" : "");
    if (r.what == E_AC) e = "+" + std::to_string(r.n) + " КД";
    if (r.what == E_SAVEB) e = "+" + std::to_string(r.n) + " к спасброскам";
    if (r.what == E_ATKDIE) e = "+" + std::to_string(r.n) + "к" + std::to_string(r.s) + " к броскам атаки";
    if (r.what == E_SAVEDIE) e = "+" + std::to_string(r.n) + "к" + std::to_string(r.s) + " к спасброскам";
    if (r.what == E_DMGRED) e = "немагический физический урон по мне −" + std::to_string(r.n);
    if (r.what == E_PIERCE) e = std::string("мой урон «") + DTN[std::clamp(r.n, 0, DT_N - 1)] + "» игнорирует сопротивление";
    if (r.what == E_POWER) e = "размен: −" + std::to_string(r.n) + " к попаданию, +" + std::to_string(2 * r.n) + " к урону оружия";
    if (r.what == E_SKILLADV) e = std::string("преимущество на проверки «") + SKN[std::clamp(r.n, 0, SK_N - 1)] + "»";
    if (r.what == E_ACMINUS) e = "−" + std::to_string(r.n) + " к КД (недостаток)";
    if (r.allyR > 0) e += " (и союзникам в " + std::to_string(r.allyR) + " фт)";
    return w + " → " + e;
}
// цена «событие → эффект»: цена эффекта × доля пользы события; применений за бой меньше — дешевле (как у способностей)
long long trigPrice(const Trig& t, const Boss& b, const Coef& C) {
    auto P = [&](int a, double m = 1.0) { return C[a] * m * scl(a); };
    const double dice = (t.n * (t.s + 1) / 2.0 + t.b) / 3.5;
    double e = 0;
    switch (t.what) {
        case X_BONUSATK: e = C[AT_X_BONUSATK] * C[AT_WPNDICE] * b.wN * (b.wS + 1) / 2.0; break;
        case X_HEAL: e = C[AT_X_HEAL] * dice; break;
        case X_TEMP: e = C[AT_X_TEMP] * dice; break;
        case X_DMG: e = C[AT_X_DMG] * dice; break;
        case X_COND: e = t.cond > 0 ? C[AT_PRONE + t.cond - 1] * scl(AT_PRONE + t.cond - 1) * C[AT_X_COND] * (1 + 0.25 * (std::max(1, t.n) - 1)) : 0; break;
        case X_STAY1: e = P(AT_X_STAY1); break;
        case X_ADVNEXT: e = P(AT_X_ADVNEXT); break;
        case X_INITB: e = C[AT_X_INITB] * t.n; break;
        case X_SPEED: e = C[AT_X_SPEED] * t.n; break;
        case X_REROLL: e = P(AT_X_REROLL); break;
    }
    if (t.what == X_SELFCOND)   // состояние на себя — помеха владельцу: очки возвращаются
        e = t.cond > 0 ? -C[AT_PRONE + t.cond - 1] * scl(AT_PRONE + t.cond - 1) * C[AT_X_SELFCOND] * (1 + 0.25 * (std::max(1, t.n) - 1)) : 0;
    e *= C[atTrigOn(t.on)] * (t.on == T_DMGTYPE ? 5.0 * g_share[std::clamp(t.arg, 0, DT_N - 1)] : 1.0);
    if (t.uses < UNL) e *= std::max(0.2, 1 - (1 - C[AT_ULIM]) * (1 - (t.uses - 1) * 0.2));
    return e < 0 ? -(long long)std::ceil(-e) : std::max(1LL, (long long)std::ceil(e));   // состояние на себя — возврат
}
inline void markTrig(const Trig& t, AMask& m) {
    m |= ONE << atTrigOn(t.on);
    m |= ONE << atTrigDo(t.what);
}
std::string describeTrig(const Trig& t) {
    std::string e = TDN[t.what];
    const std::string dice = std::to_string(t.n) + "к" + std::to_string(t.s) + (t.b ? "+" + std::to_string(t.b) : "");
    if (t.what == X_HEAL || t.what == X_TEMP || t.what == X_DMG) e += " " + dice;
    if (t.what == X_COND && t.cond > 0) e = std::string("цель ") + CN[t.cond] + " на " + std::to_string(std::max(1, t.n)) + " р.";
    if (t.what == X_INITB) e = "+" + std::to_string(t.n) + " к инициативе";
    if (t.what == X_SPEED) e = "+" + std::to_string(5 * t.n) + " фт скорости в этот ход";
    if (t.what == X_SELFCOND && t.cond > 0) e = std::string("сам ") + CN[t.cond] + " на " + std::to_string(std::max(1, t.n)) + " р.";
    if (t.on == T_HITMELEE && (t.what == X_DMG || t.what == X_COND)) e = "атакующему: " + e;
    if (t.on == T_DMGTYPE) return std::string("я получил урон «") + DTN[std::clamp(t.arg, 0, DT_N - 1)] + "» → " + e + (t.uses < UNL ? " (" + std::to_string(t.uses) + " раз за бой)" : "");
    return std::string(TON[t.on]) + " → " + e + (t.uses < UNL ? " (" + std::to_string(t.uses) + " раз за бой)" : "");
}
inline bool hasResRule(const Boss& b) {
    for (auto& r : b.rules)
        if (r.what == E_RES || r.what == E_RESNM) return true;
    return false;
}
inline bool hasWhen(const Boss& b, int w) {
    for (auto& r : b.rules)
        if (r.when == w) return true;
    return false;
}
// Аура: урон/состояние врагам в радиусе в начале их хода (всегда включена); цена ∝ радиусу
long long auraPrice(const Boss& b, const Coef& C) {
    double t = 0;
    if (b.auraN > 0) t += C[AT_AURA] * tierN(TR_AURADICE, b.auraN * (b.auraS + 1) / 7.0) * 3.5;   // лестница в к6-эквивалентах
    if (b.auraCond > 0) {
        double dm = b.auraCond == C_PRONE ? 1.0 : 1 + 0.25 * (b.auraRounds - 1);
        t += C[AT_PRONE + b.auraCond - 1] * dm * scl(AT_PRONE + b.auraCond - 1) * C[AT_AURACOND];
    }
    t *= 1 + C[AT_AURARAD] * tierN(TR_AURARAD, b.auraRad / 5.0 - 1);
    t *= suppMul(b, C, 2);
    return (long long)std::ceil(t);
}
void markAura(const Boss& b, AMask& m) {
    if (b.auraN > 0) m |= ONE << AT_AURA;
    m |= ONE << AT_AURARAD;
    if (b.auraCond > 0) {
        m |= ONE << AT_AURACOND;
        m |= ONE << (AT_PRONE + b.auraCond - 1);
    }
}
// Цена довеска: доп. урон (за очко среднего) + состояние (цена состояния × множитель довеска); одно округление
// довесок «схватить» (пакет атомов 2): схваченный опутан; урон каждый ход, пока держит
double riderGrabPrice(const Boss& b, const Coef& C) {
    if (b.rCond != C_GRAPPLE) return 0;
    double t = 0;
    if (b.rGrabRestr) t += C[AT_PRONE + C_RESTR - 1] * scl(AT_PRONE + C_RESTR - 1) * C[AT_GRABRESTR];
    if (b.rGrabDotN > 0) t += C[AT_DOT] * b.rGrabDotN * (b.rGrabDotS + 1) / 2.0 / 3.5 * C[AT_GRABDOT];
    return t;
}
long long riderPrice(const Boss& b, const Coef& C) {
    double t = riderGrabPrice(b, C);
    if (b.rN > 0) t += C[AT_RDMG] * b.rN * (b.rS + 1) / 2.0;
    if (b.rCond > 0) {
        double dm = b.rCond == C_PRONE ? 1.0 : 1 + 0.25 * (b.rRounds - 1);
        t += C[AT_PRONE + b.rCond - 1] * dm * scl(AT_PRONE + b.rCond - 1) * C[AT_RCOND];
    }
    return (long long)std::ceil(t);
}
void markRider(const Boss& b, AMask& m) {
    if (b.rN > 0) m |= ONE << AT_RDMG;
    if (b.rCond == C_GRAPPLE && b.rGrabRestr) m |= ONE << AT_GRABRESTR;
    if (b.rCond == C_GRAPPLE && b.rGrabDotN > 0) m |= ONE << AT_GRABDOT;
    if (b.rCond > 0) {
        m |= ONE << AT_RCOND;
        m |= ONE << (AT_PRONE + b.rCond - 1);
    }
}

// есть ли у босса призыв (шаблоны в tmpl бывают и обликом превращения)
inline bool hasSummonSpec(const Boss& b) {
    for (auto& s : b.abil)
        if (s.sumN > 0) return true;
    return false;
}
void markSpec(const Spec& s, AMask& m) {
    auto set = [&](int a) { m |= ONE << a; };
    if (s.dmgN) set(AT_DMG);
    if (s.cond) set(AT_PRONE + s.cond - 1);
    if (s.pushFt) set(AT_PUSH);
    if (s.pushFt && s.collN) set(AT_COLLIDE);
    if (s.dotN) set(AT_DOT);
    if (s.darkR) set(AT_DARK);
    if (s.invisN) set(AT_INVIS);
    if (s.terr) set(AT_TERR);
    if (s.healN) set(AT_HEAL);
    if (s.teleFt) set(AT_TELE);
    if (s.hide) set(AT_HIDE);
    if (s.buffN) set(AT_BUFF);
    if (s.sbAmt) set(AT_STATBUF);
    if (s.tempN) set(AT_TEMP);
    if (s.acB) set(AT_ACB);
    if (!s.self) {
        if (s.radius) set(AT_AREA);
        if (s.radius && s.shape == SH_CONE) set(AT_SHCONE);
        if (s.radius && s.shape == SH_LINE) set(AT_SHLINE);
        if (s.targets > 1 && !s.radius) set(AT_MULTI);
        if (rangeIdx(s.range) >= 1) set(AT_ARANGE);
        if (s.delivery == 2) set(AT_AUTO);
    }
    if (s.uses < UNL) set(AT_ULIM);
    if (s.recharge) set(AT_RECHARGE);
    if (s.bonus) set(AT_BONUS);
    if (s.conc) set(AT_CONC);
    if (s.slotLvl > 0) set(AT_SLOTSPEC);
    if (s.wallLen > 0) set(AT_WALL);
    if (s.ground && !s.self) set(AT_GROUND);
    if (s.selective && s.radius > 0 && !s.self) set(AT_SELECT);
    if (s.react) set(AT_REACT);
    if (s.onHit) set(AT_ONHIT);
    if (s.offhand) set(AT_TWF);
    if (s.offhand && s.twfMod) set(AT_TWFMOD);
    if (s.pool) set(AT_POOL);
    if (s.selfN) set(AT_SELFDMG);
    if (s.killN || s.killB) set(AT_KILLHEAL);
    if (s.disarm) set(AT_DISARM);
    if (s.pullFt) set(AT_PULL);
    if (s.maxHpDmg) set(AT_MAXHP);
    if (s.drain) set(AT_DRAIN);
    if (s.counter) set(AT_COUNTER);
    if (s.dispel) set(AT_DISPEL);
    if (s.formTmpl >= 0) set(AT_FORM);
    if (s.ally) set(AT_ALLYTGT);
    if (s.inAttack) set(AT_INATTACK);
    if (s.cond == C_GRAPPLE && s.grabRestr) set(AT_GRABRESTR);
    if (s.jump && s.teleFt > 0) set(AT_JUMP);
    if (s.images > 0) set(AT_IMAGES);
    if (s.globeLvl > 0) set(AT_GLOBE);
    if (s.banishN > 0) set(AT_BANISH);
    if (s.flyRounds > 0) set(AT_FLYBUFF);
    if (s.extraTurns > 0) set(AT_TIMESTOP);
    if (s.growRounds > 0) set(AT_GROW);
    if (s.lightR > 0) set(AT_LIGHT);
    if (s.healAlly) set(AT_HEALALLY);
    if (s.rechAfter && s.uses < UNL && s.recharge) set(AT_RECHAFTER);
    if (s.cond == C_GRAPPLE && s.grabDot && s.dotN > 0) set(AT_GRABDOT);
    if (s.preCast && s.self) set(AT_PRECAST);
    if (s.immSave && s.delivery == 1 && !s.self) set(AT_IMMSAVE);
    if (s.noRepeat) set(AT_NOREPEAT);
    if (s.cmdAtk) set(AT_CMDATK);
    if (s.protect) set(AT_PROTECT);
    if (s.strike) set(AT_STRIKE);
    if (s.dcB > 0) set(AT_DCB);
    if (s.noRep) set(AT_NOREP);
    if (s.sumN > 0) {
        set(AT_SUMMON);
        set(AT_MINION);
        if (s.uses >= UNL) set(AT_SUMUNL);
    }
    for (auto& d : s.more)
        if (d.n > 0) set(AT_DMGMIX), set(AT_DMG);
}

int pickByWeight(const double* w) {
    double tot = 0;
    for (int i = 0; i < DT_N; i++) tot += w[i];
    double r = rand01() * tot;
    for (int i = 0; i < DT_N; i++) {
        r -= w[i];
        if (r <= 0 && w[i] > 0) return i;
    }
    for (int i = DT_N - 1; i >= 0; i--)
        if (w[i] > 0) return i;
    return 0;
}
// 22% физические (колющий/рубящий/дробящий), остальное по весам
int pickAbilityType() {
    if (rand01() < 0.22) {
        double r = rand01();
        return r < 0.385 ? DT_PIERCING : (r < 0.731 ? DT_SLASHING : DT_BLUDGEONING);
    }
    return pickByWeight(AB_W);
}
// Характеристика спасброска — по смыслу эффекта (воля — МДР, телесное — ТЕЛ, увёртывание — ЛОВ, сила личности — ХАР)
int meaningSave(const Spec& s) {
    double r = rand01();
    if (s.cond) {
        switch (s.cond) {
            case C_PRONE:
            case C_RESTR:
            case C_GRAPPLE:
                return r < 0.7 ? STR : DEX;
            case C_POISON:
                return CON;
            case C_BLIND:
                return r < 0.6 ? CON : DEX;
            case C_STUN:
            case C_PARAL:
                return r < 0.7 ? CON : WIS;
            case C_DISTR:
                return r < 0.5 ? INT : WIS;
            case C_LIT:
                return DEX;
            case C_FRIGHT:
            case C_FLEE:
                return WIS;
            case C_CHARM:
                return r < 0.7 ? WIS : CHA;
            case C_INCAP:
                return r < 0.5 ? WIS : CHA;
            case C_WEAK:
                return r < 0.5 ? CHA : WIS;
            case C_SLOW:
                return r < 0.6 ? WIS : DEX;
            default:
                return WIS;
        }
    }
    if (s.dmgN == 0 && s.dotN == 0) return s.pushFt > 0 ? STR : WIS;
    //                            СИЛ   ЛОВ   ТЕЛ   ИНТ   МДР   ХАР
    static const double T[DT_N][6] = {// кислота
                                      {0, .7, .3, 0, 0, 0},
                                      // дробящий
                                      {.5, .3, .2, 0, 0, 0},
                                      // холод
                                      {0, .4, .6, 0, 0, 0},
                                      // огонь
                                      {0, .9, .1, 0, 0, 0},
                                      // силовое поле
                                      {0, .8, .2, 0, 0, 0},
                                      // электричество
                                      {0, 1, 0, 0, 0, 0},
                                      // некротика
                                      {0, 0, .7, 0, .3, 0},
                                      // колющий
                                      {.3, .7, 0, 0, 0, 0},
                                      // яд
                                      {0, 0, 1, 0, 0, 0},
                                      // психический
                                      {0, 0, 0, .5, .4, .1},
                                      // излучение
                                      {0, .3, .5, 0, .2, 0},
                                      // рубящий
                                      {.4, .6, 0, 0, 0, 0},
                                      // звук
                                      {.2, 0, .8, 0, 0, 0}};
    for (int k = 0; k < 6; k++) {
        r -= T[s.dtype][k];
        if (r <= 0 && T[s.dtype][k] > 0) return k;
    }
    for (int k = 5; k >= 0; k--)
        if (T[s.dtype][k] > 0) return k;
    return WIS;
}
Spec randSpec(int sub) {
    Spec s;
    (void)sub;
    // способность на себя
    if (bern(BP_SELF, 0.22)) {
        s.self = true;
        s.delivery = 2;
        s.range = 0;
        // девять видов способности на себя, поровну; после теста 4 ноября — как у игрока, несколько эффектов в одной
        // способности (каждый следующий — с шансом BP_SELFMORE)
        auto addKind = [&](int k) {
        if (k == 0) {
            s.healN = magN(MG_HEALN, 1, MAX_DICE_G);
            s.healS = DICE[catN(BC_HEALS, DICE_N)];   // грань лечения (v21)
            if (bern(BP_HEALB, 0.30)) s.healB = 1 + catN(BC_HEALS + 8, 8);   // и прибавка (второе дыхание: 1к10 + 5)
        }
        else if (k == 1)
            s.teleFt = magN(MG_TELE, 10, MAX_FT_G, 10);
        else if (k == 2)
            s.hide = true;
        else if (k == 3) {
            s.buffN = magN(MG_BUFFN, 1, MAX_DICE_G);
            s.buffS = DICE[catN(BC_BUFFS, 4)];   // грань баффа оружия: к2…к8 (v21)
            s.buffRounds = magN(MG_BUFFR, 1, MAX_ROUNDS_G);
        } else if (k == 4)
            s.tempN = magN(MG_TEMPN, 1, MAX_DICE_G);
        else if (k == 5) {
            s.acB = magN(MG_ACB, 1, MAX_COUNT_G);
            s.acRounds = magN(MG_ACR, 1, MAX_ROUNDS_G);
        } else if (k == 6)
            s.darkR = magN(MG_DARKR, 10, MAX_FT_G, 10);
        else if (k == 7)
            s.invisN = magN(MG_INVISN, 1, MAX_ROUNDS_G);
        else {
            double q = rand01();
            s.sbAmt = magN(MG_SBAMT, 1, MAX_COUNT_G);   (void)q;
            s.sbRounds = magN(MG_SBR, 1, MAX_ROUNDS_G);
        }
        };
        int kinds = 0;
        for (int n = 0; n < 4; n++) {
            const int k = catN(BC_SELFKIND, 9);
            if (kinds >> k & 1) continue;
            kinds |= 1 << k;
            addKind(k);
            if (!bern(BP_SELFMORE, 0.25)) break;
        }
        // пакет атомов 2: прыжок вместо телепорта, отражения, сфера, полёт, ходы подряд, увеличение, свет
        if (s.teleFt > 0 && bern(BP_JUMP, 0.30)) { s.jump = true; s.teleFt = magN(MG_JUMP, 10, MAX_FT_G, 10); }
        if (bern(BP_IMAGES, 0.04)) s.images = magN(MG_IMAGES, 1, MAX_COUNT_G);
        if (bern(BP_GLOBE, 0.03)) { s.globeLvl = magN(MG_GLOBEL, 1, 9); s.globeRounds = magN(MG_GLOBER, 1, MAX_ROUNDS_G); s.radius = 10; }
        if (bern(BP_FLYBUFF, 0.04)) s.flyRounds = magN(MG_FLYR, 1, MAX_ROUNDS_G);
        if (bern(BP_TIMESTOP, 0.01)) s.extraTurns = magN(MG_XTURN, 1, 10);
        if (bern(BP_GROW, 0.03)) s.growRounds = magN(MG_GROWR, 1, MAX_ROUNDS_G);
        if (bern(BP_LIGHTS, 0.03)) { s.lightR = magN(MG_LIGHTR, 10, MAX_FT_G, 10); if (!s.buffRounds) s.buffRounds = 10; }
        // союзники (v21): лечение, хиты и баффы — и на союзника в пределах дальности
        if ((s.healN || s.tempN || s.buffN || s.acB || s.sbAmt || s.invisN) && bern(BP_ALLY, 0.30)) {
            s.ally = true;
            s.range = magN(MG_ALLYR, 5, MAX_FT_G, 5);
        }
        s.bonus = bern(BP_SELFBONUS, 0.4);
        // длящийся бафф — под концентрацией
        if ((s.buffN || s.acB || s.invisN || s.sbAmt) && bern(BP_SELFCONC, 0.30)) {
            s.conc = true;
            if (s.invisN) s.invisN = magN(MG_INVISN, 3, MAX_ROUNDS_G);
        }
    } else if (bern(BP_WALL, 0.05)) {
        // барьер (№22): временная стена поперёк пути на клетке в пределах дальности, без урона
        s.ground = true;
        s.delivery = 0;
        s.range = magN(MG_WALLRANGE, 10, MAX_FT_G, 5);
        s.wallLen = magN(MG_WALLLEN, 2, W);
        s.wallRounds = magN(MG_WALLR, 1, MAX_ROUNDS_G);
    } else {
        s.delivery = catP(BC_DELIV, 3, DELIV_CUM);
        // ХАР не симулируется
        const int sv[5] = {STR, DEX, CON, INT, WIS};
        s.saveStat = sv[catN(BC_SAVE, 5)];
        // любая дальность кратная 5 фт
        s.range = bern(BP_RANGE5, 0.30) ? 5 : magN(MG_RANGE, 10, MAX_FT_G, 5);
        // радиус 5..30 фт с шагом 5
        s.radius = bern(BP_NORAD, 0.70) ? 0 : magN(MG_RADIUS, 5, MAX_FT_G, 5);
        // область можно навести на любую клетку (№9, №22); избирательная бьёт только врагов (№17)
        if (s.radius > 0) {   // форма (v21): конус и линия — от себя, их длина больше радиуса сферы
            s.shape = catN(BC_SHAPE, SH_N);
            if (s.shape == SH_CONE || s.shape == SH_LINE) {
                s.radius *= 2;
                s.range = s.radius;
            }
        } else if (!s.self && bern(BP_MULTI, 0.12))
            s.targets = magN(MG_MULTI, 2, 10);
        if (s.radius > 0 && s.shape <= SH_CUBE && bern(BP_GROUND, 0.25)) s.ground = true;
        if (s.radius > 0 && bern(BP_SELECT, 0.30)) s.selective = true;
        if (bern(BP_HASDMG, 0.70)) {
            s.dmgN = magN(MG_DMGN, 1, MAX_DICE_G);
            s.dmgS = DICE[catN(BC_DMGS, DICE_N)];
        }
        if (s.dmgN) s.dtype = pickAbilityType();
        // модификация при сборке (№10): ещё кубики другого типа урона
        if (s.dmgN && bern(BP_DMGMIX, 0.10)) {
            Spec::Dmg d;
            d.n = magN(MG_MIXN, 1, MAX_DICE_G);
            d.s = DICE[catN(BC_MIXS, DICE_N)];
            d.type = pickAbilityType();
            if (d.type != s.dtype) s.more.push_back(d);
        }
        if (bern(BP_HASCOND, 0.50) || s.dmgN == 0) {
            s.cond = 1 + catN(BC_COND, C_N - 1);
            s.condRounds = (s.cond == C_PRONE) ? 1 : magN(MG_CONDR, 1, MAX_ROUNDS_G);
            // яд — спасбросок ТЕЛ
            if (s.cond == C_POISON) s.saveStat = CON;
            // без броска состояние держится ровно 1 раунд (длительность не продаётся)
            if (s.delivery == 2) s.condRounds = 1;
        }
        if (bern(BP_PUSH, 0.12)) {
            s.pushFt = magN(MG_PUSH, 5, MAX_FT_G, 5);
            if (bern(BP_COLL, 0.35)) s.collN = magN(MG_COLL, 1, MAX_DICE_G);
        } else if (bern(BP_PULL, 0.06))   // притягивание (v21)
            s.pullFt = magN(MG_PUSH, 5, MAX_FT_G, 5);
        if (s.dmgN && bern(BP_MAXHP, 0.05)) s.maxHpDmg = true;   // прочее (v21)
        if (s.dmgN && bern(BP_DRAIN, 0.06)) s.drain = true;
        if (bern(BP_DISPEL, 0.04)) s.dispel = true;
        if (bern(BP_BANISH, 0.03)) { s.banishN = magN(MG_BANISH, 1, MAX_ROUNDS_G); s.saveStat = CHA; }   // пакет атомов 2
        if (s.dmgN && bern(BP_HEALALLY, 0.03)) s.healAlly = true;
        if (s.cond == C_GRAPPLE && bern(BP_GRABRESTR, 0.4)) s.grabRestr = true;
        if (s.cond == C_GRAPPLE && bern(BP_GRABDOT, 0.2)) {
            s.grabDot = true;
            s.dotN = magN(MG_DOTN, 1, MAX_DICE_G);
            s.dotS = DICE[catN(BC_DOTS, DICE_N)];
        }
        // область делает местность труднопроходимой
        if (s.radius >= 10 && bern(BP_TERR, 0.10)) s.terr = true;
        // урон по времени
        if (bern(BP_DOT, 0.10)) {
            s.dotN = magN(MG_DOTN, 1, MAX_DICE_G);
            s.dotS = DICE[catN(BC_DOTS, DICE_N)];
            s.dotRounds = magN(MG_DOTR, 1, MAX_ROUNDS_G);
            if (!s.dmgN) s.dtype = pickAbilityType();
        }
        s.bonus = bern(BP_BONUS, 0.10);
        // состояние на 3–10 раундов — под концентрацией
        if (s.cond && s.cond != C_PRONE && s.delivery != 2 && bern(BP_CONC, 0.30)) {
            s.conc = true;
            s.condRounds = magN(MG_CONDR, 3, MAX_ROUNDS_G);
        } else if (s.dotN > 0 && bern(BP_CONC, 0.30)) {
            s.conc = true;
            s.dotRounds = magN(MG_DOTR, 3, MAX_ROUNDS_G);
        }
        // спасбросок — по смыслу эффекта
        s.saveStat = meaningSave(s);
        // этап 5б: своя СЛ способности (там, где есть спасбросок) и состояние без повторного спаса
        if ((s.delivery == 1 || (s.delivery == 0 && s.cond && s.cond != C_GRAPPLE)) && bern(BP_DCB, 0.20)) s.dcB = 1 + catN(BC_DCB, 8);
        if (s.cond && s.cond != C_PRONE && s.cond != C_GRAPPLE && s.delivery != 2 && s.condRounds >= 2 && bern(BP_NOREP, 0.15)) s.noRep = true;
    }
    {
        int u = catP(BC_USES, 4, USES_CUM);   // лимит или без лимита; лимит — во весь технический диапазон
        s.uses = u == 3 ? UNL : magN(MG_USES, 1, MAX_COUNT_G);
    }
    // перезарядка вместо лимита
    if (s.uses >= UNL && !s.self && bern(BP_RECHARGE, 0.20)) {
        double r2 = rand01();
        s.recharge = r2 < 0.40 ? 6 : (r2 < 0.80 ? 5 : 4);
    } else if (s.uses < UNL && bern(BP_RECHAFTER, 0.06)) {   // пакет атомов 3: кончились применения — перезарядка вернёт все
        s.recharge = 5 + irand(2);
        s.rechAfter = true;
    }
    // пакет атомов 1 (5 ноября): вместо одной атаки, невосприимчивость после успеха, не два раунда подряд, с начала боя
    if (!s.self && !s.bonus && bern(BP_INATTACK, 0.08)) s.inAttack = true;
    if (s.delivery == 1 && !s.self && bern(BP_IMMSAVE, 0.08)) s.immSave = true;
    if (bern(BP_NOREPEAT, 0.05)) s.noRepeat = true;
    if (s.self && (s.buffN || s.acB || s.tempN || s.invisN || s.sbAmt) && bern(BP_PRECAST, 0.12)) s.preCast = true;
    // реакция (№23): срабатывает сама по условию, вместо действия
    if (bern(BP_REACT, 0.08)) {
        s.inAttack = s.preCast = false;   // реакция — не часть хода
        s.react = 1 + catN(BC_REACTT, 4);
        s.bonus = false;
        if (s.react == 4 && !s.self && bern(BP_COUNTER, 0.3)) {   // контрзаклинание (v21): гасит способность врага в зоне
            const int rr = s.range, us = s.uses;
            s = Spec{};
            s.self = s.counter = true;
            s.react = 4;
            s.range = std::max(30, rr);
            s.uses = us;
        }
    }
    return s;
}

// ---------------------------------------------------------------------------
// Генератор босса
// ---------------------------------------------------------------------------
// Политика сборки миньонов: босс САМ решает, брать ли миньонов, какую долю очков вложить, сколько копий и какой лимит
// одновременно. Значения по умолчанию — среднее того, что делал случайный генератор; «умные» значения подбирает ./arena
// learnbuild. pUse, share, copies, capFrac
struct BuildPol {
    double v[4] = {0.5, 0.265, 4.5, 0.55};
};
const char* BPN[4] = {"pUse", "share", "copies", "capFrac"};
const double BPLO[4] = {0.0, 0.03, 1.0, 0.1}, BPHI[4] = {1.0, 0.6, 10.0, 1.0};
// «Умная» сборка, найденная перебором ./arena learnbuild + сеткой (59.8% против случайно собранного, см. v19): всегда
// брать миньонов, 2 копии, призывать обе сразу
const BuildPol SMART_BP = {{1.0, 0.30, 2.0, 1.0}};
// если задана — makeBoss собирает миньонов по ней, а не случайно
thread_local const BuildPol* g_bp = nullptr;
// доля времени, в которую действует условие (ХП>50%, ХП<=50%, нет состояний)
const double CD_W[3] = {0.55, 0.45, 0.70};
inline double condDefPrice(const Coef& C, int trig, int scope) {
    return C[AT_CONDDEF] * scl(AT_CONDDEF) * 5.0 * (scope == 1 ? 1.0 : g_nmShare) * CD_W[trig - 1];
}
Boss makeBoss(long long budget, const Coef& C, bool allowSummon, bool force = false);
Boss makeBossOnce(long long budget, const Coef& C, bool allowSummon, bool force) {
    // минимальный бюджет босса
    if (budget < MIN_BUDGET) budget = MIN_BUDGET;
    if (budget > MAX_BUDGET) budget = MAX_BUDGET;
    budget += STAT_BASE;   // видимый бюджет считает характеристики от 10; внутри учёт абсолютный
    BuildScope bscope;
    Boss b;
    long long spent = 0;
    double prevB = g_B;
    g_B = (double)budget;
    double passLeft = budget * (0.05 + 0.40 * warp(BW_PASS, rand01()));
    g_bstate.budget = (double)budget;
    auto buy = [&](double cost) {
        long long c = (long long)std::ceil(cost);
        if (c > passLeft) return false;
        passLeft -= c;
        spent += c;
        g_bstate.spent = (double)spent;
        g_bstate.passLeft = passLeft;
        return true;
    };
    auto mark = [&](int a) { b.atoms |= ONE << a; };

    auto P = [&](int a, double m = 1.0) { return C[a] * m * scl(a); };
    // скорость (v21, №7): покупается вся, с нуля, шагами по 5 фт, первой из пассивов (без неё босс не ходит). Обычно 30 фт,
    // иногда любая от 5 до 60; не хватает очков — на 5 фт меньше. Атом отмечен только у быстрых (> 30 фт): у всех он
    // есть, и винрейт «владельцев» иначе ничего бы не мерил.
    {
        int sp = bern(BP_SPEED, 0.20) ? magN(MG_SPEED, 5, MAX_FT_G, 5) : 30;
        while (sp > 0 && !buy(P(AT_SPEED, speedUnits(sp)))) sp -= 5;
        b.speed = sp;
        if (sp > 30) mark(AT_SPEED);
    }
    // подавление: какие типы урона на ход отключают регенерацию / ауру / защиты (генератор выбирает сам); за это —
    // скидка на подавляемое
    if (bern(BP_SUPP, 0.25)) {
        int cnt = 1 + (rand01() < 0.4) + (rand01() < 0.15);
        for (int k = 0; k < cnt; k++) b.suppMask |= 1u << pickByWeight(VUL_W);
        b.suppTgt = (rand01() < 0.7 ? 1 : 0) | (rand01() < 0.5 ? 2 : 0) | (rand01() < 0.4 ? 4 : 0);
        if (!b.suppTgt) b.suppTgt = 1;
    }
    if (bern(BP_REGEN, (b.suppMask && (b.suppTgt & 1)) ? 0.60 : 0.20)) {
        int n = magN(MG_REGEN, 1, MAX_DICE_G);
        if (buy(P(AT_REGEN, n) * suppMul(b, C, 1))) {
            b.regenN = n;
            mark(AT_REGEN);
        }
    }
    // защиты по типам урона: цена типа = коэф * 5 * доля урона этого типа; уязвимость ВОЗВРАЩАЕТ очки
    auto typeCost = [&](int a, int t) { return P(a, 5.0 * g_share[t]) * (a == AT_VULN ? 1.0 : suppMul(b, C, 4)); };
    if (bern(BP_RESIST, 0.30)) {
        int n = 1 + (rand01() < 0.40) + (rand01() < 0.15);
        for (int k = 0; k < n; k++) {
            int t = pickByWeight(RES_W);
            if ((b.resMask >> t) & 1) continue;
            if (buy(typeCost(AT_RESIST, t))) {
                b.resMask |= 1u << t;
                mark(AT_RESIST);
            }
        }
    }
    if (bern(BP_IMMTYPE, 0.22)) {
        int n = 1 + (rand01() < 0.30);
        for (int k = 0; k < n; k++) {
            int t = pickByWeight(IMM_W);
            if (((b.resMask | b.immMask) >> t) & 1) continue;
            if (buy(typeCost(AT_IMMTYPE, t))) {
                b.immMask |= 1u << t;
                mark(AT_IMMTYPE);
            }
        }
    }
    if (bern(BP_VULN, 0.15)) {
        int n = 1 + (rand01() < 0.30);
        for (int k = 0; k < n; k++) {
            int t = pickByWeight(VUL_W);
            if (((b.resMask | b.immMask | b.vulnMask) >> t) & 1) continue;
            long long ref = (long long)std::ceil(typeCost(AT_VULN, t));
            b.vulnMask |= 1u << t;
            spent -= ref;
            passLeft += ref;
            mark(AT_VULN);
        }
    }
    if (bern(BP_RESNM, 0.08) && buy(P(AT_RESNM, 5.0 * g_nmShare) * suppMul(b, C, 4))) {
        b.resNM = true;
        mark(AT_RESNM);
    }
    if (bern(BP_IMMNM, 0.08) && buy(P(AT_IMMNM, 5.0 * g_nmShare) * suppMul(b, C, 4))) {
        b.immNM = true;
        mark(AT_IMMNM);
    }
    if (bern(BP_WMAGIC, 0.10) && buy(P(AT_WMAGIC))) {
        b.wMagic = true;
        mark(AT_WMAGIC);
    } else if (bern(BP_WSILVER, 0.06) && buy(P(AT_WMAGIC) * C[AT_WSILVER])) {   // пакет атомов 2: посеребрённое
        b.wSilver = true;
        mark(AT_WSILVER);
    }
    // легендарные действия: 1–5 очков (чаще всего 3)
    if (bern(BP_LEGACT, 0.10)) {
        int pts = magN(MG_LEGACT, 1, MAX_COUNT_G);
        if (buy(P(AT_LEGACT, pts))) {
            b.legAct = pts;
            mark(AT_LEGACT);
        }
    }
    // Парирование: +2..+5 к КД против одной ближней атаки за раунд (в бестиарии 3.4% карточек)
    if (bern(BP_PARRY, 0.08)) {
        int pb = magN(MG_PARRY, 1, MAX_COUNT_G);
        if (buy(P(AT_PARRY, pb))) {
            b.parry = pb;
            mark(AT_PARRY);
        }
    }
    if (bern(BP_LIGHTP, 0.04)) {   // пакет атомов 2: свет вокруг себя
        const int r = magN(MG_LIGHTR, 10, MAX_FT_G, 10);
        if (buy(C[AT_LIGHT] * r / 10.0)) { b.lightR = r; mark(AT_LIGHT); }
    }
    if (bern(BP_MAGICRES, 0.10) && buy(P(AT_MAGICRES))) {   // пакет атомов 1 (сопротивление магии — у 15% карточек бестиария)
        b.magicRes = true;
        mark(AT_MAGICRES);
    }
    if (bern(BP_SPELLRES, 0.03) && buy(P(AT_SPELLRES))) {
        b.spellRes = true;
        mark(AT_SPELLRES);
    }
    if (bern(BP_CRITIMM, 0.03) && buy(P(AT_CRITIMM))) {
        b.critImm = true;
        mark(AT_CRITIMM);
    }
    if (bern(BP_UNCANNY, 0.04) && buy(P(AT_UNCANNY))) {
        b.uncanny = true;
        mark(AT_UNCANNY);
    }
    if (bern(BP_IMMPUSH, 0.08) && buy(P(AT_IMMPUSH))) {
        b.immPush = true;
        mark(AT_IMMPUSH);
    }
    if (bern(BP_DISENGB, 0.08) && buy(P(AT_DISENGB))) {
        b.disengB = true;
        mark(AT_DISENGB);
    }
    // аура: урон и/или состояние врагам в радиусе в начале их хода
    if (bern(BP_AURA, (b.suppMask && (b.suppTgt & 2)) ? 0.30 : 0.10)) {
        double r = rand01(), q = rand01();
        b.auraRad = magN(MG_AURARAD, 10, MAX_FT_G, 5);   (void)q;
        bool dm = r < 0.75, cd = r > 0.55;
        if (dm) {
            b.auraN = magN(MG_AURAN, 1, MAX_DICE_G);
            b.auraS = DICE[catN(BC_AURAS, DICE_N)];
            b.auraType = pickAbilityType();
        }
        if (cd) {
            b.auraCond = 1 + catN(BC_AURAC, C_N - 1);
            b.auraRounds = b.auraCond == C_PRONE ? 1 : magN(MG_AURAR, 1, MAX_ROUNDS_G);
        }
        long long ac = auraPrice(b, C);
        if (ac > 0 && buy((double)ac))
            markAura(b, b.atoms);
        else {
            b.auraN = 0;
            b.auraRad = 0;
            b.auraCond = 0;
            b.auraRounds = 1;
        }
    }
    if (bern(BP_DARKV, 0.35)) {
        double r = rand01();
        int idx = r < 0.30 ? 1 : (r < 0.80 ? 2 : 3);
        if (buy(P(AT_DARKV, idx))) {
            b.dv = idx == 3 ? 120 : 30 * idx;
            mark(AT_DARKV);
        }
    }
    if (bern(BP_BLINDS, 0.06)) {
        double r = rand01();
        int idx = r < 0.40 ? 1 : (r < 0.80 ? 2 : 3);
        if (buy(P(AT_BLINDS, idx))) {
            b.blindsight = idx == 1 ? 10 : (idx == 2 ? 30 : 60);
            mark(AT_BLINDS);
        }
    }
    if (bern(BP_TRUESIGHT, 0.04)) {   // истинное зрение (v21)
        const int k = catN(BC_TRUESIGHT, 4);
        if (buy(P(AT_TRUESIGHT, k + 1))) {
            static const int TS[4] = {10, 30, 60, 120};
            b.truesight = TS[k];
            mark(AT_TRUESIGHT);
        }
    }
    if (bern(BP_IGNTERR, 0.06) && buy(P(AT_IGNTERR))) {
        b.ignDiff = true;
        mark(AT_IGNTERR);
    }
    if (bern(BP_CLIMB, 0.05) && buy(P(AT_CLIMB))) {   // скорости движения (v21)
        b.climbS = true;
        mark(AT_CLIMB);
    }
    if (bern(BP_SWIM, 0.05) && buy(P(AT_SWIM))) {
        b.swimS = true;
        mark(AT_SWIM);
    }
    if (bern(BP_BURROW, 0.03) && buy(P(AT_BURROW))) {
        b.burrowS = true;
        mark(AT_BURROW);
    }
    if (bern(BP_EVASION, 0.04) && buy(P(AT_EVASION))) {
        b.evasion = true;
        mark(AT_EVASION);
    }
    if (bern(BP_LAIR, 0.04)) {   // действия логова
        const int lv = 1 + catN(BC_LAIR, 3);
        if (buy(P(AT_LAIR, lv))) {
            b.lair = lv;
            mark(AT_LAIR);
        }
    }
    if (bern(BP_SUNSENS, 0.03)) {   // недостаток: очки возвращаются
        b.sunSens = true;
        buy(-(double)(long long)std::ceil(P(AT_SUNSENS)));
        mark(AT_SUNSENS);
    }
    if (bern(BP_RIPOSTE, 0.05) && buy(P(AT_RIPOSTE))) {
        b.riposte = true;
        mark(AT_RIPOSTE);
    }
    if (bern(BP_SURGE, 0.06)) {
        int n = magN(MG_SURGE, 1, MAX_COUNT_G);
        if (buy(P(AT_SURGE, n))) {
            b.surge = n;
            mark(AT_SURGE);
        }
    }
    // легендарное сопротивление: N раз за бой (в книгах чаще всего «3/день»)
    if (bern(BP_LEGRES, 0.12)) {
        int n = magN(MG_LEGRES, 1, MAX_COUNT_G);
        if (buy(P(AT_LEGRES, n))) {
            b.legRes = n;
            mark(AT_LEGRES);
        }
    }
    for (int k = 1; k < C_N; k++)
        if (bern(BP_IMMCOND, 0.08 * 8.0 / (C_N - 1)) && buy(P(AT_IMMCOND))) {
            b.immCond |= 1u << k;
            mark(AT_IMMCOND);
        }
    // владения (v21): бонус мастерства +3…+6 (за каждую единицу сверх +2); владения дальше стоят × мастерство/2
    if (bern(BP_PROF, 0.25)) {
        int pr = 3 + catN(BC_PROF, 4);
        while (pr > 2 && !buy(P(AT_PROF, pr - 2))) pr--;
        b.prof = pr;
        if (pr > 2) mark(AT_PROF);
    }
    for (int k = 0; k < SK_N; k++)
        if (skCombat(k) && bern(BP_SKILL, 0.10) && buy(P(AT_SKILLC, b.prof / 2.0))) {
            b.skillProf |= 1u << k;
            mark(AT_SKILLC);
            if (bern(BP_SKILLX, 0.20) && buy(P(AT_SKILLC, b.prof / 2.0))) b.skillExp |= 1u << k;
        }
    for (int st = 0; st < STAT_N; st++)
        if (bern(BP_SAVEPROF, 0.06) && buy(P(AT_SAVEPROF, b.prof / 2.0))) {
            b.saveProf |= 1u << st;
            mark(AT_SAVEPROF);
        }
    if (bern(BP_FLY, 0.12) && buy(P(AT_FLY))) {
        b.fly = true;
        mark(AT_FLY);
    }
    // «когда → что» (v21): до 4 правил; эффект, затем подходящее к нему условие (резист и спасброски — только условия о
    // себе); «атаки по мне с преимуществом» возвращает очки
    for (int k = 0; k < 4 && bern(BP_RULE, k == 0 ? 0.45 : 0.30); k++) {
        Rule r;
        r.what = bern(BP_RUNEW, 0.12) ? E_SKILLADV + catN(BC_RUNEW, 3) : catN(BC_RUWHAT, std::min((int)E_N, 16));
        if (r.what == E_SKILLADV) r.n = irand(SK_N);
        if (r.what == E_ACMINUS) r.n = magN(MG_ACMIN, 1, 20);
        do r.when = catN(BC_RUWHEN, W_N);
        while (!ruleAllowed(r.when, r.what));
        if (r.when == W_FOECOND) r.warg = 1 + catN(BC_RUCOND, C_N - 1);
        if (r.what == E_DMG) {
            r.n = magN(MG_RUN, 1, MAX_DICE_G);
            r.s = DICE[catN(BC_RUS, DICE_N)];
            r.once = bern(BP_RUONCE, 0.4);
        } else if (r.what == E_AC || r.what == E_SAVEB)
            r.n = magN(MG_RUN, 1, 20);   // технический предел правила: +20
        else if (r.what == E_DMGRED)
            r.n = magN(MG_RUN, 1, 1000);
        else if (r.what == E_ATKDIE || r.what == E_SAVEDIE) {   // Благословение: к4
            r.n = 1;
            r.s = DICE[catN(BC_RUS, 4)];
        } else if (r.what == E_PIERCE)
            r.n = catN(BC_RUCOND, DT_N);   // какой тип урона
        else if (r.what == E_POWER)
            r.n = magN(MG_RUN, 1, 20);
        if (!r.once && r.what != E_ADVVSME && bern(BP_RAURA, 0.15)) r.allyR = magN(MG_RAURA, 5, MAX_FT_G, 5);   // аура и на своих
        const long long pr = rulePrice(r, b, C);
        if (pr < 0) {
            spent += pr;
            passLeft -= pr;
        } else if (!buy((double)pr))
            continue;
        r.price = pr;
        b.rules.push_back(r);
        markRule(r, b.atoms);
    }


    // потолок 40 — просто защита от бесконечного цикла, реально упрётся в бюджет раньше
    for (int i = 0; i < 40 && passLeft >= 3; i++) {
        // шанс остановиться раньше, чтобы не у всех был максимум способностей
        if (i > 0 && bern(BP_ABSTOP, 0.15)) break;
        Spec s = randSpec(i);
        for (int t = 0; t < 8; t++) {
            s.price = specPrice(s, C);
            if (s.price <= passLeft) break;
            if (!s.more.empty())
                s.more.pop_back();
            else if (s.dmgN > 1)
                s.dmgN = (s.dmgN + 1) / 2;
            else if (s.cond) {
                s.cond = 0;
                s.condRounds = 1;
                if (s.dmgN == 0) s.dmgN = 1;
            } else if (s.dotN) {
                s.dotN = 0;
                s.dotRounds = 0;
                if (s.dmgN == 0) s.dmgN = 1;
            } else if (s.collN)
                s.collN = 0;
            else if (s.pushFt)
                s.pushFt = 0;
            else if (s.wallLen > 1)
                s.wallLen = (s.wallLen + 1) / 2;
            else if (s.wallRounds > 1)
                s.wallRounds--;
            else
                break;
        }
        s.price = specPrice(s, C);
        long long extra = 0;
        int newL = 0, newN = 0;
        // способность за ячейку: уровень ячейки по силе способности; пул ячеек этого уровня покупается один раз
        if (s.uses >= UNL && !s.recharge && bern(BP_SLOT, 0.25)) {
            int lvl = std::clamp(1 + (int)(s.price / (0.04 * budget)), 1, 9);
            Spec t = s;
            t.slotLvl = lvl;
            long long p = specPrice(t, C), need = 0, n = 0;
            if (b.slots[lvl] == 0) {
                n = lvl <= 3 ? 1 + irand(3) : (lvl <= 6 ? 1 + irand(2) : 1);
                need = (long long)std::ceil(C[AT_SLOT] * lvl * n);
                newL = lvl;
                newN = (int)n;
            }
            if (p + need <= passLeft) {
                s = t;
                s.price = p;
                extra = need;
            } else
                newL = 0;
        }
        const long long fee = abilFee(C, b.abil.size() + 1) - abilFee(C, b.abil.size());   // наценка за очередную способность
        if (s.price + extra + fee <= passLeft && buy((double)(s.price + extra + fee))) {
            b.abil.push_back(s);
            g_bstate.nAbil = (int)b.abil.size();
            markSpec(s, b.atoms);
            if (fee > 0) mark(AT_NABIL);
            if (newL && extra > 0) {
                b.slots[newL] = newN;
                mark(AT_SLOT);
            }
        }
    }

    // пробный компонент (замер лестниц)
    if (g_probe.tier == TR_NABIL) {   // замер лестницы числа способностей: n одноразовых способностей с состоянием (как у сильного Сборщика)
        static const int CK[8] = {C_PARAL, C_STUN, C_FRIGHT, C_RESTR, C_SLOW, C_INCAP, C_CHARM, C_BLIND};
        for (int i = 0; i < (int)g_probe.n; i++) {
            Spec ps;
            ps.delivery = 1;
            ps.range = 60;
            ps.cond = CK[i % 8];
            ps.condRounds = 3;
            ps.uses = 1;
            ps.bonus = (i % 2) == 1;
            ps.saveStat = meaningSave(ps);
            ps.price = specPrice(ps, C);
            const long long cost = ps.price + abilFee(C, b.abil.size() + 1) - abilFee(C, b.abil.size());
            if (spent + cost > (long long)(0.85 * budget)) {
                g_probe.fail = true;
                break;
            }
            spent += cost;
            b.abil.push_back(ps);
            markSpec(ps, b.atoms);
            if (b.abil.size() > (size_t)ABIL_FREE) mark(AT_NABIL);
        }
    } else if (g_probe.tier >= 0 && g_probe.tier != TR_ATT) {
        const int n = (int)g_probe.n;
        Spec ps;
        ps.delivery = 1;
        ps.saveStat = DEX;
        ps.range = 30;
        ps.dmgN = 4;
        ps.dmgS = 6;
        ps.dtype = DT_FIRE;
        bool isSpec = true;
        switch (g_probe.tier) {
            case TR_RANGE:
                ps.range = 5 + 5 * n;
                break;
            case TR_AREA:
                ps.radius = 5 * n;
                ps.range = 60;
                break;
            case TR_PUSH:
                ps.dmgN = 2;
                ps.saveStat = STR;
                ps.pushFt = 5 * n;
                break;
            case TR_TELE:
                ps = Spec();
                ps.self = true;
                ps.delivery = 2;
                ps.range = 0;
                ps.teleFt = 10 * n;
                break;
            case TR_DMG:
                ps.dmgN = n;
                break;
            case TR_TEMP:
                ps = Spec();
                ps.self = true;
                ps.delivery = 2;
                ps.range = 0;
                ps.tempN = n;
                break;
            case TR_ACB:
                ps = Spec();
                ps.self = true;
                ps.delivery = 2;
                ps.range = 0;
                ps.acB = n;
                ps.acRounds = 5;
                break;
            default:
                isSpec = false;
        }
        if (isSpec) {
            ps.price = specPrice(ps, C);
            if (spent + ps.price > (long long)(0.85 * budget))
                g_probe.fail = true;
            else {
                spent += ps.price;
                b.abil.push_back(ps);
                markSpec(ps, b.atoms);
            }
        } else if (g_probe.tier == TR_SPEED) {
            if (b.speed > 0) spent -= (long long)std::ceil(P(AT_SPEED, speedUnits(b.speed)));
            long long pr = (long long)std::ceil(P(AT_SPEED, tierN(TR_SPEED, n)));
            if (spent + pr > (long long)(0.85 * budget))
                g_probe.fail = true;
            else {
                spent += pr;
                b.speed = 5 * n;
                mark(AT_SPEED);
            }
            // радиус ауры / кубики урона ауры
        } else {
            if (b.auraRad > 0) spent -= auraPrice(b, C);
            b.auraRad = g_probe.tier == TR_AURARAD ? 5 * (n + 1) : 10;
            b.auraN = g_probe.tier == TR_AURADICE ? n : 1;
            b.auraS = 6;
            b.auraType = DT_FIRE;
            b.auraCond = 0;
            b.auraRounds = 1;
            long long pr = auraPrice(b, C);
            if (spent + pr > (long long)(0.85 * budget)) {
                g_probe.fail = true;
                b.auraRad = 0;
                b.auraN = 0;
            } else {
                spent += pr;
                markAura(b, b.atoms);
            }
        }
    }
    // призыв — способность (v21): босс выделяет очки на приспешников (alloc), собирает ОДИН шаблон тем же генератором, что
    // и боссов, и покупает способность «призвать k копий» с ценой способности (действие или бонусное, применения,
    // концентрация). Шаблон стоит полную цену за каждую копию и каждое применение (без лимита — как C[AT_SUMUNL]
    // применений). Число копий всего (n) и доля за одно применение (k = доля·n) — те же параметры политики сборки
    if (allowSummon && b.abil.size() < 12 && (force || bern(BP_SUMMON, g_bp ? g_bp->v[0] : 0.5))) {
        double alloc = g_bp ? budget * g_bp->v[1] : budget * (0.08 + 0.37 * warp(BW_SUMALLOC, rand01()));
        int n = g_bp ? std::clamp((int)std::lround(g_bp->v[2]), 1, 10) : magN(MG_SUMN, 1, 20);
        const double minB = 40;
        auto tb = [&](int nn) { return alloc / (minMult(C) * nn); };
        while (n > 1 && tb(n) < minB) n--;
        double mb = tb(n);
        if (mb >= minB) {
            Boss mn = makeBoss((long long)mb, C, false);
            const int k = g_bp ? std::clamp((int)std::lround(g_bp->v[3] * n), 1, n) : 1 + catN(BC_SUMK, n);
            Spec ss;
            ss.self = true;
            ss.delivery = 2;
            ss.range = 0;
            ss.sumN = k;
            ss.sumTmpl = (int)b.tmpl.size();
            ss.sumCost = mn.cost;
            ss.uses = std::max(1, (n + k - 1) / k);
            Boss mn2;   // разные приспешники (v21): в четверти призывов — вторая группа другого шаблона (вдвое дешевле)
            const bool mix = bern(BP_SUMMIX, 0.25) && mb / 2 >= minB;
            if (mix) {
                mn2 = makeBoss((long long)(mb / 2), C, false);
                ss.sumMore.push_back({(long long)b.tmpl.size() + 1, 1, mn2.cost});
            }
            if (bern(BP_SUMCONC, 0.25)) ss.conc = true;     // призыв на концентрации: дешевле, но приспешники исчезают с ней
            if (bern(BP_SUMBONUS, 0.15)) ss.bonus = true;    // бонусным действием
            if (bern(BP_SUMUNL, 0.15)) ss.uses = UNL;      // без лимита применений
            ss.price = specPrice(ss, C);
            const long long fee = abilFee(C, b.abil.size() + 1) - abilFee(C, b.abil.size());
            // не влезает в бюджет — призыва нет; под приспешников нельзя отдать резерв на характеристики и ХП
            if (spent + ss.price + fee <= std::min((long long)(0.95 * budget), budget - RESERVE)) {
                spent += ss.price + fee;
                b.tmpl.push_back(mn);
                if (mix) b.tmpl.push_back(mn2);
                b.abil.push_back(ss);
                g_bstate.nAbil = (int)b.abil.size();
                markSpec(ss, b.atoms);
                if (fee > 0) mark(AT_NABIL);
                long long rf = (long long)std::ceil(P(AT_REDIRECT));
                if (bern(BP_REDIRECT, 0.35) && spent + rf <= std::min((long long)(0.95 * budget), budget - RESERVE)) {
                    spent += rf;
                    b.redirect = true;
                    mark(AT_REDIRECT);
                }
            }
        }
    }
    // превращение (v21): облик — шаблон, собранный тем же генератором на долю бюджета; способность «превратиться»
    // (действием или бонусным, 1–3 раза за бой) стоит облик × применения × C[AT_FORM]
    if (allowSummon && b.abil.size() < 12 && bern(BP_FORM, 0.03)) {
        const double fb = budget * (0.2 + 0.3 * rand01());
        if (fb >= 40) {
            Boss mn = makeBoss((long long)fb, C, false);
            Spec fs;
            fs.self = true;
            fs.delivery = 2;
            fs.range = 0;
            fs.formTmpl = (int)b.tmpl.size();
            fs.sumCost = mn.cost;
            fs.uses = magN(MG_FORMU, 1, 10);
            if (bern(BP_FORMBONUS, 0.3)) fs.bonus = true;
            fs.price = specPrice(fs, C);
            const long long fee = abilFee(C, b.abil.size() + 1) - abilFee(C, b.abil.size());
            if (spent + fs.price + fee <= std::min((long long)(0.95 * budget), budget - RESERVE)) {
                spent += fs.price + fee;
                b.tmpl.push_back(mn);
                b.abil.push_back(fs);
                g_bstate.nAbil = (int)b.abil.size();
                markSpec(fs, b.atoms);
                if (fee > 0) mark(AT_NABIL);
            }
        }
    }

    long long remain = std::max(0LL, budget - spent - RESERVE);   // резерв под минимальные характеристики и ХП

    // оружие: основное + запасное (арсенал); кубики без предела, число атак свободное
    {
        // Парирование и контратака требуют ближнего оружия
        Wp p = buildWeapon(C, (double)(long long)(remain * 0.5 * warp(BW_WPN, rand01())), b.parry > 0 || b.riposte);
        // на такое число атак не хватило бюджета оружия
        if (g_probe.tier == TR_ATT && p.att != (int)g_probe.n + 1) g_probe.fail = true;
        if (p.n >= 1) {
            b.wN = p.n;
            b.wS = p.s;
            b.wRange = p.range;
            b.wAtt = p.att;
            b.reach = p.reach;
            b.wFinesse = p.finesse;
            b.wAmmo = p.ammo;
            b.wType = p.type;
            b.wcost = p.cost;
            markWp(p, b.atoms);
        } else {
            b.wN = 0;
            b.wS = 0;
            b.wAtt = 1;
            b.wRange = 5;
            b.reach = 5;
            b.wFinesse = false;
            b.wAmmo = false;
            b.wcost = 0;
        }
    }
    // без владения своим оружием (v21): мастерство не идёт к атакам оружием, очки возвращаются
    if (b.wN > 0 && bern(BP_NOWPROF, 0.05)) {
        const long long ref = (long long)std::ceil(P(AT_NOWPROF, b.prof / 2.0));
        b.wNoProf = true;
        spent -= ref;
        remain += ref;
        mark(AT_NOWPROF);
    }
    // арсенал: 1–2 запасных вида оружия, бот выбирает по ситуации
    if (b.wN > 0 && bern(BP_ARSENAL, 0.20)) {
        int na = 1 + (rand01() < 0.3);
        for (int a = 0; a < na; a++) {
            long long left = remain - b.wcost - b.acost;
            Wp q = buildWeapon(C, (double)(long long)(left * 0.3 * rand01()), false);
            if (q.n >= 1 && b.acost + q.cost <= (long long)(0.4 * (remain - b.wcost))) {
                q.multi = bern(BP_MULTIWPN, 0.5);   // укус + когти: в бестиарии — самая частая форма мультиатаки
                b.alt.push_back(q);
                b.acost += q.cost;
                markWp(q, b.atoms);
            }
        }
    }
    // довесок к удару: только урон / только состояние / оба
    if (b.wN > 0 && bern(BP_RIDER, 0.25)) {
        double r = rand01();
        bool dm = r < 0.7, cd = r > 0.5;
        if (dm) {
            b.rN = magN(MG_RN, 1, MAX_DICE_G);
            b.rS = DICE[catN(BC_RS, DICE_N)];
            b.rType = pickAbilityType();
        }
        if (cd) {
            b.rCond = 1 + catN(BC_RCOND, C_N - 1);
            b.rRounds = b.rCond == C_PRONE ? 1 : magN(MG_RR, 1, MAX_ROUNDS_G);
            if (b.rCond == C_GRAPPLE && bern(BP_GRABRESTR, 0.4)) b.rGrabRestr = true;   // пакет атомов 2
            if (b.rCond == C_GRAPPLE && bern(BP_GRABDOT, 0.2)) { b.rGrabDotN = magN(MG_DOTN, 1, MAX_DICE_G); b.rGrabDotS = DICE[catN(BC_DOTS, DICE_N)]; }
        }
        b.rcost = riderPrice(b, C);
        if (b.rcost <= 0 || b.rcost > (long long)(0.4 * (remain - b.wcost))) {
            b.rN = 0;
            b.rS = 0;
            b.rCond = 0;
            b.rRounds = 1;
            b.rcost = 0;
        } else
            markRider(b, b.atoms);
    }

    // оружие и Зуро (v21): лёгкое ближнее оружие и атака второй рукой; дальняя дистанция; запас костей с приёмами
    // «при попадании»; удар «при попадании» без запаса (кара) с уроном себе и лечением, если цель умерла
    if (b.wN > 0) {
        long long avail = remain - b.wcost - b.acost - b.rcost;
        auto addSpec = [&](Spec sp) {
            if (b.abil.size() >= 12) return false;
            sp.price = specPrice(sp, C);
            const long long fee = abilFee(C, b.abil.size() + 1) - abilFee(C, b.abil.size());
            if (sp.price + fee > avail / 3) return false;
            avail -= sp.price + fee;
            remain -= sp.price + fee;
            spent += sp.price + fee;
            b.abil.push_back(sp);
            g_bstate.nAbil = (int)b.abil.size();
            markSpec(sp, b.atoms);
            if (fee > 0) mark(AT_NABIL);
            return true;
        };
        // доспехи и щит (v21): двуручное (обе руки) или универсальное (кость больше двумя руками) ближнее оружие
        if (b.wRange <= 5 && bern(BP_TWOH, 0.20)) b.wTwoH = true;
        if (b.wRange <= 5 && !b.wTwoH && bern(BP_VERS, 0.25)) {
            int k = 0;
            while (k < DICE_N - 1 && DICE[k] <= b.wS) k++;
            if (DICE[k] > b.wS) {
                b.wVers = DICE[k];
                const long long vp = weaponHandsPrice(b, C);
                if (vp > avail / 4) b.wVers = 0;
            }
        }
        if (b.wTwoH) {
            const long long r2 = -weaponHandsPrice(b, C);   // возврат
            spent -= r2;
            remain += r2;
            avail += r2;
        } else if (b.wVers) {
            const long long vp = weaponHandsPrice(b, C);
            b.wcost += vp;
            avail -= vp;
        }
        if (b.wRange <= 5 && bern(BP_WHEAVY, b.wTwoH ? 0.6 : 0.1)) b.wHeavy = true;   // тяжёлое (v21)
        if (b.wRange <= 5 && !b.wTwoH && !b.wHeavy && bern(BP_WLIGHT, 0.30)) b.wLight = true;
        if (b.wRange > 5 && bern(BP_WLONG, 0.50)) {
            const int lng = magN(MG_WLONG, std::min(b.wRange + 5, MAX_FT_G), MAX_FT_G, 5);
            const long long lp = weaponLongPrice(C, b.wN, b.wS, b.wRange, lng, b.reach, b.wAtt);
            if (lp <= avail / 4) {
                b.wLong = lng;
                b.wcost += lp;
                avail -= lp;
                mark(AT_WLONG);
            }
        }
        if (b.wLight && bern(BP_TWF, 0.35)) {
            Spec o;
            o.offhand = o.bonus = true;
            o.range = 5;
            o.delivery = 0;
            o.dmgN = b.wN;
            o.dmgS = b.wS;
            o.dtype = b.wType;
            o.twfMod = bern(BP_TWFMOD, 0.5);
            addSpec(o);
        }
        if (bern(BP_POOL, 0.15)) {
            b.poolN = magN(MG_POOLN, 1, MAX_COUNT_G);
            b.poolS = DICE[catN(BC_POOLS, DICE_N)];
            int made = 0;
            for (int k = 0, n = 1 + catN(BC_MANK, 3); k < n; k++) {
                Spec m;
                m.onHit = m.pool = true;
                m.poolN = b.poolN;
                m.poolS = b.poolS;
                m.range = 5;
                m.delivery = bern(BP_MANSAVE, 0.5) ? 1 : 0;
                const int e = catN(BC_MANEFF, 4);
                if (e == 1) {
                    m.cond = 1 + catN(BC_COND, C_N - 1);
                    m.condRounds = 1;
                } else if (e == 2)
                    m.pushFt = magN(MG_PUSH, 5, MAX_FT_G, 5);
                else if (e == 3)
                    m.disarm = true;
                m.saveStat = m.disarm ? STR : meaningSave(m);
                if (m.delivery == 1 && !m.cond && !m.pushFt && !m.disarm) m.delivery = 0;   // спасаться не от чего
                made += addSpec(m);
            }
            if (!made) b.poolN = 0;
        }
        if (bern(BP_SMITE, 0.10)) {
            Spec m;
            m.onHit = true;
            m.range = 5;
            m.delivery = 0;
            m.dmgN = magN(MG_DMGN, 1, MAX_DICE_G);
            m.dmgS = DICE[catN(BC_DMGS, DICE_N)];
            m.dtype = pickAbilityType();
            const int u = catP(BC_USES, 4, USES_CUM);
            m.uses = u == 3 ? UNL : magN(MG_USES, 1, MAX_COUNT_G);
            if (bern(BP_SELFDMG, 0.3)) {
                m.selfN = magN(MG_SELFN, 1, MAX_DICE_G);
                m.selfS = DICE[catN(BC_DOTS, DICE_N)];
            }
            if (bern(BP_KILLHEAL, 0.3)) {
                m.killN = magN(MG_HEALN, 1, MAX_DICE_G);
                m.killS = DICE[catN(BC_HEALS, DICE_N)];
            }
            addSpec(m);
        }
        // союзники (v21): реакция за союзника рядом — помеха атаке по нему или удар оружием по атакующему
        if (bern(BP_PROTECT, 0.06) || bern(BP_STRIKE, 0.06)) {
            Spec p;
            p.self = true;
            p.react = 5;
            p.range = 5;
            p.uses = UNL;
            if (bern(BP_STRIKE, 0.5)) p.strike = true;
            else p.protect = true;
            addSpec(p);
        }
    }
    // приказ союзнику атаковать (v21): имеет смысл с приспешниками
    if (hasSummonSpec(b) && bern(BP_CMDATK, 0.25)) {
        Spec c;
        c.self = c.ally = c.cmdAtk = true;
        c.bonus = true;
        c.range = 30;
        c.uses = UNL;
        c.price = specPrice(c, C);
        const long long fee = abilFee(C, b.abil.size() + 1) - abilFee(C, b.abil.size());
        if (b.abil.size() < 12 && c.price + fee <= (remain - b.wcost - b.acost - b.rcost) / 4) {
            remain -= c.price + fee;
            spent += c.price + fee;
            b.abil.push_back(c);
            g_bstate.nAbil = (int)b.abil.size();
            markSpec(c, b.atoms);
            if (fee > 0) mark(AT_NABIL);
        }
    }
    // «событие → эффект» (v21): до двух; событие, подходящий эффект, применений за бой
    for (int k = 0; k < 2 && bern(BP_TRIG, k == 0 ? 0.30 : 0.20); k++) {
        Trig t;
        t.on = bern(BP_TRIGDMGT, 0.08) ? T_DMGTYPE : (bern(BP_TRIGCHARGE, 0.06) ? T_CHARGE : catN(BC_TRIGON, 12));   // в слоте 12 вариантов
        if (t.on == T_DMGTYPE) t.arg = pickAbilityType();   // тип урона, на который срабатывает
        bool any = false;   // у события может не быть разрешённых эффектов (например, «после Рывка» пока выключено)
        for (int x = 0; x < X_N; x++) any = any || trigAllowed(t.on, x);
        if (!any) continue;
        do t.what = catN(BC_TRIGDO, X_N);
        while (!trigAllowed(t.on, t.what));
        t.n = magN(MG_TRIGN, 1, MAX_DICE_G);
        t.s = DICE[catN(BC_TRIGS, DICE_N)];
        if (t.what == X_COND || t.what == X_SELFCOND) t.cond = 1 + catN(BC_COND, C_N - 1);
        if (bern(BP_TRIGLIM, 0.5)) t.uses = magN(MG_TRIGU, 1, MAX_COUNT_G);
        if (t.what == X_STAY1) t.uses = 1;
        const long long tp = trigPrice(t, b, C);   // после оружия: атака бонусом стоит по цене удара оружием
        if (tp > (remain - b.wcost - b.acost - b.rcost) / 5) continue;
        remain -= tp;
        spent += tp;
        b.trigs.push_back(t);
        markTrig(t, b.atoms);
    }
    long long rest = remain - b.wcost - b.acost - b.rcost;
    const long long restFull = rest + RESERVE;   // то, что делится на характеристики, КД и ХП (резерв возвращается)
    const int mains[5] = {STR, DEX, INT, WIS, CHA};
    b.mainStat = mains[catN(BC_MAIN, 5)];
    for (auto& sp : b.abil)
        if (sp.sbAmt) {
            double q = rand01();
            sp.sbStat = q < 0.45
                            ? b.mainStat
                            : (q < 0.70 ? ((b.wAmmo || b.wFinesse) ? DEX : STR) : (q < 0.85 ? CON : irand(STAT_N)));
        }
    std::array<double, STAT_N> w{};
    for (int s2 = 0; s2 < STAT_N; s2++) w[s2] = warp(BC_STAT + s2, rand01()) + 0.1;
    w[b.mainStat] += 1.0;
    double wsum = 0;
    for (double x : w) wsum += x;
    long long statBudget = (long long)(rest * (0.35 + 0.25 * warp(BW_STAT, rand01())));
    long long acBudget = (long long)(rest * (0.10 + 0.15 * warp(BW_AC, rand01())));
    long long statSpent = 0;
    for (int i = 0; i < STAT_N; i++) {
        // характеристика от 1 до STAT_MAX (0 — недееспособное существо); остаток бюджета уходит в ХП
        b.stats[i] = std::clamp(maxV((long long)(statBudget * w[i] / wsum)), 1, STAT_MAX);
        statSpent += tri(b.stats[i]);
    }
    // КД растёт с той же скоростью, что и бонус атаки (иначе цены плывут с бюджетом)
    b.acV = std::min(maxV(acBudget) / 2, AC_MAX - 10);   // столько же КД, сколько давала прежняя покупка на эти очки
    // доспехи и щит (v21): вид доспеха (тяжёлый — при СИЛ от 13), щит — если обе руки не заняты
    b.armor = catN(BC_ARMOR, AR_N);
    if (b.armor == AR_NONE && bern(BP_UNARM, 0.20)) {   // пакет атомов 3: защита без доспеха
        b.unarmoredStat = bern(BP_UNARMSTAT, 0.5) ? WIS : CON;
        mark(AT_UNARMORED);
    }
    if (b.armor == AR_HEAVY && b.stats[STR] < 13) b.armor = AR_MEDIUM;
    b.armStealth = b.armor == AR_HEAVY || (b.armor == AR_MEDIUM && bern(BP_ARMSTEALTH, 0.3));
    b.shield = !(b.wN > 0 && b.wTwoH) && !hasOffhand(b) && bern(BP_SHIELD, 0.25);
    b.noArmProf = (b.armor || b.shield) && bern(BP_NOARMPROF, 0.05);
    if (bern(BP_SIZE, 0.30)) b.size = catN(BC_SIZE, 6);   // размер (v21): чаще средний
    if (restFull - statSpent - acCost(0) - armorPrice(b, C) - sizePrice(b, C) < 2) b.size = 2;
    while (b.shield && restFull - statSpent - acCost(b.acV) - armorPrice(b, C) - sizePrice(b, C) < 2 && b.acV == 0) b.shield = false;
    while (b.acV > 0 && restFull - statSpent - acCost(b.acV) - armorPrice(b, C) - sizePrice(b, C) < 2) b.acV--;   // на копеечных бюджетах минимальные характеристики дороже КД
    if (restFull - statSpent - acCost(b.acV) - armorPrice(b, C) - sizePrice(b, C) < 2) b.armor = AR_NONE, b.shield = b.armStealth = b.noArmProf = false;
    b.ac = calcAC(b);
    markArmor(b, b.atoms);
    // Пересчёт цен по готовому телу (после теста 4 ноября): доп. атаки, бафф оружия, бонус КД и концентрация зависят от
    // характеристик и КД, а они покупаются последними. Разница — из хитов; не хватает — снимаем КД, затем характеристики.
    const PriceCtx pcPrev = g_pc;
    long long dPrice = 0;   // насколько подорожало купленное до характеристик
    auto reprice = [&]() {
        setPriceCtx(b);
        if (b.wN > 0) {
            long long w = wpCostOf(C, b.wN, b.wS, b.wRange, b.reach, b.wAtt, b.wFinesse, b.wAmmo);
            if (b.wVers > b.wS && !b.wTwoH) w += weaponHandsPrice(b, C);
            if (b.wLong > b.wRange) w += weaponLongPrice(C, b.wN, b.wS, b.wRange, b.wLong, b.reach, b.wAtt);
            dPrice += w - b.wcost;
            b.wcost = w;
        }
        long long a = 0;
        for (auto& q : b.alt) a += (q.cost = wpPrice(q, C));
        dPrice += a - b.acost;
        b.acost = a;
        for (auto& sp : b.abil) {
            const long long np = specPrice(sp, C);
            dPrice += np - sp.price;
            spent += np - sp.price;
            sp.price = np;
        }
        for (auto& r : b.rules) {
            const long long np = rulePrice(r, b, C);
            dPrice += np - r.price;
            spent += np - r.price;
            r.price = np;
        }
    };
    // хиты не ниже половины прежних: сначала снимаем лишние атаки (их цена выросла сильнее всего), потом КД, потом характеристики
    const long long lo0 = restFull - statSpent - acCost(b.acV) - armorPrice(b, C) - sizePrice(b, C), need = std::max(2LL, lo0 / 2);
    reprice();
    for (int guard = 0; guard < 400 && restFull - dPrice - statSpent - acCost(b.acV) - armorPrice(b, C) - sizePrice(b, C) < need; guard++) {
        if (b.wN > 0 && b.wAtt > 1) b.wAtt = std::max(1, b.wAtt * 3 / 4);
        else if (b.acV > 0) b.acV--;
        else {
            int hi = 0;
            for (int i = 1; i < STAT_N; i++) if (b.stats[i] > b.stats[hi]) hi = i;
            if (b.stats[hi] <= 1) break;
            statSpent -= tri(b.stats[hi]) - tri(b.stats[hi] - 1);
            b.stats[hi]--;
        }
        b.ac = calcAC(b);
        reprice();
    }
    g_pc = pcPrev;
    {   // атак могло стать меньше: метка «доп. атака» — по содержимому
        bool many = b.wN > 0 && b.wAtt >= 2;
        for (auto& q : b.alt) many = many || q.att >= 2;
        if (!many) b.atoms.w[AT_WPNATT >> 6] &= ~(1ULL << (AT_WPNATT & 63));
    }
    // ИНТ<=3: взять в руки оружие нечем — только укус и когти
    if (b.wN > 0 && b.stats[INT] <= 3) b.wNatural = true;
    long long leftover = restFull - dPrice - statSpent - acCost(b.acV) - armorPrice(b, C) - sizePrice(b, C);
    b.hp = std::max(1, (int)(leftover / 2));
    b.cost = spent + b.wcost + b.acost + b.rcost + statSpent + acCost(b.acV) + armorPrice(b, C) + sizePrice(b, C) + 2LL * b.hp;
    // подавление осталось только если есть что подавлять
    if (b.suppMask) {
        bool has = ((b.suppTgt & 1) && b.regenN) || ((b.suppTgt & 2) && b.auraRad > 0) ||
                   ((b.suppTgt & 4) && (b.resMask | b.immMask || b.resNM || b.immNM || hasResRule(b)));
        if (has)
            mark(AT_SUPP);
        else {
            b.suppMask = 0;
            b.suppTgt = 0;
        }
    }
    g_B = prevB;
    return b;
}
Boss makeBoss(long long budget, const Coef& C, bool allowSummon, bool force) {
    Boss b;
    for (int t = 0; t < 40; t++) {
        b = makeBossOnce(budget, C, allowSummon, force);
        if (!force || !allowSummon || hasSummonSpec(b)) break;
    }
    return b;
}
// Пара соперников: один (случайно выбранный) босс ОБЯЗАТЕЛЬНО с миньонами, второй — по желанию (50%)
void makePair(long long B, const Coef& C, Boss& A, Boss& Bo) {
    int fs = irand(2);
    Boss f = makeBoss(B, C, true, true), o = makeBoss(B, C, true, false);
    if (fs == 0) {
        A = std::move(f);
        Bo = std::move(o);
    } else {
        A = std::move(o);
        Bo = std::move(f);
    }
}

// ---------------------------------------------------------------------------
// Мир, бойцы, движение
// ---------------------------------------------------------------------------
struct Fighter {
    Boss b;
    mutable long long fpKey = -1;   // кэш квадрата крупного (fpN): узел и версия карты
    mutable int fpVal = 1;
    int team = 0;
    int hp = 1, maxHp = 1;
    int hazTurn = -1;   // номер хода (g_turnSerial), когда его уже задела опасная зона
    bool up = false;    // стоит на втором ярусе (мост, балкон, навес)
    int alt = 0;        // высота полёта над землёй (настилом), уровней по 10 фт (v21)
    int lairLast = 0;   // прошлое действие логова (1 обвал, 2 трясина): подряд одно и то же нельзя
    // превращение (v21): в облике — тело шаблона со своим запасом хитов; свой облик (Boss) и хиты ждут возврата
    bool inForm = false;
    int formHpSave = 0, formMaxSave = 0;
    std::shared_ptr<Boss> formOrig;
    int x = 0, y = 0, init = 0;
    // cimm: невосприимчивость после окончания состояния
    int cond[C_N] = {};
    int cstat[C_N] = {};
    int cdc[C_N] = {};
    int cimm[C_N] = {};
    int cgrit[C_N] = {};   // нарастающая стойкость (v21, этап 7): проваленных повторных спасбросков от этого жёсткого контроля подряд
    bool hidden = false, fresh = false;
    // приспешник: кто призвал (индекс бойца) и какой способностью; vanished — исчез (концентрация призыва снята)
    int summoner = -1, sumSpec = -1;
    bool vanished = false;
    std::vector<int> sumMade;   // у призывателя: призвано каждой способностью за бой (технический потолок)
    int sumTurn = -1, sumTurnN = 0;   // призывов в раунде sumTurn (растяжка)
    unsigned onceUsed = 0;   // правила «когда → что» с уроном «раз в ход», сработавшие в этот ход (биты по номеру правила)
    int poolLeft = 0;   // кости запаса (приёмы)
    int helpBy = -1;      // Помощь (v21): кто отметил меня — первая атака его союзника по мне с преимуществом
    mutable std::vector<int> trigLeft;   // «событие → эффект» (v21): сколько раз ещё сработает (переброс спаса — и в const-проверках)
    bool advNext = false, pendBonus = false;   // преимущество на следующую атаку; ждёт атака бонусным действием
    int pendSpeed = 0, pendTgt = -1;           // добавка к скорости этого хода; цель атаки бонусом
    int noOAvs = -1;   // Подвижный (v21): этот боец не провоцирует от меня до конца хода того, кто меня ударил
    bool readied = false; // Подготовка (v21): ударю реакцией, когда враг войдёт в досягаемость
    int readyAbil = -1;   // 8 ноября: подготовленное действие — оружие (−1) или способность k
    int readyTrig = 1;    // условие: 1 — враг вошёл в досягаемость (дальность способности), 2 — враг применил способность в ней
    bool wAtkTurn = false, disarmed = false;   // атаковал оружием в этот ход (для второй руки); обезоружен
    bool riderUsed = false, reactionUsed = false, dodging = false, disengaged = false,
         wasReckless = false;
    // источники очарования и захвата   // legLeft — очки легендарных действий   // lrLeft — оставшиеся заряды
    // легендарного сопротивления
    int poisonTick = 0;
    int lrLeft = 0;
    int legLeft = 0;
    int charmSrc = -1, grapSrc = -1;
    // действующий бафф характеристики (значение прибавлено прямо к b.stats)
    int sbStat = 0, sbAmt = 0, sbRounds = 0;
    int buffRounds = 0, buffN = 0, buffS = 4;
    // урон по времени, висящий на бойце
    int dotN = 0, dotS = 6, dotType = DT_FIRE, dotRounds = 0;
    // политика этой команды
    const Pol* pol = &g_pol;
    // ходом управляет обучаемый бот
    bool rl = false;
    // подавление пассивок (ходов осталось), идёт ли свой ход
    int supp = 0;
    bool inTurn = false;
    // концентрация (индекс способности; СЛ проверки за каждое попадание с последней проверки), чьё это DoT/состояние
    // (+1), всплески, ячейки
    // погона (DMG): истощение (0–5), рывки за бой, лимит рывков без риска (3 + мод. ТЕЛ), рывок в этом ходу, осложнение, ждущее бойца, штраф к скорости в этом ходу, побег
    int exh = 0, dashes = 0, dashLimit = 3, comp = 0, speedPen = 0;
    // свои случайные числа для решений бота (шум, послушание, направление отхода): броски кубиков идут из общего rng,
    // поэтому ход, записанный примитивами и повторённый, даёт тот же бой (v21, №4)
    Rng ai;
    bool dashedNow = false, fled = false;
    bool struckFoe = false;   // в этот ход атаковал врага или применил по нему способность (погоня, v21 №13)
    int fledWhy = 0;   // 1 вышел за край арены, 2 оторвался от преследователя, 3 преследователь выбился из сил
    int concSpec = -1, dotConc = 0, surgeLeft = 0;
    std::vector<int> concDCs;
    int condConc[C_N] = {};
    int slotLeft[10] = {};
    // невидимость: ходов осталось (не спадает от атаки, в отличие от «скрытности»)
    int invisRounds = 0;
    // временные хиты; бонус КД и сколько своих ходов он ещё действует
    int temp = 0, acBuff = 0, acBuffRounds = 0;
    // кто последним нанёс урон (для реакции «мне нанесли урон»; −1 — никто), сбрасывается после проверки реакций
    int hurtBy = -1;
    std::vector<int> uses;
    std::vector<int> usedRound;   // раунд последнего применения способности k (для «не два раунда подряд»)
    std::vector<int> immAbil;     // «невосприимчив после успеха»: ключи (заклинатель × 64 + способность)
    // пакет атомов 2: состояние от механик (не входит в C_N — сеть-боец считает состояния по своей таблице)
    bool restrByGrab = false;     // опутан, пока схвачен
    int grabDotN = 0, grabDotS = 6, grabDotType = DT_BLUDGEONING, grabDotSrc = -1;   // урон в начале хода, пока схвачен
    int images = 0;               // копии-отражения
    int globeLvl = 0, globeR = 0, globeRounds = 0;   // своя сфера неуязвимости
    int banished = 0, banishSrc = -1;   // изгнан на N раундов (вне боя)
    int flyBuff = 0;              // полёт на N раундов (b.fly был false)
    int extraTurns = 0;           // остановка времени: ещё ходов подряд
    int growRounds = 0;           // увеличен на N раундов
    int lightRounds = 0, lightR = 0;   // свет от способности
    int turnX0 = -1, turnY0 = -1; // где начал ход (наскок: разбег)
    int mod(int s) const { return modOf(b.stats[s]); }
    int mainMod() const { return mod(b.mainStat); }
    // боеприпасное — только ЛОВ, метательное — СИЛ (или фехтовальное)
    int wMod() const {
        if (b.wRange > 5) return b.wAmmo ? mod(DEX) : (b.wFinesse ? std::max(mod(STR), mod(DEX)) : mod(STR));
        return b.wFinesse ? std::max(mod(STR), mod(DEX)) : mod(STR);
    }
    int dc() const { return 8 + b.prof + mainMod(); }
    // бонус атаки оружием (мастерство — если владеет своим оружием) и способностью (мастерство всегда)
    int wAtk() const { return wMod() + (b.wNoProf ? 0 : b.prof); }
    int sAtk() const { return mainMod() + b.prof; }
    // бонус проверки навыка: модификатор + мастерство при владении + ещё раз при экспертизе
    int skill(int k) const { return mod(SKST[k]) + (((b.skillProf >> k) & 1u) ? b.prof : 0) + (((b.skillExp >> k) & 1u) ? b.prof : 0); }
};
// Реакция — один путь списания для всех реакций (провоцированная атака, Парирование, контратака, перенаправление,
// способность-реакция)
inline void spendReaction(Fighter& f) {
    f.reactionUsed = true;
}
// Метрики использования (ТЗ v21, №6) за бой, по главным боссам 0 и 1: атак оружием и способностями (из них — из-за
// пределов досягаемости цели), пройдено фт (из них — не на сближение: отход, выход из укрытия, возврат), применений
// скрытности, невидимости, тьмы. Обнуляются в начале боя; калибровка по ним не снижает цену неиспользуемых атомов
enum UseKind { U_WATK, U_WOUT, U_SATK, U_SOUT, U_FT, U_FTAWAY, U_HIDE, U_INVIS, U_DARK, U_N };
thread_local long long g_use[2][U_N] = {};
// применений способностей по атомам (их отметки markSpec) за бой, у главных боссов 0 и 1 — используемость атомов способностей
thread_local long long g_castAtom[2][AT_N] = {};

constexpr int MAXT = 64;   // команд в бою — технический предохранитель (v21: ограничения нет, только он)
thread_local unsigned g_mapSerial = 0;   // версии карт (World::mapVer) — общие для потока, чтобы не совпадали у разных боёв
struct World {
    // diff — труднопроходимая местность, dark — тьма
    bool wall[W][W] = {};
    bool climb[W][W] = {};
    bool diff[W][W] = {};
    bool dark[W][W] = {};
    // арена — прямоугольник aw × ah клеток (мин. 5×5), всё за его пределами — стена; theme: 0 дикая местность, 1 город
    int aw = W, ah = W, theme = 0;
    bool pit[W][W] = {};                  // ущелье: пешком не пройти, обзор не закрывает, мост — обычные клетки в нём
    bool water[W][W] = {};                // ручей (труднопроходим: diff); отдельный слой нужен для рисунка и описания
    unsigned char height[W][W] = {};      // возвышенность: 0, 1, 2 (по 10 фт); подъём +5 фт движения за уровень, сброс вниз — падение
    bool tree[W][W] = {};                 // дерево (высокий предмет): обзор закрывает, внизу не пройти — только залезть (вершина на TREE_UP выше)
    unsigned char haz[W][W] = {};         // опасная зона: вид (HAZ), 0 — нет
    bool ladder[W][W] = {};               // лестница: с неё и на неё — любой перепад высоты (лезть: +5 фт за уровень)
    unsigned char deck[W][W] = {};        // второй ярус (мост, балкон, навес, потолок): уровень его верха, 0 — нет
    short dhp[W][W] = {};                 // хиты второго яруса (обрушить)
    unsigned char door[W][W] = {};        // дверь в проёме: 0 нет, 1 закрыта (как стена: не пройти, не видно), 2 открыта
    bool day = true;                      // день: под открытым небом — солнце (солнечная чувствительность, v21)
    // версия карты: растёт, когда меняются стены, ямы, деревья, настилы (кэш квадратов крупных). Новый мир сразу берёт
    // свою версию: с 0 у всех кэш потока принимал за свои клетки прошлого боя на том же адресе (бой зависел от предыдущих)
    unsigned mapVer = ++g_mapSerial;
    bool strong[W][W] = {};               // крепкая стена (крепость, башни): больше хитов
    bool mainc[W][W] = {};                // клетка основной связной части арены (там начинают бой)
    unsigned long long wseed = 0;         // мир, из которого вырезана арена (0 — не из мира), и угол участка
    int wsize = 0, wx = 0, wy = 0;
    int hazN = 2, hazDC = 13;             // урон опасной зоны — hazN к10, спасбросок СЛ hazDC (по силе боссов боя)
    short ohp[W][W] = {};                 // хиты объекта в клетке (стена, дерево, укрытие); 0 — неразрушим (край арены, барьеры способностей)
    // погоня: идёт ли, кто преследуемый (индекс босса), не терял ли он из виду преследователя за раунд
    bool chaseOn = false, chaseSeen = true;
    int chasePrey = -1;
    // cmd — цель, выбранная главным боссом команды: миньоны бьют её
    std::vector<Fighter> f;
    int cmd[MAXT] = {};   // по команде (заполняется в начале боя)
    // динамические изменения арены от способностей: {x, y, вид (1 временная стена, 2 труднопроходимая местность, 3 тьма), раундов до исчезновения (−1 навсегда)}
    std::vector<std::array<int, 4>> dyn;
    // туман войны (v21, №12): что сторона знает о врагах — {x, y, раунд, когда видели} по индексу бойца (−1 — не знает);
    // раунд, когда сторона последний раз видела хоть одного врага
    std::vector<std::array<int, 3>> known[MAXT];
    int knownRound[MAXT] = {};
    // команды (v21): бойцы 0..nLead−1 — главные (из состава боя), остальные — приспешники; nTeams — команд в бою; kills —
    // убитых врагов на счету команды (очки, если бой дошёл до предела раундов)
    int nTeams = 2, nLead = 2;
    mutable int kills[MAXT] = {};
};
// ---- объекты и высота (v21, местность) ----
// Уровень клетки — в единицах по 10 фт: земля (height) плюс вершина дерева, если существо на нём. Расстояние между
// клетками — трёхмерное, как в PHB: 5 фт × наибольшее из смещений по x, y и высоте (уровень = 2 клетки).
// Объекты — стена, дерево, укрытие — имеют КД и хиты (DMG «Объекты»: дерево КД 15, камень КД 17; иммунитет к яду и
// психическому урону). Разрушенный объект оставляет обломки — труднопроходимую местность.
constexpr int TREE_UP = 2, WALL_UP = 3;   // дерево — 20 фт, стена — 30 фт над землёй
constexpr int OBJ_WALL_HP = 54, OBJ_TREE_HP = 27, OBJ_CLIMB_HP = 27, OBJ_STRONG_HP = 120, OBJ_DOOR_HP = 18;
// Опасные зоны (v21, местность): вещество задаёт только тип урона и спасбросок. Как в DMG: урон, когда существо впервые
// за ход входит в зону или начинает в ней ход; спасбросок — половина. Летун не касается жидкостей и льда, но не облаков.
struct HazKind { const char* name; int dtype, save; bool flySafe; };
constexpr HazKind HAZ[] = {{"", 0, 0, true},
                           {"лава", DT_FIRE, DEX, true},          {"кислота", DT_ACID, DEX, true},
                           {"ядовитый дым", DT_POISON, CON, false}, {"ледяное поле", DT_COLD, CON, true},
                           {"грозовое поле", DT_LIGHTNING, DEX, false}, {"некротический туман", DT_NECROTIC, CON, false}};
constexpr int HAZ_N = 7;
inline int zAt(const World& w, int x, int y) { return w.height[y][x] + (w.tree[y][x] ? TREE_UP : 0); }
// Второй ярус (2.5D): в клетке земля (height, дерево) и, если есть, верхний настил deck. Под настилом пройти можно,
// если хватает высоты по росту (рост: до среднего — 1 уровень, большой — 2, огромный — 3, громадный — 4); настил, на
// который не забраться, — просто потолок. Шаг между узлами (клетка, ярус): перепад до 1 уровня — подъём (+5 фт за
// уровень), больше — обрыв: только по лестнице, на дерево и с него, летуну — под открытым небом (не под настилом).
constexpr int DECK_HP = 40;
inline int sizeLv(const Fighter& f) { return f.b.size <= 2 ? 1 : f.b.size - 1; }
inline int nodeZ(const World& w, int x, int y, int l) { return l ? w.deck[y][x] : zAt(w, x, y); }
inline int zF(const World& w, const Fighter& f) { return nodeZ(w, f.x, f.y, f.up ? 1 : 0) + f.alt; }
// Высота полёта (v21): летун висит на alt уровней (по 10 фт) над землёй или настилом под собой — до ALT_MAX, а под настилом
// (потолком) — пока помещается по росту. Подняться или опуститься на уровень — 10 фт движения.
constexpr int ALT_MAX = 6;
inline bool canStayAloft(const Fighter& f);   // держится в воздухе (ниже)
inline int maxAltAt(const World& w, const Fighter& f, int x, int y, int l) {
    if (!f.b.fly) return 0;
    int m = ALT_MAX;
    const int n = sizeLv(f) > 1 ? sizeLv(f) : 1;
    for (int dy = 0; dy < n; dy++)
        for (int dx = 0; dx < n; dx++) {
            const int cx = x + dx, cy = y + dy;
            if (cx >= W || cy >= W || l || !w.deck[cy][cx]) continue;
            m = std::min(m, std::max(0, w.deck[cy][cx] - zAt(w, cx, cy) - sizeLv(f)));
        }
    return m;
}
inline int dist3(int x0, int y0, int z0, int x1, int y1, int z1) { return 5 * std::max({std::abs(x1 - x0), std::abs(y1 - y0), 2 * std::abs(z1 - z0)}); }
// Клетки по размеру (PHB): до среднего — 1 клетка, большой — 2×2, огромный — 3×3, громадный — 4×4. Позиция бойца (x, y) —
// левая верхняя клетка его квадрата. Расстояние — между ближайшими клетками квадратов, обзор — от любой клетки до любой,
// область задевает, если накрыла хоть одну клетку
inline int fpFull(const Fighter& f) { return sizeLv(f); }
int fpN(const Fighter& f);   // занятый квадрат с учётом протискивания (ниже)
inline int fpGap(int a0, int an, int b0, int bn) { return std::max({0, b0 - (a0 + an - 1), a0 - (b0 + bn - 1)}); }
inline int distFP(int ax, int ay, int az, int an, int bx, int by, int bz, int bn) {
    return 5 * std::max({fpGap(ax, an, bx, bn), fpGap(ay, an, by, bn), 2 * std::abs(az - bz)});
}
inline bool fpOverlap(int ax, int ay, int an, int bx, int by, int bn) { return ax < bx + bn && bx < ax + an && ay < by + bn && by < ay + an; }
inline bool nodeOK1(const World& w, const Fighter& f, int x, int y, int l) {
    if (x < 0 || y < 0 || x >= w.aw || y >= w.ah || w.wall[y][x]) return false;
    if (l) return w.deck[y][x] > 0;
    return (!w.pit[y][x] || f.b.burrowS) && (!w.deck[y][x] || w.deck[y][x] - zAt(w, x, y) >= sizeLv(f));   // копатель — и под ущельем
}
// квадрат n×n в узле (клетка, ярус): весь на арене, без стен и ям, без деревьев (крупный на дерево не лезет), перепад
// внутри квадрата не больше уровня
inline bool nodeOKn(const World& w, const Fighter& f, int x, int y, int l, int n) {
    if (n == 1) return nodeOK1(w, f, x, y, l);
    if (!nodeOK1(w, f, x, y, l)) return false;
    const int z0 = l ? w.deck[y][x] : zAt(w, x, y);
    for (int dy = 0; dy < n; dy++)
        for (int dx = 0; dx < n; dx++) {
            const int cx = x + dx, cy = y + dy;
            if (!nodeOK1(w, f, cx, cy, l) || (!l && w.tree[cy][cx]) || std::abs((l ? w.deck[cy][cx] : zAt(w, cx, cy)) - z0) > 1) return false;
        }
    return true;
}
// клетка стоит 10 фт: лазалка (кроме лазуна и копателя) или труднопроходимая местность (кроме лёгкой поступи, копателя и —
// для воды — пловца)
inline bool roughCell(const World& w, const Fighter& f, int x, int y, int l) {
    if (l || f.b.burrowS) return false;
    if (w.climb[y][x] && !f.b.climbS) return true;
    return w.diff[y][x] && !f.b.ignDiff && !(f.b.swimS && w.water[y][x]);
}
// Протискивание (PHB): крупное существо может втиснуться в место на размер меньше — тогда движение вдвое дороже, его
// атаки и спасброски ЛОВ с помехой, атаки по нему с преимуществом.
// Кэш узлов для крупного (поиск пути проверяет узел несколько раз): квадрат (0 — не встать, n или n−1) и «неровно» (лазалка
// или труднопроходимая местность хоть под одной клеткой). Сбрасывается, когда меняются боец, его размер или карта.
static thread_local unsigned char fitV[2 * W * W];
static thread_local unsigned fitSt[2 * W * W], fitCur = 0;
static thread_local const void* fitOwnerW = nullptr;
static thread_local const void* fitOwnerF = nullptr;
static thread_local unsigned fitVer = 0;
static thread_local int fitSize = -1;
inline unsigned char fitInfo(const World& w, const Fighter& f, int x, int y, int l) {
    const int key = f.b.size | (f.b.ignDiff ? 256 : 0) | (f.b.climbS ? 512 : 0) | (f.b.swimS ? 1024 : 0) | (f.b.burrowS ? 2048 : 0);
    if (fitOwnerW != &w || fitOwnerF != &f || fitVer != w.mapVer || fitSize != key) {
        fitOwnerW = &w;
        fitOwnerF = &f;
        fitVer = w.mapVer;
        fitSize = key;
        if (++fitCur == 0) {
            std::memset(fitSt, 0, sizeof fitSt);
            fitCur = 1;
        }
    }
    if (x < 0 || y < 0 || x >= W || y >= W) return 0;
    const int k = (l ? W * W : 0) + y * W + x;
    if (fitSt[k] == fitCur) return fitV[k];
    const int n = fpFull(f);
    int m = nodeOKn(w, f, x, y, l, n) ? n : (nodeOKn(w, f, x, y, l, n - 1) ? n - 1 : 0);
    bool rough = false;
    for (int dy = 0; dy < m && !rough; dy++)
        for (int dx = 0; dx < m && !rough; dx++)
            rough = roughCell(w, f, x + dx, y + dy, l);
    fitSt[k] = fitCur;
    return fitV[k] = (unsigned char)(m | (rough ? 8 : 0));
}
inline bool nodeOK(const World& w, const Fighter& f, int x, int y, int l) {
    return fpFull(f) == 1 ? nodeOK1(w, f, x, y, l) : (fitInfo(w, f, x, y, l) & 7) != 0;
}
// квадрат f, стоящего в узле: полный или (протиснулся) на размер меньше
inline int fpAt(const World& w, const Fighter& f, int x, int y, int l) {
    if (fpFull(f) == 1) return 1;
    const int m = fitInfo(w, f, x, y, l) & 7;
    return m ? m : fpFull(f);
}
inline bool stepOK(const World& w, const Fighter& f, int x, int y, int l, int nx, int ny, int nl) {
    if (!nodeOK(w, f, nx, ny, nl)) return false;
    const int dz = std::abs(nodeZ(w, nx, ny, nl) - nodeZ(w, x, y, l));
    if (dz <= 1 || w.ladder[y][x] || w.ladder[ny][nx]) return true;
    if (!l && !nl && (f.b.climbS || f.b.burrowS)) return true;   // лазун — по скале, копатель — сквозь землю
    if (!l && !nl && (w.tree[y][x] || w.tree[ny][nx]) && dz <= TREE_UP + 1) return true;
    return f.b.fly && !w.deck[y][x] && !w.deck[ny][nx];
}
inline bool isObject(const World& w, int x, int y) { return x >= 0 && y >= 0 && x < w.aw && y < w.ah && (w.wall[y][x] || w.tree[y][x] || w.climb[y][x] || w.door[y][x]); }
inline int objAC(const World& w, int x, int y) { return w.wall[y][x] ? 17 : ((w.tree[y][x] || w.door[y][x]) ? 15 : 17); }
inline int cellDist(const World* w, int x0, int y0, int x1, int y1) {
    const int dz = w ? 2 * std::abs(zAt(*w, x0, y0) - zAt(*w, x1, y1)) : 0;
    return 5 * std::max({std::abs(x1 - x0), std::abs(y1 - y0), dz});
}
void hazardHit(World& w, Fighter& f);   // опасная зона под бойцом (ниже)
void setDoor(World& w, int x, int y, int st);   // открыть (2) или закрыть (1) дверь (ниже)
// хиты объектам: в начале боя (после генерации или карты игрока)
inline void initObjects(World& w) {
    w.mapVer = ++g_mapSerial;   // новая карта
    for (int y = 0; y < w.ah; y++)
        for (int x = 0; x < w.aw; x++) {
            w.ohp[y][x] = (short)(w.wall[y][x] ? (w.strong[y][x] ? OBJ_STRONG_HP : OBJ_WALL_HP)
                                  : (w.tree[y][x] ? OBJ_TREE_HP : (w.door[y][x] ? OBJ_DOOR_HP : (w.climb[y][x] ? OBJ_CLIMB_HP : 0))));
            w.dhp[y][x] = (short)(w.deck[y][x] ? DECK_HP : 0);
        }
}
// мир текущего боя (v21, ауры союзников): правила-ауры союзников проверяются и там, где мира под рукой нет (спасброски,
// резисты); nullptr — вне боя (тесты с ручными бойцами — ауры не действуют)
thread_local const World* g_curW = nullptr;
thread_local bool g_heavyDis = false;
thread_local bool g_countered = false;   // способность погашена контрзаклинанием (v21)   // атака тяжёлым оружием маленького существа (помеха)
void doWeapon(World& w, Fighter& me, int tIdx, int nAtt = -1, int man = -1, bool offhand = false, bool twfMod = false);
inline bool canReact(const Fighter& d);
void fireTrig(World& w, Fighter& me, int on, Fighter* tgt);   // «событие → эффект» (v21), ниже
void readyFire(World& w, int gi, int fi);   // подготовленное действие бойца gi по fi (ниже, после doSpec)
thread_local int g_trigType = -1;      // тип полученного урона для события T_DMGTYPE
thread_local bool g_saveVsAbil = false;   // спасбросок идёт от способности (сопротивление магии)
thread_local int g_curAbil = 0;           // номер способности, которая сейчас действует (невосприимчивость после успеха)
int distFt(const Fighter& a, const Fighter& b);
// правила, действующие на x: свои (k — номер правила) и правила-ауры союзников рядом (k = −1: «раз в ход» у аур нет)
template <class F>
inline void forRules(const Fighter& x, F&& f) {
    for (size_t k = 0; k < x.b.rules.size(); k++) f(x.b.rules[k], (int)k);
    if (!g_curW) return;
    for (auto& y : g_curW->f)
        if (&y != &x && y.hp > 0 && y.team == x.team)
            for (auto& r : y.b.rules)
                if (r.allyR > 0 && distFt(x, y) <= r.allyR) f(r, -1);
}
int fpN(const Fighter& f) {
    if (fpFull(f) == 1 || !g_curW) return fpFull(f);
    const long long key = ((((long long)g_curW->mapVer * W + f.y) * W + f.x) * 2 + (f.up ? 1 : 0)) * 8 + f.b.size;   // размер меняет превращение
    if (f.fpKey != key) {
        f.fpKey = key;
        f.fpVal = fpAt(*g_curW, f, f.x, f.y, f.up ? 1 : 0);
    }
    return f.fpVal;
}
inline bool squeezed(const Fighter& f) { return fpN(f) < fpFull(f); }
int distFt(const Fighter& a, const Fighter& b) {
    if (!g_curW) return distFP(a.x, a.y, 0, fpN(a), b.x, b.y, 0, fpN(b));
    return distFP(a.x, a.y, zF(*g_curW, a), fpN(a), b.x, b.y, zF(*g_curW, b), fpN(b));
}
// от бойца до клетки (земля клетки): от ближайшей клетки его квадрата
inline int distFC(const World& w, const Fighter& f, int x, int y) { return distFP(f.x, f.y, zF(w, f), fpN(f), x, y, zAt(w, x, y), 1); }
// прямая видимость: линия от глаз (уровень клетки + 5 фт) до глаз; закрывают стена (на WALL_UP выше земли), дерево (на
// TREE_UP) и земля клетки, если линия проходит ниже их верха. На ровной арене — как раньше: закрывают стены и деревья
// Настил закрывает обзор сквозь себя: линия, пересекающая его уровень над этой клеткой (в том числе над своей и над клеткой
// цели — стоящий под мостом не видит стоящего на нём), закрыта
bool losZ(const World& w, int x0, int y0, int z0, int x1, int y1, int z1) {
    int dx = std::abs(x1 - x0), dy = std::abs(y1 - y0), sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1, err = dx - dy,
        x = x0, y = y0;
    const double za = z0 + 0.5, zb = z1 + 0.5;
    const int n = std::max(dx, dy);
    auto slab = [&](int cx, int cy, double lo, double hi) { const int d = w.deck[cy][cx]; return d > 0 && std::min(lo, hi) < d && std::max(lo, hi) > d; };
    if (n == 0) return !slab(x0, y0, za, zb);   // одна клетка: стоящий на настиле и стоящий под ним
    if (slab(x0, y0, za, za + (zb - za) * 0.5 / n) || slab(x1, y1, zb - (zb - za) * 0.5 / n, zb)) return false;
    int i = 0;
    while (!(x == x1 && y == y1)) {
        int e2 = 2 * err;
        if (e2 > -dy) {
            err -= dy;
            x += sx;
        }
        if (e2 < dx) {
            err += dx;
            y += sy;
        }
        i++;
        if (x == x1 && y == y1) break;
        const double zl = za + (zb - za) * i / n;
        const bool shut = w.wall[y][x] || w.door[y][x] == 1;
        const int top = w.height[y][x] + (shut ? WALL_UP : (w.tree[y][x] ? TREE_UP : 0));
        if ((shut || w.tree[y][x] || w.height[y][x] > 0) && top > zl) return false;
        if (slab(x, y, za + (zb - za) * (i - 0.5) / n, za + (zb - za) * (i + 0.5) / n)) return false;
    }
    return true;
}
bool los(const World& w, int x0, int y0, int x1, int y1) { return losZ(w, x0, y0, zAt(w, x0, y0), x1, y1, zAt(w, x1, y1)); }
// видимость между квадратами: есть линия от какой-нибудь клетки одного до какой-нибудь клетки другого (к каждой клетке b —
// от ближайшей к ней клетки a)
bool losFP(const World& w, int ax, int ay, int az, int an, int bx, int by, int bz, int bn) {
    if (an == 1 && bn == 1) return losZ(w, ax, ay, az, bx, by, bz);
    for (int dy = 0; dy < bn; dy++)
        for (int dx = 0; dx < bn; dx++) {
            const int x1 = bx + dx, y1 = by + dy;
            if (losZ(w, std::clamp(x1, ax, ax + an - 1), std::clamp(y1, ay, ay + an - 1), az, x1, y1, bz)) return true;
        }
    return false;
}
// видимость между бойцами (с их ярусом) и от бойца до клетки (земля клетки)
bool losF(const World& w, const Fighter& a, const Fighter& b) { return losFP(w, a.x, a.y, zF(w, a), fpN(a), b.x, b.y, zF(w, b), fpN(b)); }
bool losFC(const World& w, const Fighter& a, int x, int y) { return losFP(w, a.x, a.y, zF(w, a), fpN(a), x, y, zAt(w, x, y), 1); }
bool inShapeF(int shape, int size, int ox, int oy, int cx, int cy, const Fighter& e) {
    if (10 * e.alt > std::max(size, 5)) return false;   // летун выше области (она — от земли на свой размер)
    const int n = fpN(e);
    for (int dy = 0; dy < n; dy++)
        for (int dx = 0; dx < n; dx++)
            if (inShape(shape, size, ox, oy, cx, cy, e.x + dx, e.y + dy)) return true;
    return false;
}
// клетку (x, y) занимает чей-то квадрат (кроме self)
bool occupied(const World& w, int x, int y, const Fighter* self) {
    for (auto& g : w.f)
        if (&g != self && g.hp > 0 && fpOverlap(g.x, g.y, fpN(g), x, y, 1)) return true;
    return false;
}
// Бойцы мешают друг другу, только если их объёмы пересекаются: квадрат и высота — от уровня ног на рост (средний 10 фт,
// большой 20, огромный 30, громадный 40). Под стоящим на мосту, под летуном выше роста — пройти можно (v21)
inline bool vOverlap(int za, const Fighter& a, int zb, const Fighter& b) { return za < zb + sizeLv(b) && zb < za + sizeLv(a); }
// f, поставленный в узел (x, y, l) на своей высоте, задевает g
inline bool touchesAt(const World& w, const Fighter& f, int x, int y, int l, const Fighter& g) {
    return &g != &f && g.hp > 0 && fpOverlap(g.x, g.y, fpN(g), x, y, fpAt(w, f, x, y, l)) &&
           vOverlap(nodeZ(w, x, y, l) + std::min(f.alt, maxAltAt(w, f, x, y, l)), f, zF(w, g), g);
}
// квадрат f, поставленный в (x, y), задевает чужой
bool blockedAt(const World& w, const Fighter& f, int x, int y) {
    for (auto& g : w.f)
        if (touchesAt(w, f, x, y, f.up ? 1 : 0, g)) return true;
    return false;
}
// все клетки квадрата f в (x, y) удовлетворяют ok(cx, cy) (и лежат на арене)
template <class P>
inline bool fpAll(const World& w, const Fighter& f, int x, int y, P&& ok) {
    const int n = fpN(f);
    for (int dy = 0; dy < n; dy++)
        for (int dx = 0; dx < n; dx++) {
            const int cx = x + dx, cy = y + dy;
            if (cx < 0 || cy < 0 || cx >= w.aw || cy >= w.ah || !ok(cx, cy)) return false;
        }
    return true;
}
// чужой квадрат, задетый квадратом f в (x, y) (для удара при столкновении); nullptr — нет
Fighter* blockerAt(World& w, const Fighter& f, int x, int y) {
    for (auto& g : w.f)
        if (touchesAt(w, f, x, y, f.up ? 1 : 0, g)) return &g;
    return nullptr;
}
// не заканчивать ход в занятой клетке
void nudge(const World& w, Fighter& f) {
    if (!blockedAt(w, f, f.x, f.y)) return;
    for (int r = 1; r < 14; r++)
        for (int dy = -r; dy <= r; dy++)
            for (int dx = -r; dx <= r; dx++) {
                int nx = f.x + dx, ny = f.y + dy;
                if (!fpAll(w, f, nx, ny, [&](int cx, int cy) { return !w.wall[cy][cx] && w.door[cy][cx] != 1 && !w.pit[cy][cx]; }) || blockedAt(w, f, nx, ny)) continue;
                const bool up = f.up && w.deck[ny][nx] > 0;   // на настиле — по настилу, иначе на землю
                if (!up && !nodeOK(w, f, nx, ny, 0)) continue;
                f.x = nx;
                f.y = ny;
                f.up = up;
                return;
            }
}
// Кто сейчас наносит урон (индекс бойца, −1 — никто: яд, осложнения погони): для реакции «мне нанесли урон» (№23)
thread_local int g_srcIdx = -1;
void oppAttack(World& w, Fighter& g, Fighter& victim);
// Способность-реакция (№23): боец meIdx реакцией отвечает на событие trig от srcIdx; prevDist — расстояние до входа в зону (trig 3)
bool tryReact(World& w, int meIdx, int trig, int srcIdx, int prevDist = -1);
void riposte(World& w, Fighter& d, Fighter& a);
// Запись хода бота примитивами (v21, №4): пока g_rec задан, ход бойца g_recIdx пишется как последовательность примитивов
struct Prim;
thread_local std::vector<Prim>* g_rec = nullptr;
thread_local int g_recIdx = -1;
void recordMove(int idx, int x, int y, int budget);
// цена шага в клетку (x, y) из (fx, fy): лазалка и труднопроходимая местность 10 фт, подъём +5 фт за уровень
static int stepCostL(const World& w, const Fighter& f, int fx, int fy, int fl, int x, int y, int l) {
    int cost = 5;
    if (!f.b.fly) {
        // лазалка или труднопроходимая местность хоть под одной клеткой квадрата
        const bool rough = fpFull(f) == 1 ? roughCell(w, f, x, y, l) : (fitInfo(w, f, x, y, l) & 8) != 0;
        if (rough)
            cost = 10;
        const int up = nodeZ(w, x, y, l) - nodeZ(w, fx, fy, fl);   // подъём (лестница, дерево, на настил): +5 фт за уровень
        if (up > 0 && !f.b.climbS && !f.b.burrowS) cost += 5 * up;   // лазун и копатель — без надбавки
    }
    if (fpFull(f) > 1 && (fitInfo(w, f, x, y, l) & 7) < fpFull(f)) cost *= 2;   // протискивается: движение вдвое дороже
    if (!l && w.door[y][x] == 1) cost += 5;   // закрытую дверь по пути открывают (взаимодействие с предметом)
    return cost;
}
static int stepCost(const World& w, const Fighter& f, int fx, int fy, int x, int y) { return stepCostL(w, f, fx, fy, f.up, x, y, f.up); }
bool isKnown(const World& w, int team, int i);
void revealTo(World& w, int team, int i);
// путь f к клетке (tx, ty) — кратчайший по цене шага (лазалка, трудная местность, подъём), в обход стен, ущелий и
// известных врагов (в саму клетку цели можно, даже если там враг). Тот же поиск строит клетки-кандидаты сети
// (reachable в prim_net.h): клетка, до которой он насчитал N фт, достижима за N фт. Пути в обход врагов нет — путь
// без их учёта (упрётся во врага). Неизвестный враг (туман) не обходится: в него упираются.
struct PStep {   // шаг пути: клетка и ярус (0 — земля, 1 — настил)
    int first, second, l;
};
static thread_local int pdCost[2 * W * W], pdPrev[2 * W * W], pdStamp[2 * W * W], pdFoe[W * W], pdCur = 0;
static void pathTo(const World& w, const Fighter& f, int tx, int ty, std::vector<PStep>& path) {
    path.clear();
    if (f.x == tx && f.y == ty) return;
    const int goal = ty * W + tx, from = f.y * W + f.x + (f.up ? W * W : 0);
    // крупный идёт левой верхней клеткой в цель; если там не встать (стена, край, дерево) — до узла, где его квадрат накрывает цель
    const bool cover = fpFull(f) > 1 && !nodeOK(w, f, tx, ty, 0) && !nodeOK(w, f, tx, ty, 1);
    std::vector<int> foes;   // известные враги, которых путь обходит (первый проход)
    auto foeUnder = [&](int x, int y, int l, int st) {   // f в узле (x, y, l) задевает известного врага (квадрат и высота)
        const int fn = fpAt(w, f, x, y, l);
        bool near = false;   // быстрая проверка по клеткам, потом — точная с высотой
        for (int dy = 0; dy < fn && !near; dy++)
            for (int dx = 0; dx < fn && !near; dx++)
                near = x + dx < W && y + dy < W && pdFoe[(y + dy) * W + x + dx] == st;
        if (!near) return false;
        for (int i : foes)
            if (touchesAt(w, f, x, y, l, w.f[i])) return true;
        return false;
    };
    for (int pass = 0; pass < 2; pass++) {
        const int st = ++pdCur;
        if (pass == 0) {
            const int fi = (int)(&f - &w.f[0]);
            const bool inWorld = fi >= 0 && fi < (int)w.f.size();
            for (size_t i = 0; i < w.f.size(); i++) {
                const Fighter& g = w.f[i];
                // враг, чей квадрат накрывает цель пути, не обходится (к нему и идём — как раньше в саму клетку цели)
                if (g.hp > 0 && g.team != f.team && (!inWorld || isKnown(w, f.team, (int)i)) && !fpOverlap(g.x, g.y, fpN(g), tx, ty, 1) && (foes.push_back((int)i), true))
                    for (int dy = 0; dy < fpN(g); dy++)
                        for (int dx = 0; dx < fpN(g); dx++)
                            if (g.x + dx < W && g.y + dy < W) pdFoe[(g.y + dy) * W + g.x + dx] = st;
            }
        }
        std::vector<std::pair<int, int>> q;   // (цена, узел) — Дейкстра
        int end = -1;
        pdStamp[from] = st;
        pdCost[from] = 0;
        pdPrev[from] = -1;
        q.push_back({0, from});
        bool found = false, skipped = false;   // skipped — какой-то узел не взят из-за врага (иначе второй проход тот же)
        int best = from, bestGap = 1 << 20, bestCost = 0;   // ближе всего к цели (если до неё не дойти)
        while (!q.empty()) {
            std::pop_heap(q.begin(), q.end(), std::greater<>());
            const auto [v, c] = q.back();
            q.pop_back();
            if (v != pdCost[c]) continue;
            const int l = c / (W * W), x = c % W, y = (c % (W * W)) / W;
            if (c % (W * W) == goal || (cover && c != from && fpOverlap(x, y, fpAt(w, f, x, y, l), tx, ty, 1))) {   // крупный — квадрат накрыл цель
                found = true;
                end = c;
                break;
            }
            {
                const int m = fpFull(f) > 1 ? fpAt(w, f, x, y, l) : 1, gp = std::max(fpGap(x, m, tx, 1), fpGap(y, m, ty, 1));
                if (gp < bestGap || (gp == bestGap && v < bestCost)) best = c, bestGap = gp, bestCost = v;
            }
            for (int dy = -1; dy <= 1; dy++)
                for (int dx = -1; dx <= 1; dx++)
                    for (int nl = 0; nl < 2; nl++) {
                        const int nx = x + dx, ny = y + dy, cell = ny * W + nx, n = cell + nl * W * W;
                        if ((!dx && !dy) || !stepOK(w, f, x, y, l, nx, ny, nl)) continue;
                        if (pass == 0 && cell != goal && foeUnder(nx, ny, nl, st)) {
                            skipped = true;
                            continue;
                        }
                        const int haz = !nl && w.haz[ny][nx] && !(f.b.fly && HAZ[w.haz[ny][nx]].flySafe) ? 1 : 0;
                        const int nv = v + 64 * stepCostL(w, f, x, y, l, nx, ny, nl) + haz;   // футы × 64 + клетки зон: сначала короче, потом безопаснее
                        if (pdStamp[n] != st || nv < pdCost[n]) {
                            pdStamp[n] = st;
                            pdCost[n] = nv;
                            pdPrev[n] = c;
                            q.push_back({nv, n});
                            std::push_heap(q.begin(), q.end(), std::greater<>());
                        }
                    }
        }
        if (!found && pass == 0 && skipped) continue;   // враги мешали — второй проход без них
        if (!found) end = best;   // до цели не дойти: как можно ближе к ней (PHB — идёт, сколько может)
        if (end == from) return;
        for (int c = end; c != from; c = pdPrev[c]) path.push_back({c % W, (c % (W * W)) / W, c / (W * W)});
        std::reverse(path.begin(), path.end());
        return;
    }
}
static bool enemyAt(const World& w, const Fighter& f, int x, int y) {
    for (auto& g : w.f)
        if (g.team != f.team && touchesAt(w, f, x, y, f.up ? 1 : 0, g)) return true;
    return false;
}
// Куда дойдёт f, если идёт к t, пока не окажется в desiredFt от него (и, если needLos, не увидит его), не дальше speed фт:
// без провоцированных атак и реакций (их учитывает moveToCell). enterTarget — можно встать в саму клетку цели.
std::pair<int, int> planStop(const World& w, const Fighter& f, const Fighter& t, int desiredFt, int speed, bool needLos, bool enterTarget) {
    int px = f.x, py = f.y, pl = f.up;
    const int tz = zF(w, t);
    const int fn = fpN(f), tn = fpN(t);
    auto inPos = [&]() { return distFP(px, py, nodeZ(w, px, py, pl) + f.alt, fn, t.x, t.y, tz, tn) <= desiredFt && (!needLos || losFP(w, px, py, nodeZ(w, px, py, pl) + f.alt, fn, t.x, t.y, tz, tn)); };
    if (inPos() || speed <= 0) return {px, py};
    std::vector<PStep> path;
    pathTo(w, f, t.x, t.y, path);
    int left = speed;
    for (auto& c : path) {
        if (c.first == t.x && c.second == t.y && !enterTarget) break;
        const int cost = stepCostL(w, f, px, py, pl, c.first, c.second, c.l);
        if (left < cost || enemyAt(w, f, c.first, c.second)) break;
        px = c.first;
        py = c.second;
        pl = c.l;
        left -= cost;
        if (inPos()) break;
    }
    return {px, py};
}
// Примитив «иди в клетку» (v21, №4): f идёт к (cx, cy) не дальше speed фт. Каждый шаг, выводящий f из досягаемости
// ближнего врага (без Отхода, реакция не потрачена), даёт ему провоцированную атаку ДО шага (как в PHB); вход в зону
// врага может вызвать его реакцию. Возвращает потраченные футы.
// расстояние до ближайшего известного врага (для метрики скорости)
static int nearestKnownFoe(const World& w, const Fighter& f) {
    int d = 1 << 20;
    for (size_t i = 0; i < w.f.size(); i++)
        if (w.f[i].hp > 0 && w.f[i].team != f.team && isKnown(w, f.team, (int)i)) d = std::min(d, distFt(f, w.f[i]));
    return d;
}
int moveToCell(World& w, Fighter& f, int cx, int cy, int speed) {
    const int fi = (int)(&f - &w.f[0]);
    recordMove(fi, cx, cy, speed);
    if (speed <= 0 || (f.x == cx && f.y == cy)) return 0;
    std::vector<PStep> path;
    pathTo(w, f, cx, cy, path);
    int left = speed;
    for (auto& c : path) {
        const int cost = stepCostL(w, f, f.x, f.y, f.up, c.first, c.second, c.l);
        if (left < cost) break;
        if (enemyAt(w, f, c.first, c.second)) {
            // упёрся в невидимого (неизвестного) врага: он становится известен команде, попытка стоит 5 фт
            for (size_t i = 0; i < w.f.size(); i++) {
                const Fighter& g = w.f[i];
                if (g.team != f.team && touchesAt(w, f, c.first, c.second, c.l, g) && !isKnown(w, f.team, (int)i)) {
                    revealTo(w, f.team, (int)i);
                    left -= 5;
                    break;
                }
            }
            break;
        }
        if (!f.disengaged) {
            for (size_t i = 0; i < w.f.size(); i++) {
                Fighter& g = w.f[i];
                // провоцированная атака — ближняя атака оружием: ближнее или метательное, безоружный и лучник не атакуют
                if (g.hp <= 0 || g.team == f.team || g.reactionUsed || !meleeWeapon(g.b)) continue;
                // участники погони (главные боссы) одновременно бегут в одну сторону: провоцированных атак друг по другу нет (DMG)
                if (w.chaseOn && fi < 2 && (int)i < 2) continue;
                // недееспособный не реагирует
                if (g.cond[C_STUN] || g.cond[C_PARAL] || g.cond[C_INCAP]) continue;
                // не атакует очаровавшего
                if (g.cond[C_CHARM] > 0 && g.charmSrc == fi) continue;
                if (g.noOAvs == fi) continue;   // Подвижный (v21): я ударил g в ближнем бою — он не провоцирует от меня
                bool wasAdj = distFt(g, f) <= meleeReach(g.b);
                bool nowAdj = distFP(g.x, g.y, zF(w, g), fpN(g), c.first, c.second, nodeZ(w, c.first, c.second, c.l) + std::min(f.alt, maxAltAt(w, f, c.first, c.second, c.l)), fpN(f)) <= meleeReach(g.b);
                if (wasAdj && !nowAdj) {
                    spendReaction(g);
                    const int src0 = g_srcIdx;
                    g_srcIdx = (int)i;   // урон провоцированной атаки наносит g
                    oppAttack(w, g, f);
                    g_srcIdx = src0;
                    if (f.hp <= 0) return speed - left;
                }
            }
        }
        const int fx0 = f.x, fy0 = f.y, fz0 = zF(w, f);
        const bool useMe = fi >= 0 && fi < 2;
        const int dBefore = useMe ? nearestKnownFoe(w, f) : 0;
        if (!c.l && w.door[c.second][c.first] == 1) setDoor(w, c.first, c.second, 2);   // открыл дверь по пути
        f.x = c.first;
        f.y = c.second;
        f.up = c.l;
        f.alt = std::min(f.alt, maxAltAt(w, f, f.x, f.y, f.up));   // под настилом — ниже (бесплатно)
        left -= cost;
        hazardHit(w, f);
        if (f.hp <= 0) return speed - left;
        if (useMe) {   // метрика использования скорости (№6): шаг, который не приблизил к ближайшему известному врагу
            g_use[fi][U_FT] += cost;
            if (nearestKnownFoe(w, f) >= dBefore) g_use[fi][U_FTAWAY] += cost;
        }
        // Подготовка (v21): враг вошёл в досягаемость оружия того, кто подготовился, — удар реакцией
        for (size_t i = 0; i < w.f.size(); i++) {
            Fighter& g = w.f[i];
            if (!g.readied || g.readyTrig != 1 || g.hp <= 0 || g.team == f.team || !canReact(g)) continue;
            const bool ab = g.readyAbil >= 0 && g.readyAbil < (int)g.b.abil.size();
            if (!ab && (g.b.wN <= 0 || g.disarmed)) continue;
            const int reach = ab ? std::max(5, specReach(g.b, g.b.abil[g.readyAbil])) : atkDist(g.b), before = distFP(g.x, g.y, zF(w, g), fpN(g), fx0, fy0, fz0, fpN(f));
            if (before <= reach || distFt(g, f) > reach || !losF(w, g, f)) continue;
            spendReaction(g);
            g.readied = false;
            evPush("{\"k\":\"ready\",\"who\":" + std::to_string(i) + ",\"tgt\":" + std::to_string(fi) + "}");
            readyFire(w, (int)i, fi);
            if (f.hp <= 0) return speed - left;
        }
        // реакция врага «вошёл в зону» (№23)
        for (size_t i = 0; i < w.f.size(); i++) {
            const Fighter& g = w.f[i];
            if (g.hp <= 0 || g.team == f.team || !hasReact(g.b)) continue;
            tryReact(w, (int)i, 3, fi, distFP(g.x, g.y, zF(w, g), fpN(g), fx0, fy0, fz0, fpN(f)));
            if (f.hp <= 0) return speed - left;
        }
        if (f.x != c.first || f.y != c.second) break;   // реакция сдвинула (толчок): дальше по старому пути не идём
        if (f.x == cx && f.y == cy) break;
    }
    nudge(w, f);
    return speed - left;
}
// Смена высоты летуна (v21): подъём из досягаемости ближнего врага провоцирует его атаку (как шаг прочь), Отход — нет
void setAlt(World& w, Fighter& f, int a) {
    const int fi = (int)(&f - &w.f[0]);
    if (!f.disengaged)
        for (size_t i = 0; i < w.f.size() && f.hp > 0; i++) {
            Fighter& g = w.f[i];
            if (g.hp <= 0 || g.team == f.team || g.reactionUsed || !meleeWeapon(g.b)) continue;
            if (g.cond[C_STUN] || g.cond[C_PARAL] || g.cond[C_INCAP] || (g.cond[C_CHARM] > 0 && g.charmSrc == fi) || g.noOAvs == fi) continue;
            const bool wasAdj = distFt(g, f) <= meleeReach(g.b);
            const int a0 = f.alt;
            f.alt = a;
            const bool nowAdj = distFt(g, f) <= meleeReach(g.b);
            f.alt = a0;
            if (wasAdj && !nowAdj) {
                spendReaction(g);
                const int src0 = g_srcIdx;
                g_srcIdx = (int)i;
                oppAttack(w, g, f);
                g_srcIdx = src0;
            }
        }
    if (f.hp <= 0 || !canStayAloft(f)) return;   // упал от провоцированной атаки (сбит с ног) — высоты больше нет
    f.alt = a;
    hazardHit(w, f);
}
// Двигает f к t (до desiredFt от него), возвращает потраченные футы: решает, в какую клетку идти, и идёт туда (moveToCell)
int moveToward(World& w, Fighter& f, const Fighter& t, int desiredFt, int speed, bool needLos, bool enterTarget = false) {   // enterTarget: дойти до самой клетки цели (для игрока), иначе встать рядом
    if (speed <= 0) return 0;
    const auto c = planStop(w, f, t, desiredFt, speed, needLos, enterTarget);
    if (c.first == f.x && c.second == f.y) return 0;
    return moveToCell(w, f, c.first, c.second, speed);
}

// ---------------------------------------------------------------------------
// Правила: броски, состояния, урон
// ---------------------------------------------------------------------------
int d20(bool adv, bool dis) {
    if (adv == dis) return rollD20();
    int a = rollD20(), c = rollD20();
    return adv ? std::max(a, c) : std::min(a, c);
}
bool selfOn(const Fighter& me, const Rule& r);
int saveBonus(const Fighter& t, int stat) {
    int b = 0;   // «+N к спасброскам» — свои правила и ауры союзников (v21)
    forRules(t, [&](const Rule& r, int) {
        if (r.what == E_SAVEB && selfOn(t, r)) b += r.n;
    });
    return t.mod(stat) + (((t.b.saveProf >> stat) & 1u) ? t.b.prof : 0) + b;
}
bool advSave(const Fighter& t);
bool useReroll(const Fighter& f, int on);
// броски для показа игроку (кадры): пишутся, только когда бой записывается (g_evLog), чтобы не тормозить обучение
thread_local bool g_evLog = false;
void evPush(const std::string& json);
inline int fIdx(const Fighter& f) { return g_curW ? (int)(&f - &g_curW->f[0]) : -1; }
inline void evSave(const Fighter& t, int stat, int r, int b, int dc, bool ok, bool autoFail) {
    if (!g_evLog) return;
    evPush("{\"k\":\"save\",\"who\":" + std::to_string(fIdx(t)) + ",\"stat\":" + std::to_string(stat) + ",\"d20\":" + std::to_string(r) +
           ",\"b\":" + std::to_string(b) + ",\"dc\":" + std::to_string(dc) + ",\"ok\":" + (ok ? "1" : "0") + (autoFail ? ",\"auto\":1" : "") + "}");
}
bool saveOK(const Fighter& t, int stat, int dc) {
    // PHB: оглушён/парализован автоматически проваливает СИЛ и ЛОВ
    if ((t.cond[C_STUN] || t.cond[C_PARAL]) && (stat == STR || stat == DEX)) { evSave(t, stat, 0, 0, dc, false, true); return false; }
    // опутан — помеха на спасброски ЛОВ
    const bool adv = advSave(t), dis = (stat == DEX && (t.cond[C_RESTR] > 0 || squeezed(t))) || t.exh >= 3 || ((stat == STR || stat == DEX) && t.b.noArmProf && (t.b.armor || t.b.shield));
    int die = 0;   // «+ кость к спасброскам» (Благословение) — свои правила и ауры (v21)
    forRules(t, [&](const Rule& r, int) {
        if (r.what == E_SAVEDIE && selfOn(t, r)) die += rollDice(r.n, r.s);
    });
    const int sb = saveBonus(t, stat);
    int r = d20(adv, dis);
    bool ok = r + sb + die >= dc;
    if (!ok && useReroll(t, T_MYSAVEFAIL)) { r = d20(adv, dis); ok = r + sb + die >= dc; }   // переброс (Везунчик)
    evSave(t, stat, r, sb + die, dc, ok, false);
    return ok;
}
// счётчик для статистики
thread_local long long g_lrUsed = 0;
// статистика перезарядки
thread_local long long g_rechUsed = 0, g_rechRolls = 0, g_rechOk = 0;
thread_local long long g_attacksMade = 0, g_legUsed = 0;
// статистика атак и легендарных действий
thread_local long long g_concCast = 0, g_concBroken = 0, g_surge = 0, g_ripUsed = 0, g_reactUsed = 0;
// Легендарное сопротивление: проваленный спасбросок становится успешным, пока есть заряды.
// Бот тратит заряд только на значимый эффект (см. lrWorth).
bool saveLR(Fighter& t, int stat, int dc, bool significant) {
    if (saveOK(t, stat, dc)) return true;
    if (significant && t.lrLeft > 0) {
        t.lrLeft--;
        g_lrUsed++;
        return true;
    }
    return false;
}
double dmgMult(const Boss& b, int t, bool magical, bool extraRes = false);
bool lrWorth(const Fighter& t, const Spec& s) {
    // потеря хода — всегда стоит заряда
    if (s.cond == C_STUN || s.cond == C_DISTR || s.cond == C_PARAL || s.cond == C_INCAP || s.cond == C_CHARM ||
        s.cond == C_FLEE)
        return true;
    // долгий контроль
    if (s.cond && s.condRounds >= 3) return true;
    double avg = 0;
    for (auto& d : s.dmgParts()) avg += d.n * (d.s + 1) / 2.0 * dmgMult(t.b, d.type, true);
    // удар, срезающий четверть оставшихся ХП
    return avg >= t.pol->v[PO_LRFRAC] * t.hp;
}
void fallCheck(Fighter& f);   // летун падает (ниже)
// захват (пакет атомов 2): схваченный опутан / получает урон каждый ход, пока его держит src
void grabExtras(Fighter& t, int src, bool restr, int dotN, int dotS, int type) {
    if (t.cond[C_GRAPPLE] <= 0 || t.grapSrc != src) return;
    if (restr) {
        t.cond[C_RESTR] = std::max(t.cond[C_RESTR], 1000);
        t.cstat[C_RESTR] = -1;
        t.restrByGrab = true;
    }
    if (dotN > 0) {
        t.grabDotN = dotN;
        t.grabDotS = dotS;
        t.grabDotType = type;
        t.grabDotSrc = src;
    }
}
// захват кончился — кончается и то, что держалось на нём
void grabSync(Fighter& t) {
    if (t.cond[C_GRAPPLE] > 0) return;
    if (t.restrByGrab) t.cond[C_RESTR] = 0;
    t.restrByGrab = false;
    t.grabDotN = 0;
}
bool applyCond(Fighter& t, int kind, int rounds, int stat, int dc, bool repeatSave, int src = -1, int concSrc = 0) {
    if (t.b.immCond & (1u << kind) || t.cimm[kind] > 0 || t.banished > 0) return false;
    // размеры (v21): схватить можно существо не больше чем на ступень крупнее себя
    if (kind == C_GRAPPLE && g_curW && src >= 0 && src < (int)g_curW->f.size() && t.b.size > g_curW->f[src].b.size + 1) return false;
    t.cond[kind] = std::max(t.cond[kind], rounds);
    // из захвата выбираются действием (СЛ), а не повторным спасом
    t.cstat[kind] = (repeatSave && kind != C_GRAPPLE) ? stat : -1;
    t.cdc[kind] = dc;
    // чьей концентрацией держится (индекс+1), 0 — ничьей
    t.condConc[kind] = concSrc;
    fallCheck(t);   // сбит с ног, опутан, схвачен, оглушён, парализован — летун падает
    if (kind == C_CHARM) t.charmSrc = src;
    if (kind == C_GRAPPLE) t.grapSrc = src;
    return true;
}
inline bool specMagical(const Boss& b, int type) {
    return !isPhys(type) || b.wMagic;
}
// оружие пробивает сопротивление немагическому физическому: магическое или (пакет атомов 2) посеребрённое
inline bool wPierceNM(const Boss& b) { return b.wMagic || b.wSilver; }
inline bool specMagical(const Boss& b, const Spec& s) {
    return specMagical(b, s.dtype);
}
// множитель урона: иммунитет 0; сопротивление ×0.5; уязвимость ×2 (вместе — ×1)
double dmgMult(const Boss& b, int t, bool magical, bool extraRes) {
    if ((b.immMask >> t) & 1) return 0.0;
    if (b.immNM && isPhys(t) && !magical) return 0.0;
    bool res = ((b.resMask >> t) & 1) || (b.resNM && isPhys(t) && !magical) || extraRes;
    bool vul = (b.vulnMask >> t) & 1;
    return (res ? 0.5 : 1.0) * (vul ? 2.0 : 1.0);
}
// «когда → что»: условие о себе (без противника)
bool selfOn(const Fighter& me, const Rule& r) {
    switch (r.when) {
        case W_ALWAYS: return true;
        case W_HPLOW: return me.hp * 2 <= me.maxHp;
        case W_HPHIGH: return me.hp * 2 > me.maxHp;
        case W_NOCOND:
            for (int k = 1; k < C_N; k++)
                if (me.cond[k] > 0) return false;
            return true;
        case W_RECKLESS: return me.wasReckless;
        case W_TWOWEAP: return me.b.wN > 0 && !me.disarmed && hasOffhand(me.b);
        case W_HEAVY: return me.b.wN > 0 && !me.disarmed && me.b.wHeavy;
    }
    return false;
}
// переброс к20 по событию (v21): тратит одно применение
bool useReroll(const Fighter& f, int on) {
    if (f.b.trigs.empty() || f.trigLeft.size() != f.b.trigs.size()) return false;
    for (size_t k = 0; k < f.b.trigs.size(); k++) {
        const Trig& t = f.b.trigs[k];
        if (t.on != on || t.what != X_REROLL || f.trigLeft[k] <= 0) continue;
        if (t.uses < UNL) f.trigLeft[k]--;
        return true;
    }
    return false;
}
// резист по правилу (условие о себе), пока его не подавили
bool condDefActive(const Fighter& d, int type, bool magical) {
    if (d.supp > 0 && (d.b.suppTgt & 4)) return false;
    bool on = false;
    forRules(d, [&](const Rule& r, int) {
        if ((r.what == E_RES || (r.what == E_RESNM && isPhys(type) && !magical)) && selfOn(d, r)) on = true;
    });
    return on;
}
// преимущество на спасброски по правилу
bool advSave(const Fighter& t) {
    bool on = g_saveVsAbil && t.b.magicRes;   // сопротивление магии: преимущество на спасброски от способностей
    forRules(t, [&](const Rule& r, int) {
        if (r.what == E_ADVSAVE && selfOn(t, r)) on = true;
    });
    return on;
}
// Урон по бойцу. concCheck = false — проверку концентрации ставит вызывающий (один урон из нескольких типов — одна
// проверка на сумму, PHB). Возвращает урон, который боец получил (после защит, вместе с ушедшим во временные хиты).
void shapeBack(Fighter& f);   // превращение: возврат (ниже)
int hurt(Fighter& d, int dmg, int type, bool magical, bool concCheck = true) {
    if (dmg <= 0 || d.banished > 0) return 0;   // изгнанного не достать
    if (g_track) {
        g_dmgT[type] += dmg;
        if (isPhys(type) && !magical) g_dmgNM += dmg;
    }
    // броски и ресурсы (v21): урон немагического физического меньше на N (Мастер тяжёлых доспехов); урон типа, которым
    // источник «игнорирует сопротивление», проходит сквозь резист (не сквозь иммунитет)
    if (isPhys(type) && !magical)
        forRules(d, [&](const Rule& r, int) {
            if (r.what == E_DMGRED && selfOn(d, r)) dmg -= r.n;
        });
    if (dmg <= 0) return 0;
    bool pierce = false;
    if (g_curW && g_srcIdx >= 0 && g_srcIdx < (int)g_curW->f.size())
        for (auto& r : g_curW->f[g_srcIdx].b.rules)
            if (r.what == E_PIERCE && r.n == type && selfOn(g_curW->f[g_srcIdx], r)) pierce = true;
    // защиты подавлены — остаётся лишь уязвимость
    const bool imm = ((d.b.immMask >> type) & 1) || (d.b.immNM && isPhys(type) && !magical);
    dmg = (int)std::floor(dmg * ((d.supp > 0 && (d.b.suppTgt & 4)) || (pierce && !imm)
                                     ? (((d.b.vulnMask >> type) & 1) ? 2.0 : 1.0)
                                     : dmgMult(d.b, type, magical, condDefActive(d, type, magical))));
    if (dmg <= 0) return 0;
    if (g_srcIdx >= 0) d.hurtBy = g_srcIdx;
    // урон подавляющего типа: пассивки отключены до конца следующего хода владельца
    if ((d.b.suppMask >> type) & 1) d.supp = d.inTurn ? 2 : 1;
    // концентрация: на каждое попадание своя СЛ спасброска ТЕЛ = max(10, урон/2); урон, ушедший во временные хиты,
    // тоже полученный урон (PHB)
    if (concCheck && d.concSpec >= 0) d.concDCs.push_back(std::max(10, dmg / 2));
    const int taken = dmg;
    // временные хиты поглощают урон первыми
    int ab = std::min(d.temp, dmg);
    d.temp -= ab;
    dmg -= ab;
    const bool wasUp = d.hp > 0;
    d.hp -= dmg;
    if (d.hp <= 0 && d.inForm) shapeBack(d);   // облик пал: свой облик, лишний урон — на свои хиты
    // «событие → эффект» (v21): мои хиты упали до 0 — остаться с 1 хитом (Неумолимая ярость) или получить временные хиты
    if (d.hp <= 0 && !d.b.trigs.empty() && d.trigLeft.size() == d.b.trigs.size())
        for (size_t k = 0; k < d.b.trigs.size(); k++) {
            const Trig& t = d.b.trigs[k];
            if (t.on != T_DOWN || d.trigLeft[k] <= 0) continue;
            if (t.uses < UNL) d.trigLeft[k]--;
            if (t.what == X_STAY1) d.hp = 1;
            if (t.what == X_TEMP && d.hp <= 0) {   // временные хиты не спасают от 0 — но их получает тот, кто остался
                d.hp = 1;
                d.temp = std::max(d.temp, rollDice(t.n, t.s) + t.b);
            }
            if (d.hp > 0) break;
        }
    // пакет атомов 1: «я получил урон выбранного типа» (страх огня) — пока жив
    if (taken > 0 && d.hp > 0 && g_curW && !d.b.trigs.empty()) {
        const int prevT = g_trigType;
        g_trigType = type;
        fireTrig(const_cast<World&>(*g_curW), d, T_DMGTYPE, nullptr);
        g_trigType = prevT;
    }
    // очки команды (v21): убитый враг — на счёт команды того, кто нанёс урон
    if (wasUp && d.hp <= 0 && g_curW && g_srcIdx >= 0 && g_srcIdx < (int)g_curW->f.size() && g_curW->f[g_srcIdx].team != d.team && g_curW->f[g_srcIdx].team < MAXT)
        g_curW->kills[g_curW->f[g_srcIdx].team]++;
    return taken;
}
bool allyAdjacent(const World& w, const Fighter& me, const Fighter& target) {
    for (auto& g : w.f)
        if (&g != &me && g.hp > 0 && g.team == me.team &&
            5 * std::max(std::abs(g.x - target.x), std::abs(g.y - target.y)) <= 5)
            return true;
    return false;
}
// «когда → что»: условие с противником foe (цель моей атаки или тот, кто атакует меня); melee — моя атака ближняя
// (безрассудство даёт преимущество только ближним атакам, а атаки по безрассудному — любые)
bool ruleOn(const World& w, const Fighter& me, const Fighter* foe, const Rule& r, bool offense, bool melee) {
    switch (r.when) {
        case W_ALLYADJ: return foe && allyAdjacent(w, me, *foe);
        case W_FOECOND: return foe && foe->cond[r.warg] > 0;
        case W_FOEHPLOW: return foe && foe->hp * 2 <= foe->maxHp;
        case W_RECKLESS: return me.wasReckless && (!offense || melee);
    }
    return selfOn(me, r);
}
// +КД по правилам против атакующего a
// «когда → что: преимущество на проверки навыка sk» (8 ноября; n — номер навыка)
bool skillAdv(const Fighter& f, int sk) {
    bool on = false;
    forRules(f, [&](const Rule& r, int) {
        if (r.what == E_SKILLADV && r.n == sk && selfOn(f, r)) on = true;
    });
    return on;
}
int ruleAC(const World& w, const Fighter& d, const Fighter& a) {
    int ac = 0;
    forRules(d, [&](const Rule& r, int) {
        if (r.what == E_AC && ruleOn(w, d, &a, r, false, false)) ac += r.n;
        if (r.what == E_ACMINUS && ruleOn(w, d, &a, r, false, false)) ac -= r.n;   // недостаток (пакет атомов 3)
    });
    return ac;
}
bool enemyAdjacent(const World& w, const Fighter& me) {
    for (auto& g : w.f)
        if (g.hp > 0 && g.team != me.team && distFt(me, g) <= 5) return true;
    return false;
}
// Видит ли viewer цель t: слепое зрение видит всё в радиусе, ослеплённый и «скрытый» не видны, цель в тьме видна лишь с
// тёмным зрением достаточной дальности
inline bool litAt(const World& w, const Fighter& t);   // свет (ниже)
bool canSee(const World& w, const Fighter& v, const Fighter& t) {
    if (t.banished > 0) return false;   // изгнан — вне боя
    int d = distFt(v, t);
    if (v.b.blindsight >= d) return true;
    const bool ts = v.b.truesight >= d && !v.cond[C_BLIND];   // истинное зрение (v21): невидимых и сквозь тьму
    if (v.cond[C_BLIND] || t.hidden || (t.invisRounds > 0 && !ts)) return false;
    if (w.dark[t.y][t.x] && v.b.dv < d && !ts) return false;
    // ночь (пакет атомов 2, свет): без тёмного зрения неосвещённое видно не дальше 30 фт
    if (!w.day && d > 30 && v.b.dv < d && !ts && !litAt(w, t)) return false;
    return true;
}
// цель освещена: в радиусе своего или чужого света (пассив «свет вокруг себя» или способность на время)
inline bool litAt(const World& w, const Fighter& t) {
    for (auto& g : w.f) {
        if (g.hp <= 0 || g.banished > 0) continue;
        const int r = std::max(g.b.lightR, g.lightRounds > 0 ? g.lightR : 0);
        if (r > 0 && distFt(g, t) <= r) return true;
    }
    return false;
}
thread_local int g_curRound = 0;   // номер текущего раунда (туман войны, восприятие МДР, наблюдение сети)
// ---- Туман войны (v21, №12): сторона видит врага, если его видит хоть один её боец (canSee и нет стены между ними).
// Бот, сеть и игрок знают только видимых врагов и тех, кого видели в прошлом раунде на той же клетке (атаковать «угаданную
// клетку» можно, с помехой). Атака или способность выдают позицию. Если сторона 5 раундов не знает ни одного врага, она их
// слышит (технический предохранитель от бесконечного боя вслепую).
bool teamSees(const World& w, int team, const Fighter& t) {
    for (auto& g : w.f)
        if (g.hp > 0 && g.team == team && !g.fled && (&g == &t || (canSee(w, g, t) && losF(w, g, t)))) return true;
    return false;
}
inline std::array<int, 3>& knownOf(World& w, int team, int i) {
    auto& K = w.known[team];
    if ((int)K.size() <= i) K.resize(w.f.size() > (size_t)i ? w.f.size() : (size_t)i + 1, {-1, -1, -1});
    return K[i];
}
void revealTo(World& w, int team, int i) {
    if (team < 0 || team > 1 || i < 0 || i >= (int)w.f.size()) return;
    knownOf(w, team, i) = {w.f[i].x, w.f[i].y, g_curRound};
    w.knownRound[team] = g_curRound;
}
void updateKnown(World& w, int team) {
    for (size_t i = 0; i < w.f.size(); i++)
        if (w.f[i].hp > 0 && w.f[i].team != team && teamSees(w, team, w.f[i])) revealTo(w, team, (int)i);
}
// враг i известен стороне: виден или стоит там, где его видели в этом или прошлом раунде
bool isKnown(const World& w, int team, int i) {
    const Fighter& e = w.f[i];
    if (e.team == team || teamSees(w, team, e)) return true;
    if (i >= (int)w.known[team].size()) return false;
    const auto& k = w.known[team][i];
    return k[2] >= 0 && k[0] == e.x && k[1] == e.y && k[2] >= g_curRound - 1;
}
// на солнце: день, клетка не во тьме и не под навесом (стоящий на настиле — под небом)
inline bool inSun(const World& w, const Fighter& f) { return w.day && !w.dark[f.y][f.x] && (f.up || !w.deck[f.y][f.x]); }
void advState(const World& w, const Fighter& a, const Fighter& d, int range, bool& adv, bool& dis) {
    // не видят меня — преимущество; не вижу цель — помеха
    adv = !canSee(w, d, a);
    dis = !canSee(w, a, d);
    if (d.dodging) dis = true;
    // «когда → что»: мои правила на атаку, правила цели на атаки по ней (безрассудство — тоже правило: рискнул в свой ход,
    // по тебе бьют с преимуществом до следующего хода)
    forRules(a, [&](const Rule& r, int) {
        if (r.what == E_ADVATK && ruleOn(w, a, &d, r, true, range <= 5)) adv = true;
        if (r.what == E_DISATK && ruleOn(w, a, &d, r, true, range <= 5)) dis = true;   // недостаток (пакет атомов 3)
    });
    forRules(d, [&](const Rule& r, int) {
        if ((r.what == E_DISVSME || r.what == E_ADVVSME) && ruleOn(w, d, &a, r, false, false)) (r.what == E_DISVSME ? dis : adv) = true;
    });
    if (d.cond[C_RESTR] || d.cond[C_BLIND] || d.cond[C_STUN] || d.cond[C_PARAL] || d.cond[C_LIT]) adv = true;
    if (d.cond[C_PRONE]) {
        if (distFt(a, d) <= 5)
            adv = true;
        else
            dis = true;
    }
    if (a.exh >= 3 || a.cond[C_PRONE] || a.cond[C_RESTR] || a.cond[C_FRIGHT] || a.cond[C_POISON] || a.cond[C_BLIND] ||
        a.cond[C_WEAK] || a.cond[C_FLEE])
        dis = true;
    if (range > 5 && enemyAdjacent(w, a)) dis = true;
    if (range > 5 && distFt(a, d) > range) dis = true;   // дальше обычной дистанции оружия (дальняя дистанция) — с помехой
    if (d.helpBy >= 0 && d.helpBy < (int)w.f.size() && &w.f[d.helpBy] != &a && w.f[d.helpBy].team == a.team) adv = true;   // Помощь союзника (v21)
    if (a.advNext) adv = true;   // «событие → эффект»: преимущество на следующую атаку
    if (a.b.noArmProf && (a.b.armor || a.b.shield)) dis = true;   // доспех или щит без владения
    if (squeezed(a)) dis = true;   // протискивается (PHB)
    if (a.b.sunSens && inSun(w, a)) dis = true;   // солнечная чувствительность
    if (squeezed(d)) adv = true;
}
int coverBonus(const World& w, int x0, int y0, int x1, int y1) {
    int dx = std::abs(x1 - x0), dy = std::abs(y1 - y0), sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1, err = dx - dy,
        x = x0, y = y0;
    while (!(x == x1 && y == y1)) {
        int e2 = 2 * err;
        if (e2 > -dy) {
            err -= dy;
            x += sx;
        }
        if (e2 < dx) {
            err += dx;
            y += sy;
        }
        // полукрытие: +2 КД (PHB "Укрытия")
        if ((x != x1 || y != y1) && (x != x0 || y != y0) && w.climb[y][x]) return 2;
    }
    return w.tree[y1][x1] ? 2 : 0;   // в кроне дерева — полукрытие листвы
}
inline bool canReact(const Fighter& d) {
    return d.hp > 0 && !d.reactionUsed && !d.cond[C_STUN] && !d.cond[C_PARAL] && !d.cond[C_INCAP];
}
// Невероятное уклонение: реакцией вдвое меньше урона от атаки, которая попала (бот тратит, если урон >= 10% максимума
// ХП)
int applyUncanny(Fighter& d, int dmg) {
    if (d.b.uncanny && canReact(d) && dmg >= d.pol->v[PO_UNCANNY] * d.maxHp) {
        spendReaction(d);
        return dmg / 2;
    }
    return dmg;
}
int allyReact(World& w, Fighter& a, Fighter& d);   // ниже: реакция за союзника (1 — помеха атаке, −1 — атакующий пал)
inline void evRoll(const Fighter& a, const Fighter& d, int r, int b, int ac, bool adv, bool dis, bool hit, bool crit) {
    if (!g_evLog) return;
    evPush("{\"k\":\"roll\",\"who\":" + std::to_string(fIdx(a)) + ",\"tgt\":" + std::to_string(fIdx(d)) + ",\"d20\":" + std::to_string(r) +
           ",\"b\":" + std::to_string(b) + ",\"ac\":" + std::to_string(ac) + ",\"adv\":" + std::to_string(adv == dis ? 0 : (adv ? 1 : -1)) +
           ",\"hit\":" + (hit ? "1" : "0") + ",\"crit\":" + (crit ? "1" : "0") + "}");
}
bool attackRoll(World& w, Fighter& a, Fighter& d, int mod, int range, bool& crit) {
    if (a.team != d.team) {
        a.struckFoe = true;
        revealTo(w, d.team, (int)(&a - &w.f[0]));   // атака выдаёт атакующего (туман войны)
    }
    // реакция цели «меня атакуют» (№23): до броска; если цель ушла (телепорт) или атакующий пал — атака не состоялась
    crit = false;
    if (hasReact(d.b)) {
        const int dx0 = d.x, dy0 = d.y;
        tryReact(w, (int)(&d - &w.f[0]), 1, (int)(&a - &w.f[0]));
        if (a.hp <= 0 || d.x != dx0 || d.y != dy0) return false;
    }
    // реакция «когда атакуют союзника рядом» (v21): помеха этой атаке или удар оружием по атакующему
    const int pr = allyReact(w, a, d);
    if (pr < 0) return false;   // атакующий пал от удара защитника
    const bool protDis = pr == 1;
    // отражения (пакет атомов 2): атака может уйти в копию (3 копии — 6+, 2 — 8+, 1 — 11+ на к20); копия КД 10 + ЛОВ
    if (d.images > 0) {
        const int need = d.images >= 3 ? 6 : (d.images == 2 ? 8 : 11);
        if (rollD20() >= need) {
            if (rollD20() + mod >= 10 + d.mod(DEX)) d.images--;
            crit = false;
            return false;
        }
    }
    bool adv, dis;
    advState(w, a, d, range, adv, dis);
    if (protDis || g_heavyDis) dis = true;
    if (d.helpBy >= 0 && d.helpBy < (int)w.f.size() && &w.f[d.helpBy] != &a && w.f[d.helpBy].team == a.team) d.helpBy = -1;   // Помощь — на одну атаку
    a.advNext = false;   // и преимущество от события — тоже
    int r = d20(adv, dis);
    crit = (r == 20);
    if (r == 1) { evRoll(a, d, r, mod, -1, adv, dis, false, false); return false; }
    bool noCover = false;
    int die = 0;   // броски и ресурсы (v21): «+ кость к броскам атаки», «атаки не замечают укрытия»
    forRules(a, [&](const Rule& rl, int) {
        if (rl.what == E_ATKDIE && ruleOn(w, a, &d, rl, true, range <= 5)) die += rollDice(rl.n, rl.s);
        if (rl.what == E_NOCOVER && ruleOn(w, a, &d, rl, true, range <= 5)) noCover = true;
    });
    int ac = d.b.ac + (d.acBuffRounds > 0 ? d.acBuff : 0) + (noCover ? 0 : coverBonus(w, a.x, a.y, d.x, d.y)) + ruleAC(w, d, a);
    bool hit = crit || r + mod + die >= ac;   // mod — полный бонус атаки (wAtk или sAtk: с мастерством)
    // переброс (v21): промахнулся — свой переброс (Везунчик); попали по мне — заставить перебросить (Второй шанс)
    if (!hit && useReroll(a, T_MISS)) {
        r = d20(adv, dis);
        crit = r == 20;
        if (r == 1) { evRoll(a, d, r, mod + die, ac, adv, dis, false, false); return false; }
        hit = crit || r + mod + die >= ac;
    }
    if (hit && !crit && useReroll(d, T_HITBY)) {
        r = d20(adv, dis);
        crit = r == 20;
        if (r == 1) { evRoll(a, d, r, mod + die, ac, adv, dis, false, false); return false; }
        hit = crit || r + mod + die >= ac;
    }
    // Парирование: реакцией +к КД против ближней атаки, которая попала бы; нужно видеть атакующего (скрытый не виден);
    // парируют оружием ближнего боя или голыми руками, но не с луком в руках
    if (hit && !crit && range <= 5 && d.b.parry > 0 && canReact(d) && handsForMelee(d.b) && !a.hidden &&
        r + mod + die < ac + d.b.parry) {
        spendReaction(d);
        hit = false;
    }
    // PHB: попадание в упор по парализованному — критическое
    if (hit && d.cond[C_PARAL] && distFt(a, d) <= 5) crit = true;
    if (crit && d.b.critImm) crit = false;   // иммунитет к критам (пакет атомов 1): попадание — обычное
    evRoll(a, d, r, mod + die, ac, adv, dis, hit, crit);
    // «по мне попали атакой вблизи» (огненный щит): урон или состояние атакующему
    if (hit && range <= 5 && !d.b.trigs.empty()) fireTrig(w, d, T_HITMELEE, &a);
    // «попал вблизи после разбега» (наскок, пакет атомов 2): за этот ход сместился хотя бы на 20 фт
    if (hit && range <= 5 && !a.b.trigs.empty() && a.turnX0 >= 0 && 5 * std::max(std::abs(a.x - a.turnX0), std::abs(a.y - a.turnY0)) >= 20)
        fireTrig(w, a, T_CHARGE, &d);
    return hit;
}
void oppAttack(World& w, Fighter& g, Fighter& victim) {
    bool crit;
    if (attackRoll(w, g, victim, g.wAtk(), 5, crit)) {
        int dmg = rollDice(g.b.wN * (crit ? 2 : 1), wDie(g.b));   // провоцирует только вооружённый (moveToward)
        hurt(victim, applyUncanny(victim, std::max(dmg + g.wMod(), 1)), g.b.wType, wPierceNM(g.b));
        riposte(w, victim, g);
    }
}
// Реакция «контратака»: по тому, кто попал по мне ближней атакой, — одна ближняя атака оружием или, без оружия,
// кулаком (1 + мод. СИЛ) (общий каркас: одна реакция за раунд)
void riposte(World& w, Fighter& d, Fighter& a) {
    if (&d == &a || d.team == a.team) return;   // своя область по себе или союзнику — не повод для контратаки
    if (!d.b.riposte || !handsForMelee(d.b) || !canReact(d) || a.hp <= 0 || distFt(d, a) > meleeReach(d.b)) return;
    spendReaction(d);
    g_ripUsed++;
    bool crit;
    if (attackRoll(w, d, a, d.wAtk(), 5, crit)) {
        int dmg = d.b.wN > 0 ? rollDice(d.b.wN * (crit ? 2 : 1), wDie(d.b)) : 1;
        const int src0 = g_srcIdx;
        g_srcIdx = (int)(&d - &w.f[0]);   // урон контратаки наносит d
        hurt(a, std::max(dmg + d.wMod(), 1), d.b.wType, wPierceNM(d.b));
        g_srcIdx = src0;
    }
}
double pHitEst(const World& w, const Fighter& a, const Fighter& d, int mod, int range) {
    bool adv, dis;
    advState(w, a, d, range, adv, dis);
    // ожидаемый эффект Парирования
    double ac = d.b.ac + (d.acBuffRounds > 0 ? d.acBuff : 0) + coverBonus(w, a.x, a.y, d.x, d.y) + ruleAC(w, d, a) +
                ((d.b.parry > 0 && range <= 5 && canReact(d)) ? a.pol->v[PO_PARRYW] * d.b.parry : 0.0);
    double p = std::clamp((21.0 - (ac - mod)) / 20.0, 0.05, 0.95);
    if (adv && !dis) return 1 - (1 - p) * (1 - p);
    if (dis && !adv) return p * p;
    return p;
}
double pFailEst(const Fighter& t, int stat, int dc) {
    if ((t.cond[C_STUN] || t.cond[C_PARAL]) && (stat == STR || stat == DEX)) return 1.0;
    double p = std::clamp((dc - saveBonus(t, stat) - 1) / 20.0, 0.0, 1.0);
    bool dis = stat == DEX && t.cond[C_RESTR] > 0;
    const bool sa = advSave(t);
    double q = (sa && !dis) ? p * p : ((dis && !sa) ? 1 - (1 - p) * (1 - p) : p);
    // ИИ знает, что у цели есть заряды легендарного сопротивления
    return t.lrLeft > 0 ? q * 0.25 : q;
}

// ---------------------------------------------------------------------------
// Оценка ожидаемой ценности (для решений бота)
// ---------------------------------------------------------------------------
double evWeaponBase(const World& w, const Fighter& a, const Fighter& d) {
    if (a.b.wN <= 0) return 0;   // безоружный атаки оружием не делает
    double dice = a.b.wN * (wDie(a.b) + 1) / 2.0 + (a.buffRounds > 0 ? a.buffN * (a.buffS + 1) / 2.0 : 0) + a.wMod();
    const bool melee = wpAtkRange(a.b, distFt(a, d)) <= 5;
    forRules(a, [&](const Rule& r, int) {   // «когда → что»: урон каждого попадания (и ауры союзников)
        if (r.what == E_DMG && !r.once && ruleOn(w, a, &d, r, true, melee)) dice += r.n * (r.s + 1) / 2.0;
    });
    return a.b.wAtt * pHitEst(w, a, d, a.wAtk(), wpAtkRange(a.b, distFt(a, d))) * std::max(0.5, dice) *
           dmgMult(d.b, a.b.wType, wPierceNM(a.b)) * ((d.b.uncanny && canReact(d)) ? 0.8 : 1.0);
}
double condValue(const World& w, const Fighter& me, const Fighter& t, int kind, int rounds) {
    if (t.cond[kind] > 0 || t.cimm[kind] > 0 || (t.b.immCond & (1u << kind))) return 0;
    static const double m[C_N] = {0, 0.3, 0.6, 0.4, 0.4, 0.5, 1.3, 0.3, 1.0, 1.0, 1.6, 1.2, 0.4, 0.4, 0.3, 0.9};
    // «подсвечен» усиливает МОИ атаки, остальное режет урон цели
    return me.pol->v[PO_CONDS] * m[kind] * std::min(rounds, 3) *
           (kind == C_LIT ? evWeaponBase(w, me, t) : evWeaponBase(w, t, me));
}
// ожидаемая ценность удара оружием: базовая + довесок (раз в ход, при хотя бы одном попадании)
double evWeapon(const World& w, const Fighter& a, const Fighter& d) {
    double e = evWeaponBase(w, a, d);
    double any0 = 1 - std::pow(1 - pHitEst(w, a, d, a.wAtk(), wpAtkRange(a.b, distFt(a, d))), a.b.wAtt);
    // «когда → что»: урон раз в ход (при хотя бы одном попадании)
    const bool melee = wpAtkRange(a.b, distFt(a, d)) <= 5;
    for (size_t k = 0; k < a.b.rules.size(); k++) {
        const Rule& r = a.b.rules[k];
        if (a.b.wN > 0 && r.what == E_DMG && r.once && !((a.onceUsed >> k) & 1u) && ruleOn(w, a, &d, r, true, melee))
            e += any0 * r.n * (r.s + 1) / 2.0 * dmgMult(d.b, a.b.wType, wPierceNM(a.b));
    }
    if (a.b.wN <= 0 || (a.b.rN <= 0 && a.b.rCond <= 0)) return e;
    double p = pHitEst(w, a, d, a.wAtk(), wpAtkRange(a.b, distFt(a, d))), any = 1 - std::pow(1 - p, a.b.wAtt), r = 0;
    if (a.b.rN > 0) r += a.b.rN * (a.b.rS + 1) / 2.0 * dmgMult(d.b, a.b.rType, !isPhys(a.b.rType) || a.b.wMagic);
    if (a.b.rCond > 0) {
        double pf = a.b.rCond == C_GRAPPLE ? 1.0 : pFailEst(d, condSaveStat(a.b.rCond), a.dc());
        r += pf * condValue(w, a, d, a.b.rCond, a.b.rRounds);
    }
    return e + any * r;
}
// упрётся ли толчок в стену или существо раньше, чем пройдёт полную длину
bool pushBlocked(const World& w, const Fighter& src, const Fighter& t, int ft) {
    int sx = (t.x > src.x) - (t.x < src.x), sy = (t.y > src.y) - (t.y < src.y);
    for (int i = 0; i < ft / 5; i++) {
        int nx = t.x + sx * (i + 1), ny = t.y + sy * (i + 1);
        if (!fpAll(w, t, nx, ny, [&](int cx, int cy) { return !w.wall[cy][cx] && !w.pit[cy][cx] && !w.tree[cy][cx] && w.height[cy][cx] <= w.height[t.y][t.x]; }) || blockedAt(w, t, nx, ny)) return true;
    }
    return false;
}
double evSpecOne(const World& w, const Spec& s, const Fighter& me, const Fighter& t) {
    double dmg = 0, dc = me.dc() + s.dcB;
    for (auto& d : s.dmgParts()) dmg += d.n * (d.s + 1) / 2.0 * dmgMult(t.b, d.type, specMagical(me.b, d.type));
    double push = t.b.immPush ? 0.0
                              : me.pol->v[PO_PUSHW] * s.pushFt / 5.0 +
                                    (s.collN > 0 && pushBlocked(w, me, t, s.pushFt) ? s.collN * 3.5 : 0.0),
           cv = s.cond ? condValue(w, me, t, s.cond, s.condRounds) : 0;
    double ter = (s.terr && !t.b.fly && !t.b.ignDiff) ? me.pol->v[PO_TERRW] * evWeaponBase(w, t, me) : 0;
    double dot = s.dotN > 0 ? s.dotN * (s.dotS + 1) / 2.0 * std::min(s.dotRounds, 3) * dmgMult(t.b, s.dtype, true) *
                                  me.pol->v[PO_DOTW]
                            : 0;
    if (s.delivery == 0) {
        double ph = pHitEst(w, me, t, me.sAtk(), s.range), pf = pFailEst(t, s.saveStat, dc);
        return ph * (dmg + pf * cv + push + dot) + ter;
    }
    if (s.delivery == 1) {
        double pf = pFailEst(t, s.saveStat, dc);
        return dmg * (pf + (1 - pf) * 0.5) + pf * cv + push + pf * dot + ter;
    }
    return dmg + cv + push + dot + ter;
}
// Ценность области с центром (cx, cy): враги в радиусе — польза, свои (и я сам) — вред, если область не избирательная (№17)
double areaValue(const World& w, const Spec& s, const Fighter& me, int cx, int cy) {
    double ev = 0;
    for (auto& e : w.f) {
        if (e.hp <= 0 || !inShapeF(s.shape, s.radius, me.x, me.y, cx, cy, e)) continue;
        if (e.team != me.team)
            ev += evSpecOne(w, s, me, e);
        else if (!s.selective)
            ev -= evSpecOne(w, s, me, e);
    }
    return ev;
}
double evWeapon(const World& w, const Fighter& a, const Fighter& d);
double evSpec(const World& w, const Spec& s, const Fighter& me, const Fighter& center) {
    if (s.offhand) return evWeaponBase(w, me, center) / std::max(1, me.b.wAtt);   // одна атака
    if (s.onHit) {   // действие Атака + приём на первое попадание
        Spec r = s;
        r.onHit = false;
        r.delivery = s.delivery == 1 ? 1 : 2;
        if (s.pool) r.more.push_back({1, s.poolS, me.b.wType});
        const double p = pHitEst(w, me, center, me.wAtk(), wpAtkRange(me.b, distFt(me, center))), any = 1 - std::pow(1 - p, me.b.wAtt);
        return evWeapon(w, me, center) + any * evSpecOne(w, r, me, center);
    }
    if (s.radius == 0 && s.targets > 1) {   // несколько целей: главная и ещё лучшие враги в пределах дальности
        std::vector<double> ev;
        for (auto& e : w.f)
            if (&e != &center && e.hp > 0 && e.team != me.team && distFt(me, e) <= s.range && losF(w, me, e)) ev.push_back(evSpecOne(w, s, me, e));
        std::sort(ev.rbegin(), ev.rend());
        double v = evSpecOne(w, s, me, center);
        for (int k = 0; k < s.targets - 1 && k < (int)ev.size(); k++) v += ev[k];
        return v;
    }
    if (s.radius == 0) return evSpecOne(w, s, me, center);
    return areaValue(w, s, me, center.x, center.y);
}
// Барьер (№22) для бота: ценен, если ближник ещё не подошёл, а я бьюсь издали — стена перед ним стоит доли его урона за
// каждый раунд барьера (до трёх)
double wallValue(const World& w, const Spec& s, const Fighter& me, const Fighter& e) {
    if (s.wallLen <= 0 || !meleeWeapon(e.b) || meleeWeapon(me.b) || distFt(me, e) <= meleeReach(e.b)) return 0;
    return me.pol->v[PO_WALLW] * evWeaponBase(w, e, me) * std::min(s.wallRounds, 3);
}
// Ценность способности по клетке (cx, cy): всё, что накроет область (враги в радиусе), и барьер перед врагом e
double evSpecAt(const World& w, const Spec& s, const Fighter& me, int cx, int cy, const Fighter* wallFor = nullptr) {
    double ev = 0;
    if (s.dmgN || !s.more.empty() || s.cond || s.pushFt || s.dotN || s.terr) ev += areaValue(w, s, me, cx, cy);
    if (wallFor) ev += wallValue(w, s, me, *wallFor);
    return ev;
}
// Лучшая клетка для способности по клетке (№9, №22): центр на враге или сдвинутый к себе так, чтобы враг остался на
// краю области (достаёт дальше дальности и из-за угла); барьер — на клетку перед ближником. Клетка в пределах дальности
// и видна мне. Возвращает ценность (0 — некуда).
double bestGroundCell(const World& w, const Spec& s, const Fighter& me, const std::vector<int>& enemies, int& gx, int& gy) {
    double best = 0;
    gx = gy = -1;
    auto tryCell = [&](int cx, int cy, const Fighter* wallFor) {
        if (cx < 0 || cy < 0 || cx >= w.aw || cy >= w.ah || w.wall[cy][cx]) return;
        if (distFC(w, me, cx, cy) > s.range || !losFC(w, me, cx, cy)) return;
        const double ev = evSpecAt(w, s, me, cx, cy, wallFor);
        if (ev > best) {
            best = ev;
            gx = cx;
            gy = cy;
        }
    };
    for (int ei : enemies) {
        const Fighter& e = w.f[ei];
        if (e.hp <= 0) continue;
        const int sx = (me.x > e.x) - (me.x < e.x), sy = (me.y > e.y) - (me.y < e.y);
        if (s.wallLen > 0) tryCell(e.x + sx, e.y + sy, &e);
        if (s.wallLen > 0 && !(s.dmgN || s.cond || s.pushFt || s.dotN || s.terr)) continue;
        tryCell(e.x, e.y, nullptr);
        const int k = std::min(s.radius / 5, std::max(std::abs(me.x - e.x), std::abs(me.y - e.y)) - 1);
        if (k > 0 && s.shape <= SH_CUBE) tryCell(e.x + sx * k, e.y + sy * k, nullptr);
    }
    return best;
}

// ---------------------------------------------------------------------------
// Действия
// ---------------------------------------------------------------------------
// команда в строю: жив и не сбежал хоть один её главный боец
inline bool teamIn(const World& w, int t) {
    for (int i = 0; i < w.nLead && i < (int)w.f.size(); i++)
        if (w.f[i].team == t && w.f[i].hp > 0 && !w.f[i].fled) return true;
    return false;
}
bool over(const World& w) {
    if (w.nLead == 2 && w.nTeams == 2)
        return w.f[0].hp <= 0 || w.f[1].hp <= 0 || w.f[0].fled || w.f[1].fled;   // fled — сбежал (вышел за арену или оторвался от погони): проиграл
    int in = 0;   // несколько команд (v21): бой идёт, пока в строю хотя бы две
    for (int t = 0; t < w.nTeams && in < 2; t++) in += teamIn(w, t);
    return in < 2;
}
int nearestEnemyInRange(const World& w, const Fighter& me, int range) {
    int best = -1, bd = 1 << 30;
    for (size_t i = 0; i < w.f.size(); i++) {
        const Fighter& e = w.f[i];
        if (e.hp <= 0 || e.team == me.team || !isKnown(w, me.team, (int)i)) continue;   // туман войны: только известные
        // очарованный не может атаковать очаровавшего
        if (me.cond[C_CHARM] > 0 && me.charmSrc == (int)i) continue;
        int d = distFt(me, e);
        if (d <= range && losF(w, me, e) && e.hp < bd) {
            bd = e.hp;
            best = (int)i;
        }
    }
    return best;
}
// Что сделал боец в этот ход — используется только для визуализатора (реплей).
struct ActInfo {
    std::string type = "none";
    int target = -1;
    int abil = -1;   // номер применённой способности (для просмотрщика)
    int gx = -1, gy = -1;   // клетка, по которой применена способность «по клетке»
};
static thread_local ActInfo g_act;
// события погони и побега для кадров просмотрщика (JSON-объекты); пишутся всегда, но читаются только при записи реплея
static thread_local std::vector<std::string> g_evPending;
void evPush(const std::string& json) {
    if (g_evPending.size() < 64) g_evPending.push_back(json);
}
// Рычаги управления ходом для обучаемого бота (RL): тактика хода поверх готовой эвристики
// stance: 0 обычная, 1 держать позицию, 2 сближение вплотную, 3 кайтинг, 4 отход (движение), 5 Отход (действие), 6
// Уклонение, 7 сначала лечение/баффы, 8 без самобаффов, 9 снять концентрацию (бесплатно, v21 №24) и дальше как 0; tgt: 0 авто, 1 босс, 2 приспешник, 3 слабейший; pref: -1 нет, 0
// оружие, 1+k способность k
struct Ovr {
    bool active = false;
    int stance = 0, tgt = 0, pref = -1;
};
thread_local Ovr g_ovr;
// g_lastHp — доля ХП боссов в конце боя
void (*g_rlTurn)(World&, int) = nullptr;
thread_local bool g_rlTeam[2] = {false, false};
thread_local double g_lastHp[2] = {1, 1};

// ---- Концентрация и ячейки ----
// наименьшая ячейка >= L
int findSlot(const Fighter& f, int L) {
    for (int k = L; k <= 9; k++)
        if (f.slotLeft[k] > 0) return k;
    return 0;
}
void endStatBuff(Fighter& f) {
    if (f.sbAmt) f.b.stats[f.sbStat] -= f.sbAmt;
    f.sbAmt = 0;
    f.sbRounds = 0;
}
// Перенаправление: цель атаки меняется местами с соседним союзником, и атака достаётся ему (реакция)
Fighter& redirected(World& w, const Fighter& a, Fighter& d) {
    if (!d.b.redirect || !canReact(d) || a.hidden || !canSee(w, d, a)) return d;
    Fighter* best = nullptr;
    for (auto& g : w.f)
        if (&g != &d && g.hp > 0 && g.team == d.team && distFt(g, d) <= 5 && (!best || g.hp > best->hp)) best = &g;
    if (!best) return d;
    std::swap(best->x, d.x);
    std::swap(best->y, d.y);
    spendReaction(d);
    return *best;
}
// концентрация сорвана: снимаются состояния и урон по времени, наложенные ею, и баффы заклинателя
void breakConc(World& w, int idx) {
    Fighter& c = w.f[idx];
    if (c.concSpec < 0) return;
    for (auto& f : w.f) {
        for (int k = 1; k < C_N; k++)
            if (f.cond[k] > 0 && f.condConc[k] == idx + 1) f.cond[k] = 0;
        if (f.dotRounds > 0 && f.dotConc == idx + 1) f.dotRounds = 0;
    }
    const Spec& s = c.b.abil[c.concSpec];
    if (s.sumN > 0)   // призыв на концентрации: его приспешники исчезают
        for (auto& f : w.f)
            if (f.summoner == idx && f.sumSpec == c.concSpec && f.hp > 0) {
                f.hp = 0;
                f.vanished = true;
            }
    if (s.buffN) c.buffRounds = 0;
    if (s.sbAmt) endStatBuff(c);
    if (s.acB) c.acBuffRounds = 0;
    if (s.invisN) c.invisRounds = 0;
    c.concSpec = -1;
    c.concDCs.clear();
    g_concBroken++;
}
// ---- Способность — единая структура (переходник поверх Spec, оружия и встроенных манёвров): цена + эффект.
// Атака оружием — способность за действие; Рывок, Уклонение, Отход — встроенные способности. Категория выводится из
// эффекта и отдельно не хранится. Проверка и списание цены — один путь (canPay, payEcon, paySpec) для бота, сети и игрока.
enum Econ { EC_ACTION, EC_BONUS, EC_REACTION, EC_FREE, EC_ATTACK };   // EC_ATTACK — одна атака действия «Атака» (пакет атомов 1)
enum EffKind { EF_WEAPON, EF_SPEC, EF_DASH, EF_DODGE, EF_DISENGAGE, EF_SUMMON, EF_HELP, EF_READY, EF_N };
enum AbCat { CAT_ATTACK, CAT_SPELL, CAT_SUMMON, CAT_MANEUVER, CAT_N };
const char* CATN[CAT_N] = {"атака", "заклинание", "призыв", "манёвр"};
struct AbCost {
    int econ = EC_ACTION;
    // способность Boss::abil, чьи ресурсы тратятся (применения, ячейка, перезарядка, концентрация); −1 — таких нет
    int spec = -1, slotLvl = 0, uses = UNL, recharge = 0;
    bool conc = false;
};
struct Ability {
    int eff = EF_WEAPON;
    AbCost cost;
};
inline Ability builtinAbility(int eff, int econ = EC_ACTION) {
    Ability a;
    a.eff = eff;
    a.cost.econ = econ;
    return a;
}
inline Ability specAbility(const Boss& b, int k) {
    const Spec& s = b.abil[k];
    Ability a;
    a.eff = s.sumN > 0 ? EF_SUMMON : EF_SPEC;   // эффект определяет категорию
    a.cost.econ = s.react ? EC_REACTION : (s.jump && s.teleFt > 0 ? EC_FREE : (s.inAttack ? EC_ATTACK : (s.bonus ? EC_BONUS : EC_ACTION)));
    a.cost.spec = k;
    a.cost.slotLvl = s.slotLvl;
    a.cost.uses = s.uses;
    a.cost.recharge = s.recharge;
    a.cost.conc = s.conc;
    return a;
}
// Переходник: все способности бойца по его сборке — атака оружием (если вооружён), способности Boss::abil (и реакции),
// Рывок, Уклонение, Отход действием и бонусным действием (если умеет); призыв — способность Boss::abil с эффектом sumN
std::vector<Ability> abilitiesOf(const Boss& b) {
    std::vector<Ability> v;
    if (b.wN > 0) v.push_back(builtinAbility(EF_WEAPON));
    for (size_t k = 0; k < b.abil.size(); k++) v.push_back(specAbility(b, (int)k));
    v.push_back(builtinAbility(EF_DASH));
    v.push_back(builtinAbility(EF_DODGE));
    v.push_back(builtinAbility(EF_DISENGAGE));
    if (b.disengB) v.push_back(builtinAbility(EF_DISENGAGE, EC_BONUS));
    v.push_back(builtinAbility(EF_HELP));    // Помощь и Подготовка — у всех, как Рывок (v21)
    if (b.wN > 0) v.push_back(builtinAbility(EF_READY));
    return v;
}
// категория способности сборки (решение владельца): призыв — «призыв»; по врагу без ячейки и концентрации — «атака»;
// с ячейкой, концентрацией или на себя — «заклинание»
inline int specCategory(const Spec& s) {
    if (s.sumN > 0) return CAT_SUMMON;
    return (s.self || s.slotLvl > 0 || s.conc) ? CAT_SPELL : CAT_ATTACK;
}
inline int abCategory(const Boss& b, const Ability& a) {
    switch (a.eff) {
        case EF_WEAPON: return CAT_ATTACK;
        case EF_SPEC:
        case EF_SUMMON: return specCategory(b.abil[a.cost.spec]);
        default: return CAT_MANEUVER;
    }
}
// Хватает ли ресурсов самой способности (применения, концентрация, ячейка); экономику действия проверяет canPay
bool resReady(const Fighter& me, const AbCost& c, const char** why = nullptr) {
    auto no = [&](const char* m) {
        if (why) *why = m;
        return false;
    };
    if (c.spec < 0) return true;
    if (me.inForm) return no("В облике способности недоступны.");
    if (me.uses[c.spec] <= 0) return no("Способность использована.");
    if (c.conc && me.concSpec >= 0) return no("Вы уже держите концентрацию.");
    if (c.slotLvl > 0 && !findSlot(me, c.slotLvl)) return no("Нет подходящей ячейки заклинания.");
    const Spec& s = me.b.abil[c.spec];
    if (s.pool && me.poolLeft <= 0) return no("Кости запаса кончились.");
    if ((s.onHit || s.offhand) && (me.b.wN <= 0 || me.disarmed)) return no("Нужно оружие в руке.");
    if (s.offhand && !me.wAtkTurn) return no("Атака второй рукой — после атаки оружием в этот ход.");
    if (s.noRepeat && c.spec < (int)me.usedRound.size() && me.usedRound[c.spec] >= 0 && me.usedRound[c.spec] >= g_curRound - 1)
        return no("Не два раунда подряд: эта способность была в прошлом раунде.");
    return true;
}
inline bool specResReady(const Fighter& me, int k) {
    return resReady(me, specAbility(me.b, k).cost);
}
// Плата за способность k (один путь списания): применение, наименьшая подходящая ячейка, концентрация. takeConc = false —
// эффект без длительности (прыжок): концентрацию не занимает
void paySpec(World& w, Fighter& me, int k, bool takeConc) {
    const Spec& s = me.b.abil[k];
    if (k < (int)me.usedRound.size()) me.usedRound[k] = g_curRound;   // «не два раунда подряд»
    {   // используемость (№6): каждое применение способности отмечает её атомы
        const int i = (int)(&me - &w.f[0]);
        if (i >= 0 && i < 2) {
            AMask m = 0;
            markSpec(s, m);
            for (int a = 0; a < AT_N; a++)
                if ((m >> a) & ONE) g_castAtom[i][a]++;
        }
    }
    me.uses[k]--;
    if (s.slotLvl > 0) {
        const int L = findSlot(me, s.slotLvl);
        if (L) me.slotLeft[L]--;
    }
    if (takeConc && s.conc) {
        const int myIdx = (int)(&me - &w.f[0]);
        if (me.concSpec >= 0) breakConc(w, myIdx);
        me.concSpec = k;
        me.concDCs.clear();
        g_concCast++;
    }
}
// проверка концентрации: на каждое полученное попадание спасбросок ТЕЛ против своей СЛ max(10, урон/2)
void resolveConc(World& w) {
    for (size_t i = 0; i < w.f.size(); i++) {
        Fighter& f = w.f[i];
        if (f.concSpec < 0) continue;
        if (f.hp <= 0) {
            breakConc(w, (int)i);
            continue;
        }
        std::vector<int> dcs;
        dcs.swap(f.concDCs);
        for (int dc : dcs)
            if (d20(false, false) + saveBonus(f, CON) < dc) {
                breakConc(w, (int)i);
                break;
            }
    }
}
void applyRider(World& w, Fighter& me, Fighter& t, bool crit) {
    if (me.b.rN > 0)
        hurt(t, rollDice(me.b.rN * (crit ? 2 : 1), me.b.rS), me.b.rType, !isPhys(me.b.rType) || me.b.wMagic);
    if (me.b.rCond > 0 && t.hp > 0) {
        int st = condSaveStat(me.b.rCond), dc = me.dc();
        Spec sp;
        sp.cond = me.b.rCond;
        sp.condRounds = me.b.rRounds;
        // захват — без спасброска (СЛ побега)
        bool ok = me.b.rCond == C_GRAPPLE ? false : saveLR(t, st, dc, lrWorth(t, sp));
        if (!ok && applyCond(t, me.b.rCond, me.b.rRounds, st, dc, true, (int)(&me - &w.f[0])) && me.b.rCond == C_GRAPPLE)
            grabExtras(t, (int)(&me - &w.f[0]), me.b.rGrabRestr, me.b.rGrabDotN, me.b.rGrabDotS, me.b.wType);
    }
}
// nAtt<0 — полное действие Атака
// досягаемость цели t: дальше неё t не ответит атакой оружием (безоружный не отвечает вовсе)
inline int threatDist(const Fighter& t) {
    return t.b.wN > 0 ? atkDist(t.b) : 0;
}
inline void useAttack(const World& w, const Fighter& me, int tIdx, bool weapon) {
    const int i = (int)(&me - &w.f[0]);
    if (i < 0 || i > 1 || tIdx < 0 || tIdx >= (int)w.f.size()) return;
    g_use[i][weapon ? U_WATK : U_SATK]++;
    if (distFt(me, w.f[tIdx]) > threatDist(w.f[tIdx])) g_use[i][weapon ? U_WOUT : U_SOUT]++;
}
void hitOne(World& w, const Spec& s, Fighter& me, Fighter& t0);
// приём «при попадании» (v21): плата (применение, кость запаса) — только при попадании; эффекты способности ложатся на
// попавшую цель (без своего броска атаки; со спасброском, если доставка 1), кость запаса — к урону; урон себе; лечение
// себе, если цель умерла от удара; обезоруживание
void applyManeuver(World& w, Fighter& me, int si, Fighter& t, bool crit) {
    const Spec s = me.b.abil[si];
    paySpec(w, me, si, true);
    g_act.abil = si;
    if (s.pool) me.poolLeft--;
    Spec r = s;
    r.onHit = false;
    r.delivery = s.delivery == 1 ? 1 : 2;   // уже попал: без своего броска
    r.radius = 0;
    if (s.pool) r.more.push_back({1, s.poolS, s.dmgN > 0 ? s.dtype : me.b.wType});
    if (crit) {   // крит удваивает кости приёма, как и кости оружия
        r.dmgN *= 2;
        for (auto& d : r.more) d.n *= 2;
    }
    if (r.dmgN > 0 || !r.more.empty() || r.cond || r.pushFt || r.dotN) hitOne(w, r, me, t);
    if (s.disarm && t.hp > 0 && t.b.wN > 0 && !t.b.wNatural && (s.delivery != 1 || !saveLR(t, STR, me.dc() + s.dcB, false))) t.disarmed = true;
    if (s.selfN > 0) hurt(me, rollDice(s.selfN, s.selfS), s.dtype, true);
    if ((s.killN > 0 || s.killB > 0) && t.hp <= 0 && me.hp > 0) me.hp = std::min(me.maxHp, me.hp + rollDice(s.killN, s.killS) + s.killB);
}
// man — приём «при попадании» (индекс способности, −1 — нет); offhand — атака второй рукой (одна, модификатор к урону
// только со стилем или если он отрицательный)
void doWeaponMain(World& w, Fighter& me, int tIdx, int nAtt, int man, bool offhand, bool twfMod);
// удары оружием мультиатаки (запасное с флагом multi): по той же цели, если достают, иначе по ближайшей в досягаемости
void altMultiAttacks(World& w, Fighter& me, int tIdx) {
    for (size_t k = 0; k < me.b.alt.size(); k++) {
        if (!me.b.alt[k].multi) continue;
        if (me.hp <= 0 || me.disarmed || over(w)) return;
        swapWeapon(me.b, k);
        int t = tIdx;
        if (t < 0 || t >= (int)w.f.size() || w.f[t].hp <= 0 || distFt(me, w.f[t]) > atkDist(me.b)) t = nearestEnemyInRange(w, me, atkDist(me.b));
        if (t >= 0) doWeaponMain(w, me, t, me.b.wAtt, -1, false, false);
        swapWeapon(me.b, k);
    }
}
// Атака оружием; nAtt == −1 — целое действие «Атака»: все удары основным оружием и (пакет атомов 1) оружием мультиатаки
void doWeapon(World& w, Fighter& me, int tIdx, int nAtt, int man, bool offhand, bool twfMod) {
    doWeaponMain(w, me, tIdx, nAtt, man, offhand, twfMod);
    if (nAtt == -1 && man < 0 && !offhand && !me.b.alt.empty()) altMultiAttacks(w, me, tIdx);
}
void doWeaponMain(World& w, Fighter& me, int tIdx, int nAtt, int man, bool offhand, bool twfMod) {
    if (me.b.wN <= 0 || me.disarmed) return;   // безоружный (или обезоруженный) атаки оружием не делает (v21)
    useAttack(w, me, tIdx, true);
    if (!offhand) me.wAtkTurn = true;
    g_act.type = wpAtkRange(me.b, distFt(me, w.f[tIdx])) > 5 ? "attack-ranged" : "attack-melee";
    g_act.target = tIdx;
    int total = nAtt < 0 ? me.b.wAtt : std::min(nAtt, me.b.wAtt);
    for (int i = 0; i < total; i++) {
        if (over(w)) return;
        if (w.f[tIdx].hp <= 0) {
            tIdx = nearestEnemyInRange(w, me, atkDist(me.b));
            if (tIdx < 0) return;
        }
        Fighter& t = redirected(w, me, w.f[tIdx]);
        bool crit;
        const int range = wpAtkRange(me.b, distFt(me, t));   // метательным вплотную бьют как ближним
        // размен (v21, Мастер большого оружия): −N к попаданию, +2N к урону — когда это выгоднее по ожиданию
        int power = 0;
        forRules(me, [&](const Rule& rl, int) {
            if (rl.what == E_POWER && ruleOn(w, me, &t, rl, true, range <= 5)) power = std::max(power, rl.n);
        });
        if (power > 0) {
            const double avg = me.b.wN * (wDie(me.b) + 1) / 2.0 + me.wMod(), p1 = pHitEst(w, me, t, me.wAtk(), range), p2 = pHitEst(w, me, t, me.wAtk() - power, range);
            if (!(p2 * (avg + 2 * power) > p1 * avg)) power = 0;
        }
        g_heavyDis = me.b.wHeavy && me.b.size < 2;   // размеры (v21): маленьким тяжёлое оружие — с помехой
        bool hit = attackRoll(w, me, t, me.wAtk() - power, range, crit);
        g_heavyDis = false;
        g_attacksMade++;
        me.hidden = false;
        if (!hit) continue;
        int dmg = 2 * power + rollDice(me.b.wN * (crit ? 2 : 1), wDie(me.b)) + (offhand && !twfMod ? std::min(0, me.wMod()) : me.wMod());
        if (me.growRounds != 0) dmg += rollDice(crit ? 2 : 1, 4);   // увеличение (пакет атомов 2): +1к4 к урону оружия
        if (me.buffRounds > 0) dmg += rollDice(me.buffN * (crit ? 2 : 1), me.buffS);
        // «когда → что»: кубики к урону оружия (каждое попадание или раз в ход)
        forRules(me, [&](const Rule& r, int k) {
            if (r.what != E_DMG || (r.once && k >= 0 && ((me.onceUsed >> k) & 1u)) || !ruleOn(w, me, &t, r, true, range <= 5)) return;
            dmg += rollDice(r.n * (crit ? 2 : 1), r.s);
            if (r.once && k >= 0) me.onceUsed |= 1u << k;
        });
        const int hpBefore = t.hp;
        hurt(t, applyUncanny(t, std::max(dmg, 1)), me.b.wType, wPierceNM(me.b));
        if (crit) fireTrig(w, me, T_CRIT, &t);                      // «событие → эффект» (v21)
        if (hpBefore > 0 && t.hp <= 0) fireTrig(w, me, T_KILL, &t);
        if (range <= 5) {   // Подвижный (v21): после моей атаки ближнего боя цель не провоцирует от меня до конца хода
            bool noOA = false;
            forRules(me, [&](const Rule& rl, int) {
                if (rl.what == E_NOOA && selfOn(me, rl)) noOA = true;
            });
            if (noOA) t.noOAvs = (int)(&me - &w.f[0]);
        }
        if (man >= 0 && me.hp > 0) {   // приём — на первое попадание этого действия
            applyManeuver(w, me, man, t, crit);
            man = -1;
        }
        if (!me.riderUsed && (me.b.rN > 0 || me.b.rCond > 0)) {
            me.riderUsed = true;
            applyRider(w, me, t, crit);
        }
        if (range <= 5) riposte(w, t, me);
    }
}
// реакция «когда атакуют союзника рядом» (v21): свой рядом с целью тратит реакцию — помеха этой атаке (как стиль
// «Защита») или удар оружием по атакующему (как «Страж»). 1 — помеха, 0 — нет, −1 — атакующий пал
int allyReact(World& w, Fighter& a, Fighter& d) {
    bool protDis = false;
    for (size_t gi = 0; gi < w.f.size() && !protDis; gi++) {
        Fighter& g = w.f[gi];
        if (&g == &d || &g == &a || g.hp <= 0 || g.team != d.team || !canReact(g)) continue;
        for (size_t k = 0; k < g.b.abil.size(); k++) {
            const Spec& s = g.b.abil[k];
            if (s.react != 5 || !specResReady(g, (int)k) || distFt(g, d) > std::max(5, s.range)) continue;
            if (s.strike && (g.b.wN <= 0 || g.disarmed || distFt(g, a) > atkDist(g.b))) continue;
            spendReaction(g);
            paySpec(w, g, (int)k, false);
            evPush("{\"k\":\"react\",\"who\":" + std::to_string(gi) + ",\"abil\":" + std::to_string(k) + ",\"trig\":5}");
            g_reactUsed++;
            if (s.protect) protDis = true;
            if (s.strike) {
                const ActInfo saved = g_act;
                doWeapon(w, g, (int)(&a - &w.f[0]), 1);
                g_act = saved;
                if (a.hp <= 0) return -1;
            }
            break;
        }
    }
    return protDis ? 1 : 0;
}
// «событие → эффект» (v21): событие on у бойца me, tgt — цель события (кого критнул, убил, кто провалил спас). Атака
// бонусным действием и добавка скорости ждут хода (resolvePending: там есть бюджет хода)
void fireTrig(World& w, Fighter& me, int on, Fighter* tgt) {
    if (me.b.trigs.empty() || me.trigLeft.size() != me.b.trigs.size() || me.hp <= 0) return;
    for (size_t k = 0; k < me.b.trigs.size(); k++) {
        const Trig& t = me.b.trigs[k];
        if (t.on != on || me.trigLeft[k] <= 0 || t.what == X_INITB || t.what == X_STAY1) continue;
        if (on == T_DMGTYPE && t.arg != g_trigType) continue;
        if ((t.what == X_DMG || t.what == X_COND) && (!tgt || tgt->hp <= 0)) continue;
        if (t.uses < UNL) me.trigLeft[k]--;
        switch (t.what) {
            case X_BONUSATK:
                me.pendBonus = true;
                me.pendTgt = tgt ? (int)(tgt - &w.f[0]) : -1;
                break;
            case X_HEAL: me.hp = std::min(me.maxHp, me.hp + rollDice(t.n, t.s) + t.b); break;
            case X_TEMP: me.temp = std::max(me.temp, rollDice(t.n, t.s) + t.b); break;
            case X_DMG: hurt(*tgt, rollDice(t.n, t.s) + t.b, me.b.wN > 0 ? me.b.wType : DT_FORCE, me.b.wMagic); break;
            case X_COND: if (t.cond > 0) applyCond(*tgt, t.cond, std::max(1, t.n), condSaveStat(t.cond), me.dc(), true, (int)(&me - &w.f[0])); break;
            case X_ADVNEXT: me.advNext = true; break;
            case X_SPEED: me.pendSpeed += 5 * t.n; break;
            case X_SELFCOND: if (t.cond > 0) applyCond(me, t.cond, std::max(1, t.n), -1, 0, false); break;   // без спасброска
        }
    }
}
// притягивание (v21): цель сдвигается к источнику по шагу, пока не встанет вплотную; стены, ущелья и существа останавливают
// опасная зона под f: урон не чаще раза за ход (номер хода — g_turnSerial)
thread_local int g_turnSerial = 0;
void hazardHit(World& w, Fighter& f) {
    int k = 0;   // зона хоть под одной клеткой квадрата
    for (int dy = 0; dy < fpN(f) && !k; dy++)
        for (int dx = 0; dx < fpN(f) && !k; dx++)
            if (f.x + dx < W && f.y + dy < W) k = w.haz[f.y + dy][f.x + dx];
    // летун над землёй не касается жидкостей и льда, а с 20 фт и выше — никаких зон
    if (!k || f.hp <= 0 || ((f.b.fly || f.up) && HAZ[k].flySafe) || f.alt >= 2 || f.hazTurn == g_turnSerial) return;
    f.hazTurn = g_turnSerial;
    int dmg = rollDice(w.hazN, 10);
    const bool ok = saveOK(f, HAZ[k].save, w.hazDC);
    if (ok) dmg /= 2;
    const int src0 = g_srcIdx, hp0 = f.hp;
    g_srcIdx = -1;
    hurt(f, dmg, HAZ[k].dtype, false);
    g_srcIdx = src0;
    evPush("{\"k\":\"haz\",\"who\":" + std::to_string((int)(&f - &w.f[0])) + ",\"kind\":" + std::to_string(k) + ",\"dmg\":" + std::to_string(hp0 - f.hp) + ",\"save\":" + (ok ? "1" : "0") + "}");
}
void pullToward(World& w, Fighter& src, Fighter& t, int ft) {
    if (t.b.immPush || t.b.size > src.b.size + 1) return;
    for (int i = 0; i < ft / 5; i++) {
        if (fpGap(t.x, fpN(t), src.x, fpN(src)) <= 1 && fpGap(t.y, fpN(t), src.y, fpN(src)) <= 1) break;
        const int nx = t.x + ((src.x > t.x) - (src.x < t.x)), ny = t.y + ((src.y > t.y) - (src.y < t.y));
        if (!fpAll(w, t, nx, ny, [&](int cx, int cy) { return !w.wall[cy][cx] && w.door[cy][cx] != 1 && !w.pit[cy][cx] && !w.tree[cy][cx]; }) || blockedAt(w, t, nx, ny)) break;
        if (!stepOK(w, t, t.x, t.y, t.up, nx, ny, t.up)) break;   // по своему ярусу, без обрывов
        t.x = nx;
        t.y = ny;
    }
    hazardHit(w, t);
}
void pushAway(World& w, Fighter& src, Fighter& t, int ft, int collN = 0) {
    if (t.b.immPush || t.b.size > src.b.size + 1) return;   // размеры (v21): толкнуть — не больше чем на ступень крупнее
    int steps = ft / 5;
    int sx = (t.x > src.x) - (t.x < src.x), sy = (t.y > src.y) - (t.y < src.y);
    const int h0 = zF(w, t);
    for (int i = 0; i < steps; i++) {
        int nx = t.x + sx, ny = t.y + sy;
        bool out = nx < 0 || ny < 0 || nx >= W || ny >= W;
        if (!out && t.up && !w.wall[ny][nx] && !w.deck[ny][nx] && !blockedAt(w, t, nx, ny)) {   // столкнули с настила: падает вниз
            t.x = nx;
            t.y = ny;
            t.up = false;
            break;
        }
        if (!out && t.up) {   // по настилу: дальше только по настилу
            if (w.wall[ny][nx] || blockedAt(w, t, nx, ny) || std::abs(w.deck[ny][nx] - w.deck[t.y][t.x]) > 1) break;
            t.x = nx;
            t.y = ny;
            continue;
        }
        // упёрся (стена, ущелье, уступ вверх, существо): урон при столкновении получает толкаемый и, если это существо, преграда
        out = out || !fpAll(w, t, nx, ny, [](int, int) { return true; });   // квадрат выходит за арену
        if (out || !fpAll(w, t, nx, ny, [&](int cx, int cy) { return !w.wall[cy][cx] && w.door[cy][cx] != 1 && !w.pit[cy][cx] && !w.tree[cy][cx] && w.height[cy][cx] <= w.height[t.y][t.x]; }) ||
            blockedAt(w, t, nx, ny)) {
            if (collN > 0) {
                hurt(t, rollDice(collN, 6), DT_FORCE, true);
                if (!out)
                    if (Fighter* g = blockerAt(w, t, nx, ny)) hurt(*g, rollDice(collN, 6), DT_FORCE, true);
            }
            break;
        }
        t.x = nx;
        t.y = ny;
    }
    // сброс с возвышенности или настила: падение, по 1к6 за уровень (10 фт) и сбит с ног
    const int drop = h0 - zF(w, t);
    if (drop > 0 && t.hp > 0) {
        hurt(t, rollDice(drop, 6), DT_BLUDGEONING, false);
        if (t.hp > 0) applyCond(t, C_PRONE, 1, -1, 0, false);
    }
    hazardHit(w, t);
}
// цель внутри чужой (или своей) сферы неуязвимости, а заклинатель снаружи: способность уровня не выше сферы не проходит
bool globeBlocks(const World& w, const Spec& s, const Fighter& me, const Fighter& t) {
    const int lvl = s.slotLvl > 0 ? s.slotLvl : 1;   // способности без ячейки — как 1-й уровень
    for (auto& g : w.f)
        if (g.hp > 0 && g.globeRounds > 0 && lvl <= g.globeLvl && distFt(g, t) <= g.globeR && distFt(g, me) > g.globeR) return true;
    return false;
}
void hitOne(World& w, const Spec& s, Fighter& me, Fighter& t0) {
    if (t0.banished > 0) return;                    // изгнанного нет на поле
    if (globeBlocks(w, s, me, t0)) return;          // сфера неуязвимости (пакет атомов 2)
    if (s.healAlly && t0.team == me.team) {         // способность лечит союзников вместо урона (пакет атомов 2)
        int h = 0;
        for (auto& part : s.dmgParts()) h += rollDice(part.n, part.s);
        if (&t0 != &me || s.radius > 0) t0.hp = std::min(t0.maxHp, t0.hp + h);
        return;
    }
    if (me.team != t0.team) me.struckFoe = true;
    Fighter& t = (s.delivery == 0 && s.radius == 0) ? redirected(w, me, t0) : t0;
    int dc = me.dc() + s.dcB;
    bool crit = false;
    bool applyC = false, applyD = false, saveFailed = false;
    // урон по компонентам (№10): каждый тип бросается и проходит защиты цели отдельно
    const auto parts = s.dmgParts();
    std::vector<int> dmg(parts.size(), 0);
    auto roll = [&](bool twice) {
        for (size_t k = 0; k < parts.size(); k++) dmg[k] = rollDice(parts[k].n * (twice ? 2 : 1), parts[k].s);
    };
    if (s.delivery == 0) {
        if (!attackRoll(w, me, t, me.sAtk(), s.range, crit)) return;
        roll(crit);
        // Невероятное уклонение: одна реакция на всю атаку, решение по сумме, вдвое меньше каждый компонент
        int tot = 0;
        for (int x : dmg) tot += x;
        if (!parts.empty() && applyUncanny(t, tot) < tot)
            for (int& x : dmg) x /= 2;
        // урон по времени при попадании — без спасброска
        applyD = s.dotN > 0;
        // захват при попадании — без спасброска
        g_saveVsAbil = true;
        applyC = s.cond && (s.cond == C_GRAPPLE || !saveLR(t, s.saveStat, dc, lrWorth(t, s)));
        g_saveVsAbil = false;
    } else if (s.delivery == 1) {
        // невосприимчив после успеха (пакет атомов 1): эта способность этого заклинателя его больше не берёт
        const int immKey = (int)(&me - &w.f[0]) * 64 + g_curAbil;
        if (s.immSave && std::find(t.immAbil.begin(), t.immAbil.end(), immKey) != t.immAbil.end()) return;
        g_saveVsAbil = true;
        bool ok = saveLR(t, s.saveStat, dc, lrWorth(t, s));
        g_saveVsAbil = false;
        if (ok && s.immSave) t.immAbil.push_back(immKey);
        roll(false);
        const bool evade = t.b.evasion && s.saveStat == DEX && s.radius > 0 && !t.cond[C_STUN] && !t.cond[C_PARAL];   // Увёртливость (PHB)
        if (ok || evade)
            for (int& x : dmg) x = ok && evade ? 0 : x / 2;
        applyC = s.cond && !ok;
        applyD = s.dotN > 0 && !ok;
        saveFailed = !ok;
    } else {
        roll(false);
        applyC = s.cond > 0;
        applyD = s.dotN > 0;
    }
    // сопротивление урону от способностей (пакет атомов 1): вдвое меньше; с резистом к типу не складывается
    if (t.b.spellRes)
        for (size_t k = 0; k < parts.size(); k++)
            if (!((t.b.resMask >> parts[k].type) & 1)) dmg[k] /= 2;
    // один источник урона — одна проверка концентрации на сумму полученного (PHB)
    int taken = 0;
    const int hpBefore = t.hp;
    for (size_t k = 0; k < parts.size(); k++) taken += hurt(t, dmg[k], parts[k].type, specMagical(me.b, parts[k].type), false);
    // прочее (v21): урон снижает максимум хитов; вампиризм — половина нанесённого себе; притягивание; рассеивание
    if (s.maxHpDmg && taken > 0) {
        t.maxHp = std::max(1, t.maxHp - taken);
        t.hp = std::min(t.hp, t.maxHp);
    }
    if (s.drain && taken > 0 && me.hp > 0) me.hp = std::min(me.maxHp, me.hp + taken / 2);
    const bool landed = s.delivery == 2 || (s.delivery == 1 ? saveFailed : true);
    if (s.pullFt > 0 && t.hp > 0 && landed) pullToward(w, me, t, s.pullFt);
    if (s.dispel && t.hp > 0 && landed) {
        t.buffRounds = t.acBuffRounds = t.invisRounds = 0;
        if (t.sbRounds > 0) {
            t.sbRounds = 0;
            endStatBuff(t);
        }
        if (t.concSpec >= 0) breakConc(w, (int)(&t - &w.f[0]));
    }
    if (me.team != t.team) {   // «событие → эффект» (v21): враг провалил спасбросок от моей способности; убил
        if (saveFailed) fireTrig(w, me, T_SAVEFAIL, &t);
        if (hpBefore > 0 && t.hp <= 0) fireTrig(w, me, T_KILL, &t);
    }
    if (taken > 0 && t.concSpec >= 0) t.concDCs.push_back(std::max(10, taken / 2));
    if (applyC && t.hp > 0 &&
        applyCond(t, s.cond, s.condRounds, s.saveStat, dc, s.delivery != 2 && !s.noRep, (int)(&me - &w.f[0]),
                  s.conc ? (int)(&me - &w.f[0]) + 1 : 0) && s.cond == C_GRAPPLE)
        grabExtras(t, (int)(&me - &w.f[0]), s.grabRestr, s.grabDot ? s.dotN : 0, s.dotS, s.dtype);
    if (s.grabDot && s.cond == C_GRAPPLE) applyD = false;   // урон по времени — пока держит (grabExtras), а не на N раундов
    // изгнание (пакет атомов 2): цель исчезает с поля на N раундов (атака — при попадании, спасбросок — при провале)
    if (s.banishN > 0 && t.hp > 0 && (s.delivery != 1 || saveFailed)) {
        t.banished = std::max(t.banished, s.banishN);
        t.banishSrc = (int)(&me - &w.f[0]);
    }
    // один урон по времени на цель: заменяется, если новый не слабее
    if (applyD && t.hp > 0) {
        double nw = s.dotN * (s.dotS + 1) / 2.0 * s.dotRounds, old = t.dotN * (t.dotS + 1) / 2.0 * t.dotRounds;
        if (nw >= old) {
            t.dotN = s.dotN;
            t.dotS = s.dotS;
            t.dotType = s.dtype;
            t.dotRounds = s.dotRounds;
            t.dotConc = s.conc ? (int)(&me - &w.f[0]) + 1 : 0;
        }
    }
    if (s.pushFt && t.hp > 0) pushAway(w, me, t, s.pushFt, s.collN);
    if (s.delivery == 0 && s.range <= 5) riposte(w, t, me);
}
// Запись изменения арены (для просмотрщика) и временная стена: линия из n клеток поперёк направления от колдующего к клетке (cx, cy), по центру на ней.
// Клетки с существами, ущелья и уже стены пропускаются. Стена непроходима, закрывает обзор; через rounds раундов исчезает.
void dynAdd(World& w, int x, int y, int kind, int rounds) { w.dyn.push_back({x, y, kind, rounds}); }
// дверь: состояние в мире и в изменениях арены (6 открыта, 7 закрыта — последняя запись по клетке)
void setDoor(World& w, int x, int y, int st) {
    if (!w.door[y][x] || w.door[y][x] == st) return;
    w.door[y][x] = (unsigned char)st;
    for (size_t i = 0; i < w.dyn.size();)
        if (w.dyn[i][0] == x && w.dyn[i][1] == y && (w.dyn[i][2] == 6 || w.dyn[i][2] == 7)) w.dyn.erase(w.dyn.begin() + i);
        else i++;
    dynAdd(w, x, y, st == 2 ? 6 : 7, -1);
    evPush(std::string("{\"k\":\"door\",\"x\":") + std::to_string(x) + ",\"y\":" + std::to_string(y) + ",\"open\":" + (st == 2 ? "1" : "0") + "}");
}
int placeWall(World& w, const Fighter& me, int cx, int cy, int n, int rounds) {
    const int dx = cx - me.x, dy = cy - me.y, ax = std::abs(dx), ay = std::abs(dy), sx = dx > 0 ? 1 : -1, sy = dy > 0 ? 1 : -1;
    int px, py;
    if (ax == 0 && ay == 0) { px = 1; py = 0; }
    else if (ax >= 2 * ay) { px = 0; py = 1; }
    else if (ay >= 2 * ax) { px = 1; py = 0; }
    else { px = -sy; py = sx; }
    int placed = 0;
    for (int i = -(n - 1) / 2; i <= n / 2; i++) {
        const int x = cx + px * i, y = cy + py * i;
        if (x < 0 || y < 0 || x >= w.aw || y >= w.ah || w.wall[y][x] || w.pit[y][x] || occupied(w, x, y, nullptr)) continue;
        w.wall[y][x] = true;
        w.mapVer = ++g_mapSerial;
        dynAdd(w, x, y, 1, rounds + 1);
        placed++;
    }
    return placed;
}
// в конце раунда: временные стены тают
void expireDyn(World& w) {
    for (size_t i = 0; i < w.dyn.size();) {
        auto& d = w.dyn[i];
        if (d[3] > 0 && --d[3] == 0) {
            if (d[2] == 1) w.wall[d[1]][d[0]] = false, w.mapVer = ++g_mapSerial;
            w.dyn.erase(w.dyn.begin() + i);
        } else
            i++;
    }
}
// урон объекту в клетке (x, y): хиты кончились — объект рушится, остаются обломки (труднопроходимо). Яд и психический — мимо
bool hitObject(World& w, int x, int y, int dmg, int dtype) {
    if (!isObject(w, x, y) || w.ohp[y][x] <= 0 || dmg <= 0 || dtype == DT_POISON || dtype == DT_PSYCHIC) return false;
    w.ohp[y][x] = (short)std::max(0, w.ohp[y][x] - dmg);
    if (w.ohp[y][x] > 0) return false;
    if (w.door[y][x]) {   // выбитая дверь: пустой проём
        w.door[y][x] = 0;
        dynAdd(w, x, y, 8, -1);
        evPush("{\"k\":\"break\",\"x\":" + std::to_string(x) + ",\"y\":" + std::to_string(y) + "}");
        return true;
    }
    w.wall[y][x] = w.tree[y][x] = w.climb[y][x] = false;
    w.mapVer = ++g_mapSerial;
    w.diff[y][x] = true, w.mapVer = ++g_mapSerial;
    dynAdd(w, x, y, 4, -1);
    evPush("{\"k\":\"break\",\"x\":" + std::to_string(x) + ",\"y\":" + std::to_string(y) + "}");
    return true;
}
// настил (мост, балкон, потолок) рушится: стоявшие на нём падают (1к6 за уровень, сбиты с ног), стоявших под ним бьёт
// обвал (2к10 дробящего, спасбросок ЛОВ СЛ 15 — половина); внизу обломки
bool hitDeck(World& w, int x, int y, int dmg, int dtype) {
    if (x < 0 || y < 0 || x >= w.aw || y >= w.ah || !w.deck[y][x] || w.dhp[y][x] <= 0 || dmg <= 0 || dtype == DT_POISON || dtype == DT_PSYCHIC) return false;
    w.dhp[y][x] = (short)std::max(0, w.dhp[y][x] - dmg);
    if (w.dhp[y][x] > 0) return false;
    const int top = w.deck[y][x];
    w.deck[y][x] = 0;
    w.mapVer = ++g_mapSerial;
    dynAdd(w, x, y, 5, -1);
    evPush("{\"k\":\"collapse\",\"x\":" + std::to_string(x) + ",\"y\":" + std::to_string(y) + "}");
    for (auto& f : w.f) {
        if (f.hp <= 0 || f.x != x || f.y != y) continue;
        if (f.up) {
            f.up = false;
            const int drop = top - zAt(w, x, y);
            if (drop > 0) hurt(f, rollDice(drop, 6), DT_BLUDGEONING, false);
            if (f.hp > 0) applyCond(f, C_PRONE, 1, -1, 0, false);
        } else {
            int d = rollDice(2, 10);
            if (saveOK(f, DEX, 15)) d /= 2;
            hurt(f, d, DT_BLUDGEONING, false);
        }
    }
    if (!w.wall[y][x] && !w.pit[y][x]) {
        w.diff[y][x] = true, w.mapVer = ++g_mapSerial;
        dynAdd(w, x, y, 4, -1);
    }
    return true;
}
// область способности задевает объекты: урон кубиками способности (объект не спасается), по разу на клетку
void areaHitsObjects(World& w, const Spec& s, const Fighter& me, int cx, int cy) {
    if (s.dmgN <= 0 && s.more.empty()) return;
    const int rr = s.radius / 5 + 1;
    const bool fromMe = s.shape == SH_CONE || s.shape == SH_LINE;
    const int bx = fromMe ? me.x : cx, by = fromMe ? me.y : cy;
    for (int y = std::max(0, by - rr); y <= std::min(w.ah - 1, by + rr); y++)
        for (int x = std::max(0, bx - rr); x <= std::min(w.aw - 1, bx + rr); x++) {
            if (!inShape(s.shape, s.radius, me.x, me.y, cx, cy, x, y)) continue;
            if (w.deck[y][x] && w.dhp[y][x] > 0) hitDeck(w, x, y, rollDice(std::max(1, s.dmgN), s.dmgS), s.dmgN > 0 ? s.dtype : (s.more.empty() ? DT_FORCE : s.more[0].type));
            if (!isObject(w, x, y) || w.ohp[y][x] <= 0) continue;
            if (s.dmgN > 0 && hitObject(w, x, y, rollDice(s.dmgN, s.dmgS), s.dtype)) continue;
            for (auto& m : s.more)
                if (hitObject(w, x, y, rollDice(m.n, m.s), m.type)) break;
        }
}
void summonFrom(World& w, int idx, int si);
// Превращение (PHB, Дикий облик): тело — шаблон облика (размер, СИЛ/ЛОВ/ТЕЛ, КД, оружие, скорость, передвижение, защиты,
// хиты — свой запас); ИНТ, МДР, ХАР, мастерство, способности (в облике недоступны), правила, легендарное, логово — свои.
// Хиты облика кончились — возврат в свой облик, лишний урон переходит на свои хиты
void shapeInto(World& w, Fighter& f, int t) {
    if (f.inForm || t < 0 || t >= (int)f.b.tmpl.size()) return;
    auto orig = std::make_shared<Boss>(f.b);
    Boss nb = f.b.tmpl[t];
    for (int st : {INT, WIS, CHA}) nb.stats[st] = orig->stats[st];
    nb.abil = orig->abil;
    nb.tmpl = orig->tmpl;
    nb.rules = orig->rules;
    nb.trigs = orig->trigs;
    nb.legAct = orig->legAct;
    nb.legRes = orig->legRes;
    nb.lair = orig->lair;
    nb.prof = std::max(nb.prof, orig->prof);
    for (int L = 0; L < 10; L++) nb.slots[L] = orig->slots[L];
    nb.mainStat = orig->mainStat;
    nb.cost = orig->cost;
    nb.alt.clear();
    f.formOrig = orig;
    f.b = nb;
    f.inForm = true;
    f.formHpSave = f.hp;
    f.formMaxSave = f.maxHp;
    f.hp = f.maxHp = std::max(1, nb.hp);
    f.alt = std::min(f.alt, f.b.fly ? ALT_MAX : 0);
    evPush("{\"k\":\"form\",\"who\":" + std::to_string((int)(&f - &w.f[0])) + ",\"on\":1}");
    nudge(w, f);   // облик крупнее — раздвинуться
    fallCheck(f);  // облик не летает — падает
}
// хиты облика кончились (или конец облика): свой облик, лишний урон — на свои хиты
void shapeBack(Fighter& f) {
    if (!f.inForm || !f.formOrig) return;
    const int excess = std::max(0, -f.hp);
    f.b = *f.formOrig;
    f.formOrig.reset();
    f.inForm = false;
    f.maxHp = f.formMaxSave;
    f.hp = f.formHpSave - excess;
    if (g_curW) evPush("{\"k\":\"form\",\"who\":" + std::to_string((int)(&f - &g_curW->f[0])) + ",\"on\":0}");
    fallCheck(f);
}
// союзники (v21): цель способности «на союзника» — я или свой в пределах дальности и видимости. pref — выбранный (игроком,
// ботом), если подходит; иначе: лечение — тому, кому больше не хватает хитов (по доле), временные хиты — у кого их нет и
// хитов меньше, баффы — тому, у кого этого баффа нет (себе — в первую очередь); приказ атаковать — союзнику, который
// достаёт врага оружием и может ответить реакцией. −1 — некому
int pickAlly(const World& w, const Fighter& me, const Spec& s, int pref = -1) {
    const int myIdx = (int)(&me - &w.f[0]);
    auto ok = [&](int i) {
        if (i < 0 || i >= (int)w.f.size()) return false;
        const Fighter& g = w.f[i];
        if (g.hp <= 0 || g.team != me.team || g.fled) return false;
        if (i != myIdx && (distFt(me, g) > s.range || !losF(w, me, g))) return false;
        if (s.cmdAtk) {
            if (i == myIdx || g.b.wN <= 0 || g.disarmed || !canReact(g)) return false;
            return nearestEnemyInRange(w, g, atkDist(g.b)) >= 0;
        }
        return true;
    };
    if (ok(pref)) return pref;
    int best = -1;
    double bv = -1e18;
    for (int i = 0; i < (int)w.f.size(); i++) {
        if (!ok(i)) continue;
        const Fighter& g = w.f[i];
        double v;
        if (s.cmdAtk)
            v = g.b.wN * (g.b.wS + 1) / 2.0 * g.b.wAtt;
        else if (s.healN || s.healB)
            v = 1.0 - (double)g.hp / std::max(1, g.maxHp);
        else if (s.tempN)
            v = (g.temp > 0 ? -1.0 : 0.0) + 1.0 - (double)g.hp / std::max(1, g.maxHp);
        else {
            const bool has = (s.buffN && g.buffRounds > 0) || (s.acB && g.acBuffRounds > 0) || (s.sbAmt && g.sbRounds > 0) || (s.invisN && g.invisRounds > 0);
            v = (has ? -10.0 : 0.0) + (i == myIdx ? 1.0 : 0.0) + g.maxHp / 1e6;
        }
        if (v > bv) {
            bv = v;
            best = i;
        }
    }
    return best;
}
void doSpec(World& w, Fighter& me, int si, int tIdx, int gx = -1, int gy = -1) {
    const Spec& s = me.b.abil[si];
    g_act.abil = si;
    g_curAbil = si;
    // приём «при попадании» — действие Атака оружием с приёмом (плата — при попадании); вторая рука — одна атака оружием
    if (s.onHit) {
        doWeapon(w, me, tIdx, -1, si);
        return;
    }
    if (s.offhand) {
        paySpec(w, me, si, false);
        doWeapon(w, me, tIdx, 1, -1, true, s.twfMod);
        return;
    }
    if (s.recharge) g_rechUsed++;
    paySpec(w, me, si, true);
    if (w.f.size() >= 2) revealTo(w, 1 - me.team, (int)(&me - &w.f[0]));   // способность выдаёт применившего (туман войны)
    {   // метрики использования (№6)
        const int i = (int)(&me - &w.f[0]);
        if (i >= 0 && i < 2) {
            if (s.hide) g_use[i][U_HIDE]++;
            if (s.invisN > 0) g_use[i][U_INVIS]++;
            if (s.darkR > 0) g_use[i][U_DARK]++;
        }
        if (!s.self && tIdx >= 0 && tIdx < (int)w.f.size() && w.f[tIdx].team != me.team) useAttack(w, me, tIdx, false);
    }
    if (s.formTmpl >= 0) {   // превращение
        shapeInto(w, me, s.formTmpl);
        g_act.type = "form";
        return;
    }
    if (s.sumN > 0) {   // призыв — эффект способности
        summonFrom(w, (int)(&me - &w.f[0]), si);
        g_act.type = "summon";
        return;
    }
    // реакция врагов «применил способность в зоне» (№23): до того, как способность сработает; павший не довёл её
    for (size_t i = 0; i < w.f.size(); i++)
        if (w.f[i].hp > 0 && w.f[i].team != me.team && hasReact(w.f[i].b)) tryReact(w, (int)i, 4, (int)(&me - &w.f[0]));
    // подготовка «враг применил способность» (8 ноября): подготовленное оружие или способность — по нему
    for (size_t i = 0; i < w.f.size() && me.hp > 0; i++) {
        Fighter& g = w.f[i];
        if (!g.readied || g.readyTrig != 2 || g.hp <= 0 || g.team == me.team || !canReact(g)) continue;
        const bool ab = g.readyAbil >= 0 && g.readyAbil < (int)g.b.abil.size();
        const int reach = ab ? std::max(5, specReach(g.b, g.b.abil[g.readyAbil])) : atkDist(g.b);
        if (distFt(g, me) > reach || !losF(w, g, me) || (!ab && (g.b.wN <= 0 || g.disarmed))) continue;
        spendReaction(g);
        g.readied = false;
        readyFire(w, (int)i, (int)(&me - &w.f[0]));
    }
    if (me.hp <= 0) return;
    if (g_countered) {   // контрзаклинание (v21): способность погашена, плата уже списана
        g_countered = false;
        g_act.type = "countered";
        return;
    }
    if (s.self && s.cmdAtk) {   // приказ: союзник бьёт оружием своей реакцией по ближайшему врагу в досягаемости
        const int gi = pickAlly(w, me, s, tIdx);
        g_act.type = "command";
        g_act.target = gi;
        if (gi >= 0) {
            Fighter& g = w.f[gi];
            const int e = nearestEnemyInRange(w, g, atkDist(g.b));
            if (e >= 0) {
                spendReaction(g);
                const ActInfo saved = g_act;
                doWeapon(w, g, e, 1);
                g_act = saved;
            }
        }
        return;
    }
    if (s.self) {
        // союзники (v21): эффекты «на себя» у способности «на союзника» — тому, кого выбрали (или себе)
        const int ti = s.ally ? pickAlly(w, me, s, tIdx) : -1;
        Fighter& tg = ti >= 0 ? w.f[ti] : me;
        if (s.healN || s.healB) {
            tg.hp = std::min(tg.maxHp, tg.hp + rollDice(s.healN, s.healS) + s.healB);
            g_act.type = "heal";
        }
        if (s.hide) {
            me.hidden = true;
            g_act.type = "hide";
        }
        if (s.buffN) {
            tg.buffN = s.buffN;
            tg.buffS = s.buffS;
            tg.buffRounds = s.buffRounds;
            g_act.type = "buff";
        }
        if (s.sbAmt) {
            endStatBuff(tg);
            tg.sbStat = s.sbStat;
            tg.sbAmt = s.sbAmt;
            tg.sbRounds = s.sbRounds;
            tg.b.stats[s.sbStat] += s.sbAmt;
            g_act.type = "statbuff";
        }
        // не лечат и не складываются
        if (s.tempN) {
            tg.temp = std::max(tg.temp, rollDice(s.tempN, 6));
            g_act.type = "temp";
        }
        if (s.acB) {
            tg.acBuff = s.acB;
            tg.acBuffRounds = s.acRounds;
            g_act.type = "acbuff";
        }
        if (s.darkR) {
            int rr = s.darkR / 5;
            for (int y = std::max(0, me.y - rr); y <= std::min(W - 1, me.y + rr); y++)
                for (int x = std::max(0, me.x - rr); x <= std::min(W - 1, me.x + rr); x++) {
                if (!w.dark[y][x]) dynAdd(w, x, y, 3, -1);
                w.dark[y][x] = true;
            }
            g_act.type = "darkness";
        }
        if (s.invisN) {
            tg.invisRounds = s.invisN;
            g_act.type = "invisible";
        }
        // пакет атомов 2: отражения, сфера неуязвимости, полёт на время, ходы подряд, увеличение, свет
        if (s.images > 0) tg.images = std::max(tg.images, s.images);
        if (s.globeLvl > 0) {
            tg.globeLvl = s.globeLvl;
            tg.globeR = std::max(10, s.radius);
            tg.globeRounds = std::max(1, s.globeRounds);
        }
        if (s.flyRounds > 0 && (!tg.b.fly || tg.flyBuff > 0)) {
            tg.b.fly = true;
            tg.flyBuff = std::max(tg.flyBuff, s.flyRounds);
        }
        if (s.extraTurns > 0) me.extraTurns += s.extraTurns;
        if (s.growRounds > 0 && tg.growRounds <= 0 && tg.b.size < 5) {
            tg.b.size++;
            if (g_curW && blockedAt(w, tg, tg.x, tg.y)) tg.b.size--;   // не помещается — только урон
            else tg.growRounds = -s.growRounds;   // минус: размер вырос (вернуть по окончании)
            if (tg.growRounds == 0) tg.growRounds = s.growRounds;
        } else if (s.growRounds > 0 && tg.growRounds == 0) tg.growRounds = s.growRounds;
        if (s.lightR > 0) {
            tg.lightR = s.lightR;
            tg.lightRounds = std::max(1, s.buffRounds > 0 ? s.buffRounds : 10);
        }
        g_act.target = ti >= 0 && ti != (int)(&me - &w.f[0]) ? ti : -1;
        return;
    }
    if (s.ground) {   // способность по клетке: область вокруг неё, труднопроходимая местность, барьер
        g_act.type = "ability-ground";
        g_act.target = -1;
        g_act.gx = gx;
        g_act.gy = gy;
        if (s.dmgN || !s.more.empty() || s.cond || s.pushFt || s.dotN)
            for (auto& e : w.f)
                if (e.hp > 0 && (e.team != me.team || !s.selective) && inShapeF(s.shape, s.radius, me.x, me.y, gx, gy, e)) hitOne(w, s, me, e);
        if (s.radius > 0) areaHitsObjects(w, s, me, gx, gy);
        if (s.terr) {
            const int rr = s.radius / 5 + 1;
            const bool fromMe = s.shape == SH_CONE || s.shape == SH_LINE;
            const int bx = fromMe ? me.x : gx, by = fromMe ? me.y : gy;
            for (int y = std::max(0, by - rr); y <= std::min(w.ah - 1, by + rr); y++)
                for (int x = std::max(0, bx - rr); x <= std::min(w.aw - 1, bx + rr); x++)
                    if (inShape(s.shape, s.radius, me.x, me.y, gx, gy, x, y) && !w.wall[y][x] && !w.diff[y][x]) { w.diff[y][x] = true, w.mapVer = ++g_mapSerial; dynAdd(w, x, y, 2, -1); }
        }
        if (s.wallLen > 0) placeWall(w, me, gx, gy, s.wallLen, s.wallRounds);
        me.hidden = false;
        return;
    }
    g_act.type = s.radius > 0 ? "ability-area" : (s.range > 5 ? "ability-ranged" : "ability-melee");
    g_act.target = tIdx;
    Fighter& c = w.f[tIdx];
    if (s.radius == 0) {
        hitOne(w, s, me, c);
        if (s.targets > 1) {   // ещё цели на выбор: лучшие враги в пределах дальности (бот и сеть выбирают главную)
            std::vector<std::pair<double, int>> more;
            for (size_t i = 0; i < w.f.size(); i++) {
                const Fighter& e = w.f[i];
                if ((int)i == tIdx || e.hp <= 0 || e.team == me.team || distFt(me, e) > s.range || !losF(w, me, e) || !isKnown(w, me.team, (int)i)) continue;
                more.push_back({-evSpecOne(w, s, me, e), (int)i});
            }
            std::sort(more.begin(), more.end());
            for (int k = 0; k < s.targets - 1 && k < (int)more.size() && me.hp > 0; k++) hitOne(w, s, me, w.f[more[k].second]);
        }
    } else {
        int cx = c.x, cy = c.y;
        for (auto& e : w.f)
            if (e.hp > 0 && (e.team != me.team || !s.selective) && inShapeF(s.shape, s.radius, me.x, me.y, cx, cy, e))
                hitOne(w, s, me, e);
        areaHitsObjects(w, s, me, cx, cy);
        if (s.terr) {
            const int rr = s.radius / 5 + 1;
            const bool fromMe = s.shape == SH_CONE || s.shape == SH_LINE;
            const int bx = fromMe ? me.x : cx, by = fromMe ? me.y : cy;
            for (int y = std::max(0, by - rr); y <= std::min(W - 1, by + rr); y++)
                for (int x = std::max(0, bx - rr); x <= std::min(W - 1, bx + rr); x++) {
                    if (!inShape(s.shape, s.radius, me.x, me.y, cx, cy, x, y)) continue;
                    if (!w.diff[y][x] && !w.wall[y][x]) dynAdd(w, x, y, 2, -1);
                    w.diff[y][x] = true, w.mapVer = ++g_mapSerial;
                }
        }
    }
    me.hidden = false;
}
// Способность-реакция (№23). Срабатывает сама (у бота, сети и игрока одинаково), если есть реакция, способность доступна
// и полезна: враждебная — по виновнику события в пределах дальности (по клетке — с центром на нём), на себя — на себя
// (лечение — если ХП ниже половины, телепорт — прочь от виновника). Одна реакция за раунд, общий лимит с остальными.
bool tryReact(World& w, int meIdx, int trig, int srcIdx, int prevDist) {
    if (meIdx < 0 || srcIdx < 0 || meIdx >= (int)w.f.size() || srcIdx >= (int)w.f.size() || (w.f.size() >= 2 && over(w))) return false;
    Fighter& me = w.f[meIdx];
    Fighter& src = w.f[srcIdx];
    if (!canReact(me) || src.hp <= 0 || me.team == src.team) return false;
    const int d = distFt(me, src);
    for (size_t k = 0; k < me.b.abil.size(); k++) {
        const Spec& s = me.b.abil[k];
        if (s.react != trig || !specResReady(me, (int)k)) continue;
        const int zone = s.self ? std::max(s.range, 5) : s.range;   // зона реакции — дальность способности
        if (s.counter) {   // контрзаклинание (v21): гасит способность врага в зоне
            if (trig != 4 || d > zone || !losF(w, me, src)) continue;
            spendReaction(me);
            paySpec(w, me, (int)k, false);
            evPush("{\"k\":\"react\",\"who\":" + std::to_string(meIdx) + ",\"abil\":" + std::to_string(k) + ",\"trig\":4,\"counter\":1}");
            g_countered = true;
            g_reactUsed++;
            return true;
        }
        if (trig == 3 && !(prevDist > zone && d <= zone)) continue;   // вошёл в зону только что
        if ((trig == 3 || trig == 4) && d > zone) continue;
        int gx = -1, gy = -1, tx = -1, ty = -1;
        if (s.self) {
            if (s.healN && me.hp * 2 >= me.maxHp) continue;
            if (s.teleFt > 0) {   // прыжок прочь от виновника
                int dx = (me.x > src.x) - (me.x < src.x), dy = (me.y > src.y) - (me.y < src.y);
                if (!dx && !dy) dx = 1;
                for (int st = s.teleFt / 5; st >= 1 && tx < 0; st--) {
                    const int nx = me.x + dx * st, ny = me.y + dy * st;
                    if (!fpAll(w, me, nx, ny, [&](int cx, int cy) { return !w.wall[cy][cx] && !w.pit[cy][cx]; }) || blockedAt(w, me, nx, ny)) continue;
                    tx = nx;
                    ty = ny;
                }
                if (tx < 0) continue;
            }
        } else {
            if (me.cond[C_CHARM] > 0 && me.charmSrc == srcIdx) continue;
            if (d > s.range || !losF(w, me, src)) continue;
            double ev;
            if (s.ground) {
                gx = src.x;
                gy = src.y;
                ev = evSpecAt(w, s, me, gx, gy, &src);
            } else
                ev = evSpec(w, s, me, src);
            if (ev <= 0) continue;
        }
        spendReaction(me);
        const ActInfo saved = g_act;
        const int src0 = g_srcIdx;
        g_srcIdx = meIdx;
        evPush("{\"k\":\"react\",\"who\":" + std::to_string(meIdx) + ",\"abil\":" + std::to_string(k) + ",\"trig\":" + std::to_string(trig) + "}");
        if (tx >= 0) {
            me.x = tx;
            me.y = ty;
            me.up = !nodeOK(w, me, me.x, me.y, 0) && w.deck[me.y][me.x] > 0;
            hazardHit(w, me);
            paySpec(w, me, (int)k, false);
        } else
            doSpec(w, me, (int)k, srcIdx, gx, gy);
        g_srcIdx = src0;
        g_act = saved;
        g_reactUsed++;
        return true;
    }
    return false;
}
// Реакции «мне нанесли урон» (№23): после действия или хода — по тому, кто нанёс урон последним
void resolveReactions(World& w) {
    for (int pass = 0; pass < 4; pass++) {
        std::vector<std::pair<int, int>> pend;
        for (size_t i = 0; i < w.f.size(); i++)
            if (w.f[i].hurtBy >= 0) {
                if (w.f[i].hp > 0 && hasReact(w.f[i].b)) pend.push_back({(int)i, w.f[i].hurtBy});
                w.f[i].hurtBy = -1;
            }
        if (pend.empty()) return;
        for (auto& p : pend) tryReact(w, p.first, 2, p.second);
    }
}
// жёсткий контроль: теряется ход или управление
inline bool hardCtl(int k) { return k == C_STUN || k == C_DISTR || k == C_PARAL || k == C_INCAP || k == C_CHARM || k == C_FLEE; }
void endOfTurn(Fighter& me) {
    me.turnX0 = me.turnY0 = -1;   // вне своего хода разбега нет (атаки реакцией — без наскока)
    // пакет атомов 2: сфера, полёт на время, увеличение, свет — по своим раундам
    if (me.globeRounds > 0) me.globeRounds--;
    if (me.flyBuff > 0 && --me.flyBuff == 0) {
        me.b.fly = false;
        fallCheck(me);
    }
    if (me.growRounds > 0) me.growRounds--;
    else if (me.growRounds < 0 && ++me.growRounds == 0) me.b.size = std::max(0, me.b.size - 1);   // размер вырастал — вернуть
    if (me.lightRounds > 0) me.lightRounds--;
    for (int k = 1; k < C_N; k++) {
        if (me.cond[k] > 0) {
            // нарастающая стойкость (v21, этап 7): каждый проваленный повторный спасбросок от жёсткого контроля — +2 к следующим
            const int dc = me.cdc[k] - (hardCtl(k) ? 2 * me.cgrit[k] : 0);
            if (k != C_PRONE && me.cstat[k] >= 0 && saveLR(me, me.cstat[k], dc, hardCtl(k)))
                me.cond[k] = 0;
            else {
                me.cond[k]--;
                if (k != C_PRONE && me.cstat[k] >= 0 && hardCtl(k)) me.cgrit[k]++;
            }
            if (me.cond[k] == 0) me.cgrit[k] = 0;
            // защита от вечного контроля: до конца СЛЕДУЮЩЕГО своего хода
            if (me.cond[k] == 0 && k != C_PRONE) me.cimm[k] = 1;
        } else if (me.cimm[k] > 0)
            me.cimm[k]--;
    }
    if (me.buffRounds > 0) me.buffRounds--;
    if (me.sbRounds > 0 && --me.sbRounds == 0) endStatBuff(me);
    if (me.acBuffRounds > 0) me.acBuffRounds--;
    if (me.invisRounds > 0) me.invisRounds--;
    if (me.supp > 0) me.supp--;
}
int speedOf(const Fighter& f);
// летун держится в воздухе, пока может двигаться (PHB): не сбит с ног, не опутан и не схвачен (скорость 0), не оглушён и не
// парализован. Иначе падает: 1к6 дробящего за каждые 10 фт высоты, сбит с ног
inline bool canStayAloft(const Fighter& f) {
    return f.b.fly && !f.cond[C_PRONE] && !f.cond[C_RESTR] && !f.cond[C_GRAPPLE] && !f.cond[C_STUN] && !f.cond[C_PARAL] && f.hp > 0;
}
void fallCheck(Fighter& f) {
    if (f.alt <= 0 || canStayAloft(f)) return;
    const int h = f.alt;
    f.alt = 0;
    if (f.hp <= 0) return;
    const int hp0 = f.hp;
    hurt(f, rollDice(h, 6), DT_BLUDGEONING, false);
    f.cond[C_PRONE] = std::max(f.cond[C_PRONE], 1);
    if (g_curW) evPush("{\"k\":\"fall\",\"who\":" + std::to_string((int)(&f - &g_curW->f[0])) + ",\"ft\":" + std::to_string(10 * h) + ",\"dmg\":" + std::to_string(hp0 - f.hp) + "}");
}
int speedOf(const Fighter& f) {
    int sp = f.b.speed;
    if (f.cond[C_RESTR] || f.cond[C_GRAPPLE] || f.cond[C_PARAL] || f.exh >= 5) return 0;
    if (f.cond[C_SLOW]) sp /= 2;
    if (f.exh >= 2) sp /= 2;   // истощение 2: скорость вдвое
    return std::max(0, sp - f.speedPen);   // осложнение погони этого хода
}
// Сколько приспешников призовёт способность si бойца idx сейчас: sumN копий, но не выше технических потолков (живых от
// способности и у босса, призвано за бой способностью и у босса — limity.json)
int summonRoom(const World& w, int idx, int si) {
    const Fighter& me = w.f[idx];
    const Spec& s = me.b.abil[si];
    const Limits& L = limits();
    int aliveAbil = 0, aliveBoss = 0, fightBoss = 0;
    for (auto& g : w.f)
        if (g.summoner == idx) {
            fightBoss++;
            if (g.hp > 0) {
                aliveBoss++;
                aliveAbil += g.sumSpec == si;
            }
        }
    const int made = si < (int)me.sumMade.size() ? me.sumMade[si] : 0;
    return std::max(0, std::min({s.sumTotal(), L.sumAliveAbil - aliveAbil, L.sumFightAbil - made, L.sumAliveBoss - aliveBoss, L.sumFightBoss - fightBoss}));
}
// Призыв способностью si: копии шаблона появляются рядом с призывателем и ходят сразу после него; живут до гибели, а
// призванные способностью с концентрацией исчезают, когда концентрация снята (breakConc)
void summonFrom(World& w, int idx, int si) {
    int m = summonRoom(w, idx, si);
    // бойцы лежат в w.f, и на них держат ссылки: перекладывать вектор нельзя. Бой отводит место под все потолки;
    // нет места (мир собран вручную) — призывается сколько влезает, и это растяжка
    if (w.f.size() + m > w.f.capacity()) {
        tripwire("призыв: нет места в мире", (int)w.f.capacity(), (int)(w.f.size() + m));
        m = (int)(w.f.capacity() - w.f.size());
    }
    const Limits& L = limits();
    for (int i = 0; i < m; i++) {
        const Fighter& me = w.f[idx];   // ссылка заново: push_back ниже может переложить бойцов
        Fighter g;
        const Spec& ss = me.b.abil[si];
        int ti = ss.sumTmpl, k = i - ss.sumN;   // i-я копия: сначала основная группа, потом остальные
        for (size_t q = 0; k >= 0 && q < ss.sumMore.size(); q++) {
            ti = (int)ss.sumMore[q][0];
            k -= (int)ss.sumMore[q][1];
        }
        g.b = me.b.tmpl[ti];
        g.b.tmpl.clear();
        // приспешниками управляет эвристика
        g.team = me.team;
        g.pol = me.pol;
        g.rl = false;
        g.summoner = idx;
        g.sumSpec = si;
        // (в v11–v16 эти присваивания случайно попали в комментарий: миньоны появлялись с 1 ХП)
        g.hp = g.maxHp = g.b.hp;
        g.x = me.x;
        g.y = me.y;
        g.up = me.up;
        g.fresh = true;
        g.ai.seed(rng.next());
        // миньон действует сразу после своего босса
        g.init = me.init - 1;
        g.uses.assign(g.b.abil.size(), 0);
        g.usedRound.assign(g.b.abil.size(), -10);
        g.poolLeft = g.b.poolN;
        g.trigLeft.clear();
        for (auto& t : g.b.trigs) g.trigLeft.push_back(t.uses);
        g.lrLeft = g.b.legRes;
        g.legLeft = g.b.legAct;
        g.surgeLeft = g.b.surge;
        for (int L2 = 1; L2 < 10; L2++) g.slotLeft[L2] = g.b.slots[L2];
        for (size_t k = 0; k < g.b.abil.size(); k++) g.uses[k] = g.b.abil[k].recharge && !(g.b.abil[k].rechAfter && g.b.abil[k].uses < UNL) ? 1 : g.b.abil[k].uses;
        nudge(w, g);
        w.f.push_back(g);
    }
    Fighter& me = w.f[idx];
    if ((int)me.sumMade.size() <= si) me.sumMade.resize(me.b.abil.size(), 0);
    me.sumMade[si] += m;
    // растяжки: живых от способности и у босса, призвано за бой, призывов за ход
    int aliveAbil = 0, aliveBoss = 0, fightBoss = 0;
    for (auto& g : w.f)
        if (g.summoner == idx) {
            fightBoss++;
            if (g.hp > 0) aliveBoss++, aliveAbil += g.sumSpec == si;
        }
    if (aliveAbil > L.warnAliveAbil) tripwire("призыв: живых от способности", L.warnAliveAbil, aliveAbil);
    if (aliveBoss > L.warnAliveBoss) tripwire("призыв: живых у босса", L.warnAliveBoss, aliveBoss);
    if (me.sumMade[si] > L.warnFightAbil) tripwire("призыв: за бой способностью", L.warnFightAbil, me.sumMade[si]);
    if (fightBoss > L.warnFightBoss) tripwire("призыв: за бой у босса", L.warnFightBoss, fightBoss);
    if (me.sumTurn != g_curRound) me.sumTurn = g_curRound, me.sumTurnN = 0;
    if (++me.sumTurnN > L.warnTurnSummons) tripwire("призыв: призывов за ход", L.warnTurnSummons, me.sumTurnN);
}

// Перезарядка: в начале СВОЕГО хода бросок d6 по каждой потраченной способности; возврат при результате >= порога
void rechargeStart(Fighter& me) {
    for (size_t i = 0; i < me.b.abil.size(); i++) {
        const Spec& s = me.b.abil[i];
        if (s.recharge > 0 && me.uses[i] <= 0) {
            g_rechRolls++;
            if (rollDie(6) >= s.recharge) {
                me.uses[i] = s.rechAfter && s.uses < UNL ? s.uses : 1;   // пакет атомов 3: вернулись все применения
                g_rechOk++;
            }
        }
    }
}
// Ауры врагов: в начале хода бойца урон и/или состояние от каждой ауры, в радиусе которой он стоит. true — боец погиб.
bool applyAuras(World& w, int idx) {
    Fighter& me = w.f[idx];
    for (size_t j = 0; j < w.f.size(); j++) {
        const Fighter& o = w.f[j];
        if (o.hp <= 0 || o.team == me.team || o.b.auraRad <= 0 || distFt(o, me) > o.b.auraRad ||
            (o.supp > 0 && (o.b.suppTgt & 2)))
            continue;
        if (o.b.auraN > 0) {
            const int src0 = g_srcIdx;
            g_srcIdx = (int)j;   // урон ауры наносит её владелец
            hurt(me, rollDice(o.b.auraN, o.b.auraS), o.b.auraType, true);
            g_srcIdx = src0;
            if (me.hp <= 0) return true;
        }
        if (o.b.auraCond > 0) {
            int st = condSaveStat(o.b.auraCond), dc = o.dc();
            Spec sp;
            sp.cond = o.b.auraCond;
            sp.condRounds = o.b.auraRounds;
            bool ok = o.b.auraCond == C_GRAPPLE ? false : saveLR(me, st, dc, lrWorth(me, sp));
            if (!ok) applyCond(me, o.b.auraCond, o.b.auraRounds, st, dc, true, (int)j);
        }
    }
    return false;
}
// ---------------------------------------------------------------------------
// Ум бойца. Решения бота спрашивают у Brain, что бойцу доступно; Pol задаёт, как он взвешивает варианты; Ovr/g_rlTurn —
// вход для обучаемого бота. ИНТ: <=3 инстинкт (бьёт ближайшего, без тактик, часто ошибается), 4-7 простая тактика
// (лечится, но без кайтинга, отхода, баффов и фокуса), 8-11 средний (вся прежняя тактика, без случайных чисел), 12-15
// хорошая и 16+ полная (сейчас играют как средний: ступени заняты под обучаемого бота). МДР: дальность, на которой боец
// замечает врагов (МДР>=10 — всю карту; дальше добавляется 60 фт за раунд боя). ХАР главного босса: послушание
// миньонов.
// ---------------------------------------------------------------------------
const int SENSE_INF = 1 << 28;
struct Brain {
    int lvl = 2;
    double noise = 0;
    bool focus = true, selfSimple = true, selfTactics = true, kite = true, disengage = true, dodge = true,
         evalSummon = true;
    int sense = SENSE_INF;
    double obey = 1.0;
};
Brain brainOf(const World& w, const Fighter& me) {
    Brain b;
    int in = me.b.stats[INT];
    b.lvl = in <= 3 ? 0 : (in <= 7 ? 1 : (in <= 11 ? 2 : (in <= 15 ? 3 : 4)));
    if (b.lvl <= 1) {
        b.focus = b.selfTactics = b.kite = b.disengage = b.dodge = b.evalSummon = false;
        b.noise = b.lvl == 0 ? 0.35 : 0.15;
        if (b.lvl == 0) b.selfSimple = false;
    }
    int wis = me.b.stats[WIS];
    if (wis < 10) b.sense = 60 * std::max(1, wis - 3);
    if (me.team >= 0 && me.team < (int)w.f.size()) {
        int cha = w.f[me.team].b.stats[CHA];
        if (cha < 10) b.obey = std::max(0.2, 1.0 - 0.1 * (10 - cha));
    }
    return b;
}
// Состояние хода: оставшееся движение и потраченные действие/бонусное действие
struct TurnState {
    int speed = 0, speed0 = 0;
    bool actionUsed = false, bonusUsed = false;
    bool lastWasAttack = false;   // последнее действие — Атака или способность (для всплеска действий)
    int swaps = 0, orders = 0;    // смен оружия и приказов за ход (их цена растёт со счётчиком)
    bool spent = false;           // за ход применены атака, заклинание или призыв (пустой ход сети запрещён; манёвры — Рывок,
                                  // Уклонение, Отход — и взаимодействия ход непустым не делают, решение владельца)
    int x0 = -1, y0 = -1;         // клетка в начале хода: шаг, после которого боец вернулся туда же, тратой не считается
    int steps = 0;                // выполнено решений за ход
    int atkLeft = 0;              // игрок бьёт атаки действия Атака по одной (между ними можно идти и менять цель): сколько ещё осталось
    int altLeft[8] = {};          // мультиатака из разных оружий: сколько ударов ещё у запасного оружия k в этом действии «Атака»
};
// начало действия «Атака»: у оружия мультиатаки (запасное с флагом multi) — свои удары
inline void initAltLeft(TurnState& ts, const Fighter& me) {
    for (int k = 0; k < 8; k++) ts.altLeft[k] = k < (int)me.b.alt.size() && me.b.alt[k].multi ? me.b.alt[k].att : 0;
}
inline bool attackStarted(const TurnState& ts) {
    if (ts.atkLeft > 0) return true;
    for (int k = 0; k < 8; k++) if (ts.altLeft[k] > 0) return true;
    return false;
}
// отложенное от событий: атака оружием бонусным действием (если оно свободно в этот ход) и добавка скорости
void resolvePending(World& w, int idx, TurnState& ts) {
    Fighter& me = w.f[idx];
    if (me.pendSpeed > 0) {
        ts.speed += me.pendSpeed;
        me.pendSpeed = 0;
    }
    if (!me.pendBonus) return;
    me.pendBonus = false;
    if (ts.bonusUsed || me.b.wN <= 0 || me.disarmed || me.hp <= 0 || over(w)) return;
    int t = me.pendTgt;
    if (t < 0 || t >= (int)w.f.size() || w.f[t].hp <= 0 || distFt(me, w.f[t]) > atkDist(me.b)) t = nearestEnemyInRange(w, me, atkDist(me.b));
    if (t < 0) return;
    ts.bonusUsed = true;
    const ActInfo saved = g_act;
    doWeapon(w, me, t, 1);
    g_act = saved;
}
// Можно ли заплатить цену: ресурсы способности (применения, концентрация, ячейка), затем экономика действия. why —
// причина отказа для игрока и журнала
bool canPay(const Fighter& me, const TurnState& ts, const AbCost& c, const char** why = nullptr) {
    auto no = [&](const char* m) {
        if (why) *why = m;
        return false;
    };
    if (!resReady(me, c, why)) return false;
    if (c.econ == EC_ACTION && ts.actionUsed) return no("Действие уже потрачено.");
    if (c.econ == EC_BONUS && ts.bonusUsed) return no("Бонусное действие уже потрачено.");
    if (c.econ == EC_REACTION && me.reactionUsed) return no("Реакция уже потрачена.");
    if (c.econ == EC_ATTACK && ts.actionUsed && ts.atkLeft <= 0) return no("Атаки действия «Атака» уже потрачены.");
    return true;
}
// Непустой ли ход (запрет пустого хода сети): применены атака, заклинание или призыв, или боец стоит не там, где начал
// ход (шаг туда и обратно не в счёт); Рывок, Уклонение, Отход и взаимодействия сами по себе ход непустым не делают
inline bool turnSpent(const TurnState& ts, const Fighter& me) {
    return ts.spent || (ts.x0 >= 0 && (me.x != ts.x0 || me.y != ts.y0));
}
// Списать экономику действия (ресурсы самой способности списывает paySpec при её применении)
inline void payEcon(TurnState& ts, Fighter& me, int econ) {
    if (econ == EC_ATTACK) {   // вместо одной атаки: начинает действие «Атака» (остальные атаки — оружием) или тратит одну из оставшихся
        if (ts.atkLeft > 0) ts.atkLeft--;
        else {
            ts.actionUsed = true;
            ts.atkLeft = std::max(0, me.b.wAtt - 1);
            initAltLeft(ts, me);
        }
    } else if (econ == EC_ACTION) ts.actionUsed = true;
    else if (econ == EC_BONUS) ts.bonusUsed = true;
    else if (econ == EC_REACTION) spendReaction(me);
}
// ---- Примитивы хода (v21, №4): ход бота, игрока и сети — последовательность таких шагов. Движок следит за бюджетом:
// оставшаяся скорость, действие, бонусное действие, всплеск. Двигаться можно до и после действия.
enum PrimKind {
    PR_END,         // закончить ход
    PR_MOVE,        // идти в клетку (x, y); a — предел движения в фт (−1 — вся оставшаяся скорость)
    PR_ATTACK,      // атака оружием по a; b = 1 — безрассудно; x = 1 — одна атака (игрок, TurnState::atkLeft)
    PR_SPELL,       // способность a: по цели b или по клетке (x, y) (телепорт и «по клетке»)
    PR_DASH,        // Рывок (действие): движение +скорость
    PR_DODGE,       // Уклонение (действие)
    PR_DISENGAGE,   // Отход: a = 0 действием, 1 бонусным (если умеет)
    PR_SUMMON,      // призвать a приспешников (действие)
    PR_SWAP,        // сменить оружие на запасное a (бесплатно)
    PR_DROPCONC,    // прекратить концентрацию (бесплатно)
    PR_SURGE,       // всплеск действий: ещё одно действие после Атаки или способности
    PR_ORDER,       // приказ приспешникам: бить a (бесплатно, главный босс)
    PR_HELP,        // Помощь (действие, v21): враг a рядом со мной — первая атака союзника по нему с преимуществом
    PR_READY,       // Подготовка (действие, v21): враг войдёт в досягаемость — удар оружием реакцией
    PR_ALT,         // высота полёта a (уровни по 10 фт): 10 фт движения за уровень; уход из досягаемости ближника — провоцирует
    PR_N
};
const char* PRN[PR_N] = {"конец хода", "идти", "атака", "способность", "Рывок", "Уклонение", "Отход", "призыв", "смена оружия", "снять концентрацию", "всплеск", "приказ", "Помощь", "Подготовка", "высота"};
struct Prim {
    int kind = PR_END, a = -1, b = -1, x = -1, y = -1;
};
void recordMove(int idx, int x, int y, int budget) {
    if (g_rec && idx == g_recIdx) g_rec->push_back({PR_MOVE, budget, -1, x, y});
}
inline void recordPrim(int idx, Prim p) {
    if (g_rec && idx == g_recIdx) g_rec->push_back(p);
}
// Начало хода (общее для бота и игрока): сбросы, регенерация, яд, урон по времени, ауры, оглушение, захват, бюджет движения.
// false — ход уже закончился (боец пал, оглушён и т.п.)
bool beginTurn(World& w, int idx, TurnState& ts) {
    Fighter& me = w.f[idx];
    if (me.hp <= 0 || over(w)) return false;
    g_act = ActInfo{};
    me.turnX0 = me.x;   // наскок (пакет атомов 2): разбег считается от клетки начала хода
    me.turnY0 = me.y;
    if (me.banished > 0) {   // изгнан: ход пропускается; изгнавший пал — возвращается сразу
        const bool srcGone = me.banishSrc < 0 || me.banishSrc >= (int)w.f.size() || w.f[me.banishSrc].hp <= 0;
        me.banished = srcGone ? 0 : me.banished - 1;
        if (me.banished > 0) return false;
    }
    // сброс в начале своего хода (§10, §12: реакция восстанавливается)
    me.dodging = false;
    me.disengaged = false;
    me.struckFoe = false;
    me.riderUsed = false;
    me.onceUsed = 0;
    me.reactionUsed = false;
    me.wasReckless = false;
    me.wAtkTurn = false;
    me.readied = false;   // Подготовка — до начала моего следующего хода
    me.pendBonus = false;
    me.pendSpeed = 0;
    fallCheck(me);   // не может держаться в воздухе (скорость 0 и т. п.) — падает
    me.alt = std::min(me.alt, maxAltAt(w, me, me.x, me.y, me.up));
    for (auto& g : w.f) {
        if (g.helpBy == idx) g.helpBy = -1;   // и Помощь тоже
        if (g.noOAvs == idx) g.noOAvs = -1;   // и «не провоцирует» (Подвижный)
    }
    if (me.disarmed) {   // обезоружен: подбирает оружие — тратит взаимодействие хода
        me.disarmed = false;
        ts.swaps++;
    }
    // очки легендарных действий восстанавливаются в начале своего хода
    me.legLeft = me.b.legAct;
    // бросок перезарядки в начале своего хода
    rechargeStart(me);
    // концентрация закончилась сама, если эффект уже снят
    if (me.concSpec >= 0) {
        const Spec& cs = me.b.abil[me.concSpec];
        bool act = (cs.buffN && me.buffRounds > 0) || (cs.sbAmt && me.sbRounds > 0) ||
                   (cs.acB && me.acBuffRounds > 0) || (cs.invisN && me.invisRounds > 0);
        for (auto& f : w.f)
            if (cs.sumN > 0 && f.summoner == idx && f.sumSpec == me.concSpec && f.hp > 0) act = true;
        for (auto& f : w.f) {
            for (int k = 1; k < C_N; k++)
                if (f.cond[k] > 0 && f.condConc[k] == idx + 1) act = true;
            if (f.dotRounds > 0 && f.dotConc == idx + 1) act = true;
        }
        if (!act) me.concSpec = -1;
    }
    if (me.b.regenN && !(me.supp > 0 && (me.b.suppTgt & 1)))
        me.hp = std::min(me.maxHp, me.hp + rollDice(me.b.regenN, 6));
    g_turnSerial++;   // опасная зона: новый ход — может задеть снова; начал ход в зоне — урон
    hazardHit(w, me);
    if (me.hp <= 0) return false;
    // тик урона от яда, повторный спас по ТЕЛ уже обрабатывает endOfTurn
    if (me.cond[C_POISON] > 0 && me.hp > 0) {
        // яд: считается типом «яд» (иммунным и резистным он нипочём не наносится)
        hurt(me, rollDie(4), DT_POISON, true);
        if (me.hp <= 0) return false;
    }
    // урон по времени
    if (me.dotRounds > 0 && me.hp > 0) {
        hurt(me, rollDice(me.dotN, me.dotS), me.dotType, true);
        me.dotRounds--;
        if (me.hp <= 0) return false;
    }
    // ауры врагов
    if (applyAuras(w, idx)) return false;
    if (me.cond[C_STUN] || me.cond[C_PARAL]) {
        endOfTurn(me);
        g_act.type = "stunned";
        return false;
    }
    // захват кончается, если схвативший пал или недееспособен
    if (me.cond[C_GRAPPLE] > 0 && me.grapSrc >= 0) {
        const Fighter& gr = w.f[me.grapSrc];
        if (gr.hp <= 0 || gr.cond[C_STUN] || gr.cond[C_PARAL] || gr.cond[C_INCAP]) me.cond[C_GRAPPLE] = 0;
    }
    grabSync(me);
    if (me.cond[C_GRAPPLE] > 0 && me.grabDotN > 0) {   // захват с уроном (пакет атомов 2): каждый ход, пока держат
        const int s0 = g_srcIdx;
        g_srcIdx = me.grabDotSrc;
        hurt(me, rollDice(me.grabDotN, me.grabDotS), me.grabDotType, false);
        g_srcIdx = s0;
        if (me.hp <= 0) return false;
    }
    // схваченный, которому нечем атаковать (нет оружия или враг вне досягаемости), тратит действие на побег (СЛ из способности)
    bool escapeTried = false;
    if (me.cond[C_GRAPPLE] > 0 && !me.cond[C_DISTR] && !me.cond[C_INCAP] &&
        (me.b.wN <= 0 || nearestEnemyInRange(w, me, atkDist(me.b)) < 0)) {
        escapeTried = true;
        const bool sa = me.skill(SK_ATHL) >= me.skill(SK_ACRO);
        if (d20(skillAdv(me, sa ? SK_ATHL : SK_ACRO), false) + std::max(me.skill(SK_ATHL), me.skill(SK_ACRO)) >= me.cdc[C_GRAPPLE]) me.cond[C_GRAPPLE] = 0;   // Атлетика или Акробатика
        grabSync(me);
    }
    int speed = speedOf(me);
    if (me.cond[C_PRONE]) {
        me.cond[C_PRONE] = 0;
        speed /= 2;
    }
    // общий бюджет движения на ход (отход + сближение + бег)
    ts.speed = ts.speed0 = speed;
    ts.x0 = me.x;
    ts.y0 = me.y;
    // недееспособный не использует действия
    ts.actionUsed = me.cond[C_DISTR] > 0 || me.cond[C_INCAP] > 0 || escapeTried;
    ts.bonusUsed = me.cond[C_INCAP] > 0;
    fireTrig(w, me, T_TURN, nullptr);   // «событие → эффект» (v21): в начале моего хода
    resolvePending(w, idx, ts);
    return true;
}
// Страх с бегством (общее правило для бота, игрока и сети): действие — Рывок прочь от ближайшего известного врага
// (движение вдвое), провоцированные атаки действуют; дошёл до края арены — шагнул за него: побег и поражение.
// true — боец сбежал, ход окончен.
bool forcedFlee(World& w, int idx, TurnState& ts) {
    Fighter& me = w.f[idx];
    if (!(me.cond[C_FLEE] > 0 && !me.cond[C_INCAP] && !ts.actionUsed)) return false;
    int focus = -1, fd = 1 << 30;
    for (int pass = 0; pass < 2 && focus < 0; pass++)   // сначала известные, если таких нет — любые
        for (size_t e = 0; e < w.f.size(); e++)
            if (w.f[e].hp > 0 && w.f[e].team != me.team && (pass || isKnown(w, me.team, (int)e)) && distFt(me, w.f[e]) < fd) {
                fd = distFt(me, w.f[e]);
                focus = (int)e;
            }
    if (focus < 0) return false;
    auto* rec0 = g_rec;   // вынужденное бегство — правило, а не решение: в запись хода не идёт
    g_rec = nullptr;
    payEcon(ts, w.f[idx], EC_ACTION);
    g_act.type = "flee";
    const Fighter& F = w.f[focus];
    const int dx = me.x - F.x, dy = me.y - F.y, speed = ts.speed;
    const int sx = dx == 0 ? (irand(2) * 2 - 1) : (dx > 0 ? 1 : -1), sy = dy == 0 ? (irand(2) * 2 - 1) : (dy > 0 ? 1 : -1), steps = 2 * speed / 5 + 1;
    me.dashedNow = true;
    const int bx = sx > 0 ? w.aw - 1 - me.x : me.x, by = sy > 0 ? w.ah - 1 - me.y : me.y;
    if ((std::min(bx, by) + 1) * 5 <= 2 * speed) {
        me.fled = true;
        me.fledWhy = 1;
        evPush("{\"k\":\"fled\",\"who\":" + std::to_string(idx) + ",\"why\":1}");
        endOfTurn(me);
        g_rec = rec0;
        return true;
    }
    Fighter away;   // +1 клетка: moveToward не заходит в клетку самой «цели»
    away.x = std::clamp(me.x + sx * steps, 0, w.aw - 1);
    away.y = std::clamp(me.y + sy * steps, 0, w.ah - 1);
    moveToward(w, me, away, 0, 2 * speed, false);
    ts.speed = 0;
    g_rec = rec0;
    return false;
}
// Исполнитель примитива (v21, №4). check — проверить правила и вернуть причину отказа в msg (игрок, сеть); без проверки —
// повтор записанного хода бота. true — примитив выполнен.
bool applyPrim0(World& w, int idx, TurnState& ts, const Prim& p, bool check, std::string* msg);
// исполнитель с подсчётом шагов хода (ts.steps — признак сети «сколько уже решено за ход»)
bool applyPrim(World& w, int idx, TurnState& ts, const Prim& p, bool check, std::string* msg = nullptr) {
    const bool ok = applyPrim0(w, idx, ts, p, check, msg);
    if (ok) ts.steps++;
    if (ok) {   // «событие → эффект» (v21): после Рывка и Уклонения — события; отложенное (атака бонусом, скорость)
        if (p.kind == PR_DASH) fireTrig(w, w.f[idx], T_DASH, nullptr);
        if (p.kind == PR_DODGE) fireTrig(w, w.f[idx], T_DODGE, nullptr);
        resolvePending(w, idx, ts);
    }
    return ok;
}
bool applyPrim0(World& w, int idx, TurnState& ts, const Prim& p, bool check, std::string* msg) {
    Fighter& me = w.f[idx];
    auto no = [&](const char* why) {
        if (msg) *msg = why;
        return false;
    };
    auto enemyOk = [&](int t) {
        return t >= 0 && t < (int)w.f.size() && w.f[t].hp > 0 && w.f[t].team != me.team && !w.f[t].fled && isKnown(w, me.team, t) &&
               !(me.cond[C_CHARM] > 0 && me.charmSrc == t);
    };
    switch (p.kind) {
        case PR_END:
            return true;
        case PR_MOVE: {
            if (check) {
                if (p.x < 0 || p.y < 0 || p.x >= w.aw || p.y >= w.ah) return no("Туда нельзя: это за пределами арены.");
                if (w.wall[p.y][p.x] || w.pit[p.y][p.x]) return no("Клетка непроходима (стена или ущелье).");
                if (ts.speed < 5) return no("Движения не осталось.");
                if (me.cond[C_FRIGHT] > 0) {   // испуганный не приближается добровольно
                    int nowD = 1 << 30, newD = 1 << 30;
                    for (size_t i = 0; i < w.f.size(); i++) {
                        const Fighter& g = w.f[i];
                        if (g.hp > 0 && g.team != me.team && isKnown(w, me.team, (int)i)) {   // только известные (туман войны)
                            nowD = std::min(nowD, 5 * std::max(std::abs(g.x - me.x), std::abs(g.y - me.y)));   // по плану (как у сети):
                            newD = std::min(newD, 5 * std::max(std::abs(g.x - p.x), std::abs(g.y - p.y)));     // ярус клетки ещё неизвестен
                        }
                    }
                    if (newD < nowD) return no("Вы испуганы: приближаться к врагу нельзя.");
                }
                // каждое решение что-то тратит: шаг, который никуда не ведёт (своя клетка, путь сразу упирается во врага
                // или не хватает скорости на первую клетку), не тратит скорость — его нет
                if (p.x == me.x && p.y == me.y) return no("Вы уже стоите в этой клетке.");
                std::vector<PStep> path;
                pathTo(w, me, p.x, p.y, path);
                const int budget = p.a >= 0 ? std::min(ts.speed, p.a) : ts.speed;
                bool knownFoe = false;   // в известного врага не шагнуть; в невидимого — можно упереться (он раскроется, 5 фт)
                for (size_t i = 0; !path.empty() && i < w.f.size(); i++) {
                    const Fighter& g = w.f[i];
                    if (g.team != me.team && touchesAt(w, me, path[0].first, path[0].second, path[0].l, g) && isKnown(w, me.team, (int)i)) knownFoe = true;
                }
                if (path.empty() || knownFoe || stepCostL(w, me, me.x, me.y, me.up, path[0].first, path[0].second, path[0].l) > budget)
                    return no("Туда не сдвинуться: путь закрыт или не хватает скорости на первый шаг.");
            }
            const int budget = p.a >= 0 ? std::min(ts.speed, p.a) : ts.speed;
            const int moved = moveToCell(w, me, p.x, p.y, budget);
            ts.speed -= moved;
            g_act = ActInfo{};
            g_act.type = "move";
            return true;
        }
        case PR_ATTACK: {   // x == 1 — одна атака (игрок): первая тратит действие, остальные атаки этого действия — без платы
            const Ability ab = builtinAbility(EF_WEAPON);
            // y >= 1 — удар запасным оружием мультиатаки y−1 (укус + когти в одном действии «Атака», пакет атомов 1)
            if (p.y >= 1) {
                const int k = p.y - 1;
                if (k >= (int)me.b.alt.size() || k >= 8 || !me.b.alt[k].multi) return no("Это оружие не бьёт в мультиатаке.");
                const bool started = attackStarted(ts);
                if (check) {
                    if (started ? ts.altLeft[k] <= 0 : ts.actionUsed) return no(started ? "Удары этим оружием в этом действии уже потрачены." : "Действие уже потрачено.");
                    if (me.disarmed) return no("Вы обезоружены.");
                    if (!enemyOk(p.a)) return no("Нужна живая известная цель-враг (не очаровавшая вас).");
                    swapWeapon(me.b, (size_t)k);
                    const bool far = distFt(me, w.f[p.a]) > atkDist(me.b);
                    swapWeapon(me.b, (size_t)k);
                    if (far) return no("Цель дальше дальности этого оружия.");
                    if (!losF(w, me, w.f[p.a])) return no("Цель не видна: путь закрыт стеной.");
                }
                if (!started) {   // действие «Атака» начато этим оружием: все удары основного ещё впереди
                    payEcon(ts, me, EC_ACTION);
                    ts.atkLeft = me.b.wAtt;
                    initAltLeft(ts, me);
                }
                const int nNow = std::clamp(p.x, 1, ts.altLeft[k]);   // сколько ударов этим оружием — по этой цели сразу
                ts.altLeft[k] -= nNow;
                g_act = ActInfo{};
                swapWeapon(me.b, (size_t)k);
                doWeapon(w, me, p.a, nNow);
                swapWeapon(me.b, (size_t)k);
                ts.lastWasAttack = true;
                ts.spent = true;
                return true;
            }
            // x >= 1 — игрок: столько атак действия «Атака» по этой цели сразу (остальные — потом, по другим целям; 8 ноября);
            // cont — атаки действия уже начаты (игрок; способность «вместо одной атаки» — и бот)
            const bool one = p.x >= 1, cont = ts.atkLeft > 0;
            const int nNow = !one ? 0 : std::clamp(p.x, 1, cont ? ts.atkLeft : std::max(1, me.b.wAtt));
            if (check) {
                const char* why = nullptr;
                if (!cont && !canPay(me, ts, ab.cost, &why)) return no(why);
                if (me.b.wN <= 0) return no("У вас нет оружия: атаковать нечем.");
                if (!enemyOk(p.a)) return no("Нужна живая известная цель-враг (не очаровавшая вас).");
                if (distFt(me, w.f[p.a]) > atkDist(me.b)) return no("Цель дальше дальности оружия.");
                if (!losF(w, me, w.f[p.a])) return no("Цель не видна: путь закрыт стеной.");
            }
            if (p.b == 1 && hasWhen(me.b, W_RECKLESS) && me.b.wRange <= 5) me.wasReckless = true;
            g_act = ActInfo{};
            doWeapon(w, me, p.a, one ? nNow : (cont ? ts.atkLeft : -1));
            if (cont) ts.atkLeft = one ? ts.atkLeft - nNow : 0;
            else {
                payEcon(ts, me, ab.cost.econ);
                ts.atkLeft = one ? std::max(0, me.b.wAtt - nNow) : 0;
                initAltLeft(ts, me);
            }
            // целое действие (бот): удары оружием мультиатаки уже сделаны в doWeapon(−1); после «вместо одной атаки» — здесь
            if (!one) {
                if (cont && !me.b.alt.empty()) altMultiAttacks(w, me, p.a);
                for (int k = 0; k < 8; k++) ts.altLeft[k] = 0;
            }
            ts.lastWasAttack = true;
            ts.spent = true;
            return true;
        }
        case PR_SPELL: {
            if (p.a < 0 || p.a >= (int)me.b.abil.size()) return no("Нет такой способности.");
            const Spec s = me.b.abil[p.a];   // копия: превращение меняет тело (me.b) посреди примитива
            const Ability ab = specAbility(me.b, p.a);
            if (check) {
                if (s.react) return no("Это реакция: она срабатывает сама.");
                const char* why = nullptr;
                if (!canPay(me, ts, ab.cost, &why)) return no(why);
                if (s.sumN > 0 && summonRoom(w, idx, p.a) <= 0) return no("Технический потолок призыва (limity.json): больше не призвать.");
            }
            g_act = ActInfo{};
            if (s.self && s.teleFt > 0) {   // телепорт в клетку
                if (check) {
                    if (!fpAll(w, me, p.x, p.y, [&](int cx, int cy) { return !w.wall[cy][cx] && !w.pit[cy][cx]; }) || blockedAt(w, me, p.x, p.y))
                        return no("Туда не прыгнуть: клетка закрыта или занята.");
                    if (distFC(w, me, p.x, p.y) > s.teleFt) return no("Дальше дальности прыжка.");
                    if (s.jump && distFC(w, me, p.x, p.y) > ts.speed) return no("Прыжок тратит движение: его не хватает.");
                    if (s.jump && !losFC(w, me, p.x, p.y)) return no("Прыжок: путь закрыт стеной.");
                }
                if (s.jump) ts.speed = std::max(0, ts.speed - distFC(w, me, p.x, p.y));   // прыжок (пакет атомов 2) — за движение
                me.x = p.x;
                me.y = p.y;
                me.up = !nodeOK(w, me, me.x, me.y, 0) && w.deck[me.y][me.x] > 0;
                hazardHit(w, me);
                paySpec(w, me, p.a, false);
                g_act.type = "teleport";
                g_act.abil = p.a;
            } else if (s.self) {
                // «и на союзника»: цель — союзник в пределах дальности и на виду (иначе — на себя)
                if (check && p.b >= 0 && p.b != idx) {
                    if (!s.ally) return no("Эта способность только на себя.");
                    if (p.b >= (int)w.f.size() || w.f[p.b].hp <= 0 || w.f[p.b].team != me.team || w.f[p.b].fled) return no("Нужен живой союзник.");
                    if (distFt(me, w.f[p.b]) > s.range) return no("Союзник дальше дальности способности.");
                    if (!losF(w, me, w.f[p.b])) return no("Союзник не виден: путь закрыт стеной.");
                }
                const bool form = s.formTmpl >= 0;
                doSpec(w, me, p.a, p.b >= 0 ? p.b : idx);
                if (form && me.inForm) {   // скорость облика: потраченное движение остаётся потраченным
                    const int used = ts.speed0 - ts.speed;
                    ts.speed0 = speedOf(me);
                    ts.speed = std::max(0, ts.speed0 - used);
                }
            } else if (s.ground) {
                if (check) {
                    if (p.x < 0 || p.y < 0 || p.x >= w.aw || p.y >= w.ah) return no("Выберите клетку на арене.");
                    if (distFC(w, me, p.x, p.y) > s.range) return no("Клетка дальше дальности способности.");
                    if (!losFC(w, me, p.x, p.y)) return no("Клетка не видна: путь закрыт стеной.");
                }
                doSpec(w, me, p.a, -1, p.x, p.y);
            } else {
                if (check) {
                    // лечит союзников (пакет атомов 2): целью может быть и союзник
                    const bool allyOk = s.healAlly && p.b >= 0 && p.b < (int)w.f.size() && w.f[p.b].hp > 0 && w.f[p.b].team == me.team;
                    if (!allyOk && !enemyOk(p.b)) return no("Нужна живая известная цель-враг (не очаровавшая вас).");
                    if (distFt(me, w.f[p.b]) > specReach(me.b, s)) return no("Цель дальше дальности способности.");
                    if (!losF(w, me, w.f[p.b])) return no("Цель не видна: путь закрыт стеной.");
                }
                doSpec(w, me, p.a, p.b);
            }
            payEcon(ts, me, ab.cost.econ);
            if (ab.cost.econ == EC_ACTION) ts.lastWasAttack = !s.self;
            ts.spent = true;
            return true;
        }
        case PR_DASH: {
            const Ability ab = builtinAbility(EF_DASH);
            const char* why = nullptr;
            if (check && !canPay(me, ts, ab.cost, &why)) return no(why);
            payEcon(ts, me, ab.cost.econ);
            ts.speed += ts.speed0;
            me.dashedNow = true;
            g_act = ActInfo{};
            g_act.type = "dash";
            return true;
        }
        case PR_HELP: {   // Помощь (v21): враг рядом со мной, первая атака союзника по нему — с преимуществом
            const Ability ab = builtinAbility(EF_HELP);
            const char* why = nullptr;
            if (check) {
                if (!canPay(me, ts, ab.cost, &why)) return no(why);
                if (!enemyOk(p.a)) return no("Нужна живая известная цель-враг.");
                if (distFt(me, w.f[p.a]) > 5) return no("Помочь можно только против врага вплотную к вам.");
            }
            payEcon(ts, me, ab.cost.econ);
            w.f[p.a].helpBy = idx;
            g_act = ActInfo{};
            g_act.type = "help";
            g_act.target = p.a;
            return true;
        }
        case PR_ALT: {   // высота полёта (v21)
            const int cost = 10 * std::abs(p.a - me.alt);
            if (check) {
                if (!me.b.fly) return no("Вы не умеете летать.");
                if (!canStayAloft(me) || speedOf(me) <= 0) return no("Сейчас не взлететь: вы сбиты с ног, опутаны, схвачены или не можете двигаться.");
                if (p.a < 0 || p.a > maxAltAt(w, me, me.x, me.y, me.up)) return no(p.a < 0 ? "Ниже земли не опуститься." : "Выше не подняться: потолок или предел высоты.");
                if (p.a == me.alt) return no("Вы уже на этой высоте.");
                if (cost > ts.speed) return no("Не хватает движения: уровень высоты — 10 фт.");
            }
            ts.speed -= cost;
            setAlt(w, me, p.a);
            g_act = ActInfo{};
            g_act.type = "alt";
            return true;
        }
        case PR_READY: {   // Подготовка (v21): до моего следующего хода — удар реакцией по врагу, вошедшему в досягаемость
            const Ability ab = builtinAbility(EF_READY);
            const char* why = nullptr;
            if (check) {
                if (!canPay(me, ts, ab.cost, &why)) return no(why);
                if (p.a >= (int)me.b.abil.size()) return no("Нет такой способности.");
                if (p.a >= 0 && (me.b.abil[p.a].react || !resReady(me, specAbility(me.b, p.a).cost))) return no("Эту способность сейчас не подготовить.");
                if (p.a < 0 && (me.b.wN <= 0 || me.disarmed)) return no("Подготовить удар нечем: нет оружия.");
            }
            payEcon(ts, me, ab.cost.econ);
            me.readied = true;
            me.readyAbil = p.a >= 0 && p.a < (int)me.b.abil.size() ? p.a : -1;   // 8 ноября: что подготовлено
            me.readyTrig = p.b == 2 ? 2 : 1;                                      // и при каком условии
            g_act = ActInfo{};
            g_act.type = "ready";
            return true;
        }
        case PR_DODGE: {
            const Ability ab = builtinAbility(EF_DODGE);
            const char* why = nullptr;
            if (check && !canPay(me, ts, ab.cost, &why)) return no(why);
            payEcon(ts, me, ab.cost.econ);
            me.dodging = true;
            g_act = ActInfo{};
            g_act.type = "dodge";
            return true;
        }
        case PR_DISENGAGE: {
            // a = 1 — Отход бонусным действием (способность есть, только если боец умеет)
            const Ability ab = builtinAbility(EF_DISENGAGE, p.a == 1 ? EC_BONUS : EC_ACTION);
            const char* why = nullptr;
            if (check && p.a == 1 && (!me.b.disengB || !canPay(me, ts, ab.cost))) return no("Отход бонусным действием недоступен.");
            if (check && !canPay(me, ts, ab.cost, &why)) return no(why);
            payEcon(ts, me, ab.cost.econ);
            if (ab.cost.econ == EC_ACTION) {
                g_act = ActInfo{};
                g_act.type = "disengage";
            }
            me.disengaged = true;
            return true;
        }
        case PR_SUMMON:   // призыв — способность: a — её номер (то же, что «способность a» на себя)
            if (p.a < 0 || p.a >= (int)me.b.abil.size() || me.b.abil[p.a].sumN <= 0) return no("Нет такой призывающей способности.");
            return applyPrim0(w, idx, ts, Prim{PR_SPELL, p.a, idx}, check, msg);
        case PR_SWAP:
            // смена оружия: 1-я за ход бесплатно, 2-я — бонусное действие, 3-я — действие, дальше платить нечем
            if (p.a < 0 || p.a >= (int)me.b.alt.size()) return no("Нет такого запасного оружия.");
            if (ts.swaps >= 3) return no("Оружие уже сменено трижды за ход: платить нечем.");
            if (ts.swaps == 1) {
                if (check && ts.bonusUsed) return no("Вторая смена оружия — бонусное действие, а оно потрачено.");
                payEcon(ts, me, EC_BONUS);
            } else if (ts.swaps == 2) {
                if (check && ts.actionUsed) return no("Третья смена оружия — действие, а оно потрачено.");
                payEcon(ts, me, EC_ACTION);
                ts.lastWasAttack = false;
            }
            ts.swaps++;
            swapWeapon(me.b, (size_t)p.a);
            return true;
        case PR_DROPCONC:
            if (me.concSpec < 0) return no("Вы ни на чём не концентрируетесь.");
            breakConc(w, idx);
            g_act = ActInfo{};
            g_act.type = "dropconc";
            return true;
        case PR_SURGE:
            if (check && (me.surgeLeft <= 0 || !ts.actionUsed || !ts.lastWasAttack))
                return no("Всплеск действий недоступен: нужен остаток и уже потраченное действие Атака или способность.");
            me.surgeLeft--;
            g_surge++;
            ts.actionUsed = false;
            return true;
        case PR_ORDER:
            // простой приказ (одна цель всем приспешникам): бесплатно, раз за ход; дорогие приказы — после №18
            if (ts.orders >= 1) return no("Приказ уже отдан в этот ход.");
            // цель приказа — живой известный враг (очаровавший босса тоже: бить его могут приспешники)
            if (check && (idx >= w.nLead || p.a < 0 || p.a >= (int)w.f.size() || w.f[p.a].hp <= 0 || w.f[p.a].team == me.team ||
                          w.f[p.a].fled || !isKnown(w, me.team, p.a)))
                return no("Приказ отдаёт главный босс, цель — живой известный враг.");
            ts.orders++;
            if (idx < w.nLead && p.a >= 0) {
                w.cmd[me.team] = p.a;
                evPush("{\"k\":\"order\",\"who\":" + std::to_string(idx) + ",\"tgt\":" + std::to_string(p.a) + "}");
            }
            return true;
    }
    return no("Неизвестный примитив.");
}
// Запись и повтор ходов бойца who примитивами: проверка «пустой политики» (повтор хода бота даёт тот же бой) и
// обучение сети копированием бота. replay = false — ходы бота пишутся в turns, true — ходы берутся из turns.
struct PrimLog {
    int who = -1;
    bool replay = false;
    std::vector<std::vector<Prim>> turns;
    size_t next = 0;
};
thread_local PrimLog* g_primLog = nullptr;
// Повтор записанного хода: начало хода и бегство — по правилам, дальше записанные примитивы (без проверки)
// g_replayHook — посмотреть решение перед его повтором (обучение сети копированием бота); p == nullptr — конец хода
thread_local void (*g_replayHook)(World&, int, const TurnState&, const Prim*) = nullptr;
void replayTurn(World& w, int idx, const std::vector<Prim>& prims) {
    TurnState ts;
    if (!beginTurn(w, idx, ts)) return;
    if (forcedFlee(w, idx, ts)) return;
    for (auto& p : prims) {
        if (over(w) || w.f[idx].hp <= 0) break;
        if (p.kind == PR_END) break;
        if (g_replayHook) g_replayHook(w, idx, ts, &p);
        applyPrim(w, idx, ts, p, false);
    }
    if (g_replayHook && !over(w) && w.f[idx].hp > 0) g_replayHook(w, idx, ts, nullptr);
    endOfTurn(w.f[idx]);
}
// подготовленное действие (8 ноября): способность (на себя — себе) или одна атака оружием
void readyFire(World& w, int gi, int fi) {
    Fighter& g = w.f[gi];
    if (g.readyAbil >= 0 && g.readyAbil < (int)g.b.abil.size()) {
        if (resReady(g, specAbility(g.b, g.readyAbil).cost)) doSpec(w, g, g.readyAbil, g.b.abil[g.readyAbil].self ? gi : fi);
    } else
        doWeapon(w, g, fi, 1);
}
void takeTurn(World& w, int idx) {
    TurnState ts;
    if (!beginTurn(w, idx, ts)) return;
    Fighter& me = w.f[idx];
    if (forcedFlee(w, idx, ts)) return;
    // №24: сеть может бесплатно снять свою концентрацию (стойка 9), дальше ход как в обычной стойке
    if (g_ovr.active && g_ovr.stance == 9 && me.concSpec >= 0) {
        recordPrim(idx, {PR_DROPCONC});
        breakConc(w, idx);
    }
    int speed = ts.speed;
    const int speed0 = ts.speed0;
    bool &actionUsed = ts.actionUsed, &bonusUsed = ts.bonusUsed;   // бюджет хода — общий TurnState (платит payEcon)

    const Brain br = brainOf(w, me);
    std::vector<int> enemies;
    for (size_t i = 0; i < w.f.size(); i++)
        if (w.f[i].hp > 0 && w.f[i].team != me.team && !(me.cond[C_CHARM] > 0 && me.charmSrc == (int)i) &&
            (br.sense >= SENSE_INF || distFt(me, w.f[i]) <= br.sense + 60 * g_curRound) && isKnown(w, me.team, (int)i))
            enemies.push_back((int)i);
    // очарованному некого атаковать — но состояние всё равно идёт и заканчивается
    if (enemies.empty()) {
        // туман войны: никого не видно — идёт к месту, где последний раз видел врага (самые свежие сведения, ближе)
        int bk = -1;
        for (size_t i = 0; i < w.f.size() && i < w.known[me.team].size(); i++) {
            const auto& k = w.known[me.team][i];
            if (w.f[i].hp <= 0 || w.f[i].team == me.team || k[2] < 0 || (k[0] == me.x && k[1] == me.y)) continue;
            if (bk < 0 || k[2] > w.known[me.team][bk][2] ||
                (k[2] == w.known[me.team][bk][2] && std::max(std::abs(k[0] - me.x), std::abs(k[1] - me.y)) <
                                                         std::max(std::abs(w.known[me.team][bk][0] - me.x), std::abs(w.known[me.team][bk][1] - me.y))))
                bk = (int)i;
        }
        if (bk >= 0 && ts.speed > 0 && !me.cond[C_FRIGHT]) {
            Fighter spot;
            spot.x = w.known[me.team][bk][0];
            spot.y = w.known[me.team][bk][1];
            moveToward(w, me, spot, 0, ts.speed, false, true);
            g_act.type = "search";
        } else
            g_act.type = "idle";
        endOfTurn(me);
        return;
    }
    int focus = enemies[0], fd = 1 << 30;
    for (int e : enemies) {
        int d = distFt(me, w.f[e]) - (br.focus && e < w.nLead ? me.pol->v[PO_FOCUSFT] : 0);
        if (d < fd) {
            fd = d;
            focus = e;
        }
    }
    // RL: выбор цели
    if (g_ovr.active && g_ovr.tgt > 0) {
        int bestE = -1;
        double bs = 1e18;
        for (int e : enemies) {
            double sc = g_ovr.tgt == 1
                            ? (e < w.nLead ? 0.0 : 1e6) + distFt(me, w.f[e])
                            : (g_ovr.tgt == 2 ? (e >= w.nLead ? 0.0 : 1e6) + distFt(me, w.f[e]) : (double)w.f[e].hp);
            if (sc < bs) {
                bs = sc;
                bestE = e;
            }
        }
        if (bestE >= 0) focus = bestE;
    }
    // послушание миньона зависит от ХАР главного босса
    const bool obeys = !(idx >= w.nLead && br.obey < 1.0) || me.ai.unit() < br.obey;
    // приказ главного босса
    if (obeys && idx >= w.nLead && w.cmd[me.team] >= 0 &&
        std::find(enemies.begin(), enemies.end(), w.cmd[me.team]) != enemies.end())
        focus = w.cmd[me.team];
    if (idx < w.nLead) {
        recordPrim(idx, {PR_ORDER, focus});
        if (w.cmd[me.team] != focus) evPush("{\"k\":\"order\",\"who\":" + std::to_string(idx) + ",\"tgt\":" + std::to_string(focus) + "}");
        w.cmd[me.team] = focus;
    }
    Fighter& F = w.f[focus];
    double hpFrac = (double)me.hp / me.maxHp;
    // высота полёта (v21): стрелок (оружие от 30 фт) держится на 20 фт — ближнику с земли не достать, ближник — на уровне цели
    if (me.b.fly && canStayAloft(me) && speed >= 10 && !me.cond[C_FRIGHT]) {
        const int ground = zF(w, me) - me.alt, cap = maxAltAt(w, me, me.x, me.y, me.up);
        int want = atkDist(me.b) >= 30 ? 2 : zF(w, F) - ground;
        want = std::clamp(want, 0, cap);
        if (want != me.alt) {
            const int step = std::min(std::abs(want - me.alt), speed / 10), a = me.alt + (want > me.alt ? step : -step);
            recordPrim(idx, {PR_ALT, a});
            ts.speed -= 10 * step;
            speed -= 10 * step;
            setAlt(w, me, a);
            if (me.hp <= 0 || over(w)) return;
        }
    }
    // превращение (v21): облик — запас хитов и тело; бот превращается сразу, как только видит врага и может заплатить
    if (!me.inForm)
        for (size_t k = 0; k < me.b.abil.size(); k++) {
            if (me.b.abil[k].formTmpl < 0 || !canPay(me, ts, specAbility(me.b, (int)k).cost)) continue;
            const Prim fp{PR_SPELL, (int)k, idx};
            recordPrim(idx, fp);
            const int s0 = ts.speed;
            applyPrim(w, idx, ts, fp, false, nullptr);
            speed += ts.speed - s0;
            break;
        }

    // арсенал: оружие под ситуацию (дальность до цели, помехи)
    if (!me.b.alt.empty() && !me.cond[C_INCAP]) {
        auto score = [&](Fighter& m) {
            double ev = evWeapon(w, m, F);
            int d = distFt(m, F), r = atkDist(m.b);
            return ev * (d <= r + speed ? 1.0 : (d <= r + 2 * speed ? 0.7 : 0.4));
        };
        double bestS = me.b.wN > 0 ? score(me) : -1;
        int bestK = -1;
        for (size_t k = 0; k < me.b.alt.size(); k++) {
            swapWeapon(me.b, k);
            double sc = score(me);
            swapWeapon(me.b, k);
            if (sc > bestS) {
                bestS = sc;
                bestK = (int)k;
            }
        }
        if (bestK >= 0) {
            recordPrim(idx, {PR_SWAP, bestK});
            swapWeapon(me.b, (size_t)bestK);
        }
    }
    const bool selfFirst = g_ovr.active && g_ovr.stance == 7, noSelf = g_ovr.active && g_ovr.stance == 8;
    // отступить от цели не более чем на maxFt
    auto retreatBy = [&](int maxFt) {
        maxFt = std::min(maxFt, speed);
        if (maxFt < 5 || me.cond[C_RESTR] || me.cond[C_GRAPPLE]) return;
        int dx = me.x - F.x, dy = me.y - F.y, sx = dx == 0 ? ((int)me.ai.below(2) * 2 - 1) : (dx > 0 ? 1 : -1),
            sy = dy == 0 ? ((int)me.ai.below(2) * 2 - 1) : (dy > 0 ? 1 : -1), st = maxFt / 5 + 1;
        Fighter away;
        away.x = std::clamp(me.x + sx * st, 0, w.aw - 1);
        away.y = std::clamp(me.y + sy * st, 0, w.ah - 1);
        speed -= moveToward(w, me, away, 0, maxFt, false);
    };
    if (g_ovr.active && g_ovr.stance == 6 && !actionUsed) {
        recordPrim(idx, {PR_DODGE});
        me.dodging = true;
        payEcon(ts, me, EC_ACTION);
        fireTrig(w, me, T_DODGE, nullptr);   // «событие → эффект» (v21)
        g_act.type = "dodge";
    }
    if (g_ovr.active && g_ovr.stance == 5 && !actionUsed) {
        recordPrim(idx, {PR_DISENGAGE, 0});
        me.disengaged = true;
        payEcon(ts, me, EC_ACTION);
        g_act.type = "disengage";
        retreatBy(speed);
    }
    // Отход: при низком ХП и вражеском ближнике рядом лучше выйти без штрафа за провокацию, чем героически стоять
    if (br.disengage && hpFrac < me.pol->v[PO_DISENG] && meleeWeapon(F.b) && distFt(me, F) <= meleeReach(F.b) &&
        me.b.wRange > 5 && !actionUsed) {
        recordPrim(idx, {PR_DISENGAGE, 0});
        me.disengaged = true;
        payEcon(ts, me, EC_ACTION);
        g_act.type = "disengage";
        int dx = (me.x - F.x), dy = (me.y - F.y);
        int tx = std::clamp(me.x + (dx == 0 ? ((int)me.ai.below(2) * 2 - 1) : (dx > 0 ? 1 : -1)) * (speed / 5), 0, w.aw - 1);
        int ty = std::clamp(me.y + (dy == 0 ? ((int)me.ai.below(2) * 2 - 1) : (dy > 0 ? 1 : -1)) * (speed / 5), 0, w.ah - 1);
        Fighter away;
        away.x = tx;
        away.y = ty;
        // Отход: действие, реакцию не провоцирует; тратит общий бюджет движения
        speed -= moveToward(w, me, away, 0, speed, false);
    }

    // Отход бонусным действием: стрелок, до которого дотянулся ближник, отходит бонусным действием и сохраняет действие
    // для атаки
    if (br.disengage && me.b.disengB && !bonusUsed && !actionUsed && !me.disengaged && me.b.wRange > 5 &&
        meleeWeapon(F.b) && distFt(me, F) <= meleeReach(F.b)) {
        recordPrim(idx, {PR_DISENGAGE, 1});
        me.disengaged = true;
        payEcon(ts, me, EC_BONUS);
        retreatBy(speed / 2);
    }

    // самоспособности: лечение / побег / бафф
    // toward=false: прыжок ОТ врага (побег); toward=true: прыжок К врагу (сближение)
    auto trySelf = [&](auto pred, bool toward = false) {
        for (size_t i = 0; i < me.b.abil.size(); i++) {
            const Spec& s = me.b.abil[i];
            if (!s.self || s.react || !specResReady(me, (int)i) || !pred(s)) continue;
            if (!(s.jump && s.teleFt > 0) && (s.bonus ? bonusUsed : actionUsed)) continue;   // прыжок — без действия, за движение
            if (s.teleFt > 0) {
                int dx = (F.x > me.x) - (F.x < me.x), dy = (F.y > me.y) - (F.y < me.y);
                if (!toward) {
                    dx = -dx;
                    dy = -dy;
                    if (!dx && !dy) dx = 1;
                } else if (!dx && !dy)
                    continue;
                bool done = false;
                for (int st = s.teleFt / 5; st >= 1 && !done; st--) {
                    int nx = me.x + dx * st, ny = me.y + dy * st;
                    if (!fpAll(w, me, nx, ny, [&](int cx, int cy) { return !w.wall[cy][cx] && !w.pit[cy][cx]; }) || blockedAt(w, me, nx, ny)) continue;
                    // не на голову врагу
                    if (toward && 5 * std::max(std::abs(nx - F.x), std::abs(ny - F.y)) < 5) continue;
                    if (s.jump) {   // прыжок (пакет атомов 2): хватает движения и не сквозь стену — как проверяет applyPrim
                        const int d = distFC(w, me, nx, ny);
                        if (d > speed || !losFC(w, me, nx, ny)) continue;
                        speed -= d;
                    }
                    me.x = nx;
                    me.y = ny;
                    done = true;
                }
                // прыгнуть некуда — применение не тратим
                if (!done) continue;
                me.up = !nodeOK(w, me, me.x, me.y, 0) && w.deck[me.y][me.x] > 0;
                hazardHit(w, me);
                recordPrim(idx, {PR_SPELL, (int)i, -1, me.x, me.y});
                paySpec(w, me, (int)i, false);
                g_act.type = "teleport";
                g_act.target = -1;
            } else {
                recordPrim(idx, {PR_SPELL, (int)i, focus});
                doSpec(w, me, (int)i, focus);
            }
            if (s.jump && s.teleFt > 0)
                ;   // прыжок оплачен движением
            else if (s.bonus)
                payEcon(ts, me, EC_BONUS);
            else
                payEcon(ts, me, EC_ACTION);
            return true;
        }
        return false;
    };
    if (!noSelf && br.selfTactics && hpFrac < me.pol->v[PO_TELE] && distFt(me, F) <= 10) {
        if (!trySelf([](const Spec& s) { return s.teleFt > 0; })) trySelf([](const Spec& s) { return s.hide; });
    }
    if (!noSelf && br.selfSimple && hpFrac < (selfFirst ? 1.01 : me.pol->v[PO_HEAL]))
        trySelf([](const Spec& s) { return s.healN > 0; });
    // союзники (v21): лечение раненому союзнику (меньше половины хитов) и приказ атаковать — тому, кто достаёт врага
    if (!noSelf && br.selfSimple)
        for (size_t i = 0; i < me.b.abil.size(); i++) {
            const Spec& s = me.b.abil[i];
            if (!s.self || !s.ally || s.react || !specResReady(me, (int)i) || (s.bonus ? bonusUsed : actionUsed)) continue;
            const int t = pickAlly(w, me, s);
            if (t < 0 || t == idx) continue;
            const Fighter& g = w.f[t];
            const bool want = s.cmdAtk || ((s.healN || s.healB) && g.hp * 2 < g.maxHp) || (s.tempN && g.temp <= 0 && g.hp * 2 < g.maxHp);
            if (!want) continue;
            recordPrim(idx, {PR_SPELL, (int)i, t});
            doSpec(w, me, (int)i, t);
            payEcon(ts, me, s.bonus ? EC_BONUS : EC_ACTION);
            if (over(w) || me.hp <= 0) break;
        }
    if (!noSelf && br.selfTactics && me.buffRounds <= 0 &&
        distFt(me, F) <= (selfFirst ? 100000.0 : 2 * speed * me.pol->v[PO_BUFFD] + 10))
        trySelf([](const Spec& s) { return s.buffN > 0; });
    if (!noSelf && br.selfTactics && me.sbRounds <= 0 &&
        distFt(me, F) <= (selfFirst ? 100000.0 : 2 * speed * me.pol->v[PO_BUFFD] + 10))
        trySelf([](const Spec& s) { return s.sbAmt > 0; });
    if (!noSelf && br.selfSimple && me.temp <= 0 &&
        distFt(me, F) <= (selfFirst ? 100000.0 : 2 * speed * me.pol->v[PO_BUFFD] + 10))
        trySelf([](const Spec& s) { return s.tempN > 0; });
    if (!noSelf && br.selfTactics && me.acBuffRounds <= 0 &&
        distFt(me, F) <= (selfFirst ? 100000.0 : 2 * speed * me.pol->v[PO_BUFFD] + 10))
        trySelf([](const Spec& s) { return s.acB > 0; });
    // тьма вокруг себя — только если сам вижу в ней (тёмное/слепое зрение), а враг нет
    if (!noSelf && br.selfTactics && (me.b.dv >= 10 || me.b.blindsight >= 10) && F.b.dv < 30 && F.b.blindsight < 10 &&
        !w.dark[me.y][me.x] && distFt(me, F) <= 3 * speed + 60)
        trySelf([](const Spec& s) { return s.darkR > 0; });
    if (!noSelf && br.selfTactics && me.invisRounds <= 0 && F.b.blindsight < 30 &&
        distFt(me, F) <= (selfFirst ? 100000.0 : 2 * speed * me.pol->v[PO_BUFFD] + 10))
        trySelf([](const Spec& s) { return s.invisN > 0; });

    // выбор дальности: берём самый ценный вариант без учёта позиции
    double bestRaw = evWeapon(w, me, F);
    int desired = me.b.wN > 0 ? atkDist(me.b) : 5;
    for (size_t i = 0; i < me.b.abil.size(); i++) {
        const Spec& s = me.b.abil[i];
        if (s.self || s.react || !specResReady(me, (int)i)) continue;
        double ev = evSpec(w, s, me, F);
        if (ev > bestRaw) {
            bestRaw = ev;
            desired = specReach(me.b, s);
        }
        if (g_ovr.active && g_ovr.pref == 1 + (int)i && ev > 0) {
            bestRaw = 1e9;
            desired = specReach(me.b, s);
        }
    }
    if (g_ovr.active && g_ovr.pref == 0 && me.b.wN > 0) desired = atkDist(me.b);
    // призыв: босс решает, применить ли призывающую способность. Призываем, только если волна даёт не меньше пользы,
    // чем собственное лучшее действие
    for (size_t k = 0; k < me.b.abil.size(); k++) {
        const Spec& s = me.b.abil[k];
        if (s.sumN <= 0 || s.react || !canPay(me, ts, specAbility(me.b, (int)k).cost)) continue;
        const int m = summonRoom(w, idx, (int)k);
        if (m <= 0) continue;
        Fighter tmp;
        tmp.b = me.b.tmpl[s.sumTmpl];
        tmp.team = me.team;
        tmp.x = me.x;
        tmp.y = me.y;
        tmp.hp = tmp.maxHp = tmp.b.hp;
        double ev = evWeapon(w, tmp, F);
        for (auto& sp : tmp.b.abil)
            if (!sp.self) ev = std::max(ev, evSpec(w, sp, tmp, F));
        const double waveEV = ev * m;
        if (!br.evalSummon || waveEV * me.pol->v[PO_SUMMON] >= bestRaw) {
            recordPrim(idx, {PR_SPELL, (int)k, idx});
            const int econ = specAbility(me.b, (int)k).cost.econ;
            doSpec(w, me, (int)k, idx);
            payEcon(ts, w.f[idx], econ);
        }
        break;   // одна волна за ход
    }
    // перемещение (испуганный не приближается)
    bool inPos = distFt(me, F) <= desired && losF(w, me, F);
    // кайтинг: дальнобойный не даёт ближнику подойти
    if (br.kite && me.pol->v[PO_KITE] > 0 && me.b.wRange > 5 && F.b.wRange <= 5 && speed > 0 && !me.cond[C_RESTR] &&
        !me.cond[C_GRAPPLE] && !me.cond[C_FLEE]) {
        int d = distFt(me, F), threat = F.b.reach + (int)(speedOf(F) * me.pol->v[PO_KITE]),
            room = std::min(speed, desired - d);
        if (d > F.b.reach && d <= threat && room >= 5) {
            int dx = me.x - F.x, dy = me.y - F.y, sx = dx == 0 ? ((int)me.ai.below(2) * 2 - 1) : (dx > 0 ? 1 : -1),
                sy = dy == 0 ? ((int)me.ai.below(2) * 2 - 1) : (dy > 0 ? 1 : -1), st = room / 5 + 1;
            Fighter away;
            away.x = std::clamp(me.x + sx * st, 0, w.aw - 1);
            away.y = std::clamp(me.y + sy * st, 0, w.ah - 1);
            speed -= moveToward(w, me, away, 0, room, false);
            inPos = distFt(me, F) <= desired && losF(w, me, F);
        }
    }
    bool holdMove = false;
    // RL: тактика движения
    if (g_ovr.active) {
        int st = g_ovr.stance, d0 = distFt(me, F);
        if (st == 1 || st == 5 || st == 6)
            holdMove = true;
        else if (st == 2) {
            desired = 5;
            inPos = d0 <= 5 && losF(w, me, F);
        } else if (st == 3 || st == 4) {
            retreatBy(st == 4 ? speed : std::min(speed, std::max(0, desired - d0)));
            inPos = distFt(me, F) <= desired && losF(w, me, F);
            holdMove = true;
        }
    }
    // испуганный не приближается
    if (!inPos && !holdMove && !me.cond[C_FRIGHT] && !me.cond[C_FLEE]) {
        int need = distFt(me, F) - desired;
        // сначала прыжок К врагу
        if (need > speed) {
            if (br.selfTactics) trySelf([](const Spec& s) { return s.teleFt > 0; }, true);
            need = distFt(me, F) - desired;
        }
        // потом бег
        if (need > speed && !actionUsed && speed > 0) {
            const int walk = speed;
            speed += speed0;
            const size_t r0 = g_rec ? g_rec->size() : 0;
            const int moved = moveToward(w, me, F, desired, speed, true);
            speed -= moved;
            // пал от провоцированной атаки на шаге за пределом обычной скорости — шаг был в счёт Рывка (иначе повтор хода
            // с обычной скоростью этого шага не сделает)
            if (moved > walk || me.hp <= 0) {
                if (g_rec && idx == g_recIdx) g_rec->insert(g_rec->begin() + r0, Prim{PR_DASH});   // Рывок — до движения
                payEcon(ts, me, EC_ACTION);
                me.dashedNow = true;   // Рывок (в погоне считается и может утомить)
            } else
                speed = std::max(0, walk - moved);   // дальше обычной скорости не пошёл: действие не потрачено
        } else
            speed -= moveToward(w, me, F, desired, speed, true);
    }

    // основное действие и бонусное: лучший осуществимый вариант
    // 0 — действие, 1 — бонусное, 2 — всплеск действий (второе действие)
    for (int pass = 0; pass < 3; pass++) {
        if (over(w) || me.hp <= 0) break;   // бой решён (или босс пал от реакции): дальше не действует, как и повтор хода
        bool bonusPass = pass == 1;
        if (pass == 2) {
            if (me.surgeLeft <= 0 || !actionUsed || over(w) || me.hp <= 0 || me.cond[C_DISTR] || me.cond[C_INCAP] ||
                me.cond[C_FLEE] ||
                !(g_act.type.compare(0, 6, "attack") == 0 || g_act.type.compare(0, 7, "ability") == 0))
                continue;
            actionUsed = false;
        }
        if (bonusPass ? bonusUsed : actionUsed) continue;
        // cands — все осуществимые варианты (нужны только для шума)
        double best = 0;
        int bAct = -2, bT = -1, bGx = -1, bGy = -1;
        std::vector<std::array<int, 4>> cands;   // {действие, цель, клетка x, клетка y}
        if (!bonusPass && me.b.wN > 0) {   // безоружный атаки оружием не делает
            for (int e : enemies) {
                Fighter& E = w.f[e];
                if (E.hp <= 0 || distFt(me, E) > atkDist(me.b) || !losF(w, me, E)) continue;
                double ev = evWeapon(w, me, E),
                       sc = br.focus ? ev * (1 + (e < w.nLead ? me.pol->v[PO_TGTMAIN] : 0) +
                                             me.pol->v[PO_TGTKILL] * std::min(1.0, ev / std::max(1, E.hp)))
                                     : ev;
                if (br.noise > 0) cands.push_back({-1, e, -1, -1});
                if (g_ovr.active && g_ovr.pref == 0) sc *= 1000;
                if (g_ovr.active && g_ovr.tgt > 0 && e == focus) sc *= 4;
                // приказанная цель ценнее
                if (obeys && idx >= w.nLead && e == w.cmd[me.team]) sc *= 1.6;
                if (sc > best) {
                    best = sc;
                    bAct = -1;
                    bT = e;
                }
            }
        }
        for (size_t i = 0; i < me.b.abil.size(); i++) {
            const Spec& s = me.b.abil[i];
            if (s.self || s.react || s.bonus != bonusPass || !specResReady(me, (int)i)) continue;
            if (s.ground) {   // по клетке (№9, №22): лучшая клетка в пределах дальности и видимости
                int gx, gy;
                double sc = bestGroundCell(w, s, me, enemies, gx, gy);
                if (sc <= 0) continue;
                if (br.noise > 0) cands.push_back({(int)i, -1, gx, gy});
                if (g_ovr.active && g_ovr.pref == 1 + (int)i) sc *= 1000;
                if (sc > best) {
                    best = sc;
                    bAct = (int)i;
                    bT = -1;
                    bGx = gx;
                    bGy = gy;
                }
                continue;
            }
            for (int e : enemies) {
                Fighter& E = w.f[e];
                if (E.hp <= 0 || distFt(me, E) > specReach(me.b, s) || !losF(w, me, E)) continue;
                double ev = evSpec(w, s, me, E),
                       sc = br.focus ? ev * (1 + (e < w.nLead ? me.pol->v[PO_TGTMAIN] : 0) +
                                             me.pol->v[PO_TGTKILL] * std::min(1.0, ev / std::max(1, E.hp)))
                                     : ev;
                if (br.noise > 0) cands.push_back({(int)i, e, -1, -1});
                if (g_ovr.active && g_ovr.pref == 1 + (int)i) sc *= 1000;
                if (g_ovr.active && g_ovr.tgt > 0 && e == focus) sc *= 4;
                // приказанная цель ценнее
                if (obeys && idx >= w.nLead && e == w.cmd[me.team]) sc *= 1.6;
                if (sc > best) {
                    best = sc;
                    bAct = (int)i;
                    bT = e;
                    bGx = bGy = -1;
                }
            }
        }
        // ошибка: случайный вариант вместо лучшего
        if (br.noise > 0 && !cands.empty() && me.ai.unit() < br.noise) {
            auto c = cands[me.ai.below((uint32_t)cands.size())];
            bAct = c[0];
            bT = c[1];
            bGx = c[2];
            bGy = c[3];
        }
        // при низких ХП — защита вместо атаки
        if (br.dodge && pass == 0 && bAct != -2 && hpFrac < me.pol->v[PO_DODGE] && !me.cond[C_DISTR]) {
            recordPrim(idx, {PR_DODGE});
            me.dodging = true;
            payEcon(ts, me, EC_ACTION);
            fireTrig(w, me, T_DODGE, nullptr);   // «событие → эффект» (v21)
            g_act.type = "dodge";
            continue;
        }
        if (pass == 2 && bAct != -2) recordPrim(idx, {PR_SURGE});
        if (bAct == -1) {
            if (hasWhen(me.b, W_RECKLESS) && me.b.wRange <= 5 && hpFrac > me.pol->v[PO_RECK]) me.wasReckless = true;
            recordPrim(idx, {PR_ATTACK, bT, me.wasReckless ? 1 : 0});
            doWeapon(w, me, bT);
            if (!bonusPass) resolvePending(w, idx, ts);   // «событие → эффект»: атака бонусом после крита или убийства
        } else if (bAct >= 0) {
            recordPrim(idx, {PR_SPELL, bAct, bT, bGx, bGy});
            doSpec(w, me, bAct, bT, bGx, bGy);
            if (!bonusPass) resolvePending(w, idx, ts);
        }
        // нечем атаковать (v21): враг рядом и союзник при нём — Помощь; враг подходит к моей досягаемости — Подготовка;
        // иначе Уклонение
        else if (pass == 0 && bAct == -2) {
            int helpT = -1;
            for (int e : enemies) {
                const Fighter& E = w.f[e];
                if (E.hp <= 0 || distFt(me, E) > 5) continue;
                for (auto& g : w.f)
                    if (&g != &me && g.hp > 0 && g.team == me.team && g.b.wN > 0 && distFt(g, E) <= atkDist(g.b)) helpT = e;
            }
            const int near = nearestEnemyInRange(w, me, 1 << 20);
            const bool readyOk = me.b.wN > 0 && !me.disarmed && near >= 0 && distFt(me, w.f[near]) > atkDist(me.b) &&
                                 distFt(me, w.f[near]) <= atkDist(me.b) + speedOf(w.f[near]) + 5;
            if (!me.cond[C_DISTR] && (helpT >= 0 || readyOk)) {
                const Prim pp = helpT >= 0 ? Prim{PR_HELP, helpT} : Prim{PR_READY};
                recordPrim(idx, pp);
                if (helpT >= 0)
                    w.f[helpT].helpBy = idx;
                else
                    me.readied = true;
                payEcon(ts, me, EC_ACTION);
                g_act.type = helpT >= 0 ? "help" : "ready";
                continue;
            }
            recordPrim(idx, {PR_DODGE});
            me.dodging = true;
            payEcon(ts, me, EC_ACTION);
            fireTrig(w, me, T_DODGE, nullptr);   // «событие → эффект» (v21)
            g_act.type = "dodge";
            continue;
        }
        if (bAct != -2) {
            if (bonusPass)
                payEcon(ts, me, EC_BONUS);
            else {
                payEcon(ts, me, EC_ACTION);
                if (pass == 2) {
                    me.surgeLeft--;
                    g_surge++;
                }
            }
        } else if (pass == 2)
            actionUsed = true;   // всплеск не понадобился: второе действие не открывается (это не плата)
    }
    endOfTurn(me);
}

// параметры генерации карты (по умолчанию — прежняя карта)
#include "fighter_net.h"

// Арена: прямоугольник от 5×5 до 100×100 клеток (по 5 фт), тема (дикая местность или город) и особенности: стены, лазалки (укрытия), труднопроходимая
// местность, тьма, ручей (труднопроходим), ущелье с мостом, возвышенности. Всё за пределами прямоугольника — стена. Выход за арену — побег (поражение).
#include "world_gen.h"
struct MapStyle {
    int fixedW = 0, fixedH = 0, theme = -1;   // заданный размер участка и тема (−1 — как получится), для тестов и редактора
    unsigned long long worldSeed = 0;         // мир по зерну (игра; 0 — обучение: новый мир каждые 500 боёв)
    int worldSize = 1000, wx = -1, wy = -1;   // размер мира и угол участка (−1 — случайно)
};
MapStyle g_style;
// размер стороны арены из мира: 2–100, чаще средние (TZ_karta_shum.md)
static int pickArenaSide() {
    const int r = irand(100);
    if (r < 3) return 2 + irand(4);      // 2–5
    if (r < 10) return 6 + irand(4);     // 6–9
    if (r < 90) return 10 + irand(51);   // 10–60
    if (r < 95) return 61 + irand(19);   // 61–79
    return 80 + irand(21);               // 80–100
}
// основная связная часть арены: пешеход среднего роста по правилам движка (обрывы, лестницы, настилы); бой начинается в ней.
// Возвращает её размер (клеток земли)
int markMain(World& w) {
    static thread_local std::vector<int> comp, st;
    comp.assign((size_t)2 * W * W, -1);
    Fighter walker;
    walker.b.size = 2;
    int best = -1, bestN = 0, id = 0;
    for (int y = 0; y < w.ah; y++)
        for (int x = 0; x < w.aw; x++) {
            if (comp[(size_t)y * W + x] >= 0 || !nodeOK(w, walker, x, y, 0)) continue;
            int n = 0;
            st.assign(1, y * W + x);
            comp[(size_t)y * W + x] = id;
            while (!st.empty()) {
                const int c = st.back();
                st.pop_back();
                const int l = c / (W * W), cx = c % W, cy = (c % (W * W)) / W;
                if (!l) n++;
                for (int dy = -1; dy <= 1; dy++)
                    for (int dx = -1; dx <= 1; dx++)
                        for (int nl = 0; nl < 2; nl++) {
                            const int nx = cx + dx, ny = cy + dy, nn = ny * W + nx + nl * W * W;
                            if ((!dx && !dy) || !stepOK(w, walker, cx, cy, l, nx, ny, nl) || comp[(size_t)nn] >= 0) continue;
                            comp[(size_t)nn] = id;
                            st.push_back(nn);
                        }
            }
            if (n > bestN) { bestN = n; best = id; }
            id++;
        }
    std::memset(w.mainc, 0, sizeof w.mainc);
    for (int y = 0; y < w.ah; y++)
        for (int x = 0; x < w.aw; x++) w.mainc[y][x] = best >= 0 && comp[(size_t)y * W + x] == best;
    return bestN;
}
// клетка, где можно поставить бойца в начале боя: основная часть, не стена, яма, дерево, мост или дверь
static bool startCellOK(const World& w, int x, int y) {
    return !w.wall[y][x] && !w.pit[y][x] && !w.tree[y][x] && !w.deck[y][x] && !w.door[y][x] && w.mainc[y][x];
}
static int startCellsN(const World& w) {
    int n = 0;
    for (int y = 0; y < w.ah; y++)
        for (int x = 0; x < w.aw; x++) n += startCellOK(w, x, y);
    return n;
}
// мир боя: в игре — заданный (g_style.worldSeed), иначе — мир эпохи g_worldEpoch. Эпоху выставляет главный поток до запуска боёв
// (обучение — номер боя / 500, т. е. новый мир каждые 500 боёв; проверки — номер блока). Бой зависит только от зерна и эпохи,
// а не от того, сколько боёв поток сыграл до него. План мира кэшируется в каждом потоке.
long long g_worldEpoch = 0;
thread_local wg::Plan g_wplan;
inline unsigned long long worldSeedOfEpoch(long long e) {
    unsigned long long z = (unsigned long long)e * 0x9E3779B97F4A7C15ULL + 0xD1B54A32D192ED03ULL;
    z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ULL;
    z = (z ^ (z >> 27)) * 0x94D049BB133111EBULL;
    return (z ^ (z >> 31)) | 1;
}
void genMap(World& w) {
    std::memset(w.wall, 0, sizeof w.wall);
    std::memset(w.climb, 0, sizeof w.climb);
    std::memset(w.diff, 0, sizeof w.diff);
    std::memset(w.dark, 0, sizeof w.dark);
    std::memset(w.pit, 0, sizeof w.pit);
    std::memset(w.water, 0, sizeof w.water);
    std::memset(w.height, 0, sizeof w.height);
    std::memset(w.tree, 0, sizeof w.tree);
    std::memset(w.haz, 0, sizeof w.haz);
    std::memset(w.ladder, 0, sizeof w.ladder);
    std::memset(w.deck, 0, sizeof w.deck);
    std::memset(w.door, 0, sizeof w.door);
    std::memset(w.strong, 0, sizeof w.strong);
    unsigned long long ws;
    int wsz;
    if (g_style.worldSeed) {
        ws = g_style.worldSeed;
        wsz = std::clamp(g_style.worldSize, 1000, 10000);
    } else {
        ws = worldSeedOfEpoch(g_worldEpoch);
        wsz = 1000;
    }
    if (g_wplan.seed != ws || g_wplan.size != wsz) wg::buildPlan(g_wplan, ws, wsz);
    const wg::Plan& P = g_wplan;
    for (int tries = 0;; tries++) {
        w.aw = g_style.fixedW > 0 ? std::min(W, g_style.fixedW) : pickArenaSide();
        w.ah = g_style.fixedH > 0 ? std::min(W, g_style.fixedH) : pickArenaSide();
        w.aw = std::min(w.aw, wsz);
        w.ah = std::min(w.ah, wsz);
        int x0, y0;
        if (g_style.wx >= 0) {
            x0 = std::clamp(g_style.wx, 0, wsz - w.aw);
            y0 = std::clamp(g_style.wy, 0, wsz - w.ah);
        } else if (g_style.theme == 1 && !P.towns.empty()) {   // нужен город: участок у случайного поселения
            const wg::Settle& t = P.towns[(size_t)irand((int)P.towns.size())];
            x0 = std::clamp(t.x - w.aw / 2 + irand(std::max(1, t.r)) - t.r / 2, 0, wsz - w.aw);
            y0 = std::clamp(t.y - w.ah / 2 + irand(std::max(1, t.r)) - t.r / 2, 0, wsz - w.ah);
        } else {
            x0 = irand(wsz - w.aw + 1);
            y0 = irand(wsz - w.ah + 1);
        }
        int townN = 0;
        wg::fillLevelCache(P, x0, y0, w.aw, w.ah);
        for (int y = 0; y < W; y++)
            for (int x = 0; x < W; x++) {
                if (x >= w.aw || y >= w.ah) {   // за пределами арены — стена
                    w.wall[y][x] = true;
                    continue;
                }
                const wg::Cell c = wg::worldCell(P, x0 + x, y0 + y);
                w.wall[y][x] = c.wall;
                w.climb[y][x] = c.climb && !c.wall;
                w.water[y][x] = c.water;
                w.diff[y][x] = c.diff || c.water;
                w.dark[y][x] = c.dark;
                w.pit[y][x] = c.pit && !c.wall;
                w.height[y][x] = c.height;
                w.tree[y][x] = c.tree && !c.wall && !c.pit && !c.water;
                w.haz[y][x] = c.wall || c.pit ? 0 : c.haz;
                w.ladder[y][x] = c.ladder && !c.wall && !c.pit;
                w.deck[y][x] = !c.wall && c.deck > c.height ? c.deck : 0;
                w.door[y][x] = c.wall ? 0 : c.door;
                w.strong[y][x] = c.strong && c.wall;
                townN += c.town;
            }
        w.wseed = ws;
        w.wsize = wsz;
        w.wx = x0;
        w.wy = y0;
        w.theme = g_style.theme >= 0 ? g_style.theme : (townN * 4 >= w.aw * w.ah ? 1 : 0);   // тема «город» — четверть участка и больше
        const int mainN = markMain(w), startN = startCellsN(w);   // мест для расстановки должно быть хотя бы 2
        if (startN >= 2 && (mainN >= std::max(2, (int)(0.3 * w.aw * w.ah)) || g_style.wx >= 0 || tries >= 40)) break;
        if (tries >= 200) {   // совсем не вышло: пустая арена
            for (int y = 0; y < w.ah; y++)
                for (int x = 0; x < w.aw; x++) w.wall[y][x] = w.pit[y][x] = w.tree[y][x] = false, w.deck[y][x] = w.door[y][x] = 0, w.height[y][x] = 0;
            markMain(w);
            break;
        }
    }
}

// ---------------------------------------------------------------------------
// Погоня (DMG): бегущий (убегающий) и преследователь. Рывки без риска — 3 + мод. ТЕЛ за бой, дальше проверка ТЕЛ СЛ 10 или истощение; в конце каждого
// хода d20 (1–10 — осложнение для следующего участника); в конце раунда преследуемый проверяет ЛОВ (Скрытность) против пассивного МДР (Внимательность)
// преследователя: оторвался — сбежал, а сбежавший проигрывает. Провоцированных атак между участниками нет. Выход за арену — тоже побег.
// ---------------------------------------------------------------------------
thread_local long long g_chases = 0, g_escapes = 0, g_exhaustions = 0, g_complications = 0;
static bool chkBest(const Fighter& f, std::initializer_list<int> stats, int dc) {   // проверка характеристики (лучшая из перечисленных), помеха при истощении 1+
    int best = -99;
    for (int st : stats) best = std::max(best, f.mod(st));
    return d20(false, f.exh >= 1) + best >= dc;
}
static bool creatureHits(const Fighter& f, int bonus) {
    const int r = rollD20();
    return r == 20 || (r != 1 && r + bonus >= f.b.ac);
}
// Осложнение номер roll (1–10) действует на бойца f в начале его хода: город (theme 1) или дикая местность (0)
static const char* COMP_CITY[10] = {"Толпа на пути", "Рыночные лотки", "Скользкая мостовая", "Узкий проулок", "Груда ящиков", "Острый обломок", "Рухнувшие леса", "Встречный поток людей", "Городской страж", "Падающий хлам"};
static const char* COMP_WILD[10] = {"Густой кустарник", "Рытвины и коренья", "Рой насекомых", "Заросший склон", "Едкая пыльца", "Яма под листвой", "Силок", "Колючий бурелом", "Бритвенная лоза", "Местный зверь"};
// название осложнения по теме и броску к10 (бросок вне 1..10 прижимается к краю таблицы)
static const char* compName(int theme, int roll) {
    const int i = std::clamp(roll, 1, 10) - 1;
    return theme == 1 ? COMP_CITY[i] : COMP_WILD[i];
}
static void applyComplicationInner(World& w, Fighter& f, int roll);
// осложнение погони: применяет и пишет событие с итогом (для просмотрщика)
static void applyComplication(World& w, Fighter& f, int roll) {
    const int hp0 = f.hp, pen0 = f.speedPen, who = (int)(&f - &w.f[0]);
    const bool prone0 = f.cond[C_PRONE] > 0, restr0 = f.cond[C_RESTR] > 0, blind0 = f.cond[C_BLIND] > 0;
    applyComplicationInner(w, f, roll);
    std::string fx;
    auto add = [&](const std::string& t) { fx += (fx.empty() ? "" : ", ") + t; };
    if (f.hp < hp0) add("урон " + std::to_string(hp0 - f.hp));
    if (f.speedPen > pen0) add("скорость −" + std::to_string(f.speedPen - pen0) + " фт");
    if (!prone0 && f.cond[C_PRONE]) add("сбит с ног");
    if (!restr0 && f.cond[C_RESTR]) add("опутан");
    if (!blind0 && f.cond[C_BLIND]) add("ослеплён");
    if (fx.empty()) fx = "справился";
    evPush("{\"k\":\"comp\",\"who\":" + std::to_string(who) + ",\"roll\":" + std::to_string(roll) + ",\"t\":\"" + compName(w.theme, roll) + "\",\"fx\":\"" + fx + "\"}");
}
static void applyComplicationInner(World& w, Fighter& f, int roll) {
    g_complications++;
    auto prone = [&]() { if (f.hp > 0) applyCond(f, C_PRONE, 1, -1, 0, false); };
    auto dmg = [&](int n, int dieS, int type) { hurt(f, rollDice(n, dieS), type, false); };
    if (w.theme == 1) {
        switch (roll) {
            case 1: if (!chkBest(f, {DEX}, 15)) f.speedPen += 10; break;
            case 2: if (!chkBest(f, {STR, DEX}, 10)) f.speedPen += 10; break;
            case 3: if (!saveOK(f, STR, 10)) prone(); break;
            case 4: if (!chkBest(f, {DEX, INT}, 10)) f.speedPen += 10; break;
            case 5: if (!saveOK(f, DEX, 10)) prone(); break;
            case 6: if (!chkBest(f, {DEX}, 10)) { dmg(1, 4, DT_PIERCING); f.speedPen += 5; } break;
            case 7: if (!chkBest(f, {STR, DEX, CHA}, 15)) { dmg(2, 4, DT_BLUDGEONING); f.speedPen += 10; } break;
            case 8: if (!chkBest(f, {STR, DEX, CHA}, 10)) f.speedPen += 5; break;
            case 9: if (creatureHits(f, 3)) dmg(1, 6, DT_PIERCING), f.hp -= 1; break;   // страж: копьё +3, 1к6+1 колющего
            default: if (!saveOK(f, DEX, 10)) dmg(1, 4, DT_BLUDGEONING); break;
        }
    } else {
        switch (roll) {
            case 1: if (!chkBest(f, {STR, DEX}, 10)) f.speedPen += 5; break;
            case 2: if (!chkBest(f, {DEX}, 10)) f.speedPen += 10; break;
            case 3: if (creatureHits(f, 3)) dmg(4, 4, DT_PIERCING); break;   // рой насекомых
            case 4: if (!chkBest(f, {STR, DEX}, 10)) f.speedPen += 10; break;
            case 5: if (!saveOK(f, CON, 10)) { applyCond(f, C_BLIND, 1, -1, 0, false); f.speedPen += speedOf(f) / 2; } break;
            case 6:
                if (!saveOK(f, DEX, 10)) {   // яма: падение на 1к4×5 фт, по 1к6 за каждые 10 фт
                    const int fall = (1 + irand(4)) * 5;
                    if (fall >= 10) dmg(fall / 10, 6, DT_BLUDGEONING);
                    prone();
                }
                break;
            case 7: if (!saveOK(f, DEX, 15)) applyCond(f, C_RESTR, 2, STR, 12, true); break;   // силок: опутан
            case 8: if (!saveOK(f, DEX, 10)) { dmg(1, 4, DT_BLUDGEONING); dmg(1, 4, DT_PIERCING); prone(); } break;
            case 9: if (speedOf(f) >= 10) f.speedPen += 10; else if (!saveOK(f, DEX, 15)) dmg(1, 10, DT_SLASHING); break;   // бритвенная лоза: 10 фт движения или урон
            default: if (creatureHits(f, 3)) dmg(1, 8, DT_PIERCING), f.hp -= 1; break;   // местное существо кусает
        }
    }
}
// после хода босса i: начало и конец погони, рывки сверх нормы, осложнение для соперника; dist0 — расстояние между боссами до хода
static void chaseAfterTurn(World& w, int i, int dist0) {
    Fighter& me = w.f[i];
    Fighter& E = w.f[1 - i];
    if (me.hp <= 0 || E.hp <= 0 || me.fled) { me.dashedNow = false; return; }
    const int dist1 = distFt(me, E);
    const auto reachOf = [](const Fighter& f) { return f.b.wN > 0 && f.b.wRange <= 5 ? std::max(5, f.b.reach) : 5; };
    // побег — отход от реальной угрозы: враг мог бы достать за ход (досягаемость + рывок) или стреляет; обычное перемещение по большой арене погоней не считается
    const int threat = std::max(reachOf(E) + 2 * speedOf(E), E.b.wN > 0 && E.b.wRange > 5 ? E.b.wRange : 0);
    // v21, №13: «выглянуть, ударить, спрятаться» — не побег: кто в этот ход атаковал врага или применил по нему способность
    // либо остался там, где враг достанет его за свой ход (дойдёт и ударит или выстрелит), погоню не начинает
    const bool exposed = dist1 <= reachOf(E) + speedOf(E) || (E.b.wN > 0 && E.b.wRange > 5 && dist1 <= E.b.wRange);
    const bool flight = dist1 >= dist0 + 10 && dist1 > reachOf(E) && dist0 <= threat && !me.struckFoe && !exposed;   // отошёл на 10+ фт из-под угрозы и стоит вне досягаемости ближнего боя врага
    if (!w.chaseOn) {
        if (flight) {
            w.chaseOn = true;
            w.chasePrey = i;
            w.chaseSeen = true;
            g_chases++;
            evPush("{\"k\":\"chase\",\"prey\":" + std::to_string(i) + "}");
        }
    } else if (i == w.chasePrey) {
        if (dist1 + 10 <= dist0 || dist1 <= reachOf(E) || me.struckFoe) {   // преследуемый развернулся навстречу или напал: обычный бой
            w.chaseOn = false;
            evPush("{\"k\":\"chaseEnd\",\"why\":\"turned\"}");
        }
    } else if (dist1 <= reachOf(me)) {
        w.chaseOn = false;                                    // преследователь догнал
        evPush("{\"k\":\"chaseEnd\",\"why\":\"caught\"}");
    }
    if (w.chaseOn) {
        if (!losF(w, me, E)) w.chaseSeen = false;
        if (me.dashedNow) {
            me.dashes++;
            if (me.dashes > me.dashLimit && d20(false, me.exh >= 1) + me.mod(CON) < 10) {   // рывок сверх нормы: проверка ТЕЛ СЛ 10 или истощение
                me.exh = std::min(5, me.exh + 1);
                g_exhaustions++;
                evPush("{\"k\":\"exh\",\"who\":" + std::to_string(i) + ",\"lv\":" + std::to_string(me.exh) + "}");
                if (me.exh == 4) { me.maxHp = std::max(1, me.maxHp / 2); me.hp = std::min(me.hp, me.maxHp); }   // истощение 4: максимум ХП вдвое
            }
        }
        const int r = rollD20();
        if (r <= 10) E.comp = r;                              // осложнение действует на следующего участника
    }
    me.dashedNow = false;
}
// конец раунда погони: проверка ЛОВ (Скрытность) преследуемого против пассивного МДР (Внимательность) преследователя
static void chaseEndOfRound(World& w) {
    if (!w.chaseOn) return;
    Fighter& prey = w.f[w.chasePrey];
    Fighter& pu = w.f[1 - w.chasePrey];
    if (prey.hp <= 0 || pu.hp <= 0) return;
    const bool seen = w.chaseSeen;
    w.chaseSeen = true;
    if (pu.exh >= 5 && distFt(prey, pu) > std::max(5, pu.b.reach)) {   // преследователь выбился из сил (скорость 0) и выбыл из погони: преследуемый ушёл
        prey.fled = true;
        prey.fledWhy = 3;
        w.chaseOn = false;
        g_escapes++;
        evPush("{\"k\":\"fled\",\"who\":" + std::to_string(w.chasePrey) + ",\"why\":3}");
        return;
    }
    if (seen) return;   // не терял преследователя из виду: проверка проваливается сама
    int cover = 0;
    for (int dy = -6; dy <= 6; dy++)
        for (int dx = -6; dx <= 6; dx++) {
            const int x = prey.x + dx, y = prey.y + dy;
            if (x < 0 || y < 0 || x >= w.aw || y >= w.ah) continue;
            if (w.wall[y][x] || w.climb[y][x] || w.dark[y][x]) cover++;
        }
    const bool adv = cover >= 12 || w.dark[prey.y][prey.x], dis = cover <= 1 || prey.exh >= 1 || (prey.b.armStealth && prey.b.armor);   // доспех с помехой к Скрытности   // много/мало мест, где спрятаться
    if (d20(adv || skillAdv(prey, SK_STEALTH), dis) + prey.skill(SK_STEALTH) > 10 + pu.skill(SK_PERCEP) + (skillAdv(pu, SK_PERCEP) ? 5 : 0)) {   // преимущество к пассивной — +5   // Скрытность против пассивной Внимательности
        prey.fled = true;
        prey.fledWhy = 2;
        w.chaseOn = false;
        g_escapes++;
        evPush("{\"k\":\"fled\",\"who\":" + std::to_string(w.chasePrey) + ",\"why\":2}");
    }
}

static thread_local long long g_rounds = 0, g_capped = 0;
// 0 = победил A, 1 = победил B, 2 = ничья
std::string condListJson(const Fighter& f) {
    std::string s = "[";
    bool first = true;
    for (int k = 1; k < C_N; k++)
        if (f.cond[k] > 0) {
            if (!first) s += ",";
            s += "\"";
            s += CN[k];
            s += "\"";
            first = false;
        }
    s += "]";
    return s;
}
// чей туман войны показывать в реплее (−1 — ничей): реплей боя сети помечает врагов, которых её сторона не знает
thread_local int g_fogTeam = -1;
// hid — боец скрыт туманом войны от стороны игрока (или g_fogTeam): игроку не рисуется, в реплее — полупрозрачный
std::string fighterJson(const Fighter& f, int kind, bool hid = false) {
    char buf[500];
    std::snprintf(buf, sizeof buf,
                  "{\"x\":%d,\"y\":%d,\"hp\":%d,\"maxHp\":%d,\"ac\":%d,\"team\":%d,\"kind\":%d,\"temp\":%d,\"exh\":%d,"
                  "\"dash\":%d,\"dashLim\":%d,\"spd\":%d,\"fled\":%d,\"cond\":%s%s%s}",
                  f.x, f.y, f.hp, f.maxHp, f.b.ac + (f.acBuffRounds > 0 ? f.acBuff : 0), f.team, kind, f.temp, f.exh, f.dashes, f.dashLimit,
                  speedOf(f), f.fled ? f.fledWhy : 0, condListJson(f).c_str(), hid ? ",\"hid\":1" : "", f.up ? ",\"up\":1" : "");
    if (fpN(f) > 1 || f.alt > 0) {   // крупный: квадрат n×n от (x, y); летун: высота (уровни по 10 фт)
        std::string r = buf;
        if (fpN(f) > 1) r.insert(r.size() - 1, ",\"n\":" + std::to_string(fpN(f)));
        if (f.alt > 0) r.insert(r.size() - 1, ",\"alt\":" + std::to_string(f.alt));
        return r;
    }
    return buf;
}
// Легендарное действие: в конце хода ДРУГОГО существа, один вариант, пока хватает очков; очки возвращаются в начале
// своего хода. Варианты: 1 очко — одна атака оружием; 2 очка — полное действие Атака (все атаки); 1 очко — Движение на
// половину скорости без провокации.
bool legendaryTurn(World& w, int j) {
    Fighter& me = w.f[j];
    if (me.hp <= 0 || me.b.legAct <= 0 || me.legLeft <= 0 || over(w)) return false;
    // недееспособный не может
    if (me.cond[C_STUN] || me.cond[C_PARAL] || me.cond[C_INCAP]) return false;
    int focus = -1;
    double bd = 1e9;
    for (size_t e = 0; e < w.f.size(); e++) {
        const Fighter& g = w.f[e];
        if (g.hp <= 0 || g.team == me.team || !isKnown(w, me.team, (int)e)) continue;   // туман войны
        if (me.cond[C_CHARM] > 0 && me.charmSrc == (int)e) continue;
        double d = distFt(me, g) - ((int)e < w.nLead ? me.pol->v[PO_FOCUSFT] : 0);
        if (d < bd) {
            bd = d;
            focus = (int)e;
        }
    }
    if (focus < 0) return false;
    int tIdx = me.b.wN > 0 ? nearestEnemyInRange(w, me, atkDist(me.b)) : -1;   // безоружный: только движение
    g_act = ActInfo{};
    if (tIdx >= 0) {
        me.riderUsed = false;
        me.onceUsed = 0;
        // полное действие Атака стоит 2, одна атака — 1
        bool full = me.legLeft >= 2 && me.b.wAtt >= 2;
        doWeapon(w, me, tIdx, full ? -1 : 1);
        me.legLeft -= full ? 2 : 1;
        g_legUsed++;
        return true;
    }
    // Движение: подойти на половину скорости, без провоцированных атак
    if (!me.cond[C_FRIGHT] && !me.cond[C_RESTR]) {
        Fighter& F = w.f[focus];
        bool d0 = me.disengaged;
        me.disengaged = true;
        int used = moveToward(w, me, F, atkDist(me.b), speedOf(me) / 2, true);
        me.disengaged = d0;
        if (used > 0) {
            g_act.type = "legendary-move";
            g_act.target = focus;
            me.legLeft -= 1;
            g_legUsed++;
            return true;
        }
    }
    return false;
}

#include "human_turn.h"
#include "prim_net.h"   // v21: сеть-боец на примитивах и карте (№4, №5)
#include "custom_map.h"
// сведения о последнем бое для просмотрщика
struct FightInfo {
    bool ctrl[2] = {false, false};   // боссом управляет нейросеть
    int rounds = 0, result = 2, reason = 0;   // reason: 0 ничья, 1 победа убийством, 2 враг вышел за арену, 3 враг оторвался, 4 враг выбился из сил
    int aw = 0, ah = 0, theme = 0;
};
thread_local FightInfo g_fightInfo;
// Действия логова (DMG, v21): в начале раунда (инициатива 20) главный босс с логовом действует логовом — без действия и
// реакции, одно и то же два раунда подряд нельзя. Центр — известный враг, рядом с которым больше всего врагов (поровну —
// у кого меньше доля хитов). Обвал: в 10 фт от центра каждый враг — спасбросок ЛОВ против СЛ босса, провал — уровень×2к10
// дробящего, успех — половина (Увёртливость действует). Трясина: клетки в 10 фт от центра — труднопроходимая местность.
void lairAction(World& w, int i) {
    Fighter& me = w.f[i];
    if (me.hp <= 0 || me.b.lair <= 0 || me.cond[C_STUN] || me.cond[C_PARAL] || me.cond[C_INCAP] || me.supp > 0) return;
    int best = -1, bn = -1;
    double bf = 2;
    for (size_t e = 0; e < w.f.size(); e++) {
        const Fighter& t = w.f[e];
        if (t.hp <= 0 || t.team == me.team || !isKnown(w, me.team, (int)e)) continue;
        int n = 0;
        for (auto& u : w.f)
            if (u.hp > 0 && u.team != me.team && distFt(t, u) <= 10) n++;
        const double fr = (double)t.hp / std::max(1, t.maxHp);
        if (n > bn || (n == bn && fr < bf)) best = (int)e, bn = n, bf = fr;
    }
    if (best < 0) return;
    const int cx = w.f[best].x, cy = w.f[best].y, kind = me.lairLast == 1 ? 2 : 1;
    me.lairLast = kind;
    evPush("{\"k\":\"lair\",\"who\":" + std::to_string(i) + ",\"kind\":" + std::to_string(kind) + ",\"x\":" + std::to_string(cx) + ",\"y\":" + std::to_string(cy) + "}");
    if (kind == 2) {
        for (int y = cy - 2; y <= cy + 2; y++)
            for (int x = cx - 2; x <= cx + 2; x++)
                if (x >= 0 && y >= 0 && x < w.aw && y < w.ah && !w.wall[y][x] && !w.diff[y][x]) {
                    w.diff[y][x] = true, w.mapVer = ++g_mapSerial;
                    dynAdd(w, x, y, 2, -1);
                }
        return;
    }
    const int src0 = g_srcIdx;
    g_srcIdx = i;
    for (auto& t : w.f) {
        if (t.hp <= 0 || t.team == me.team) continue;
        if (std::max(fpGap(t.x, fpN(t), cx, 1), fpGap(t.y, fpN(t), cy, 1)) > 2 || 10 * t.alt > 10) continue;
        int dmg = rollDice(2 * me.b.lair, 10);
        const bool ok = saveOK(t, DEX, me.dc()), evade = t.b.evasion && !t.cond[C_STUN] && !t.cond[C_PARAL];
        if (ok || evade) dmg = ok && evade ? 0 : dmg / 2;
        hurt(t, dmg, DT_BLUDGEONING, true);
    }
    g_srcIdx = src0;
}
// Состав боя (v21, команды): главные бойцы и их команды. Два бойца из команд 0 и 1 — прежний бой «один на один» (бит в бит);
// иначе — бой нескольких команд: победа — последняя команда в строю, на пределе раундов — по очкам (доля хитов команды +
// убитые враги), равные очки — ничья (−1). Результат многокомандного боя — номер команды или −1.
struct RosterEntry {
    const Boss* b;
    int team;
};
// расстановка нескольких команд: опорная точка каждой команды — как можно дальше от уже выбранных (из 300 случайных мест
// для расстановки), бойцы команды — вокруг своей опоры, квадрат целиком на местах для расстановки и не на других
void placeTeams(const World& w, const std::vector<RosterEntry>& R, std::vector<int>& px, std::vector<int>& py) {
    const int N = (int)R.size();
    std::vector<std::array<int, 3>> placed;   // x, y, сторона квадрата
    std::vector<std::pair<int, int>> anchor(MAXT, {-1, -1});
    auto nOf = [](const Boss* b) { return b->size <= 2 ? 1 : b->size - 1; };
    auto randStart = [&]() {
        int x, y;
        do {
            x = irand(w.aw);
            y = irand(w.ah);
        } while (!startCellOK(w, x, y));
        return std::make_pair(x, y);
    };
    std::vector<std::pair<int, int>> used;
    for (int i = 0; i < N; i++) {
        const int t = R[i].team;
        if (anchor[t].first >= 0) continue;
        std::pair<int, int> best = randStart();
        int bd = -1;
        for (int k = 0; k < 300 && !used.empty(); k++) {
            const auto c = randStart();
            int d = 1 << 30;
            for (auto& u : used) d = std::min(d, std::max(std::abs(u.first - c.first), std::abs(u.second - c.second)));
            if (d > bd) bd = d, best = c;
        }
        anchor[t] = best;
        used.push_back(best);
    }
    for (int i = 0; i < N; i++) {
        const int n = nOf(R[i].b), ax = anchor[R[i].team].first, ay = anchor[R[i].team].second;
        auto fit = [&](int x, int y) {
            for (int dy = 0; dy < n; dy++)
                for (int dx = 0; dx < n; dx++)
                    if (x + dx >= w.aw || y + dy >= w.ah || x + dx < 0 || y + dy < 0 || !startCellOK(w, x + dx, y + dy)) return false;
            for (auto& p : placed)
                if (fpOverlap(p[0], p[1], p[2], x, y, n)) return false;
            return true;
        };
        bool ok = false;
        for (int r = 0; r < 40 && !ok; r++)
            for (int dy = -r; dy <= r && !ok; dy++)
                for (int dx = -r; dx <= r && !ok; dx++)
                    if (std::max(std::abs(dx), std::abs(dy)) == r && fit(ax + dx, ay + dy)) px[i] = ax + dx, py[i] = ay + dy, ok = true;
        for (int k = 0; k < 4000 && !ok; k++) {
            const auto c = randStart();
            if (fit(c.first, c.second)) px[i] = c.first, py[i] = c.second, ok = true;
        }
        if (!ok) {   // негде — в любое место для расстановки (ход раздвинет)
            const auto c = randStart();
            px[i] = c.first;
            py[i] = c.second;
        }
        placed.push_back({px[i], py[i], n});
    }
}
thread_local double g_teamScore[MAXT];   // очки команд последнего многокомандного боя
int fightRoster(const std::vector<RosterEntry>& R, std::vector<std::string>* log, std::string* mapJsonOut, const Pol* polA, const Pol* polB) {
    const int N = (int)R.size();
    int nT = 0;
    for (auto& e : R) nT = std::max(nT, e.team + 1);
    nT = std::min(nT, MAXT);
    const bool duel = N == 2 && R[0].team == 0 && R[1].team == 1 && !g_human.multi;   // комната — всегда по правилам команд
    const Boss& A = *R[0].b;
    const Boss& B = *R[std::min(1, N - 1)].b;
    AutoNet autoNet(A, B);   // бойцы с ИНТ >= 12 ходят по сети, если она загружена
    for (auto& u : g_use)
        for (auto& x : u) x = 0;
    for (auto& u : g_castAtom)
        for (auto& x : u) x = 0;
    static thread_local World w;
    g_curW = &w;   // ауры союзников (v21): мир текущего боя; после боя — снова nullptr
    struct CurWReset { ~CurWReset() { g_curW = nullptr; } } curWReset;
    w.f.clear();
    w.nLead = N;
    w.nTeams = nT;
    for (int t = 0; t < MAXT; t++) w.kills[t] = 0;
    w.f.reserve(N + (size_t)N * std::max(0, limits().sumFightBoss));   // все приспешники под потолком: ссылки на бойцов не ломаются
    if (g_customMap.on) applyCustomMap(w, g_customMap);   // карта игрока
    else genMap(w);
    if (g_customMap.on) markMain(w);   // карта игрока проверена на связность — основная часть вся
    initObjects(w);   // хиты стен, деревьев, укрытий, дверей
    w.day = g_customMap.on || irand(100) < 60;   // день или ночь (солнечная чувствительность); карта игрока — днём
    {   // сила опасных зон — по боссам боя: около 15% среднего запаса хитов за срабатывание, СЛ растёт с ним
        double avgHp = 0;
        for (auto& e : R) avgHp += e.b->hp / (double)N;
        w.hazN = std::max(1, (int)std::lround(0.15 * avgHp / 5.5));
        w.hazDC = std::clamp(11 + (int)(avgHp / 60), 11, 20);
    }
    w.dyn.clear();
    for (int t = 0; t < MAXT; t++) w.cmd[t] = -1;
    w.chaseOn = false;
    w.chaseSeen = true;
    w.chasePrey = -1;
    if (mapJsonOut) *mapJsonOut = mapToJson(w);
    const Boss* src[2] = {&A, &B};
    std::vector<int> px(N), py(N);
    if (duel) {
    // начальная расстановка: случайные свободные клетки, по возможности не ближе min(30 клеток, половина длинной стороны арены) друг от друга
        const int minStart = std::min(30, std::max(1, std::max(w.aw, w.ah) / 2));
        for (int tries = 0;; tries++) {
            if (g_customMap.on && g_customMap.hasStarts()) {   // начальные клетки заданы картой
                for (int i = 0; i < 2; i++) { px[i] = g_customMap.start[i][0]; py[i] = g_customMap.start[i][1]; }
                break;
            }
            if (tries == 0 && startCellsN(w) == 0) {   // мест нет (участок мира у заданной точки, карта игрока): пустая арена
                for (int y = 0; y < w.ah; y++)
                    for (int x = 0; x < w.aw; x++) w.wall[y][x] = w.pit[y][x] = w.tree[y][x] = false, w.deck[y][x] = w.door[y][x] = 0, w.height[y][x] = 0;
                markMain(w);
                initObjects(w);
            }
            for (int i = 0; i < 2; i++) {   // квадрат бойца (по размеру) целиком на местах для расстановки, не на сопернике
                const int n = src[i]->size <= 2 ? 1 : src[i]->size - 1;
                auto fit = [&](int x, int y) {
                    for (int dy = 0; dy < n; dy++)
                        for (int dx = 0; dx < n; dx++)
                            if (x + dx >= w.aw || y + dy >= w.ah || !startCellOK(w, x + dx, y + dy)) return false;
                    if (i == 1) {
                        const int n0 = src[0]->size <= 2 ? 1 : src[0]->size - 1;
                        if (fpOverlap(px[0], py[0], n0, x, y, n)) return false;
                    }
                    return true;
                };
                bool ok = false;
                for (int k = 0; k < 400 && !ok; k++) {
                    px[i] = irand(w.aw);
                    py[i] = irand(w.ah);
                    ok = fit(px[i], py[i]);
                }
                const int off = irand(w.aw * w.ah);
                for (int k = 0; k < w.aw * w.ah && !ok; k++) {   // случайно не нашлось — первое подходящее с случайного места
                    const int c = (k + off) % (w.aw * w.ah);
                    px[i] = c % w.aw;
                    py[i] = c / w.aw;
                    ok = fit(px[i], py[i]);
                }
                if (!ok)   // квадрат не помещается нигде: ставим в место для расстановки, ход раздвинет (nudge)
                    do {
                        px[i] = irand(w.aw);
                        py[i] = irand(w.ah);
                    } while (!startCellOK(w, px[i], py[i]));
            }
            if (std::max(std::abs(px[0] - px[1]), std::abs(py[0] - py[1])) >= minStart || tries > 50) break;
        }
    } else
        placeTeams(w, R, px, py);
    for (int i = 0; i < N; i++) {
        Fighter f;
        f.b = *R[i].b;
        f.team = R[i].team;
        f.pol = duel ? (i == 0 ? (polA ? polA : &g_pol) : (polB ? polB : &g_pol)) : &g_pol;
        f.rl = duel && (g_rlTeam[i] || autoNet.controls(i));
        f.hp = f.maxHp = f.b.hp;
        f.x = px[i];
        f.y = py[i];
        f.init = (rollD20() + f.mod(DEX)) * 100 + irand(100);
        f.uses.assign(f.b.abil.size(), 0);
        f.usedRound.assign(f.b.abil.size(), -10);
        f.poolLeft = f.b.poolN;
        f.trigLeft.clear();   // «событие → эффект» (v21): применений за бой; +инициатива — сразу
        for (auto& t : f.b.trigs) {
            f.trigLeft.push_back(t.uses);
            if (t.on == T_INIT && t.what == X_INITB) f.init += 100 * t.n;
        }
        f.lrLeft = f.b.legRes;
        f.legLeft = f.b.legAct;
        f.surgeLeft = f.b.surge;
        f.dashLimit = std::max(0, 3 + f.mod(CON));   // рывки в погоне без риска: 3 + мод. ТЕЛ
        f.ai.seed(rng.next());
        for (int L = 1; L < 10; L++) f.slotLeft[L] = f.b.slots[L];
        for (size_t k = 0; k < f.b.abil.size(); k++) f.uses[k] = f.b.abil[k].recharge && !(f.b.abil[k].rechAfter && f.b.abil[k].uses < UNL) ? 1 : f.b.abil[k].uses;
        w.f.push_back(f);
    }
    for (auto& f : w.f) fireTrig(w, f, T_INIT, nullptr);   // «событие → эффект» (v21): в начале боя
    // «действует с начала боя» (пакет атомов 1): заранее наложенные способности на себя срабатывают до первого хода,
    // без действия; применение и ячейка тратятся как обычно. Раунд — уже 0: иначе отметка «применено в раунде» бралась
    // из прошлого боя потока («не два раунда подряд» зависела от того, какой бой поток считал перед этим)
    g_curRound = 0;
    {
        const World* cw0 = g_curW;
        g_curW = &w;
        for (int i = 0; i < (int)w.f.size(); i++)
            for (int k = 0; k < (int)w.f[i].b.abil.size(); k++) {
                const Spec& s = w.f[i].b.abil[k];
                if (!s.preCast || !s.self || s.react || !resReady(w.f[i], specAbility(w.f[i].b, k).cost)) continue;
                doSpec(w, w.f[i], k, i);
            }
        g_curW = cw0;
    }
    // туман войны: в начале боя стороны знают, где стоит противник (бой начался), дальше — только то, что видят
    g_curRound = 0;
    for (int t = 0; t < MAXT; t++) {
        w.known[t].assign(t < nT ? w.f.size() : 0, {-1, -1, -1});
        w.knownRound[t] = 0;
    }
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            if (w.f[i].team != w.f[j].team) revealTo(w, w.f[i].team, j);
    g_evPending.clear();
    g_evLog = log != nullptr;
    if (g_evLog) {   // порядок ходов для показа: [боец, итог броска инициативы]
        std::vector<int> ord(N);
        for (int i = 0; i < N; i++) ord[i] = i;
        std::sort(ord.begin(), ord.end(), [&](int x, int y) { return w.f[x].init > w.f[y].init; });
        std::string o = "{\"k\":\"init\",\"order\":[";
        for (int k = 0; k < N; k++) o += (k ? "," : "") + std::string("[") + std::to_string(ord[k]) + "," + std::to_string(w.f[ord[k]].init / 100) + "]";
        evPush(o + "]}");
    }
    g_fightInfo = FightInfo{};
    g_fightInfo.ctrl[0] = w.f[0].rl;
    g_fightInfo.ctrl[1] = w.f[1].rl;
    g_fightInfo.aw = w.aw;
    g_fightInfo.ah = w.ah;
    g_fightInfo.theme = w.theme;
    // кадр для просмотрщика: состояние после действия участника actor
    auto emitFrame = [&](int round, int actor, int legendary) {
        if (!log) {
            g_evPending.clear();
            g_netDec.valid = false;
            return;
        }
        std::string fr = "{\"round\":" + std::to_string(round) + ",\"actor\":" + std::to_string(actor) + ",\"act\":\"" +
                         (actor >= 0 ? g_act.type : std::string("none")) + "\",\"target\":" + std::to_string(actor >= 0 ? g_act.target : -1) +
                         ",\"abil\":" + std::to_string(actor >= 0 ? g_act.abil : -1) + (legendary ? ",\"legendary\":1" : "") +
                         ",\"chase\":" + std::to_string(w.chaseOn ? 1 : 0) + ",\"prey\":" + std::to_string(w.chasePrey) + ",\"ev\":[";
        for (size_t k = 0; k < g_evPending.size(); k++) fr += (k ? "," : "") + g_evPending[k];
        fr += "]";
        if (actor >= 0 && g_act.gx >= 0) fr += ",\"cell\":[" + std::to_string(g_act.gx) + "," + std::to_string(g_act.gy) + "]";
        if (!w.dyn.empty()) {
            fr += ",\"dyn\":[";
            for (size_t k = 0; k < w.dyn.size(); k++) fr += (k ? "," : "") + std::string("[") + std::to_string(w.dyn[k][0]) + "," + std::to_string(w.dyn[k][1]) + "," + std::to_string(w.dyn[k][2]) + "]";
            fr += "]";
        }
        if (g_netDec.valid) fr += ",\"net\":{\"st\":" + std::to_string(g_netDec.st) + ",\"tg\":" + std::to_string(g_netDec.tg) + ",\"pf\":" + std::to_string(g_netDec.pf) + "}";
        g_netDec.valid = false;
        fr += ",\"f\":[";
        g_evPending.clear();
        for (size_t k = 0; k < w.f.size(); k++) {
            if (k) fr += ",";
            const int ht = g_human.ask && g_human.idx >= 0 && g_human.idx < (int)w.f.size() ? w.f[g_human.idx].team : g_fogTeam;
            const int kind = duel ? ((int)k < 2 ? (int)k : 2 + w.f[k].team) : ((int)k < N ? w.f[k].team % 2 : 2 + w.f[k].team % 2);   // команды: цвет — по team
            std::string fj = fighterJson(w.f[k], kind, !g_human.multi && ht >= 0 && w.f[k].team != ht && !isKnown(w, ht, (int)k));
            if (!duel) fj.insert(fj.size() - 1, ",\"lead\":" + std::to_string((int)k < N ? (int)k : w.f[k].summoner) + ",\"ld\":" + ((int)k < N ? "1" : "0"));   // команды: чей это боец
            fr += fj;
        }
        fr += "]}";
        log->push_back(fr);
    };
    g_act = ActInfo{};
    emitFrame(0, -1, 0);
    g_human.emit = emitFrame;   // игрок пишет кадры после каждой своей команды
    int rr = 0;
    for (int r = 0; r < g_maxRounds && !over(w); r++) {
        rr = r + 1;
        g_curRound = rr;
        for (int t = 0; t < nT; t++)   // предохранитель тумана: 5 раундов не знает ни одного врага — слышит, где они
            if (rr - w.knownRound[t] >= 5)
                for (size_t k = 0; k < w.f.size(); k++)
                    if (w.f[k].hp > 0 && w.f[k].team != t) revealTo(w, t, (int)k);
        std::vector<int> order;
        for (size_t i = 0; i < w.f.size(); i++)
            if (w.f[i].hp > 0 && !w.f[i].fresh) order.push_back((int)i);
        std::sort(order.begin(), order.end(), [&](int a, int b) { return w.f[a].init > w.f[b].init; });
        for (int i = 0; i < N && !over(w); i++) lairAction(w, i);   // логово — на инициативе 20, до всех
        for (int i : order) {
            if (over(w)) break;
            const int dist0 = duel && i < 2 ? distFt(w.f[i], w.f[1 - i]) : 0;
            if (duel && i < 2 && w.f[i].comp) {   // осложнение погони, выпавшее предыдущему участнику, достаётся этому
                if (w.chaseOn) applyComplication(w, w.f[i], w.f[i].comp);
                w.f[i].comp = 0;
            }
            w.f[i].inTurn = true;
            updateKnown(w, w.f[i].team);   // что сторона видит к началу хода бойца
            g_srcIdx = i;   // урон в этот ход наносит боец i (для реакции «мне нанесли урон»)
            // ход бойца; остановка времени (пакет атомов 2) — ещё ходы подряд, пока враги стоят
            for (int rep = 0; rep < 12; rep++) {
                if (g_primLog && i == g_primLog->who) {
                    if (g_primLog->replay) {
                        static const std::vector<Prim> none;
                        replayTurn(w, i, g_primLog->next < g_primLog->turns.size() ? g_primLog->turns[g_primLog->next++] : none);
                    } else {
                        g_primLog->turns.emplace_back();
                        g_rec = &g_primLog->turns.back();
                        g_recIdx = i;
                        takeTurn(w, i);
                        g_rec = nullptr;
                        g_recIdx = -1;
                    }
                } else if (g_human.ask && humanSeat(w, i) >= 0)   // игрок — и свои приспешники
                    humanTurn(w, i);
                else if (w.f[i].rl && pn::g_pctx)
                    pn::netTurnP(w, i);
                else if (g_rlTurn && w.f[i].rl)
                    g_rlTurn(w, i);
                else
                    takeTurn(w, i);
                if (w.f[i].extraTurns <= 0 || w.f[i].hp <= 0 || over(w)) break;
                w.f[i].extraTurns--;
                emitFrame(r + 1, i, 0);
            }
            w.f[i].extraTurns = 0;
            w.f[i].inTurn = false;
            if (duel && i < 2) {
                chaseAfterTurn(w, i, dist0);
                w.f[i].speedPen = 0;
            }
            resolveReactions(w);
            g_srcIdx = -1;
            resolveConc(w);
            emitFrame(r + 1, i, 0);
            // легендарные действия противников — в конце этого хода
            for (size_t j = 0; j < w.f.size() && !over(w); j++) {
                if (w.f[j].team == w.f[i].team || w.f[j].hp <= 0 || w.f[j].b.legAct <= 0) continue;
                g_srcIdx = (int)j;
                bool lgd = legendaryTurn(w, (int)j);
                resolveReactions(w);
                g_srcIdx = -1;
                resolveConc(w);
                if (lgd) emitFrame(r + 1, (int)j, 1);
                else g_evPending.clear();
            }
        }
        if (duel) chaseEndOfRound(w);
        expireDyn(w);
        if (!g_evPending.empty()) {   // события конца раунда (отрыв от погони)
            g_act = ActInfo{};
            emitFrame(r + 1, -1, 0);
        }
        for (auto& f : w.f) f.fresh = false;
    }
    g_human.emit = nullptr;
    g_rounds += rr;
    g_lastHp[0] = (double)w.f[0].hp / std::max(1, w.f[0].maxHp);
    g_lastHp[1] = (double)w.f[1].hp / std::max(1, w.f[1].maxHp);
    g_fightInfo.rounds = rr;
    auto finish = [&](int res, int reason) {
        g_fightInfo.result = res;
        g_fightInfo.reason = reason;
        return res;
    };
    if (!duel) {   // несколько команд: последняя в строю; иначе — очки
        int last = -1, in = 0;
        for (int t = 0; t < nT; t++)
            if (teamIn(w, t)) in++, last = t;
        for (int t = 0; t < nT; t++) {
            double hp = 0, mx = 0;
            for (auto& f : w.f)
                if (f.team == t) hp += std::max(0, f.hp), mx += std::max(1, f.maxHp);
            g_teamScore[t] = (mx > 0 ? hp / mx : 0) + w.kills[t];
        }
        if (in == 1) return finish(last, 1);
        if (in == 0) return finish(-1, 0);
        g_capped++;
        int best = -1;
        double bs = -1;
        bool tie = false;
        for (int t = 0; t < nT; t++) {
            if (!teamIn(w, t)) continue;
            if (g_teamScore[t] > bs + 1e-9) best = t, bs = g_teamScore[t], tie = false;
            else if (std::fabs(g_teamScore[t] - bs) <= 1e-9) tie = true;
        }
        return finish(tie ? -1 : best, 5);   // 5 — по очкам на пределе раундов
    }
    // сбежавший (вышел за арену или оторвался от преследователя) проигрывает
    if (w.f[0].fled && !w.f[1].fled && w.f[1].hp > 0) return finish(1, w.f[0].fledWhy == 1 ? 2 : (w.f[0].fledWhy == 3 ? 4 : 3));
    if (w.f[1].fled && !w.f[0].fled && w.f[0].hp > 0) return finish(0, w.f[1].fledWhy == 1 ? 2 : (w.f[1].fledWhy == 3 ? 4 : 3));
    bool a = w.f[0].hp > 0, b = w.f[1].hp > 0;
    if (a && b) g_capped++;
    if (a && !b) return finish(0, 1);
    if (b && !a) return finish(1, 1);
    return finish(2, 0);   // оба живы после предохранителя: ничья
}
int fight(const Boss& A, const Boss& B, std::vector<std::string>* log = nullptr, std::string* mapJsonOut = nullptr,
          const Pol* polA = nullptr, const Pol* polB = nullptr) {
    return fightRoster({{&A, 0}, {&B, 1}}, log, mapJsonOut, polA, polB);
}

const char* CTN[14] = {"аберрация", "зверь", "небожитель", "конструкт", "дракон", "элементаль", "фея", "исчадие", "великан", "гуманоид", "монстр", "слизь", "растение", "нежить"};
// кости хитов (Бестиарий): кость по размеру (к4 крошечный … к20 громадный), хиты ≈ N × (средняя кость + мод. ТЕЛ)
std::string hitDiceText(const Boss& b) {
    static const int HD[6] = {4, 6, 8, 10, 12, 20};
    const int d = HD[std::clamp(b.size, 0, 5)], con = modOf(b.stats[CON]);
    const double per = std::max(1.0, (d + 1) / 2.0 + con);
    const int n = std::max(1, (int)std::lround(b.hp / per)), rest = b.hp - (int)std::lround(n * (d + 1) / 2.0);
    return std::to_string(n) + "к" + std::to_string(d) + (rest > 0 ? " + " + std::to_string(rest) : (rest < 0 ? " − " + std::to_string(-rest) : ""));
}
std::string describeBoss(const Boss& b) {
    char buf[400];
    std::string r;
    r += std::string("  ") + CTN[std::clamp(b.ctype, 0, 13)] + ", кости хитов " + hitDiceText(b) + "\n";
    std::snprintf(buf, sizeof buf, "  Статы:");
    r += buf;
    for (int i = 0; i < STAT_N; i++) {
        std::snprintf(buf, sizeof buf, " %s %d", SN[i], b.stats[i]);
        r += buf;
    }
    std::snprintf(buf, sizeof buf, " | %s | КД %d (%s%s) | ХП %d | главная: %s | стоимость %lld\n", SZN[std::clamp(b.size, 0, 5)], b.ac, ARN[std::clamp(b.armor, 0, AR_N - 1)], b.shield ? ", щит" : "", b.hp, SN[b.mainStat],
                  b.cost);
    r += buf;
    if (b.wN > 0) {
        std::snprintf(buf, sizeof buf, "  Оружие%s: %dк%d, дальн. %d фт, атак за действие: %d%s (%lld очк.)\n",
                      b.wNatural ? " (естественное)" : "", b.wN, b.wS, b.wRange, b.wAtt,
                      b.wRange > 5 ? (b.wAmmo ? ", боеприпасное (ЛОВ)"
                                              : (b.wFinesse ? ", метательное фехтовальное" : ", метательное (СИЛ)"))
                                   : (b.wFinesse ? ", фехтовальное" : ""),
                      b.wcost);
        r += buf;
        if (b.truesight) r += "  Истинное зрение " + std::to_string(b.truesight) + " фт\n";
        if (b.wLight || b.wLong || b.poolN || b.wTwoH || b.wVers || b.wHeavy) {   // оружие и Зуро (v21)
            r += "  Свойства:";
            if (b.wTwoH) r += " двуручное;";
            if (b.wHeavy) r += " тяжёлое;";
            if (b.wVers) r += " универсальное (двумя руками к" + std::to_string(b.wVers) + ");";
            if (b.wLight) r += " лёгкое;";
            if (b.wLong) r += " дальняя дистанция до " + std::to_string(b.wLong) + " фт (с помехой);";
            if (b.poolN) r += " запас костей " + std::to_string(b.poolN) + "к" + std::to_string(b.poolS) + ";";
            r += "\n";
        }
    } else
        r += "  Оружие: безоружный\n";
    if (b.wN > 0 && b.wRange <= 5 && b.reach > 5) {
        std::snprintf(buf, sizeof buf, "  Досягаемость: %d фт\n", b.reach);
        r += buf;
    }
    if (b.rN > 0 || b.rCond > 0) {
        r += "  Довесок к удару (раз в ход):";
        if (b.rN > 0) {
            std::snprintf(buf, sizeof buf, " +%dк%d (%s)", b.rN, b.rS, DTN[b.rType]);
            r += buf;
        }
        if (b.rCond > 0) {
            std::snprintf(buf, sizeof buf, " + %s на %d р. (спасбросок %s)", CN[b.rCond], b.rRounds,
                          b.rCond == C_GRAPPLE ? "—" : SN[condSaveStat(b.rCond)]);
            r += buf;
        }
        std::snprintf(buf, sizeof buf, " (%lld очк.)\n", b.rcost);
        r += buf;
    }
    if (b.auraRad > 0) {
        r += "  Аура (всегда включена):";
        if (b.auraN > 0) {
            std::snprintf(buf, sizeof buf, " %dк%d (%s)", b.auraN, b.auraS, DTN[b.auraType]);
            r += buf;
        }
        if (b.auraCond > 0) {
            std::snprintf(buf, sizeof buf, " + %s на %d р. (спасбросок %s)", CN[b.auraCond], b.auraRounds,
                          b.auraCond == C_GRAPPLE ? "—" : SN[condSaveStat(b.auraCond)]);
            r += buf;
        }
        std::snprintf(buf, sizeof buf, ", радиус %d фт\n", b.auraRad);
        r += buf;
    }
    {
        bool any = false;
        for (int L = 1; L < 10; L++)
            if (b.slots[L]) any = true;
        if (any) {
            r += "  Ячейки заклинаний:";
            for (int L = 1; L < 10; L++)
                if (b.slots[L]) {
                    std::snprintf(buf, sizeof buf, " %d ур. ×%d;", L, b.slots[L]);
                    r += buf;
                }
            r += "\n";
        }
    }
    for (auto& rl : b.rules) r += "  Правило: " + describeRule(rl) + "\n";
    for (auto& tg : b.trigs) r += "  Событие: " + describeTrig(tg) + "\n";
    if (b.riposte || b.surge) {
        r += "  Реакции:";
        if (b.riposte) r += " контратака (реакция);";
        if (b.surge) {
            std::snprintf(buf, sizeof buf, " всплеск действий ×%d;", b.surge);
            r += buf;
        }
        r += "\n";
    }
    if (b.dv || b.blindsight || b.ignDiff || b.climbS || b.swimS || b.burrowS || b.evasion || b.sunSens || b.lair) {
        r += "  Чувства/движение:";
        if (b.dv) {
            std::snprintf(buf, sizeof buf, " тёмное зрение %d фт;", b.dv);
            r += buf;
        }
        if (b.blindsight) {
            std::snprintf(buf, sizeof buf, " слепое зрение %d фт;", b.blindsight);
            r += buf;
        }
        if (b.ignDiff) r += " игнорирует труднопроходимую местность;";
        if (b.climbS) r += " лазает;";
        if (b.swimS) r += " плавает;";
        if (b.burrowS) r += " копает;";
        if (b.evasion) r += " увёртливость;";
        if (b.lair) r += " логово " + std::to_string(b.lair) + ";";
        if (b.sunSens) r += " боится солнца;";
        r += "\n";
    }
    for (auto& q : b.alt) {
        std::snprintf(buf, sizeof buf, "  Запасное оружие: %dк%d (%s), дальн. %d фт%s, атак: %d%s (%lld очк.)\n", q.n,
                      q.s, DTN[q.type], q.range, (q.range <= 5 && q.reach > 5) ? " (досягаемость больше)" : "", q.att,
                      q.range > 5 ? (q.ammo ? ", боеприпасное" : ", метательное") : (q.finesse ? ", фехтовальное" : ""),
                      q.cost);
        r += buf;
    }
    if (b.suppMask) {
        auto mk2 = [&](unsigned m) {
            std::string o;
            for (int t = 0; t < DT_N; t++)
                if ((m >> t) & 1) o += std::string(o.empty() ? "" : ", ") + DTN[t];
            return o;
        };
        std::string tg;
        if (b.suppTgt & 1) tg += "регенерация ";
        if (b.suppTgt & 2) tg += "аура ";
        if (b.suppTgt & 4) tg += "резисты/иммунитеты ";
        r += "  Подавление: урон типа (" + mk2(b.suppMask) + ") отключает на ход: " + tg + "\n";
    }
    r += std::string("  Тип урона оружия: ") + DTN[b.wType] + (b.wMagic ? " (магическое)" : " (немагическое)") + "\n";
    if (b.regenN || b.resMask || b.immMask || b.vulnMask || b.resNM || b.immNM || b.fly ||
        b.speed != 30 || b.immCond || b.saveProf || b.legRes || b.legAct || b.parry || b.uncanny || b.immPush || b.magicRes || b.spellRes || b.critImm || b.wSilver || b.lightR || b.unarmoredStat >= 0 ||
        b.disengB || b.redirect || b.prof != 2 || b.wNoProf || b.skillProf || b.toolN) {
        r += "  Пассивы:";
        if (b.prof != 2) {
            std::snprintf(buf, sizeof buf, " мастерство +%d;", b.prof);
            r += buf;
        }
        if (b.wNoProf) r += " не владеет своим оружием;";
        for (int k = 0; k < SK_N; k++)
            if ((b.skillProf >> k) & 1u) r += std::string(" ") + SKN[k] + (((b.skillExp >> k) & 1u) ? " (экспертиза)" : "") + ";";
        if (b.toolN) {
            std::snprintf(buf, sizeof buf, " инструментов %d;", b.toolN);
            r += buf;
        }
        if (b.regenN) {
            std::snprintf(buf, sizeof buf, " регенерация %dк6;", b.regenN);
            r += buf;
        }
        auto mk = [&](unsigned m) {
            std::string o;
            for (int t = 0; t < DT_N; t++)
                if ((m >> t) & 1) o += std::string(o.empty() ? "" : ", ") + DTN[t];
            return o;
        };
        if (b.resMask) r += " резист: " + mk(b.resMask) + ";";
        if (b.immMask) r += " иммунитет: " + mk(b.immMask) + ";";
        if (b.vulnMask) r += " УЯЗВИМОСТЬ: " + mk(b.vulnMask) + ";";
        if (b.resNM) r += " резист к немагическому физическому;";
        if (b.immNM) r += " иммунитет к немагическому физическому;";
        if (b.parry) {
            std::snprintf(buf, sizeof buf, " парирование +%d;", b.parry);
            r += buf;
        }
        if (b.uncanny) r += " невероятное уклонение;";
        if (b.magicRes) r += " сопротивление магии;";
        if (b.spellRes) r += " сопротивление урону от способностей;";
        if (b.critImm) r += " иммунитет к критам;";
        if (b.wSilver) r += " посеребрённое оружие;";
        if (b.lightR) r += " свет " + std::to_string(b.lightR) + " фт;";
        if (b.unarmoredStat >= 0) r += std::string(" без доспеха + ") + SN[b.unarmoredStat] + ";";
        if (b.immPush) r += " иммунитет к отталкиванию;";
        if (b.redirect) r += " Перенаправление (реакция);";
        if (b.disengB) r += " Отход бонусным действием;";
        if (b.legAct) {
            std::snprintf(buf, sizeof buf, " легендарные действия %d оч.;", b.legAct);
            r += buf;
        }
        if (b.legRes) {
            std::snprintf(buf, sizeof buf, " легендарное сопротивление %d/бой;", b.legRes);
            r += buf;
        }
        if (b.fly) r += " полёт;";
        if (b.speed != 30) {
            std::snprintf(buf, sizeof buf, " скорость %d фт;", b.speed);
            r += buf;
        }
        for (int k = 0; k < STAT_N; k++)
            if ((b.saveProf >> k) & 1u) {
                std::snprintf(buf, sizeof buf, " владение спасброском %s;", SN[k]);
                r += buf;
            }
        for (int k = 1; k < C_N; k++)
            if (b.immCond & (1u << k)) {
                std::snprintf(buf, sizeof buf, " иммунитет: %s;", CN[k]);
                r += buf;
            }
        r += "\n";
    }
    for (auto& s : b.abil) r += "  Способность: " + describe(s) + "\n";
    for (size_t t = 0; t < b.tmpl.size(); t++) {
        std::snprintf(buf, sizeof buf, "  Шаблон приспешника %zu (стоимость %lld):\n", t + 1, b.tmpl[t].cost);
        r += buf;
        r += describeBoss(b.tmpl[t]);
    }
    return r;
}

#include "replay_export.h"
#include "par.h"
#include "builder_net.h"   // этап 5б: калибровка на смеси — часть боссов собирают сети-Сборщики

// Калибровка на смеси (этап 5б, решение владельца): доля пар DND_CALIB_BLD (по умолчанию 0 — только генератор), где
// боссов собирают сети-Сборщики (веса DND_CALIB_BLDA и DND_CALIB_BLDB, по умолчанию net_runs/builder5_A/B.bin). Из
// таких пар треть — Сборщик против Сборщика (A против B), две трети — Сборщик (A или B) против генератора
struct CalibBld {
    bld::BNet net[2];
    bool ok = false;
    double share = 0;
} g_cb;
void loadCalibBld() {
    const char* e = std::getenv("DND_CALIB_BLD");
    g_cb.share = e ? std::clamp(std::atof(e), 0.0, 1.0) : 0.0;
    if (g_cb.share <= 0) return;
    const char* pa = std::getenv("DND_CALIB_BLDA");
    const char* pb = std::getenv("DND_CALIB_BLDB");
    const std::string fa = pa ? pa : dndPath("net_runs/builder5_A.bin"), fb = pb ? pb : dndPath("net_runs/builder5_B.bin");
    g_cb.ok = bld::loadNet(fa, g_cb.net[0]) && bld::loadNet(fb, g_cb.net[1]);
    if (!g_cb.ok) {
        std::fprintf(stderr, "ВНИМАНИЕ: веса Сборщиков %s / %s не загрузились — калибровка только на генераторе\n", fa.c_str(), fb.c_str());
        g_cb.share = 0;
    }
}
// босс от сети-Сборщика k (0 — A, 1 — B)
Boss makeBossBld(long long B, const Coef& C, int k) {
    bld::BrainNet br(&g_cb.net[k], nullptr);
    g_bb = &br;
    Boss b = makeBoss(B, C, true, false);
    g_bb = nullptr;
    return b;
}
// пара для калибровки: kind 0 — генератор против генератора (makePair), 1 — Сборщик против генератора, 2 — Сборщик A против
// Сборщика B; side — какая сторона у Сборщика (для kind 1)
int makeCalibPair(long long B, const Coef& C, Boss& A, Boss& Bo, int& side) {
    side = -1;
    if (g_cb.share <= 0 || rand01() >= g_cb.share) {
        makePair(B, C, A, Bo);
        return 0;
    }
    const int k = irand(3);
    if (k == 2) {
        A = makeBossBld(B, C, 0);
        Bo = makeBossBld(B, C, 1);
        return 2;
    }
    side = irand(2);
    Boss nb = makeBossBld(B, C, k), gb = makeBoss(B, C, true, false);
    A = side == 0 ? std::move(nb) : std::move(gb);
    Bo = side == 0 ? std::move(gb) : std::move(nb);
    return 1;
}

int main(int argc, char** argv) {
    if (argc > 1 && std::string(argv[1]) == "replay") {
        long long budget = argc > 2 ? std::stoll(argv[2]) : 1600;
        unsigned seed = argc > 3 ? (unsigned)std::stoul(argv[3]) : (unsigned)std::time(nullptr);
        std::string outPath = argc > 4 ? argv[4] : "battle_replay.html";
        // на огромных бюджетах (гигантские ХП) может понадобиться больше 60
        if (argc > 5) g_maxRounds = std::stoi(argv[5]);
        // ./arena replay бюджет зерно out.html раунды smart: босс A собран по «умной» политике
        bool smartReplay = argc > 6 && std::string(argv[6]) == "smart";
        rng.seed(seed);
        // ВНИМАНИЕ: стартовые цены "на глаз", не откалиброванные — для просмотра боя это не важно
        Coef C;
        for (int a = 0; a < AT_N; a++) C[a] = AD[a].init;
        Boss A, B;
        if (smartReplay) {
            g_bp = &SMART_BP;
            A = makeBoss(budget, C, true, false);
            g_bp = nullptr;
            B = makeBoss(budget, C, true, false);
        } else
            makePair(budget, C, A, B);
        std::printf("=== Босс A ===\n%s\n=== Босс B ===\n%s\n", describeBoss(A).c_str(), describeBoss(B).c_str());
        std::vector<std::string> frames;
        std::string mapJson;
        int res = fight(A, B, &frames, &mapJson);
        std::printf("Победитель: %s\n", res == 0 ? "Босс A" : (res == 1 ? "Босс B" : "ничья"));
        writeViewerHTML(outPath, A, B, C, (double)budget, smartReplay ? "Умная политика / генератор" : "Случайный генератор", "Случайный генератор", seed, mapJson, frames);
        return 0;
    }
    if (argc > 1 && std::string(argv[1]) == "ladder") {
        // Бюджетная лестница: как часто босс большего бюджета побеждает босса меньшего (случайные сборки, один из двух
        // обязательно с миньонами).
        // ./arena ladder <малый=800> <большой=1600> [боёв=6000] [зерно=42]   цель плана v19: 800 против 1600 → 75–80%
        long long lo = argc > 2 ? std::stoll(argv[2]) : 800, hi = argc > 3 ? std::stoll(argv[3]) : 1600;
        int n = argc > 4 ? std::stoi(argv[4]) : 6000;
        unsigned sd = argc > 5 ? (unsigned)std::stoul(argv[5]) : 42;
        rng.seed(sd);
        Coef C;
        for (int a = 0; a < AT_N; a++) C[a] = AD[a].init;
        double w = 0;
        g_rounds = 0;
        g_capped = 0;
        for (int i = 0; i < n; i++) {
            int fs = irand(2);
            Boss s = makeBoss(lo, C, true, fs == 0), l = makeBoss(hi, C, true, fs == 1);
            // стороны меняются
            int r = (i % 2 == 0) ? fight(l, s) : fight(s, l);
            w += r == 2 ? 0.5 : (((i % 2 == 0) == (r == 0)) ? 1.0 : 0.0);
        }
        double p = w / n;
        std::printf("Бюджет %lld против %lld: больший выигрывает %.1f%% (±%.1f п.п., %d боёв); средняя длина боя %.1f "
                    "р., в лимит %.1f%%\n",
                    lo, hi, 100 * p, 100 * 2 * std::sqrt(p * (1 - p) / n), n, (double)g_rounds / n,
                    100.0 * g_capped / n);
        std::printf("Погонь на бой %.3f, побегов %.3f, истощений %.3f, осложнений %.3f\n", (double)g_chases / n, (double)g_escapes / n,
                    (double)g_exhaustions / n, (double)g_complications / n);
        return 0;
    }
    if (argc > 1 && std::string(argv[1]) == "learn") {
        // Самообучение политики: претендент (мутация) против чемпиона на одних и тех же парах боссов, стороны меняются
        // местами.
        int iters = argc > 2 ? std::stoi(argv[2]) : 150, pairs = argc > 3 ? std::stoi(argv[3]) : 1200;
        unsigned seed = argc > 4 ? (unsigned)std::stoul(argv[4]) : 7;
        Coef C;
        for (int a = 0; a < AT_N; a++) C[a] = AD[a].init;
        const long long BL6[6] = {200, 400, 800, 1600, 3200, 6400};
        typedef std::vector<std::pair<Boss, Boss>> PairV;
        auto genPairs = [&](unsigned sd, int n, long long fixedB) {
            rng.seed(sd);
            PairV v;
            for (int i = 0; i < n; i++) {
                long long B = fixedB ? fixedB : BL6[irand(6)];
                Boss a, b;
                makePair(B, C, a, b);
                v.push_back({a, b});
            }
            return v;
        };
        auto score = [&](const Pol& ch, const Pol& op, const PairV& P, unsigned sd) {
            double s = 0;
            for (size_t i = 0; i < P.size(); i++) {
                rng.seed(sd + (unsigned)i * 2);
                int r = fight(P[i].first, P[i].second, nullptr, nullptr, &ch, &op);
                s += r == 0 ? 1.0 : (r == 2 ? 0.5 : 0.0);
                rng.seed(sd + (unsigned)i * 2 + 1);
                r = fight(P[i].first, P[i].second, nullptr, nullptr, &op, &ch);
                s += r == 1 ? 1.0 : (r == 2 ? 0.5 : 0.0);
            }
            return s / (2.0 * P.size());
        };
        Pol base = Pol::baseline(), champ = base;
        int accepted = 0;
        std::printf(
            "=== Самообучение политики: %d итераций, %d пар боссов на проверку (стороны меняются), зерно %u ===\n",
            iters, pairs, seed);
        for (int it = 0; it < iters; it++) {
            PairV P = genPairs(seed * 1000 + it, pairs, 0);
            Pol ch = champ;
            double sg = 0.18 * (1.0 - 0.7 * it / iters);
            int nm = 0;
            for (int k = 0; k < PO_N; k++)
                if (rand01() < 0.25) {
                    ch.v[k] = std::clamp(ch.v[k] + randn() * sg * (PD[k].hi - PD[k].lo), PD[k].lo, PD[k].hi);
                    nm++;
                }
            if (!nm) {
                int k = irand(PO_N);
                ch.v[k] = std::clamp(ch.v[k] + randn() * sg * (PD[k].hi - PD[k].lo), PD[k].lo, PD[k].hi);
            }
            double s1 = score(ch, champ, P, seed * 100000 + it * 7), se = 0.5 / std::sqrt(2.0 * pairs);
            // предварительно лучше — проверяем на свежих парах втрое строже
            if (s1 > 0.5 + 1.0 * se) {
                PairV P2 = genPairs(seed * 1000 + it + 500000, pairs * 2, 0);
                double s2 = score(ch, champ, P2, seed * 100000 + it * 7 + 3);
                double comb = (s1 * pairs + s2 * 2 * pairs) / (3.0 * pairs), sec = 0.5 / std::sqrt(6.0 * pairs);
                if (comb > 0.5 + 1.5 * sec) {
                    champ = ch;
                    accepted++;
                    std::printf("  итерация %3d: принят (%.1f%% против чемпиона), принято %d\n", it + 1, 100 * comb,
                                accepted);
                    std::fflush(stdout);
                }
            }
            if ((it + 1) % 25 == 0) {
                std::printf("--- %d/%d, принято %d; ", it + 1, iters, accepted);
                for (int k = 0; k < PO_N; k++) std::printf("%s=%.3g ", PD[k].name, champ.v[k]);
                std::printf("\n");
                std::fflush(stdout);
            }
        }
        std::printf("\n=== Итог: обученный бот против базового (свежие пары, по бюджетам) ===\n");
        double tot = 0;
        for (int bi = 0; bi < 6; bi++) {
            PairV P = genPairs(seed * 77 + 1000 + bi, 2000, BL6[bi]);
            double sc = score(champ, base, P, 9000000 + bi * 100000);
            tot += sc;
            std::printf("  бюджет %5lld: обученный выигрывает %.1f%%\n", BL6[bi], 100 * sc);
        }
        std::printf("  в среднем: %.1f%%\n\n", 100 * tot / 6);
        for (int k = 0; k < PO_N; k++) std::printf("BAKE %s %.4f   (было %.4g)\n", PD[k].name, champ.v[k], PD[k].base);
        return 0;
    }
    if (argc > 1 && std::string(argv[1]) == "learnbuild") {
        // Босс учится решать про миньонов: (1+1)-эволюционная стратегия по 4 параметрам сборки; оценка — винрейт босса,
        // собранного по политике, против случайно собранного соперника того же бюджета (бой ведёт одна и та же боевая
        // политика у обоих).
        int iters = argc > 2 ? std::stoi(argv[2]) : 120, n = argc > 3 ? std::stoi(argv[3]) : 3000;
        unsigned seed = argc > 4 ? (unsigned)std::stoul(argv[4]) : 7;
        Coef C;
        for (int a = 0; a < AT_N; a++) C[a] = AD[a].init;
        const long long BL6[6] = {200, 400, 800, 1600, 3200, 6400};
        Pol pol = Pol::baseline();
        // bp == nullptr — случайный генератор
        auto score = [&](const BuildPol* bp, int cnt, unsigned sd, long long fixedB) {
            double s = 0;
            for (int i = 0; i < cnt; i++) {
                rng.seed(sd + (unsigned)i * 3);
                long long B = fixedB ? fixedB : BL6[irand(6)];
                g_bp = bp;
                Boss x = makeBoss(B, C, true, false);
                g_bp = nullptr;
                Boss y = makeBoss(B, C, true, false);
                int r;
                if (i % 2 == 0) {
                    r = fight(x, y, nullptr, nullptr, &pol, &pol);
                    s += r == 0 ? 1.0 : (r == 2 ? 0.5 : 0.0);
                } else {
                    r = fight(y, x, nullptr, nullptr, &pol, &pol);
                    s += r == 1 ? 1.0 : (r == 2 ? 0.5 : 0.0);
                }
            }
            return s / cnt;
        };
        BuildPol champ;
        int accepted = 0;
        std::printf("=== Босс учится решать про миньонов: %d итераций, %d боёв на оценку, зерно %u ===\n", iters, n,
                    seed);
        for (int it = 0; it < iters; it++) {
            BuildPol ch = champ;
            double sg = 0.2 * (1.0 - 0.7 * it / iters);
            int nm = 0;
            rng.seed(seed * 1000 + it);
            for (int k = 0; k < 4; k++)
                if (rand01() < 0.5) {
                    ch.v[k] = std::clamp(ch.v[k] + randn() * sg * (BPHI[k] - BPLO[k]), BPLO[k], BPHI[k]);
                    nm++;
                }
            if (!nm) {
                int k = irand(4);
                ch.v[k] = std::clamp(ch.v[k] + randn() * sg * (BPHI[k] - BPLO[k]), BPLO[k], BPHI[k]);
            }
            unsigned sd = seed * 100000 + it * 11;
            double sc = score(&ch, n, sd, 0), sh = score(&champ, n, sd, 0),
                   se = 0.5 / std::sqrt((double)n) * std::sqrt(2.0);
            if (sc > sh + 1.0 * se) {
                double sc2 = score(&ch, 2 * n, sd + 5000003, 0), sh2 = score(&champ, 2 * n, sd + 5000003, 0);
                double comb = ((sc - sh) * n + (sc2 - sh2) * 2 * n) / (3.0 * n),
                       sec = 0.5 / std::sqrt(3.0 * n) * std::sqrt(2.0);
                if (comb > 1.5 * sec) {
                    champ = ch;
                    accepted++;
                    std::printf("  итерация %3d: принят (+%.1f п.п. к прежней), принято %d: ", it + 1, 100 * comb,
                                accepted);
                    for (int k = 0; k < 4; k++) std::printf("%s=%.3g ", BPN[k], champ.v[k]);
                    std::printf("\n");
                    std::fflush(stdout);
                }
            }
        }
        std::printf("\n=== Итог: босс с обученной сборкой против случайно собранного (свежие бои) ===\n");
        double tot = 0, totD = 0;
        for (int bi = 0; bi < 6; bi++) {
            double a = score(&champ, 3000, 9000000 + bi * 7919, BL6[bi]),
                   d = score(nullptr, 3000, 9000000 + bi * 7919, BL6[bi]);
            tot += a;
            totD += d;
            std::printf("  бюджет %5lld: обученная сборка выигрывает %.1f%% (контроль: случайный генератор против "
                        "случайного %.1f%%)\n",
                        BL6[bi], 100 * a, 100 * d);
        }
        std::printf("  в среднем: %.1f%% (контроль %.1f%%)\n\n", 100 * tot / 6, 100 * totD / 6);
        for (int k = 0; k < 4; k++) std::printf("BUILD %s %.4f\n", BPN[k], champ.v[k]);
        return 0;
    }
    long long budgetArg = 0;
    int fights = 14000, iters = 30;
    unsigned seed = 42;
    double targetLen = 14.0;
    if (argc > 1) budgetArg = std::stoll(argv[1]);
    if (argc > 2) fights = std::stoi(argv[2]);
    if (argc > 3) iters = std::stoi(argv[3]);
    if (argc > 4) seed = (unsigned)std::stoul(argv[4]);
    if (argc > 5) targetLen = std::stod(argv[5]);
    if (argc > 6) g_maxRounds = std::stoi(argv[6]);
    rng.seed(seed);
    loadCalibBld();
    if (g_cb.share > 0) std::printf("калибровка на смеси: %.0f%% пар с боссами сетей-Сборщиков\n", 100 * g_cb.share);
    std::vector<long long> BL =
        budgetArg > 0 ? std::vector<long long>{budgetArg} : std::vector<long long>{200, 400, 800, 1600, 3200, 6400};
    int nB = (int)BL.size(), perB = std::max(1, fights / nB);

    Coef C;
    for (int a = 0; a < AT_N; a++) C[a] = AD[a].init;
    Coef start = C;
    std::printf("=== Арена Боссов v6: ОДНА таблица цен на все бюджеты ===\nБюджеты:");
    for (auto b : BL) std::printf(" %lld", b);
    std::printf(" | боёв на бюджет %d, итераций %d, зерно %u, целевая длина боя %.0f р.\n\n", perB, iters, seed,
                targetLen);

    struct PassRes {
        std::array<double, AT_N> wr{}, wlo{}, whi{};
        std::array<int, AT_N> gm{}, nv{};
        double len = 0, sumDiff = 0, cap = 0;
        int sumValid = 0;
        std::vector<double> lenB;
        double slope = 0;
        int slopeN = 0;
        std::vector<double> dB;
        std::array<double, AT_N> use{}, useDen{};   // метрики использования (№6): доля или применений за бой; den — база
        double bldW = 0;   // этап 5б: очки Сборщика против генератора (доля) и число таких пар, пар Сборщик–Сборщик
        int bldN = 0, bldBB = 0;
    };
    int passId = 0;
    // Прогон делится на задачи (бюджет × кусок боёв). У каждой задачи своё зерно из (зерно, номер прогона, бюджет,
    // кусок), а результаты складываются в фиксированном порядке: итог не зависит ни от числа потоков, ни от их
    // расписания.
    auto pass = [&](const Coef& Cc, int per) {
        PassRes R;
        R.wlo.fill(2.0);
        R.whi.fill(-1.0);
        for (int t = 0; t < DT_N; t++) g_dmgT[t] = 0;
        g_dmgNM = 0;
        const int CH = 16, nT = nB * CH, pid = ++passId;
        struct TaskRes {
            std::array<double, AT_N> wins{};
            std::array<int, AT_N> games{};
            double nw = 0, sw = 0;
            int ng = 0, sg = 0;
            long long rounds = 0, capped = 0;
            double dmgT[DT_N] = {};
            double dmgNM = 0;
            long long st[10] = {};
            std::array<double, AT_N> useNum{}, useDen{};   // метрики использования по владельцам атома (№6)
            double bldW = 0;   // очки Сборщика в парах «Сборщик против генератора» (этап 5б)
            int bldN = 0, bldBB = 0;
        };
        std::vector<TaskRes> tr(nT);
        std::atomic<int> nextTask(0);
        long long base[10] = {g_lrUsed,  g_rechUsed, g_rechRolls,  g_rechOk, g_attacksMade,
                              g_legUsed, g_concCast, g_concBroken, g_surge,  g_ripUsed};
        auto worker = [&]() {
            // этап 4 ТЗ (решение владельца): в калибровке всеми боссами ходит обученная сеть, если она загружена
            // (ИНТ — только игровая характеристика); без сети (DND_NETP=off) — бот, для сравнения цен
            g_forceNetMask = pn::primNet() ? 3 : 0;
            long long* cn[10] = {&g_lrUsed,  &g_rechUsed, &g_rechRolls,  &g_rechOk, &g_attacksMade,
                                 &g_legUsed, &g_concCast, &g_concBroken, &g_surge,  &g_ripUsed};
            for (;;) {
                int t = nextTask++;
                if (t >= nT) break;
                int bi = t / CH, ch = t % CH, n = per / CH + (ch < per % CH ? 1 : 0);
                TaskRes& T = tr[t];
                rng.seed((((uint64_t)seed * 1315423911ULL + (uint64_t)pid) * 2654435761ULL + (uint64_t)bi) * 40503ULL +
                         (uint64_t)ch);
                for (int k = 0; k < DT_N; k++) g_dmgT[k] = 0;
                g_dmgNM = 0;
                g_track = true;
                g_rounds = 0;
                g_capped = 0;
                long long s0[10];
                for (int k = 0; k < 10; k++) s0[k] = *cn[k];
                for (int i = 0; i < n; i++) {
                    Boss A, B;
                    int bside = -1;
                    const int kind = makeCalibPair(BL[bi], Cc, A, B, bside);
                    int res = fight(A, B);
                    if (kind == 1) {
                        T.bldW += res == 2 ? 0.5 : (res == bside ? 1.0 : 0.0);
                        T.bldN++;
                    } else if (kind == 2)
                        T.bldBB++;
                    for (int side = 0; side < 2; side++) {   // метрики использования (№6) — у владельцев атома
                        const Boss& bp = side == 0 ? A : B;
                        const long long* u = g_use[side];
                        auto addU = [&](int a, double num, double den) {
                            if (bp.at(a)) T.useNum[a] += num, T.useDen[a] += den;
                        };
                        addU(AT_WPNRANGE, (double)u[U_WOUT], (double)u[U_WATK]);
                        addU(AT_ARANGE, (double)u[U_SOUT], (double)u[U_SATK]);
                        addU(AT_SPEED, (double)u[U_FTAWAY], (double)u[U_FT]);
                        addU(AT_HIDE, (double)u[U_HIDE], 1.0);
                        addU(AT_INVIS, (double)u[U_INVIS], 1.0);
                        addU(AT_DARK, (double)u[U_DARK], 1.0);
                        // прочие атомы способностей: применений за бой у тех владельцев, у кого атом — в способности
                        AMask sm = 0;
                        for (auto& sp : bp.abil) markSpec(sp, sm);
                        for (int a = 0; a < AT_N; a++)
                            if (((sm >> a) & ONE) && a != AT_ARANGE && a != AT_HIDE && a != AT_INVIS && a != AT_DARK)
                                T.useNum[a] += (double)g_castAtom[side][a], T.useDen[a] += 1.0;
                    }
                    double sa = res == 0 ? 1.0 : (res == 2 ? 0.5 : 0.0);
                    for (int side = 0; side < 2; side++) {
                        const Boss& bp = side == 0 ? A : B;
                        double sc = side == 0 ? sa : 1.0 - sa;
                        if (bp.at(AT_SUMMON)) {
                            T.sw += sc;
                            T.sg++;
                        } else {
                            T.nw += sc;
                            T.ng++;
                        }
                        for (int a = 0; a < AT_N; a++)
                            if (bp.at(a)) {
                                T.wins[a] += sc;
                                T.games[a]++;
                            }
                    }
                }
                g_track = false;
                T.rounds = g_rounds;
                T.capped = g_capped;
                for (int k = 0; k < DT_N; k++) T.dmgT[k] = g_dmgT[k];
                T.dmgNM = g_dmgNM;
                for (int k = 0; k < 10; k++) T.st[k] = *cn[k] - s0[k];
            }
        };
        {
            const char* e = std::getenv("DND_THREADS");
            int nth = e ? std::max(1, std::atoi(e)) : std::max(1, (int)std::thread::hardware_concurrency() - 2);   // ТЗ v21: по умолчанию ядра − 2
            nth = std::min(nth, nT);
            std::vector<std::thread> th;
            for (int k = 1; k < nth; k++) th.emplace_back(worker);
            worker();
            for (auto& x : th) x.join();
        }
        long long* mc[10] = {&g_lrUsed,  &g_rechUsed, &g_rechRolls,  &g_rechOk, &g_attacksMade,
                             &g_legUsed, &g_concCast, &g_concBroken, &g_surge,  &g_ripUsed};
        // главный поток тоже брал задачи: возвращаем его счётчики и суммируем всё из результатов задач
        for (int k = 0; k < 10; k++) *mc[k] = base[k];
        for (int k = 0; k < DT_N; k++) g_dmgT[k] = 0;
        g_dmgNM = 0;
        std::array<double, AT_N> wsum{};
        std::vector<std::pair<double, double>> dpts;
        double diffSum = 0, lenSum = 0;
        int diffN = 0;
        long long capTot = 0, fTot = 0;
        for (int bi = 0; bi < nB; bi++) {
            std::array<double, AT_N> wins{};
            std::array<int, AT_N> games{};
            double nw = 0, sw = 0;
            int ng = 0, sg = 0;
            long long rounds = 0, capped = 0;
            for (int ch = 0; ch < CH; ch++) {
                const TaskRes& T = tr[bi * CH + ch];
                R.bldW += T.bldW;
                R.bldN += T.bldN;
                R.bldBB += T.bldBB;
                for (int a = 0; a < AT_N; a++) R.use[a] += T.useNum[a], R.useDen[a] += T.useDen[a];
                for (int a = 0; a < AT_N; a++) {
                    wins[a] += T.wins[a];
                    games[a] += T.games[a];
                }
                nw += T.nw;
                sw += T.sw;
                ng += T.ng;
                sg += T.sg;
                rounds += T.rounds;
                capped += T.capped;
                for (int k = 0; k < DT_N; k++) g_dmgT[k] += T.dmgT[k];
                g_dmgNM += T.dmgNM;
                for (int k = 0; k < 10; k++) *mc[k] += T.st[k];
            }
            double len = (double)rounds / per;
            R.lenB.push_back(len);
            lenSum += len;
            capTot += capped;
            fTot += per;
            for (int a = 0; a < AT_N; a++) {
                R.gm[a] += games[a];
                if (games[a] >= 100) {
                    double w = wins[a] / games[a];
                    wsum[a] += w;
                    R.nv[a]++;
                    R.wlo[a] = std::min(R.wlo[a], w);
                    R.whi[a] = std::max(R.whi[a], w);
                }
            }
            if (sg >= 100 && ng >= 100) {
                diffSum += sw / sg - nw / ng;
                diffN++;
                dpts.push_back({std::log2(BL[bi] / 1600.0), sw / sg - nw / ng});
            }
        }
        for (int a = 0; a < AT_N; a++) R.wr[a] = R.nv[a] ? wsum[a] / R.nv[a] : 0.5;
        // наклон «винрейт призывателя минус винрейт остальных» по бюджетам (на октаву бюджета)
        if (dpts.size() >= 3) {
            double mx = 0, my = 0;
            for (auto& p : dpts) {
                mx += p.first;
                my += p.second;
            }
            mx /= dpts.size();
            my /= dpts.size();
            double sxx = 0, sxy = 0;
            for (auto& p : dpts) {
                sxx += (p.first - mx) * (p.first - mx);
                sxy += (p.first - mx) * (p.second - my);
            }
            if (sxx > 0) {
                R.slope = sxy / sxx;
                R.slopeN = (int)dpts.size();
            }
            for (auto& p : dpts) R.dB.push_back(p.second);
        }
        for (int a = 0; a < AT_N; a++) R.use[a] = R.useDen[a] > 0 ? R.use[a] / R.useDen[a] : 0.0;
        R.len = lenSum / nB;
        R.sumDiff = diffN ? diffSum / diffN : 0;
        R.sumValid = diffN;
        R.cap = 100.0 * capTot / fTot;
        if (R.bldN > 0) R.bldW /= R.bldN;
        return R;
    };

    // ТЗ v21, №6 (пороги — решение владельца): атомом «почти не пользуются», если дальность (доля атак из-за пределов
    // досягаемости цели) и скорость (доля пройденного не на сближение) меньше 5%, а скрытность, невидимость, тьма —
    // меньше 0.1 применения за бой у владельцев. Таким атомам калибровка цену не снижает (только повышает)
    // и (решение владельца 2026-11-01: калибровать и по используемости) любой атом способности — меньше 0.1 применения за
    // бой у владельцев, у которых он в способности
    std::array<bool, AT_N> abilAtom{};
    auto useThr = [&](int a) {
        return (a == AT_WPNRANGE || a == AT_ARANGE || a == AT_SPEED) ? 0.05 : (a == AT_HIDE || a == AT_INVIS || a == AT_DARK || abilAtom[a]) ? 0.1 : -1.0;
    };
    auto useStr = [&](const PassRes& R) {
        char b[260];
        std::snprintf(b, sizeof b, "исп.: дальн. оружия %.1f%%, дальн. способн. %.1f%%, скорость %.1f%%, скрытн. %.2f, невид. %.2f, тьма %.2f за бой",
                      100 * R.use[AT_WPNRANGE], 100 * R.use[AT_ARANGE], 100 * R.use[AT_SPEED], R.use[AT_HIDE], R.use[AT_INVIS], R.use[AT_DARK]);
        return std::string(b);
    };
    std::printf("Кто ходит: %s\n", pn::primNet() ? "все боссы — обученная сеть (net_fighter_p.bin), ИНТ только игровая характеристика" : "все — правило-бот (сети нет)");
    Coef Csum{};
    int Ccnt = 0;
    for (int it = 0; it < iters; it++) {
        PassRes R = pass(C, perB);
        for (int a = 0; a < AT_N; a++) abilAtom[a] = abilAtom[a] || (R.useDen[a] > 0 && a != AT_WPNRANGE && a != AT_SPEED);
        // цены защит следуют за реальной долей урона по типам
        {
            double tot = 0;
            for (int t = 0; t < DT_N; t++) tot += g_dmgT[t];
            if (tot > 0) {
                for (int t = 0; t < DT_N; t++) g_share[t] = 0.5 * g_share[t] + 0.5 * (g_dmgT[t] / tot);
                g_nmShare = 0.5 * g_nmShare + 0.5 * (g_dmgNM / tot);
            }
        }
        std::printf("--- Итерация %d --- длина боя по бюджетам:", it + 1);
        for (double l : R.lenB) std::printf(" %.1f", l);
        std::printf(" | в лимит %.1f%% | наклон призывателя %.3f/окт., k=%.3f", R.cap, R.slope, C[AT_MINEXP]);
        if (R.bldN > 0) std::printf(" | Сборщик против генератора %.1f%% (%d пар), Сборщик–Сборщик %d пар", 100 * R.bldW, R.bldN, R.bldBB);
        std::printf("\n");
        std::printf("    %s\n", useStr(R).c_str());
        if (it >= iters * 2 / 3) {
            for (int a = 0; a < AT_N; a++) Csum[a] += C[a];
            Ccnt++;
        }
        if (it < iters - 1) {
            for (int a = 0; a < AT_N; a++) {
                double f = 1.0;
                // показатель: слабее призыватели на больших бюджетах → цена там дешевле
                if (AD[a].mode == 5) {
                    if (R.slopeN >= 3) C[a] = std::clamp(C[a] - 2.0 * R.slope, AD[a].lo, AD[a].hi);
                    continue;
                }
                if (AD[a].mode == 1)
                    f = std::clamp(1.0 + 0.4 * (targetLen - R.len) / targetLen, 0.8, 1.25);
                else if (AD[a].mode == 3) {
                    if (R.sumValid > 0) f = std::clamp(1.0 + R.sumDiff * 1.2, 0.75, 1.3);
                } else if (AD[a].mode == 0 && R.nv[a] > 0)
                    f = std::clamp(1.0 + (R.wr[a] - 0.5) * 1.2, 0.75, 1.3);
                // возврат: чем лучше владельцы, тем МЕНЬШЕ возврат
                else if (AD[a].mode == 4 && R.nv[a] > 0)
                    f = std::clamp(1.0 - (R.wr[a] - 0.5) * 1.2, 0.75, 1.3);
                if (useThr(a) >= 0 && R.use[a] < useThr(a)) f = std::max(f, 1.0);   // №6: не пользуются — не дешевле
                C[a] = std::clamp(C[a] * f, AD[a].lo, AD[a].hi);
            }
        }
    }
    // усреднение по последней трети — гасит шум
    if (Ccnt > 0)
        for (int a = 0; a < AT_N; a++) C[a] = Csum[a] / Ccnt;
    PassRes F = pass(C, perB * 2);
    {
        std::printf("Винрейт призывателя минус остальные по бюджетам (разность, п.п.):");
        for (double d : F.dB) std::printf(" %+.1f", 100 * d);
        std::printf(" | наклон %.3f на октаву, k=%.3f\n", F.slope, C[AT_MINEXP]);
    }
    std::printf(
        "\n=== Итог (усреднённые цены, контрольный прогон x2): коэф, винрейт среднее [мин..макс по бюджетам] ===\n");
    for (int a = 0; a < AT_N; a++) {
        char us[48] = "";
        if (useThr(a) >= 0)   // используемость: доля (дальность, скорость) или применений за бой
            std::snprintf(us, sizeof us, useThr(a) < 0.08 ? "  исп. %.1f%%" : "  исп. %.2f/бой", useThr(a) < 0.08 ? 100 * F.use[a] : F.use[a]);
        std::printf("  %-52s %8.2f -> %8.2f   %5.1f%% [%5.1f..%5.1f]  n=%d%s\n", AD[a].name, start[a], C[a],
                    100 * F.wr[a], F.nv[a] ? 100 * F.wlo[a] : 0.0, F.nv[a] ? 100 * F.whi[a] : 0.0, F.gm[a], us);
    }
    std::printf("\nИспользование (№6, контрольный прогон): %s\n", useStr(F).c_str());
    for (int a = 0; a < AT_N; a++)
        if (useThr(a) >= 0 && F.use[a] < useThr(a))
            std::printf("  почти не используется: %s — цена не снижалась\n", AD[a].name);
    std::printf("\nДлина боя по бюджетам:");
    for (double l : F.lenB) std::printf(" %.1f", l);
    std::printf(" | в лимит %.1f%%\n", F.cap);
    std::printf("\nПрименения за прогон: концентрация %lld (сорвана %lld), всплеск действий %lld, контратаки %lld\n",
                g_concCast, g_concBroken, g_surge, g_ripUsed);
    std::printf("\nДоли урона по типам в боях:");
    for (int t = 0; t < DT_N; t++) std::printf(" %s %.3f;", DTN[t], g_share[t]);
    std::printf(" немагический физический %.3f\n", g_nmShare);
    std::printf("// g_share init: {");
    for (int t = 0; t < DT_N; t++) std::printf("%.3f%s", g_share[t], t + 1 < DT_N ? ", " : "}");
    std::printf("; g_nmShare = %.3f\n", g_nmShare);
    std::printf("\n// --- для вставки в AD[].init (по порядку) ---\n");
    for (int a = 0; a < AT_N; a++) std::printf("%.4f, // %s\n", C[a], AD[a].name);

    rng.seed((uint64_t)seed * 7919 + 1);
    std::printf("\n=== Примеры боссов, собранных по итоговым ценам (бюджет %lld) ===\n", BL[nB / 2]);
    for (int i = 0; i < 3; i++) {
        Boss b = makeBoss(BL[nB / 2], C, true);
        std::printf("Босс %d\n%s", i + 1, describeBoss(b).c_str());
    }
    return 0;
}
